INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91033, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拘束", "is_correct": true, "explanation": "拘束与自在构成反义关系，指放不开、不自由，与“没有人管我”的自在相对。"}, {"text": "认真", "is_correct": false, "explanation": "认真形容做事专心、不马虎，与自在无反义关系。"}, {"text": "高大", "is_correct": false, "explanation": "高大形容身材或事物高，与自在无反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与自在无反义关系。"}], "correct_answer": "拘束", "explanations": {"拘束": "拘束与自在构成反义关系，指放不开、不自由，与“没有人管我”的自在相对。", "认真": "认真形容做事专心、不马虎，与自在无反义关系。", "高大": "高大形容身材或事物高，与自在无反义关系。", "明亮": "明亮形容光线或颜色，与自在无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91033, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "自在是想怎么样就怎么样，心里很舒服。", "primary_collocate": null, "pronunciation": "zì zài", "ipa": "tsɿ˥˩ tsai˥˩", "syllable_count": 2, "sentences": [{"text": "周末在家，我过得很自在。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人住，生活很自在。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐在沙发上看书，真自在。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在朋友家里，你可以自在一点。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿着旧衣服，觉得很自在。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休以后，爷爷过得自在极了。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在陌生人中间，一点也不自在。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这种自在的生活。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在草地上自在地玩。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人管我，我觉得很自在。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自自在在", "label": "重叠"}], "register": "中性", "sense_fingerprint": "自在：想怎样就怎样，心里舒服不拘束", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '334d3bb3-d40f-4673-8ec2-5f77f12859af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91033, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自在", "is_correct": true, "explanation": "自在：心里舒服，不拘束。"}, {"text": "志在", "is_correct": false, "explanation": "志在的声母是 zh，自在的声母是 z（zhì 与 zì），意思是立志、以……为目标。"}, {"text": "只在", "is_correct": false, "explanation": "只在的声母是 zh，声调也不同（zhǐ 与 zì），意思是仅仅在。"}, {"text": "自带", "is_correct": false, "explanation": "自带的第二音节声母是 d（dài 与 zài），意思是自己携带。"}], "explanations": {"自在": "自在：心里舒服，不拘束。", "志在": "志在的声母是 zh，自在的声母是 z（zhì 与 zì），意思是立志、以……为目标。", "只在": "只在的声母是 zh，声调也不同（zhǐ 与 zì），意思是仅仅在。", "自带": "自带的第二音节声母是 d（dài 与 zài），意思是自己携带。"}, "sentence_index": null, "correct_answer": "自在"}, "level_3": {"options": [{"text": "自在", "is_correct": true, "explanation": "自在：“我过得很自在”表示过得心里舒服、不拘束，符合周末在家放松的语境。"}, {"text": "拘束", "is_correct": false, "explanation": "语义：拘束指放不开，与周末在家的放松相反。"}, {"text": "严厉", "is_correct": false, "explanation": "搭配：“严厉”多用于人的态度或规定，不说“过得严厉”。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：严肃指郑重、不轻松，与在家休息的状态不符。"}], "explanations": {"自在": "自在：“我过得很自在”表示过得心里舒服、不拘束，符合周末在家放松的语境。", "拘束": "语义：拘束指放不开，与周末在家的放松相反。", "严厉": "搭配：“严厉”多用于人的态度或规定，不说“过得严厉”。", "严肃": "语义：严肃指郑重、不轻松，与在家休息的状态不符。"}, "sentence_index": 0, "correct_answer": "自在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做事很自在，经常出错。", "explanation": "这里应该用〈粗心〉。自在指心里舒服、不拘束，不能形容做事不仔细；“做事粗心”才是这个意思。"}, {"text": "他在台上发言，自在得声音直发抖。", "explanation": "这里应该用〈紧张〉。自在表示心里舒服，与声音发抖的状态相矛盾；形容心里发慌要用〈紧张〉。"}, {"text": "这个问题太难了，我做得很自在。", "explanation": "这里应该用〈吃力〉。自在指心里舒服、不拘束，与“太难”的语境相矛盾；题目难、做得费劲要用〈吃力〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91033, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自在", "is_correct": true, "explanation": "自在：“一点也不自在”表示在陌生人中间心里不舒服，符合语境。"}, {"text": "完整", "is_correct": false, "explanation": "语义：完整指齐全、没有残缺，与人的心理状态无关。"}, {"text": "整齐", "is_correct": false, "explanation": "语义：整齐指排列或外表有条理，不描述人在陌生人中间的感受。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：清脆形容声音，不用来形容人在陌生人中间的心理状态。"}], "explanations": {"自在": "自在：“一点也不自在”表示在陌生人中间心里不舒服，符合语境。", "完整": "语义：完整指齐全、没有残缺，与人的心理状态无关。", "整齐": "语义：整齐指排列或外表有条理，不描述人在陌生人中间的感受。", "清脆": "语义：清脆形容声音，不用来形容人在陌生人中间的心理状态。"}, "sentence_index": 6, "correct_answer": "自在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一看到考卷，就自在地皱起了眉头。", "explanation": "这里应该用〈紧张〉。自在表示心里舒服，与皱眉的焦虑反应相矛盾；心里发慌要用〈紧张〉。"}, {"text": "他一出门就自在地迷了路。", "explanation": "这里应该用〈慌张〉。自在表示心里舒服、不拘束，迷路时的心境要用〈慌张〉。"}, {"text": "他一听到噪音，就自在地捂住了耳朵。", "explanation": "这里应该用〈烦躁〉。自在表示心里舒服，捂耳是因为烦躁，要用〈烦躁〉才符合这种反应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91033, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在家里穿着拖鞋，过地很自在。", "corrected_sentence": "他在家里穿着拖鞋，过得很自在。", "error_description": "“过”后面的补语要用“得”，不能用“地”；“地”用在动词前作状语。错误形式是“过地”，正确形式是“过得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91033, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下班以后，我可以在家里自在得看书。", "corrected_sentence": "下班以后，我可以在家里自在地看书。", "error_description": "“自在”作状语修饰动词“看”时要用“地”，不能用“得”；“得”用在动词或形容词后引出补语。错误是“自在得看书”，正确是“自在地看书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
