INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91035, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心里特别想做一件事，做的时候很有劲。", "primary_collocate": null, "pronunciation": "jī qíng", "ipa": "tɕi˥ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他对工作很有激情。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人做事应该有激情。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲课的时候充满激情。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对唱歌的激情一直没有变。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作了十年，他慢慢失去了激情。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个球队踢球很有激情，大家都喜欢。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了老师的话，同学们学习更有激情了。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找一份能让我有激情的工作。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练了三年画画，激情还是那么高。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到孩子们这么有激情，老师也很高兴。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股激情", "label": "量词"}, {"form": "激情四射", "label": "复合"}], "register": "中性", "sense_fingerprint": "对做某件事的热情和干劲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae0e34c9-59ed-46c9-8c20-e1198d73bf8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91035, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "激情", "is_correct": true, "explanation": "激情 jī qíng：正确答案，指对做某事的热情和干劲。"}, {"text": "机型", "is_correct": false, "explanation": "xíng 与 qíng 声母不同（x 与 q），意思是机器的型号。"}, {"text": "知情", "is_correct": false, "explanation": "zhī（第一声）与 jī（第一声）声母不同（zh 与 j），意思是知道内情。"}, {"text": "机灵", "is_correct": false, "explanation": "líng 与 qíng 声母不同（l 与 q），意思是聪明灵活。"}, {"text": "寄情", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是把感情寄托在某事物上。"}], "explanations": {"激情": "激情 jī qíng：正确答案，指对做某事的热情和干劲。", "机型": "xíng 与 qíng 声母不同（x 与 q），意思是机器的型号。", "知情": "zhī（第一声）与 jī（第一声）声母不同（zh 与 j），意思是知道内情。", "机灵": "líng 与 qíng 声母不同（l 与 q），意思是聪明灵活。", "寄情": "jì（第四声）与 jī（第一声）声调不同，意思是把感情寄托在某事物上。"}, "sentence_index": null, "correct_answer": "激情"}, "level_3": {"options": [{"text": "激情", "is_correct": true, "explanation": "“激情”指对做事的热情和干劲，可以说“对工作很有激情”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，与对工作的态度无关。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“有房子”说拥有房屋，不能说“对工作有房子”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”形容人的体形，不能用于对工作的态度。"}], "explanations": {"激情": "“激情”指对做事的热情和干劲，可以说“对工作很有激情”。", "体重": "语义：“体重”指身体的重量，与对工作的态度无关。", "房子": "搭配：“有房子”说拥有房屋，不能说“对工作有房子”。", "身材": "体貌：“身材”形容人的体形，不能用于对工作的态度。"}, "sentence_index": 0, "correct_answer": "激情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭馆服务员有一根激情，对客人很好。", "explanation": "这里应该用〈股〉。“根”用于细长的东西，不能用来计量“激情”。"}, {"text": "她早就下定激情要去北京工作。", "explanation": "这里应该用〈决心〉。“下定”搭配“决心”，“激情”指做事时的干劲，不能说“下定激情”。"}, {"text": "他心里有一颗激情，很想去做点什么。", "explanation": "这里应该用〈股〉。“激情”计量用“一股”，“颗”用于小而圆的东西，不能用来计量抽象的激情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91035, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "激情", "is_correct": true, "explanation": "激情 jī qíng：正确答案，指对做某事的热情和干劲。"}, {"text": "痴情", "is_correct": false, "explanation": "chī（第一声）与 jī（第一声）声母不同（ch 与 j），意思是对人或事非常专一的感情。"}, {"text": "鸡鸣", "is_correct": false, "explanation": "míng 与 qíng 声母不同（m 与 q），意思是公鸡叫。"}, {"text": "机坪", "is_correct": false, "explanation": "píng 与 qíng 声母不同（p 与 q），意思是机场供飞机停放的场地。"}, {"text": "离情", "is_correct": false, "explanation": "lí（第二声）与 jī（第一声）声母与声调不同，意思是离别时的感情。"}], "explanations": {"激情": "激情 jī qíng：正确答案，指对做某事的热情和干劲。", "痴情": "chī（第一声）与 jī（第一声）声母不同（ch 与 j），意思是对人或事非常专一的感情。", "鸡鸣": "míng 与 qíng 声母不同（m 与 q），意思是公鸡叫。", "机坪": "píng 与 qíng 声母不同（p 与 q），意思是机场供飞机停放的场地。", "离情": "lí（第二声）与 jī（第一声）声母与声调不同，意思是离别时的感情。"}, "sentence_index": null, "correct_answer": "激情"}, "level_3": {"options": [{"text": "激情", "is_correct": true, "explanation": "“激情”指学习的干劲，可以说“学习更有激情了”。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“数量”可以增加或减少，但不能说“学习更有数量了”。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”指劳动报酬，与学习的状态无关。"}, {"text": "距离", "is_correct": false, "explanation": "语义：“距离”指空间或时间的间隔，与学习的干劲不相干。"}], "explanations": {"激情": "“激情”指学习的干劲，可以说“学习更有激情了”。", "数量": "搭配：“数量”可以增加或减少，但不能说“学习更有数量了”。", "工资": "语义：“工资”指劳动报酬，与学习的状态无关。", "距离": "语义：“距离”指空间或时间的间隔，与学习的干劲不相干。"}, "sentence_index": 6, "correct_answer": "激情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的激情一直很稳定，很少发脾气。", "explanation": "这里应该用〈情绪〉。“激情”强调强烈、难以抑制的劲头，不能说“稳定”；平和的心理状态要用“情绪”。"}, {"text": "他对这份工作下了很多激情。", "explanation": "这里应该用〈功夫〉。“下”搭配“功夫”“决心”，不能搭配“激情”。"}, {"text": "他心里有一只激情，很想去做点什么。", "explanation": "这里应该用〈股〉。“只”用于动物或成对器官之一，不能用来计量“激情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91035, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他做事的时候总是有一块激情，大家都很佩服。", "corrected_sentence": "他做事的时候总是有一股激情，大家都很佩服。", "error_description": "“激情”应用量词“股”，不能用“块”。“块”指成块的实物，“一股激情”指干劲，所以把“块”改为“股”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91035, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的同事对新工作有一条激情。", "corrected_sentence": "我的同事对新工作有一股激情。", "error_description": "“激情”应用量词“股”，不能用“条”。“条”用于细长的东西，此处应改为“一股激情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
