INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91036, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "强烈而难以抑制的情感。", "primary_collocate": null, "pronunciation": "jī qíng", "ipa": "tɕi˥ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "爱情的激情过去以后，他们慢慢变成了家人。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着她，心里涌起一股激情。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌里有一种难以控制的激情。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻时的激情让他做了很多冲动的事。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的激情像火一样，怎么也压不住。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他控制不住心里的激情，大声喊了起来。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位诗人把对生活的激情写进了诗里。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，球迷们的激情一直没有消失。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人刚认识时，爱情里充满了激情。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段感情开始得很快，激情也消失得很快。", "target_word": "激情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股激情", "label": "量词"}, {"form": "激情四射", "label": "复合"}], "register": "中性", "sense_fingerprint": "强烈、难以控制的感情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae0e34c9-59ed-46c9-8c20-e1198d73bf8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91036, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "激情", "is_correct": true, "explanation": "激情 jī qíng：正确答案，指强烈、难以抑制的感情。"}, {"text": "机型", "is_correct": false, "explanation": "xíng 与 qíng 声母不同（x 与 q），意思是机器的型号。"}, {"text": "痴情", "is_correct": false, "explanation": "chī（第一声）与 jī（第一声）声母不同（ch 与 j），意思是专一的感情。"}, {"text": "机灵", "is_correct": false, "explanation": "líng 与 qíng 声母不同（l 与 q），意思是聪明灵活。"}, {"text": "离情", "is_correct": false, "explanation": "lí（第二声）与 jī（第一声）声母与声调不同，意思是离别时的感情。"}], "explanations": {"激情": "激情 jī qíng：正确答案，指强烈、难以抑制的感情。", "机型": "xíng 与 qíng 声母不同（x 与 q），意思是机器的型号。", "痴情": "chī（第一声）与 jī（第一声）声母不同（ch 与 j），意思是专一的感情。", "机灵": "líng 与 qíng 声母不同（l 与 q），意思是聪明灵活。", "离情": "lí（第二声）与 jī（第一声）声母与声调不同，意思是离别时的感情。"}, "sentence_index": null, "correct_answer": "激情"}, "level_3": {"options": [{"text": "激情", "is_correct": true, "explanation": "“激情”指强烈、难以抑制的情感，可以指爱情中的激情。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是报酬，与爱情中的感情无关。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体高矮，不能用来指爱情。"}, {"text": "房租", "is_correct": false, "explanation": "搭配：“爱情的房租”不成立，“房租”不能修饰感情。"}], "explanations": {"激情": "“激情”指强烈、难以抑制的情感，可以指爱情中的激情。", "工资": "语义：“工资”是报酬，与爱情中的感情无关。", "身高": "体貌：“身高”指人的身体高矮，不能用来指爱情。", "房租": "搭配：“爱情的房租”不成立，“房租”不能修饰感情。"}, "sentence_index": 0, "correct_answer": "激情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他和老朋友之间有很深的激情，多年都没有变。", "explanation": "这里应该用〈友情〉。“激情”强烈而多指爱情等男女之间的感情，朋友间的深厚情谊要用“友情”。"}, {"text": "听到这个消息，她的心情很激情。", "explanation": "这里应该用〈激动〉。“激情”是名词，不能受“很”修饰作谓语；形容心情要用形容词“激动”。"}, {"text": "他心里有一张激情，压也压不住。", "explanation": "这里应该用〈股〉。“张”用于纸张、桌子等平面的东西，不能用来计量“激情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91036, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "激情", "is_correct": true, "explanation": "激情 jī qíng：正确答案，指强烈、难以抑制的感情。"}, {"text": "知情", "is_correct": false, "explanation": "zhī（第一声）与 jī（第一声）声母不同（zh 与 j），意思是知道内情。"}, {"text": "鸡鸣", "is_correct": false, "explanation": "míng 与 qíng 声母不同（m 与 q），意思是公鸡叫。"}, {"text": "机坪", "is_correct": false, "explanation": "píng 与 qíng 声母不同（p 与 q），意思是机场供飞机停放的场地。"}, {"text": "寄情", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是把感情寄托在某事物上。"}], "explanations": {"激情": "激情 jī qíng：正确答案，指强烈、难以抑制的感情。", "知情": "zhī（第一声）与 jī（第一声）声母不同（zh 与 j），意思是知道内情。", "鸡鸣": "míng 与 qíng 声母不同（m 与 q），意思是公鸡叫。", "机坪": "píng 与 qíng 声母不同（p 与 q），意思是机场供飞机停放的场地。", "寄情": "jì（第四声）与 jī（第一声）声调不同，意思是把感情寄托在某事物上。"}, "sentence_index": null, "correct_answer": "激情"}, "level_3": {"options": [{"text": "激情", "is_correct": true, "explanation": "“激情”指强烈的感情，可以“写进诗里”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指商品的钱数，不能用来表达对生活的感情。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，与对生活的感情无关。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“把房间写进诗里”搭配不通，“房间”不能用来表达感情。"}], "explanations": {"激情": "“激情”指强烈的感情，可以“写进诗里”。", "价格": "语义：“价格”指商品的钱数，不能用来表达对生活的感情。", "体温": "语义：“体温”指身体的温度，与对生活的感情无关。", "房间": "搭配：“把房间写进诗里”搭配不通，“房间”不能用来表达感情。"}, "sentence_index": 6, "correct_answer": "激情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父母对孩子的激情一直很深，从小到大都没变。", "explanation": "这里应该用〈亲情〉。“激情”强烈而多指爱情等感情，父母对孩子的深厚感情要用“亲情”。"}, {"text": "他对这件事下了很多激情，却没有结果。", "explanation": "这里应该用〈功夫〉。“下”搭配“功夫”“决心”，不能搭配“激情”。"}, {"text": "他心里有一座激情，压也压不住。", "explanation": "这里应该用〈股〉。“座”用于山、房屋等大而固定的东西，不能用来计量“激情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在台上唱歌的时候，身上带着一根激情。", "corrected_sentence": "她在台上唱歌的时候，身上带着一股激情。", "error_description": "“激情”应用量词“股”，不能用“根”。“根”用于细长的东西，应改为“一股激情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对这个理想有一颗激情，愿意为它付出一切。", "corrected_sentence": "他对这个理想有一股激情，愿意为它付出一切。", "error_description": "“激情”应用量词“股”，不能用“颗”。“颗”用于小而圆的东西，应改为“一股激情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
