INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91037, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "了不起是说一个人特别好，特别棒。", "primary_collocate": null, "pronunciation": "liǎo bu qǐ", "ipa": "ljɑʊ̯˨˩ pu tɕʰi˨˩", "syllable_count": 3, "sentences": [{"text": "你一个人带大三个孩子，真了不起。", "target_word": "了不起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他救了一个落水的孩子，大家都说他了不起。", "target_word": "了不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的奶奶特别了不起，七十岁还在学英语。", "target_word": "了不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师对学生很好，大家都觉得她了不起。", "target_word": "了不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你每次摔倒都自己爬起来，太了不起了！", "target_word": "了不起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小没有爸爸，自己打工上了大学，真了不起。", "target_word": "了不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小女孩才五岁就会照顾弟弟，真了不起。", "target_word": "了不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个了不起的人，从来不说别人的坏话。", "target_word": "了不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们都很努力，我觉得你们每个人都了不起。", "target_word": "了不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都夸他了不起，他却笑着说这没什么。", "target_word": "了不起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "称赞人品行或表现特别好、特别棒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5a0525c-6c30-4575-ae39-cf48177bb3a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91037, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "了不起", "is_correct": true, "explanation": "正确：“了不起”称赞一个人独自带大孩子的付出，与句意一致。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”与一个人带大三个孩子的付出相矛盾。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”与一个人带大三个孩子的努力相反。"}, {"text": "粗心", "is_correct": false, "explanation": "搭配：“粗心”多指做事疏漏，不用来评价这样的付出。"}], "explanations": {"了不起": "正确：“了不起”称赞一个人独自带大孩子的付出，与句意一致。", "冷淡": "语义：“冷淡”与一个人带大三个孩子的付出相矛盾。", "懒惰": "语义：“懒惰”与一个人带大三个孩子的努力相反。", "粗心": "搭配：“粗心”多指做事疏漏，不用来评价这样的付出。"}, "sentence_index": 0, "correct_answer": "了不起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个人留着长头发，穿着蓝色的外套，很了不起。", "explanation": "这里应该用〈醒目〉。了不起只用来称赞人的品质或成就，不能用来评价外貌穿着。"}, {"text": "他的书包是新买的，颜色很了不起。", "explanation": "这里应该用〈鲜艳〉。了不起不能用来形容物品的颜色。"}, {"text": "他的身高只有一米五，很了不起。", "explanation": "这里应该用〈矮〉。了不起用于称赞人的突出品质或成就，不能用来客观描述身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91037, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "了不起", "is_correct": true, "explanation": "正确：“了不起”称赞五岁孩子照顾弟弟的表现，与句意一致。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：“冷漠”与照顾弟弟所体现的关心相反。"}, {"text": "幼稚", "is_correct": false, "explanation": "语义：“幼稚”形容不成熟，与五岁就会照顾弟弟的表现不符。"}, {"text": "任性", "is_correct": false, "explanation": "搭配：“任性”多形容不听话的表现，不用来评价照顾弟弟的行为。"}], "explanations": {"了不起": "正确：“了不起”称赞五岁孩子照顾弟弟的表现，与句意一致。", "冷漠": "语义：“冷漠”与照顾弟弟所体现的关心相反。", "幼稚": "语义：“幼稚”形容不成熟，与五岁就会照顾弟弟的表现不符。", "任性": "搭配：“任性”多形容不听话的表现，不用来评价照顾弟弟的行为。"}, "sentence_index": 6, "correct_answer": "了不起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那张桌子是木头做的，很了不起。", "explanation": "这里应该用〈结实〉。了不起用于称赞人或突出的表现，不能用来形容桌子的质地。"}, {"text": "他的头发是卷的，很了不起。", "explanation": "这里应该用〈卷〉。了不起不能用来描述头发的形状。"}, {"text": "她的书包里装着两本书，很了不起。", "explanation": "这里应该用〈平常〉。了不起用来称赞突出的表现，不能用来说日常小事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91037, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你能坚持练琴十年，真了不起地。", "corrected_sentence": "你能坚持练琴十年，真了不起。", "error_description": "错误：“地”用于修饰其后的动词，句末单独使用不成立；“了不起”在此作谓语，应直接说“真了不起。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91037, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一个了不起地老师，学生都很爱戴他。", "corrected_sentence": "他是一个了不起的老师，学生都很爱戴他。", "error_description": "错误：修饰名词要用“的”，不能用“地”。正确：“了不起的老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
