INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91038, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容才能、成就或事物非常突出，不平凡。", "primary_collocate": null, "pronunciation": "liǎo bu qǐ", "ipa": "ljɑʊ̯˨˩ pu tɕʰi˨˩", "syllable_count": 3, "sentences": [{"text": "连专家都说这项发现很了不起。", "target_word": "了不起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥用了三年建成，真了不起。", "target_word": "了不起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她十岁就能用三种语言写诗，了不起！", "target_word": "了不起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一项了不起的成就，大家都为他鼓掌。", "target_word": "了不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画真了不起，老师也很吃惊。", "target_word": "了不起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在那么小的村子里办起学校，是很了不起的事。", "target_word": "了不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小公司做出了世界第一的手机，了不起。", "target_word": "了不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人完成了这么大的工程，真让人觉得了不起。", "target_word": "了不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的发明中，有不少都很了不起。", "target_word": "了不起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小城的历史文化真了不起，值得去看看。", "target_word": "了不起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "形容才能、成就、事物突出不平凡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5a0525c-6c30-4575-ae39-cf48177bb3a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91038, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "了不起", "is_correct": true, "explanation": "正确：“了不起”形容发现十分突出，与“连专家都说”的赞许语气相符。"}, {"text": "平庸", "is_correct": false, "explanation": "语义：“平庸”指平常、不出众，与“连专家都说”所表达的赞许相反。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”说价格低，不能用来评价一项发现。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”形容声音大，不能用来形容发现的价值。"}], "explanations": {"了不起": "正确：“了不起”形容发现十分突出，与“连专家都说”的赞许语气相符。", "平庸": "语义：“平庸”指平常、不出众，与“连专家都说”所表达的赞许相反。", "便宜": "搭配：“便宜”说价格低，不能用来评价一项发现。", "吵闹": "语义：“吵闹”形容声音大，不能用来形容发现的价值。"}, "sentence_index": 0, "correct_answer": "了不起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑很了不起，该换了。", "explanation": "这里应该用〈陈旧〉。了不起只用于称赞突出、不平凡的事物，不能用来说东西老旧。"}, {"text": "这次事故很了不起，造成了三个人受伤。", "explanation": "这里应该用〈严重〉。了不起是褒义，不能用来说事故的危害程度。"}, {"text": "这个房间很了不起，到处都是纸。", "explanation": "这里应该用〈脏乱〉。了不起是称赞的词，不能用来形容房间杂乱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91038, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "了不起", "is_correct": true, "explanation": "正确：“了不起”称赞这款手机的成就，与“世界第一”一致。"}, {"text": "落后", "is_correct": false, "explanation": "语义：“落后”与“世界第一”相反，不能用来评价这款手机。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”形容场所或气氛，不用来评价产品。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”指过时，与“世界第一”的说法矛盾。"}], "explanations": {"了不起": "正确：“了不起”称赞这款手机的成就，与“世界第一”一致。", "落后": "语义：“落后”与“世界第一”相反，不能用来评价这款手机。", "冷清": "搭配：“冷清”形容场所或气氛，不用来评价产品。", "陈旧": "语义：“陈旧”指过时，与“世界第一”的说法矛盾。"}, "sentence_index": 6, "correct_answer": "了不起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的水很了不起，鱼都死光了。", "explanation": "这里应该用〈臭〉。了不起是称赞的词，不能用来形容水的恶臭。"}, {"text": "这个厨房很了不起，只能站一个人。", "explanation": "这里应该用〈狭小〉。了不起是褒义，不能用来形容空间窄小。"}, {"text": "他的报告写得很了不起，内容也很空。", "explanation": "这里应该用〈草率〉。了不起用于称赞，不能用来形容做事马虎、内容空洞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一位了不起科学家，大家都尊敬她。", "corrected_sentence": "她是一位了不起的科学家，大家都尊敬她。", "error_description": "错误：“了不起”修饰名词时后面要加“的”，漏掉“的”不成立。正确：“了不起的科学家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一个了不起地运动员，大家都为他骄傲。", "corrected_sentence": "他是一个了不起的运动员，大家都为他骄傲。", "error_description": "错误：修饰名词要用“的”，不能用表示动作方式的“地”。正确：“了不起的运动员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
