INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91039, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "见面是两个人走到一起，看到对方。", "primary_collocate": null, "pronunciation": "jiàn miàn", "ipa": "tɕjɛn˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我明天跟老师见面。", "target_word": "见面", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们在车站见面吧。", "target_word": "见面", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们八点在学校门口见面。", "target_word": "见面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和朋友很久没见面了。", "target_word": "见面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "见面时，他先笑着跟我打招呼。", "target_word": "见面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们第一次见面是在哪里？", "target_word": "见面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天下午我要去机场跟他见面。", "target_word": "见面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们见面后，一起去吃了饭。", "target_word": "见面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们约好周六上午见面。", "target_word": "见面", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她第一次和男朋友的家人见面，有点儿紧张。", "target_word": "见面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "见了面", "label": "体标"}, {"form": "见过面", "label": "体标"}, {"form": "見面", "label": "繁体"}], "register": "中性", "sense_fingerprint": "约好时间地点，两人走到一起相见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b16ac64-fa49-4be4-b4f1-b3825b46d122') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91039, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "见面", "is_correct": true, "explanation": "正确答案。见面指两个人走到一起、彼此相见。"}, {"text": "线面", "is_correct": false, "explanation": "xiàn 与 jiàn 声母不同（x 与 j），声调相同，意思是一种细面条。"}, {"text": "碱面", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，miàn 相同，意思是碱粉。"}, {"text": "减免", "is_correct": false, "explanation": "jiǎn 与 jiàn、miǎn 与 miàn 声调都不同，意思是减少或免除。"}], "explanations": {"见面": "正确答案。见面指两个人走到一起、彼此相见。", "线面": "xiàn 与 jiàn 声母不同（x 与 j），声调相同，意思是一种细面条。", "碱面": "jiǎn（第三声）与 jiàn（第四声）声调不同，miàn 相同，意思是碱粉。", "减免": "jiǎn 与 jiàn、miǎn 与 miàn 声调都不同，意思是减少或免除。"}, "sentence_index": null, "correct_answer": "见面"}, "level_3": {"options": [{"text": "见面", "is_correct": true, "explanation": "正确答案。“跟老师见面”是常见搭配，符合语境。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：“下雨”是天气现象，不能说“跟老师下雨”。"}, {"text": "生病", "is_correct": false, "explanation": "搭配：生病不是两人共同的约定行为，不能说“明天跟老师生病”。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“跟老师”后不能接“洗澡”，句子不通。"}], "explanations": {"见面": "正确答案。“跟老师见面”是常见搭配，符合语境。", "下雨": "搭配：“下雨”是天气现象，不能说“跟老师下雨”。", "生病": "搭配：生病不是两人共同的约定行为，不能说“明天跟老师生病”。", "洗澡": "搭配：“跟老师”后不能接“洗澡”，句子不通。"}, "sentence_index": 0, "correct_answer": "见面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们通过电话见面，聊了很久。", "explanation": "这里应该用〈通话〉。见面要求双方当面相见，电话里只能听到声音，不能说通过电话见面。"}, {"text": "我和他通过信件见面，已经好几年了。", "explanation": "这里应该用〈通信〉。信件只能书面往来，见面必须当面相见，不能说通过信件见面。"}, {"text": "他们通过短信见面，约定了周末一起吃饭。", "explanation": "这里应该用〈发消息〉。短信只传递文字，见面需要双方当面相见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91039, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "见面", "is_correct": true, "explanation": "正确答案。见面指两个人走到一起、彼此相见。"}, {"text": "前面", "is_correct": false, "explanation": "qián 与 jiàn 声母不同（q 与 j），声调也不同，意思是位于前方的部分。"}, {"text": "煎面", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）只差声调，miàn 相同，意思是煎过的面条。"}, {"text": "碱面", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）只差声调，miàn 相同，意思是碱粉。"}], "explanations": {"见面": "正确答案。见面指两个人走到一起、彼此相见。", "前面": "qián 与 jiàn 声母不同（q 与 j），声调也不同，意思是位于前方的部分。", "煎面": "jiān（第一声）与 jiàn（第四声）只差声调，miàn 相同，意思是煎过的面条。", "碱面": "jiǎn（第三声）与 jiàn（第四声）只差声调，miàn 相同，意思是碱粉。"}, "sentence_index": null, "correct_answer": "见面"}, "level_3": {"options": [{"text": "见面", "is_correct": true, "explanation": "正确答案。“跟他见面”是常见搭配，符合去机场的语境。"}, {"text": "考试", "is_correct": false, "explanation": "语义：去机场不能跟他考试，与语境不符。"}, {"text": "上课", "is_correct": false, "explanation": "语义：在机场不能跟他上课，与语境不符。"}, {"text": "吃药", "is_correct": false, "explanation": "搭配：“跟他”后接“吃药”不通顺，且与机场的场景不符。"}], "explanations": {"见面": "正确答案。“跟他见面”是常见搭配，符合去机场的语境。", "考试": "语义：去机场不能跟他考试，与语境不符。", "上课": "语义：在机场不能跟他上课，与语境不符。", "吃药": "搭配：“跟他”后接“吃药”不通顺，且与机场的场景不符。"}, "sentence_index": 6, "correct_answer": "见面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电视跟我见面了。", "explanation": "这里应该用〈人〉作主语。见面只用于人与人之间，电视不能与我见面。"}, {"text": "这把椅子跟我见面了。", "explanation": "这里应该用〈人〉作主语。见面只用于人与人之间，椅子不能与我见面。"}, {"text": "这张桌子跟我见面了。", "explanation": "这里应该用〈人〉作主语。见面只用于人与人之间，桌子不能与我见面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91039, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下周对同学见面。", "corrected_sentence": "我下周跟同学见面。", "error_description": "介词误用：见面的对象要用“跟”引出，“对”不能引出见面的对象，应写作“跟同学见面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91039, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天见了面吧。", "corrected_sentence": "我们明天见面吧。", "error_description": "体标错误：表示将来的建议不能用“了”。“见了面”表示已经完成，应说“见面吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
