INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91040, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "彼此相见。", "primary_collocate": null, "pronunciation": "jiàn miàn", "ipa": "tɕjɛn˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "老朋友多年后见面，高兴极了。", "target_word": "见面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们两个人一见面就说个不停。", "target_word": "见面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好久不见，今天终于见面了。", "target_word": "见面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们昨天刚见面，不用再介绍了。", "target_word": "见面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在网上聊了很久，还没见面。", "target_word": "见面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两家人在饭店见面，气氛很好。", "target_word": "见面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们见面时，互相握了握手。", "target_word": "见面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父亲和儿子十年没见面了。", "target_word": "见面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两位队长见面后，先互相问好。", "target_word": "见面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们是在同学聚会上第一次见面。", "target_word": "见面", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "见了面", "label": "体标"}, {"form": "见过面", "label": "体标"}, {"form": "見面", "label": "繁体"}], "register": "中性", "sense_fingerprint": "双方彼此相见，常指久别重逢或第一次相见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b16ac64-fa49-4be4-b4f1-b3825b46d122') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91040, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "见面", "is_correct": true, "explanation": "正确答案。见面指彼此相见。"}, {"text": "线面", "is_correct": false, "explanation": "xiàn 与 jiàn 声母不同（x 与 j），声调相同，意思是一种细面条。"}, {"text": "碱面", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，miàn 相同，意思是碱粉。"}, {"text": "减免", "is_correct": false, "explanation": "jiǎn 与 jiàn、miǎn 与 miàn 声调都不同，意思是减少或免除。"}], "explanations": {"见面": "正确答案。见面指彼此相见。", "线面": "xiàn 与 jiàn 声母不同（x 与 j），声调相同，意思是一种细面条。", "碱面": "jiǎn（第三声）与 jiàn（第四声）声调不同，miàn 相同，意思是碱粉。", "减免": "jiǎn 与 jiàn、miǎn 与 miàn 声调都不同，意思是减少或免除。"}, "sentence_index": null, "correct_answer": "见面"}, "level_3": {"options": [{"text": "见面", "is_correct": true, "explanation": "正确答案。“多年后见面”表示久别重逢，符合语境。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：吵架与“高兴极了”的情绪矛盾，与重逢的语境不符。"}, {"text": "送别", "is_correct": false, "explanation": "语义：送别指离开时的告别，与“多年后”的重逢不合。"}, {"text": "失联", "is_correct": false, "explanation": "语义：失联表示失去联系，与“多年后”和“高兴极了”的语境相悖。"}], "explanations": {"见面": "正确答案。“多年后见面”表示久别重逢，符合语境。", "吵架": "语义：吵架与“高兴极了”的情绪矛盾，与重逢的语境不符。", "送别": "语义：送别指离开时的告别，与“多年后”的重逢不合。", "失联": "语义：失联表示失去联系，与“多年后”和“高兴极了”的语境相悖。"}, "sentence_index": 0, "correct_answer": "见面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们通过邮件见面，交换了很多资料。", "explanation": "这里应该用〈通信〉。邮件只能传递文字和文件，见面要求双方当面相见。"}, {"text": "我和老同学通过电话见面，聊到深夜。", "explanation": "这里应该用〈通话〉。电话里只能听到声音，见面要求双方当面相见。"}, {"text": "他们通过书信见面，互相寄了很多照片。", "explanation": "这里应该用〈通信〉。书信只能书面往来，见面要求双方当面相见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91040, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "见面", "is_correct": true, "explanation": "正确答案。见面指彼此相见。"}, {"text": "前面", "is_correct": false, "explanation": "qián 与 jiàn 声母不同（q 与 j），声调也不同，意思是位于前方的部分。"}, {"text": "煎面", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）只差声调，miàn 相同，意思是煎过的面条。"}, {"text": "碱面", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）只差声调，miàn 相同，意思是碱粉。"}], "explanations": {"见面": "正确答案。见面指彼此相见。", "前面": "qián 与 jiàn 声母不同（q 与 j），声调也不同，意思是位于前方的部分。", "煎面": "jiān（第一声）与 jiàn（第四声）只差声调，miàn 相同，意思是煎过的面条。", "碱面": "jiǎn（第三声）与 jiàn（第四声）只差声调，miàn 相同，意思是碱粉。"}, "sentence_index": null, "correct_answer": "见面"}, "level_3": {"options": [{"text": "见面", "is_correct": true, "explanation": "正确答案。“他们见面时”指两人相见的时候，符合语境。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病时不会互相握手，与语境不符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉时不会互相握手，句子不通。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨与互相握手没有关系，句子不通。"}], "explanations": {"见面": "正确答案。“他们见面时”指两人相见的时候，符合语境。", "生病": "语义：生病时不会互相握手，与语境不符。", "睡觉": "语义：睡觉时不会互相握手，句子不通。", "下雨": "语义：下雨与互相握手没有关系，句子不通。"}, "sentence_index": 6, "correct_answer": "见面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电视跟我见面了。", "explanation": "这里应该用〈人〉作主语。见面只用于人与人之间，电视不能与我见面。"}, {"text": "这把椅子跟我见面了。", "explanation": "这里应该用〈人〉作主语。见面只用于人与人之间，椅子不能与我见面。"}, {"text": "这张桌子跟我见面了。", "explanation": "这里应该用〈人〉作主语。见面只用于人与人之间，桌子不能与我见面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们昨天终于对老朋友见面了。", "corrected_sentence": "他们昨天终于跟老朋友见面了。", "error_description": "介词误用：见面的对象要用“跟”引出，“对”不能引出见面的对象，应写作“跟老朋友见面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父亲和儿子下个月就要见了面了。", "corrected_sentence": "父亲和儿子下个月就要见面了。", "error_description": "体标错误：“就要……了”表示即将发生，不能与“见了面”搭配，应说“就要见面了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91041, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有力", "is_correct": true, "explanation": "有力：与“无力”相反，指有力气，与“腿无力”形成对比。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：指光线充足，与“无力”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明：指头脑灵活，与“无力”没有反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "宽敞：指空间大，与“无力”没有反义关系。"}], "correct_answer": "有力", "explanations": {"有力": "有力：与“无力”相反，指有力气，与“腿无力”形成对比。", "明亮": "明亮：指光线充足，与“无力”没有反义关系。", "聪明": "聪明：指头脑灵活，与“无力”没有反义关系。", "宽敞": "宽敞：指空间大，与“无力”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91041, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有力", "is_correct": true, "explanation": "有力：与“无力”相反，指有力气，与语境中的“无力”形成对比。"}, {"text": "干净", "is_correct": false, "explanation": "干净：指没有污垢，与“无力”没有反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "便宜：指价钱低，与“无力”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静：指没有声音或不吵闹，与“无力”没有反义关系。"}], "correct_answer": "有力", "explanations": {"有力": "有力：与“无力”相反，指有力气，与语境中的“无力”形成对比。", "干净": "干净：指没有污垢，与“无力”没有反义关系。", "便宜": "便宜：指价钱低，与“无力”没有反义关系。", "安静": "安静：指没有声音或不吵闹，与“无力”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91041, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "身体没有劲，什么也做不动。", "primary_collocate": null, "pronunciation": "wú lì", "ipa": "u˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "他发烧了，全身无力。", "target_word": "无力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我饿了一天，手脚都无力。", "target_word": "无力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病了以后，她全身很无力。", "target_word": "无力", "complexity_tier": "T3", "furigana": "bìng le yǐ hòu tā quán shēn hěn wú lì", "sentence_source": "generated"}, {"text": "跑完十公里，我的腿无力，连楼也上不去。", "target_word": "无力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他无力地坐在椅子上。", "target_word": "无力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上没吃饭，我觉得头晕，身上也无力。", "target_word": "无力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他感冒好几天了，现在还是无力。", "target_word": "无力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她累得双手无力，拿不住杯子。", "target_word": "无力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问我是不是经常觉得无力。", "target_word": "无力", "complexity_tier": "T3", "furigana": "yī shēng wèn wǒ shì bu shì jīng cháng jué de wú lì", "sentence_source": "generated"}, {"text": "天太热了，大家都觉得无力，不想动。", "target_word": "无力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无力地", "label": "状语形式"}, {"form": "无力感", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体虚弱、没有力气，做不了事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4236ccb-40e1-4dd6-9f6f-04c3557493d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91041, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无力", "is_correct": true, "explanation": "无力（wúlì）：身体没有力气，什么也做不动。这里是正确答案。"}, {"text": "武力", "is_correct": false, "explanation": "武力（wǔlì）第一音节为第三声，与无力的第二声不同，意思是武器或军事力量。"}, {"text": "物理", "is_correct": false, "explanation": "物理（wùlǐ）两个音节声调都与无力不同，意思是物理学。"}, {"text": "无礼", "is_correct": false, "explanation": "无礼（wúlǐ）第二音节为第三声，与无力的第四声不同，意思是不礼貌。"}, {"text": "物力", "is_correct": false, "explanation": "物力（wùlì）第一音节为第四声，与无力的第二声不同，意思是物质资源。"}], "explanations": {"无力": "无力（wúlì）：身体没有力气，什么也做不动。这里是正确答案。", "武力": "武力（wǔlì）第一音节为第三声，与无力的第二声不同，意思是武器或军事力量。", "物理": "物理（wùlǐ）两个音节声调都与无力不同，意思是物理学。", "无礼": "无礼（wúlǐ）第二音节为第三声，与无力的第四声不同，意思是不礼貌。", "物力": "物力（wùlì）第一音节为第四声，与无力的第二声不同，意思是物质资源。"}, "sentence_index": null, "correct_answer": "无力"}, "level_3": {"options": [{"text": "无力", "is_correct": true, "explanation": "符合语境：发烧后身体没有力气，正是无力的用法。"}, {"text": "健康", "is_correct": false, "explanation": "语义：发烧时身体并不健康，“健康”与“发烧”矛盾。"}, {"text": "灵活", "is_correct": false, "explanation": "语义：“全身灵活”说明身体轻便，与“发烧”不符。"}, {"text": "精神", "is_correct": false, "explanation": "语义：“精神”指精力充沛，与“发烧”矛盾。"}], "explanations": {"无力": "符合语境：发烧后身体没有力气，正是无力的用法。", "健康": "语义：发烧时身体并不健康，“健康”与“发烧”矛盾。", "灵活": "语义：“全身灵活”说明身体轻便，与“发烧”不符。", "精神": "语义：“精神”指精力充沛，与“发烧”矛盾。"}, "sentence_index": 0, "correct_answer": "无力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的拳头很无力，一下就打碎了石板。", "explanation": "这里应该用〈有力〉。无力指身体没有劲，与一下就打碎石板矛盾，形容力气大要用有力。"}, {"text": "他性格无力，遇事总不敢说话。", "explanation": "这里应该用〈软弱〉。无力形容身体没有劲，形容性格要用软弱。"}, {"text": "他的脚步很无力，一下子就冲到了终点。", "explanation": "这里应该用〈有力〉。无力指身体没有劲，与一下子冲到终点矛盾，形容脚步有劲要用有力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91041, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无力", "is_correct": true, "explanation": "符合语境：感冒好几天后仍然没有力气，正是无力的用法。"}, {"text": "有劲", "is_correct": false, "explanation": "语义：“有劲”说明有力气，与“感冒好几天”及“还是”的语气矛盾。"}, {"text": "健壮", "is_correct": false, "explanation": "语义：“健壮”形容身体强壮，与“感冒好几天”矛盾。"}, {"text": "轻快", "is_correct": false, "explanation": "语义：“轻快”指身体灵便舒畅，与“感冒好几天”及“还是”矛盾。"}], "explanations": {"无力": "符合语境：感冒好几天后仍然没有力气，正是无力的用法。", "有劲": "语义：“有劲”说明有力气，与“感冒好几天”及“还是”的语气矛盾。", "健壮": "语义：“健壮”形容身体强壮，与“感冒好几天”矛盾。", "轻快": "语义：“轻快”指身体灵便舒畅，与“感冒好几天”及“还是”矛盾。"}, "sentence_index": 6, "correct_answer": "无力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子很无力，他一坐上去就坏了。", "explanation": "这里应该用〈结实〉。无力只形容人的身体没有劲，椅子坚固与否要用“结实”或“不结实”。"}, {"text": "我的手机很无力，一天要充三次电。", "explanation": "这里应该用〈耗电快〉。无力只形容人的身体没有劲，手机电量消耗快要说“耗电快”。"}, {"text": "这件事已经无力了，只能放弃。", "explanation": "这里应该用〈无望〉。无力只形容人的身体没有劲，事情没有希望时要用无望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
