INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91042, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "缺乏能力或条件，做不到某事。", "primary_collocate": null, "pronunciation": "wú lì", "ipa": "u˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "他没有工作，无力养活家人。", "target_word": "无力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司没钱，无力给大家发工资。", "target_word": "无力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我无力改变这件事。", "target_word": "无力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店无力和大公司竞争。", "target_word": "无力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她家很穷，无力送孩子去上学。", "target_word": "无力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对这么大的问题，我们感到很无力。", "target_word": "无力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想帮朋友，可是无力帮忙。", "target_word": "无力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人无力还债，只好卖掉房子。", "target_word": "无力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我现在无力买房子。", "target_word": "无力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，无力再工作。", "target_word": "无力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无力地", "label": "状语形式"}, {"form": "无力感", "label": "复合"}], "register": "中性", "sense_fingerprint": "缺乏能力或条件，做不到某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4236ccb-40e1-4dd6-9f6f-04c3557493d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91042, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无力", "is_correct": true, "explanation": "无力（wúlì）：缺乏能力或条件，做不到某事。这里是正确答案。"}, {"text": "武力", "is_correct": false, "explanation": "武力（wǔlì）第一音节为第三声，与无力的第二声不同，意思是武器或军事力量。"}, {"text": "物理", "is_correct": false, "explanation": "物理（wùlǐ）两个音节声调都与无力不同，意思是物理学。"}, {"text": "无理", "is_correct": false, "explanation": "无理（wúlǐ）第二音节为第三声，与无力的第四声不同，意思是没有道理。"}, {"text": "物力", "is_correct": false, "explanation": "物力（wùlì）第一音节为第四声，与无力的第二声不同，意思是物质资源。"}], "explanations": {"无力": "无力（wúlì）：缺乏能力或条件，做不到某事。这里是正确答案。", "武力": "武力（wǔlì）第一音节为第三声，与无力的第二声不同，意思是武器或军事力量。", "物理": "物理（wùlǐ）两个音节声调都与无力不同，意思是物理学。", "无理": "无理（wúlǐ）第二音节为第三声，与无力的第四声不同，意思是没有道理。", "物力": "物力（wùlì）第一音节为第四声，与无力的第二声不同，意思是物质资源。"}, "sentence_index": null, "correct_answer": "无力"}, "level_3": {"options": [{"text": "无力", "is_correct": true, "explanation": "符合语境：他没有工作，缺乏能力养活家人，正是无力的用法。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：没有工作的人难以“轻松”养活家人，与语境矛盾。"}, {"text": "富裕", "is_correct": false, "explanation": "搭配：“富裕”形容经济状况，不能直接修饰“养活家人”这样的动作。"}, {"text": "随意", "is_correct": false, "explanation": "语义：“随意”指随便、不拘束，与“没有工作”的困境不符。"}], "explanations": {"无力": "符合语境：他没有工作，缺乏能力养活家人，正是无力的用法。", "轻松": "语义：没有工作的人难以“轻松”养活家人，与语境矛盾。", "富裕": "搭配：“富裕”形容经济状况，不能直接修饰“养活家人”这样的动作。", "随意": "语义：“随意”指随便、不拘束，与“没有工作”的困境不符。"}, "sentence_index": 0, "correct_answer": "无力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我无力参加比赛，因为我根本不想去。", "explanation": "这里应该用〈不想〉。无力指力量或能力不足，因为不愿去而不参加要用不想。"}, {"text": "我的存款很多，无力买一辆车。", "explanation": "这里应该用〈能够〉。无力指缺乏能力或条件，存款充足时买车并不缺乏条件，应说能够买。"}, {"text": "他对老板的态度很无力。", "explanation": "这里应该用〈软弱〉。无力指力量或能力不足，形容态度要用软弱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91042, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无力", "is_correct": true, "explanation": "符合语境：他想帮朋友，但缺乏能力，正是无力的用法。"}, {"text": "热心", "is_correct": false, "explanation": "语义：“热心”表示愿意帮忙，与“可是”后面的转折不合。"}, {"text": "无奈", "is_correct": false, "explanation": "搭配：“无奈”多表示没有办法的心情，不直接修饰“帮忙”。"}, {"text": "积极", "is_correct": false, "explanation": "语义：“积极”表示主动努力，与“可是”后面的转折不合。"}], "explanations": {"无力": "符合语境：他想帮朋友，但缺乏能力，正是无力的用法。", "热心": "语义：“热心”表示愿意帮忙，与“可是”后面的转折不合。", "无奈": "搭配：“无奈”多表示没有办法的心情，不直接修饰“帮忙”。", "积极": "语义：“积极”表示主动努力，与“可是”后面的转折不合。"}, "sentence_index": 6, "correct_answer": "无力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很聪明，学什么都很快，却总说自己无力学习。", "explanation": "这里应该用〈不想学〉。无力指缺乏能力，与学什么都很快矛盾，因为不愿意而不学，应说不想学。"}, {"text": "他刚中了大奖，钱多得花不完，却无力买一部手机。", "explanation": "这里应该用〈能够〉。无力指缺乏能力或条件，与钱多得花不完矛盾，应说能够买。"}, {"text": "这个问题很简单，我们却无力解决它，只能在一旁看着。", "explanation": "这里应该用〈能够〉。无力指缺乏能力，与问题很简单矛盾，应说能够解决。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他无力的接受了这个结果。", "corrected_sentence": "他无力地接受了这个结果。", "error_description": "助词错误：修饰动词的状语要用“地”，不能用“的”。应说“无力地接受”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
