INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91043, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人设是给一个人物定好的样子和性格。", "primary_collocate": null, "pronunciation": "rén shè", "ipa": "ʐən˧˥ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "写故事以前，先想好主角的人设。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人设很简单：聪明，又爱笑。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家把人设画在纸上，给大家看。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要给小说里的人物定一个人设。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹喜欢这个小熊的人设，又可爱又勇敢。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们为自己的角色写人设。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人设里，他是一个爱吃的胖厨师。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她按照人设演了一个冷冷的老师。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人设不清楚，故事就不好看。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人设定好了，他们才开始画画。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个人设", "label": "量词"}, {"form": "人设崩塌", "label": "复合"}, {"form": "人設", "label": "繁体"}], "register": "口语", "sense_fingerprint": "给故事或动画人物定好的样子和性格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec25974-71fd-4a3e-aa7f-4714ae3f80b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91043, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人设", "is_correct": true, "explanation": "正确。人设指给故事或动画人物定好的样子和性格。"}, {"text": "人士", "is_correct": false, "explanation": "rén shì 与 rén shè 的韵母不同（shì 与 shè），意思是有一定身份的人。"}, {"text": "陈设", "is_correct": false, "explanation": "chén shè 与 rén shè 的声母不同（ch 与 r），意思是摆放陈列的物品。"}, {"text": "人数", "is_correct": false, "explanation": "rén shù 与 rén shè 的韵母不同（shù 与 shè），意思是人的数目。"}], "explanations": {"人设": "正确。人设指给故事或动画人物定好的样子和性格。", "人士": "rén shì 与 rén shè 的韵母不同（shì 与 shè），意思是有一定身份的人。", "陈设": "chén shè 与 rén shè 的声母不同（ch 与 r），意思是摆放陈列的物品。", "人数": "rén shù 与 rén shè 的韵母不同（shù 与 shè），意思是人的数目。"}, "sentence_index": null, "correct_answer": "人设"}, "level_3": {"options": [{"text": "人设", "is_correct": true, "explanation": "正确。“写故事以前，先想好主角的人设”指为主角定好性格和样子。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是可以事先为人物设定的特征，「主角的天气」说不通。"}, {"text": "薪水", "is_correct": false, "explanation": "语义：薪水是工作报酬，和故事里主角的设定无关。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不是人物的设定，「主角的汽油」说不通。"}], "explanations": {"人设": "正确。“写故事以前，先想好主角的人设”指为主角定好性格和样子。", "天气": "语义：天气是自然现象，不是可以事先为人物设定的特征，「主角的天气」说不通。", "薪水": "语义：薪水是工作报酬，和故事里主角的设定无关。", "汽油": "语义：汽油是燃料，不是人物的设定，「主角的汽油」说不通。"}, "sentence_index": 0, "correct_answer": "人设"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥的人设很漂亮。", "explanation": "这里应该用〈设计〉。人设指给人物定的样子和性格，不用来说桥的设计。"}, {"text": "这台手机的人设是三千块。", "explanation": "这里应该用〈价格〉。人设指给人物定的样子和性格，不用来说手机的价钱。"}, {"text": "我们的人设是下午三点开会。", "explanation": "这里应该用〈时间〉。人设指给人物定的样子和性格，不用来说开会的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.