INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91043, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人设", "is_correct": true, "explanation": "正确。“这个人设里，他是一个爱吃的胖厨师”指故事中设定的角色形象。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水是书写用的液体，“这个墨水里”不能指一个角色的设定。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，“这个数学里，他是一个爱吃的胖厨师”说不通。"}, {"text": "发音", "is_correct": false, "explanation": "配价：「里」前面的名词要能作为一个范围，发音不能作为范围。"}], "explanations": {"人设": "正确。“这个人设里，他是一个爱吃的胖厨师”指故事中设定的角色形象。", "墨水": "语义：墨水是书写用的液体，“这个墨水里”不能指一个角色的设定。", "数学": "语义：数学是学科，“这个数学里，他是一个爱吃的胖厨师”说不通。", "发音": "配价：「里」前面的名词要能作为一个范围，发音不能作为范围。"}, "sentence_index": 6, "correct_answer": "人设"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个电脑的人设很快。", "explanation": "这里应该用〈速度〉。人设指给人物定的样子和性格，不用来说电脑运行的快慢。"}, {"text": "会议的人设在三楼会议室。", "explanation": "这里应该用〈地点〉。人设指给人物定的样子和性格，不用来说会议的地点。"}, {"text": "我家的人设离学校很远。", "explanation": "这里应该用〈距离〉。人设指给人物定的样子和性格，不用来说家离学校的远近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91043, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "写故事以前，要先把主角的人设好定。", "corrected_sentence": "写故事以前，要先把主角的人设定好。", "error_description": "补语位置错误：「定好」是结果补语，不能倒过来说「好定」，应为「把人设定好」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91043, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们给这个角色定了一张人设。", "corrected_sentence": "我们给这个角色定了一个人设。", "error_description": "量词错误：「人设」应用量词「个」，「张」用于纸张、桌子等平面的东西，应说「定了一个人设」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
