INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91044, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指为人物（多为艺人或虚构角色）设定的性格、形象和特点。", "primary_collocate": null, "pronunciation": "rén shè", "ipa": "ʐən˧˥ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这位歌手的人设是温柔善良。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的人设一直是爱学习的好学生。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者给这个角色定了一个有趣的人设。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为了保持人设，从来不在网上发脾气。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员的真实性格和人设不一样。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏角色的人设很受欢迎。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司为新歌手想好了阳光男孩的人设。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的人设突然变了，粉丝都很吃惊。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部动画里每个人物都有清楚的人设。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观众说这个明星的人设太完美了。", "target_word": "人设", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个人设", "label": "量词"}, {"form": "人设崩塌", "label": "复合"}, {"form": "人設", "label": "繁体"}], "register": "口语", "sense_fingerprint": "艺人或虚构角色被设定出来的性格与形象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec25974-71fd-4a3e-aa7f-4714ae3f80b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91044, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人设", "is_correct": true, "explanation": "正确。人设指为人物（多为艺人或角色）设定的性格和形象。"}, {"text": "人数", "is_correct": false, "explanation": "rén shù 与 rén shè 的韵母不同（shù 与 shè），意思是人的数目，不是人物设定。"}, {"text": "人事", "is_correct": false, "explanation": "rén shì 与 rén shè 的韵母不同（shì 与 shè），意思是人事安排或人员事务。"}, {"text": "陈设", "is_correct": false, "explanation": "chén shè 与 rén shè 的声母不同（ch 与 r），意思是摆放陈列的物品。"}], "explanations": {"人设": "正确。人设指为人物（多为艺人或角色）设定的性格和形象。", "人数": "rén shù 与 rén shè 的韵母不同（shù 与 shè），意思是人的数目，不是人物设定。", "人事": "rén shì 与 rén shè 的韵母不同（shì 与 shè），意思是人事安排或人员事务。", "陈设": "chén shè 与 rén shè 的声母不同（ch 与 r），意思是摆放陈列的物品。"}, "sentence_index": null, "correct_answer": "人设"}, "level_3": {"options": [{"text": "人设", "is_correct": true, "explanation": "正确。“这位歌手的人设是温柔善良”指歌手被设定的性格形象。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高说的是个子的高矮，不能说是温柔善良。"}, {"text": "嗓门", "is_correct": false, "explanation": "搭配：嗓门只说声音的大小，“嗓门是温柔善良”搭配不当。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是岁数，不是性格，不能和“温柔善良”构成描述。"}], "explanations": {"人设": "正确。“这位歌手的人设是温柔善良”指歌手被设定的性格形象。", "身高": "体貌：身高说的是个子的高矮，不能说是温柔善良。", "嗓门": "搭配：嗓门只说声音的大小，“嗓门是温柔善良”搭配不当。", "年龄": "语义：年龄是岁数，不是性格，不能和“温柔善良”构成描述。"}, "sentence_index": 0, "correct_answer": "人设"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座大楼的人设很漂亮，很多人来拍照。", "explanation": "这里应该用〈设计〉。人设指为人物设定的性格和形象，不能用来说建筑的设计。"}, {"text": "她的人设天生就很高，比同学高出一头。", "explanation": "这里应该用〈身高〉。人设指为艺人或角色设定的形象，不用来说人的身高。"}, {"text": "这场演出的人设是两百块。", "explanation": "这里应该用〈价格〉。人设指为人物设定的性格和形象，不用来说演出的价钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人设", "is_correct": true, "explanation": "正确。“公司为新歌手想好了阳光男孩的人设”指为歌手设定的形象。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是遮雨的用具，不能作为为歌手设定的形象。"}, {"text": "薪水", "is_correct": false, "explanation": "语义：薪水是工作报酬，与“阳光男孩”的形象设定无关。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水是书写用的液体，与歌手的形象设定无关。"}], "explanations": {"人设": "正确。“公司为新歌手想好了阳光男孩的人设”指为歌手设定的形象。", "雨伞": "语义：雨伞是遮雨的用具，不能作为为歌手设定的形象。", "薪水": "语义：薪水是工作报酬，与“阳光男孩”的形象设定无关。", "墨水": "语义：墨水是书写用的液体，与歌手的形象设定无关。"}, "sentence_index": 6, "correct_answer": "人设"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的人设太完美了。", "explanation": "这里应该用〈款式〉。人设指为人物设定的性格和形象，不用来评价衣服的款式。"}, {"text": "这道题的人设太难了。", "explanation": "这里应该用〈难度〉。人设指为人物设定的性格和形象，不用来说题目的难易。"}, {"text": "他的人设考了九十分。", "explanation": "这里应该用〈成绩〉。人设指为人物设定的性格和形象，不用来说考试分数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一直保持过人设。", "corrected_sentence": "她一直保持着人设。", "error_description": "体标错误：「一直」表示状态持续，应用「着」，说「保持着人设」；「过」表示曾经有过的经历，与「一直」所表示的持续状态不搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个明星有一张完美的人设。", "corrected_sentence": "这个明星有一个完美的人设。", "error_description": "量词错误：「人设」应用量词「个」，「张」用于纸张、桌子等平面的东西，应说「一个完美的人设」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
