INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91045, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "辆是数车的字，一辆车，两辆车。", "primary_collocate": null, "pronunciation": "liàng", "ipa": "ljɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "门口有一辆红色的车。", "target_word": "辆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家有两辆自行车。", "target_word": "辆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "路上有三辆公共汽车。", "target_word": "辆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他昨天买了一辆新车。", "target_word": "辆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "停车场里停着五辆汽车。", "target_word": "辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆黑色的出租车很旧。", "target_word": "辆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想买一辆便宜的摩托车。", "target_word": "辆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一辆救护车从我们身边开过去了。", "target_word": "辆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路口停着一辆警车，旁边站着两个警察。", "target_word": "辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把那辆自行车放在门口了。", "target_word": "辆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "輛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "量词，用来数汽车、自行车等车子，如一辆车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82430042-cc86-4152-a716-ac186622f809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91045, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "辆", "is_correct": true, "explanation": "正确：“辆”（liàng）是数车辆的量词。"}, {"text": "两", "is_correct": false, "explanation": "“两”（liǎng，第三声）与“辆”（liàng，第四声）声调不同，意思是数量“两”。"}, {"text": "凉", "is_correct": false, "explanation": "“凉”（liáng，第二声）与“辆”声调不同，意思是温度低。"}, {"text": "浪", "is_correct": false, "explanation": "“浪”（làng）与“辆”只差韵母中间的 i，意思是波浪。"}, {"text": "粮", "is_correct": false, "explanation": "“粮”（liáng，第二声）与“辆”声调不同，意思是粮食。"}], "explanations": {"辆": "正确：“辆”（liàng）是数车辆的量词。", "两": "“两”（liǎng，第三声）与“辆”（liàng，第四声）声调不同，意思是数量“两”。", "凉": "“凉”（liáng，第二声）与“辆”声调不同，意思是温度低。", "浪": "“浪”（làng）与“辆”只差韵母中间的 i，意思是波浪。", "粮": "“粮”（liáng，第二声）与“辆”声调不同，意思是粮食。"}, "sentence_index": null, "correct_answer": "辆"}, "level_3": {"options": [{"text": "辆", "is_correct": true, "explanation": "“辆”是车的量词，与“一辆红色的车”搭配，正确。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于动物，不能用来数车。"}, {"text": "张", "is_correct": false, "explanation": "语义：“张”用于平面或有张开感的东西，车不属于这一类。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”用于书籍、册子，不能用来数车。"}], "explanations": {"辆": "“辆”是车的量词，与“一辆红色的车”搭配，正确。", "只": "搭配：“只”用于动物，不能用来数车。", "张": "语义：“张”用于平面或有张开感的东西，车不属于这一类。", "本": "搭配：“本”用于书籍、册子，不能用来数车。"}, "sentence_index": 0, "correct_answer": "辆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天买了一辆新电脑。", "explanation": "这里应该用〈台〉。“辆”只用于车，电脑要用“台”。"}, {"text": "班里来了一辆新同学。", "explanation": "这里应该用〈位〉。“辆”只用于车，指人要用“位”或“个”。"}, {"text": "墙上挂着一辆画。", "explanation": "这里应该用〈幅〉。“辆”只用于车，画要用“幅”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329c3694-5d44-4224-a3c5-49edf76ba398') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91045, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "辆", "is_correct": true, "explanation": "正确：“辆”（liàng）是数车辆的量词。"}, {"text": "梁", "is_correct": false, "explanation": "“梁”（liáng，第二声）与“辆”声调不同，意思是房屋的横木。"}, {"text": "良", "is_correct": false, "explanation": "“良”（liáng，第二声）与“辆”声调不同，意思是好。"}, {"text": "两", "is_correct": false, "explanation": "“两”（liǎng，第三声）与“辆”（liàng，第四声）声调不同，意思是数量“两”。"}, {"text": "酿", "is_correct": false, "explanation": "“酿”（niàng）与“辆”只差声母 n 和 l，意思是酿造。"}], "explanations": {"辆": "正确：“辆”（liàng）是数车辆的量词。", "梁": "“梁”（liáng，第二声）与“辆”声调不同，意思是房屋的横木。", "良": "“良”（liáng，第二声）与“辆”声调不同，意思是好。", "两": "“两”（liǎng，第三声）与“辆”（liàng，第四声）声调不同，意思是数量“两”。", "酿": "“酿”（niàng）与“辆”只差声母 n 和 l，意思是酿造。"}, "sentence_index": null, "correct_answer": "辆"}, "level_3": {"options": [{"text": "辆", "is_correct": true, "explanation": "“辆”是车的量词，与“一辆便宜的摩托车”搭配，正确。"}, {"text": "条", "is_correct": false, "explanation": "搭配：“条”用于细长的东西，不用来数摩托车。"}, {"text": "朵", "is_correct": false, "explanation": "搭配：“朵”用于花朵、云彩等，不能用于摩托车。"}, {"text": "把", "is_correct": false, "explanation": "语义：“把”指有柄的物件，摩托车不属于这一类。"}], "explanations": {"辆": "“辆”是车的量词，与“一辆便宜的摩托车”搭配，正确。", "条": "搭配：“条”用于细长的东西，不用来数摩托车。", "朵": "搭配：“朵”用于花朵、云彩等，不能用于摩托车。", "把": "语义：“把”指有柄的物件，摩托车不属于这一类。"}, "sentence_index": 6, "correct_answer": "辆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客厅里放着一辆椅子。", "explanation": "这里应该用〈把〉。“辆”只用于车，椅子要用“把”。"}, {"text": "他昨天收到一辆信。", "explanation": "这里应该用〈封〉。“辆”只用于车，信件要用“封”。"}, {"text": "她买了一辆新鞋。", "explanation": "这里应该用〈双〉。“辆”只用于车，鞋要用“双”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329c3694-5d44-4224-a3c5-49edf76ba398') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91045, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家门口停着二辆车。", "corrected_sentence": "我家门口停着两辆车。", "error_description": "数词“二”不能直接与“辆”搭配，应说“两辆”，不说“二辆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329c3694-5d44-4224-a3c5-49edf76ba398') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91045, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个辆出租车停在路边了。", "corrected_sentence": "那辆出租车停在路边了。", "error_description": "量词重复：“辆”前面不能再加“个”，应说“那辆出租车”，不说“那个辆出租车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329c3694-5d44-4224-a3c5-49edf76ba398') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
