INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91047, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "任事是担起一件事，把它做好。", "primary_collocate": null, "pronunciation": "rèn shì", "ipa": "ɻən˥˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "他是个肯任事的人。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做小组长就要敢任事。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到困难，他从不躲，总是主动任事。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个年轻人很能任事。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板喜欢肯任事的员工。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都不愿任事，工作就做不好。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她任事认真，从不马虎。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想进步，就要多任事。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一向敢任事，所以同学们选了他。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人任事，这件事才能做成。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "任事了", "label": "体标"}, {"form": "任事过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "主动担起责任，把一件事做好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b342a05-3699-4607-9d19-13216e1ae00e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91047, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "认识", "is_correct": false, "explanation": "shi（轻声）与 shì（第四声）声调不同，意思是认识、知道。"}, {"text": "任事", "is_correct": true, "explanation": "正确答案：任事 rèn shì，指主动担起一件事，把它做好。"}, {"text": "人事", "is_correct": false, "explanation": "rén（第二声）与 rèn（第四声）声调不同，意思是人事，指人员的任用、调动等事务。"}, {"text": "人世", "is_correct": false, "explanation": "rén（第二声）与 rèn（第四声）声调不同，意思是人间、世间。"}], "explanations": {"认识": "shi（轻声）与 shì（第四声）声调不同，意思是认识、知道。", "任事": "正确答案：任事 rèn shì，指主动担起一件事，把它做好。", "人事": "rén（第二声）与 rèn（第四声）声调不同，意思是人事，指人员的任用、调动等事务。", "人世": "rén（第二声）与 rèn（第四声）声调不同，意思是人间、世间。"}, "sentence_index": null, "correct_answer": "任事"}, "level_3": {"options": [{"text": "生病", "is_correct": false, "explanation": "语义：“生病”指身体不适，与“肯”所表达的积极态度不相符，句意不通。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：“失眠”指睡不着觉，与“肯担事的人”无关。"}, {"text": "任事", "is_correct": true, "explanation": "正确：“任事”指主动担起事情、把它做好，“肯任事的人”即愿意担责的人。"}, {"text": "喜欢", "is_correct": false, "explanation": "配价：“喜欢”要带宾语，“肯喜欢的人”后面缺少对象。"}], "explanations": {"生病": "语义：“生病”指身体不适，与“肯”所表达的积极态度不相符，句意不通。", "失眠": "语义：“失眠”指睡不着觉，与“肯担事的人”无关。", "任事": "正确：“任事”指主动担起事情、把它做好，“肯任事的人”即愿意担责的人。", "喜欢": "配价：“喜欢”要带宾语，“肯喜欢的人”后面缺少对象。"}, "sentence_index": 0, "correct_answer": "任事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被派到外地任事，一年后才调回来。", "explanation": "这里用的是“担任职务”的意思，不是“主动担起一件事、把它做好”的意思。"}, {"text": "他年轻时在政府任事，后来退休了。", "explanation": "这里用的是“担任职务”的意思，不是“主动担起一件事、把它做好”的意思。"}, {"text": "他在银行任事十年，每天只管喝茶看报。", "explanation": "这里用的是“担任职务”的意思，不是“主动担起一件事、把它做好”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91047, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辞职", "is_correct": false, "explanation": "语义：“辞职”指离开现职，与“认真”描述的做事态度不搭，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“睡觉”不能用“认真”来修饰，不说“睡觉认真”。"}, {"text": "任事", "is_correct": true, "explanation": "正确：“任事”指主动担起事情、把它做好，与“认真”相配，句意是她做事认真。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：“发呆”指呆坐出神，不能用来说明做事认真。"}], "explanations": {"辞职": "语义：“辞职”指离开现职，与“认真”描述的做事态度不搭，句意不通。", "睡觉": "搭配：“睡觉”不能用“认真”来修饰，不说“睡觉认真”。", "任事": "正确：“任事”指主动担起事情、把它做好，与“认真”相配，句意是她做事认真。", "发呆": "语义：“发呆”指呆坐出神，不能用来说明做事认真。"}, "sentence_index": 6, "correct_answer": "任事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在工厂任事三十年，直到退休。", "explanation": "这里用的是“担任职务”的意思，不是“主动担起一件事、把它做好”的意思。"}, {"text": "他刚到公司任事，还不熟悉这里的流程。", "explanation": "这里用的是“担任职务”的意思，不是“主动担起一件事、把它做好”的意思。"}, {"text": "他在公司任事多年，每天都要加班到很晚。", "explanation": "这里用的是“担任职务”的意思，不是“主动担起一件事、把它做好”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91047, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都说他很能没任事，什么事都愿意做。", "corrected_sentence": "大家都说他很能任事，什么事都愿意做。", "error_description": "错误：否定副词“没”不能插在助动词“能”与动词“任事”之间，与“很能”的意思相矛盾。应去掉“没”，说“很能任事”，表示主动担起事情、把它做好。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91047, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "遇到难事，他总是主动任事工作。", "corrected_sentence": "遇到难事，他总是主动任事。", "error_description": "错误：“任事”是不及物动词，本身已含“事”，后面不能再带宾语“工作”。应去掉“工作”，说“主动任事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
