INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91048, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "担任职务；负责处理事务。", "primary_collocate": null, "pronunciation": "rèn shì", "ipa": "ɻən˥˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "他在这家公司任事已经十年了。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她年轻时在政府任事。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张在银行任事，工作很忙。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚到学校任事，还不熟悉这里。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在报社任事三年了。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲一生都在工厂任事。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她愿意去山区学校任事。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾在医院任事两年。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学毕业后，他到市政府任事。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个部门任事的人都很认真。", "target_word": "任事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "任事了", "label": "体标"}, {"form": "任事过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "在某个单位担任职务、负责处理事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b342a05-3699-4607-9d19-13216e1ae00e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91048, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "认识", "is_correct": false, "explanation": "shi（轻声）与 shì（第四声）声调不同，意思是认识、知道。"}, {"text": "任事", "is_correct": true, "explanation": "正确答案：任事 rèn shì，指担任职务、负责处理事务。"}, {"text": "人事", "is_correct": false, "explanation": "rén（第二声）与 rèn（第四声）声调不同，意思是人事，指人员的任用、调动等事务。"}, {"text": "人世", "is_correct": false, "explanation": "rén（第二声）与 rèn（第四声）声调不同，意思是人间、世间。"}], "explanations": {"认识": "shi（轻声）与 shì（第四声）声调不同，意思是认识、知道。", "任事": "正确答案：任事 rèn shì，指担任职务、负责处理事务。", "人事": "rén（第二声）与 rèn（第四声）声调不同，意思是人事，指人员的任用、调动等事务。", "人世": "rén（第二声）与 rèn（第四声）声调不同，意思是人间、世间。"}, "sentence_index": null, "correct_answer": "任事"}, "level_3": {"options": [{"text": "失业", "is_correct": false, "explanation": "语义：“失业”指失去工作，与“在这家公司……已经十年了”的句意矛盾。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”指到学校学习，与“在这家公司”不符。"}, {"text": "任事", "is_correct": true, "explanation": "正确：“任事”指担任职务、负责事务，可以说在公司任职已经十年。"}, {"text": "喜欢", "is_correct": false, "explanation": "配价：“喜欢”要带宾语，“在这家公司喜欢”后面缺少对象。"}], "explanations": {"失业": "语义：“失业”指失去工作，与“在这家公司……已经十年了”的句意矛盾。", "上学": "语义：“上学”指到学校学习，与“在这家公司”不符。", "任事": "正确：“任事”指担任职务、负责事务，可以说在公司任职已经十年。", "喜欢": "配价：“喜欢”要带宾语，“在这家公司喜欢”后面缺少对象。"}, "sentence_index": 0, "correct_answer": "任事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件难题他愿意主动任事，不推给别人。", "explanation": "这里用的是“主动担起一件事、把它做好”的意思，不是“担任职务”的意思。"}, {"text": "大家都不愿干的脏活，他总是主动任事。", "explanation": "这里用的是“主动担起一件事、把它做好”的意思，不是“担任职务”的意思。"}, {"text": "那件棘手的事，只有他肯任事。", "explanation": "这里用的是“主动担起一件事、把它做好”的意思，不是“担任职务”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91048, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出生", "is_correct": false, "explanation": "语义：出生不是人能选择“愿意去”做的事，句意不通。"}, {"text": "任事", "is_correct": true, "explanation": "正确：“任事”指担任职务、负责事务，可以说愿意去山区学校担任职务。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“愿意去山区学校生气”不合情理，句意不通。"}, {"text": "爱护", "is_correct": false, "explanation": "配价：“爱护”要带宾语，“愿意去山区学校爱护”后面缺少对象。"}], "explanations": {"出生": "语义：出生不是人能选择“愿意去”做的事，句意不通。", "任事": "正确：“任事”指担任职务、负责事务，可以说愿意去山区学校担任职务。", "生气": "语义：“愿意去山区学校生气”不合情理，句意不通。", "爱护": "配价：“爱护”要带宾语，“愿意去山区学校爱护”后面缺少对象。"}, "sentence_index": 6, "correct_answer": "任事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "遇到难题他从不推诿，总是主动任事。", "explanation": "这里用的是“主动担起一件事、把它做好”的意思，不是“担任职务”的意思。"}, {"text": "这次项目他一个人主动任事，把它做得很好。", "explanation": "这里用的是“主动担起一件事、把它做好”的意思，不是“担任职务”的意思。"}, {"text": "这份难活，他一个人敢任事，把它做完了。", "explanation": "这里用的是“主动担起一件事、把它做好”的意思，不是“担任职务”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把政府任事多年，很受大家尊敬。", "corrected_sentence": "她在政府任事多年，很受大家尊敬。", "error_description": "错误：“任事”是不及物动词，不能用“把”字处置“政府”。表示地点的“政府”应由“在”引出，应说“在政府任事多年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位医生在医院很任事多年。", "corrected_sentence": "这位医生在医院任事多年。", "error_description": "错误：“任事”是动作动词，不能被程度副词“很”直接修饰，应去掉“很”，说“在医院任事多年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
