INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91053, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "来访是有人到你家或你的地方来看你。", "primary_collocate": null, "pronunciation": "lái fǎng", "ipa": "laɪ̯˧˥ fɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "昨天有一位老朋友来访。", "target_word": "来访", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "欢迎你有空来访。", "target_word": "来访", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末我家有客人来访，我要在家准备饭菜。", "target_word": "来访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的老同学每年都会来访一次。", "target_word": "来访", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有提前打电话就来访，我有点儿吃惊。", "target_word": "来访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说下个星期会有学生家长来访。", "target_word": "来访", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不在的时候，有人来访过，留了一张纸条。", "target_word": "来访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友要来访，妈妈一早就开始打扫房间。", "target_word": "来访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来访前请先给我打个电话。", "target_word": "来访", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天来访的客人带来了一些水果。", "target_word": "来访", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "来访了", "label": "体标"}, {"form": "来访过", "label": "体标"}, {"form": "來訪", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有人到你家或你的地方来看你", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c5d38-188c-4474-8f42-65925038992f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91053, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "来访", "is_correct": true, "explanation": "来访：有人来到你这里看你，与“昨天有一位老朋友”相合。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指人刚来到世上，老朋友不能昨天才出生。"}, {"text": "下雪", "is_correct": false, "explanation": "语义：“下雪”是天气现象，主语不能是“老朋友”。"}, {"text": "便宜", "is_correct": false, "explanation": "语法：“便宜”是形容词，说价格低，不能说“老朋友便宜”。"}], "explanations": {"来访": "来访：有人来到你这里看你，与“昨天有一位老朋友”相合。", "出生": "语义：“出生”指人刚来到世上，老朋友不能昨天才出生。", "下雪": "语义：“下雪”是天气现象，主语不能是“老朋友”。", "便宜": "语法：“便宜”是形容词，说价格低，不能说“老朋友便宜”。"}, "sentence_index": 0, "correct_answer": "来访"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我去朋友家来访，还带了一箱水果。", "explanation": "这里应该用〈做客〉。来访是客人来到主人这里，说话人自己去朋友家作客要用做客。"}, {"text": "下周我去校长办公室来访，商量合作的事。", "explanation": "这里应该用〈拜访〉。来访是客人来到说话人这里，说话人自己去见校长要用拜访。"}, {"text": "暑假我们去工厂来访，看了生产线。", "explanation": "这里应该用〈参观〉。来访指客人专程来拜见某人或某单位，到工厂看生产线要用参观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91053, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来访", "is_correct": true, "explanation": "来访：有人来到你家或你的地方，与“你不在的时候”和“留了一张纸条”相合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”是自身的动作，不能与“留了一张纸条”的访问情境相合。"}, {"text": "便宜", "is_correct": false, "explanation": "语法：“便宜”是形容词，说价格低，不能说“有人便宜过”。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体动作，与“你不在的时候留下纸条”的情境不合。"}], "explanations": {"来访": "来访：有人来到你家或你的地方，与“你不在的时候”和“留了一张纸条”相合。", "睡觉": "语义：“睡觉”是自身的动作，不能与“留了一张纸条”的访问情境相合。", "便宜": "语法：“便宜”是形容词，说价格低，不能说“有人便宜过”。", "咳嗽": "语义：“咳嗽”是身体动作，与“你不在的时候留下纸条”的情境不合。"}, "sentence_index": 6, "correct_answer": "来访"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天在电话里来访，聊了一个小时。", "explanation": "这里应该用〈通话〉。来访要求人亲自到说话人这里，电话交流不能用来访。"}, {"text": "暑假我们一家去北京来访，逛了很多景点。", "explanation": "这里应该用〈游览〉。来访是客人专程来拜见某人或某单位，逛景点要用游览。"}, {"text": "周末我们全家去超市来访。", "explanation": "这里应该用〈光顾〉。来访指客人专程来拜见某人或某单位，去超市购物要用光顾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91053, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的表哥每年春天都会来访一个。", "corrected_sentence": "我的表哥每年春天都会来访一次。", "error_description": "“来访”后的动量补语要用量词“次”，不能用“个”。错误形式是“来访一个”，正确形式是“来访一次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91053, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上午来访着的老师带来了一些资料。", "corrected_sentence": "上午来访的老师带来了一些资料。", "error_description": "“来访”表示一次性的动作，不能加“着”表示持续状态。应去掉“着”，改为“上午来访的老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91056, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "反义：过去指现在以前的时期，与“现今”所指的当前时期相对。"}, {"text": "海洋", "is_correct": false, "explanation": "无关：海洋是地理事物，与时间概念没有反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：桌子是家具，与“现今”没有反义关系。"}, {"text": "早晨", "is_correct": false, "explanation": "无关：早晨指一天中的时段，与“现今”没有反义关系。"}], "correct_answer": "过去", "explanations": {"过去": "反义：过去指现在以前的时期，与“现今”所指的当前时期相对。", "海洋": "无关：海洋是地理事物，与时间概念没有反义关系。", "桌子": "无关：桌子是家具，与“现今”没有反义关系。", "早晨": "无关：早晨指一天中的时段，与“现今”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91056, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "反义：过去指现在以前的时期，与“现今”相对。"}, {"text": "公园", "is_correct": false, "explanation": "无关：公园是场所，与时间概念没有反义关系。"}, {"text": "铅笔", "is_correct": false, "explanation": "无关：铅笔是文具，与“现今”没有反义关系。"}, {"text": "冬夜", "is_correct": false, "explanation": "无关：冬夜是具体的时段，与“现今”没有反义关系。"}], "correct_answer": "过去", "explanations": {"过去": "反义：过去指现在以前的时期，与“现今”相对。", "公园": "无关：公园是场所，与时间概念没有反义关系。", "铅笔": "无关：铅笔是文具，与“现今”没有反义关系。", "冬夜": "无关：冬夜是具体的时段，与“现今”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91056, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "当前这一时期；如今。", "primary_collocate": null, "pronunciation": "xiàn jīn", "ipa": "ɕjɛn˥˩ tɕin˥", "syllable_count": 2, "sentences": [{"text": "古时候路很难走，现今到处都是高速公路。", "target_word": "现今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前人们写信，现今大家发短信。", "target_word": "现今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现今的生活和三十年前完全不同。", "target_word": "现今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现今的学校都有电脑。", "target_word": "现今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现今的医生比以前多多了。", "target_word": "现今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个习惯，现今还有人保留着。", "target_word": "现今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶从古代流传到现今。", "target_word": "现今", "complexity_tier": "T3", "furigana": "zhè zhǒng chá cóng gǔ dài liú chuán dào xiàn jīn.", "sentence_source": "generated"}, {"text": "现今的城市比以前干净了。", "target_word": "现今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前很少人出国，现今出国旅游很平常。", "target_word": "现今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现今社会，找工作要会用电脑。", "target_word": "现今", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "与过去相对的当前时期，如今", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4236ccb-40e1-4dd6-9f6f-04c3557493d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91056, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现今", "is_correct": true, "explanation": "正确：现今指当前时期，与前半句“古时候路很难走”形成对比，符合句意。"}, {"text": "古代", "is_correct": false, "explanation": "语义：古代与“古时候”重复，而且古代没有高速公路，与句意矛盾。"}, {"text": "从前", "is_correct": false, "explanation": "语义：从前也属于过去，同样不会有高速公路，与“现今”的对比被打破。"}, {"text": "童年", "is_correct": false, "explanation": "搭配：“童年”是人生阶段，不能与“到处都是高速公路”这种社会状况搭配。"}], "explanations": {"现今": "正确：现今指当前时期，与前半句“古时候路很难走”形成对比，符合句意。", "古代": "语义：古代与“古时候”重复，而且古代没有高速公路，与句意矛盾。", "从前": "语义：从前也属于过去，同样不会有高速公路，与“现今”的对比被打破。", "童年": "搭配：“童年”是人生阶段，不能与“到处都是高速公路”这种社会状况搭配。"}, "sentence_index": 0, "correct_answer": "现今"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "现今我昨天就把作业交了。", "explanation": "这里不能用〈现今〉。现今指当前时期，不能与“昨天”这样已经过去的具体时间搭配；说昨天的事要删去现今。"}, {"text": "现今他两年后会搬去上海。", "explanation": "这里不能用〈现今〉。现今指当前时期，不能与“两年后”这样的将来时间搭配；说将来的安排要删去现今。"}, {"text": "现今我小时候常常在河里游泳。", "explanation": "这里应该用〈以前〉。现今指当前这一时期，不能与“小时候”这种过去的时段搭配；描述过去的习惯要用以前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91056, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现今", "is_correct": true, "explanation": "正确：现今指当前，与“这种茶从古代流传到”后面的终点相符。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”还没有到来，不能作为从古代“流传到”的终点。"}, {"text": "星期天", "is_correct": false, "explanation": "搭配：“星期天”是具体的某一天，不能作为茶流传的终点。"}, {"text": "夏天", "is_correct": false, "explanation": "搭配：“夏天”是季节，不能与“从古代流传到”这种历史跨度搭配。"}], "explanations": {"现今": "正确：现今指当前，与“这种茶从古代流传到”后面的终点相符。", "明天": "语义：“明天”还没有到来，不能作为从古代“流传到”的终点。", "星期天": "搭配：“星期天”是具体的某一天，不能作为茶流传的终点。", "夏天": "搭配：“夏天”是季节，不能与“从古代流传到”这种历史跨度搭配。"}, "sentence_index": 6, "correct_answer": "现今"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现今他三十年前就去世了。", "explanation": "这里不能用〈现今〉。现今指当前时期，与“三十年前”这种过去的具体时间冲突。"}, {"text": "现今我们明天出发去北京。", "explanation": "这里不能用〈现今〉。现今指当前，与“明天”这种将来的具体时间冲突；说明天的安排要删去现今。"}, {"text": "现今他是在1980年出生的。", "explanation": "这里不能用〈现今〉。现今指当前，与“1980年出生”这样的具体过去时间冲突；说过去的出生要用具体年份或那时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "现今人们出门都带着手机现今。", "corrected_sentence": "现今人们出门都带着手机。", "error_description": "错误：句末多出一个重复的“现今”。正确：“现今”只需出现一次，应写成“现今人们出门都带着手机。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "现今的，很多人都用智能手机。", "corrected_sentence": "现今，很多人都用智能手机。", "error_description": "错误：“现今”与逗号之间多了一个“的”。正确：应写成“现今，很多人都用智能手机。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
