INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91057, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "养是照顾小动物或小孩，给他们吃的喝的，让他们长大。", "primary_collocate": null, "pronunciation": "yǎng", "ipa": "jɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "我家养了一只小狗，每天都要喂它。", "target_word": "养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在家里养猫，每天给猫喂饭。", "target_word": "养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一个人养两个孩子，非常辛苦。", "target_word": "养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你养过乌龟吗？它们吃什么？", "target_word": "养", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家养着一条大黑狗，很听话。", "target_word": "养", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想养一只小兔子，可是妈妈不同意。", "target_word": "养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "养孩子要花很多钱，也很辛苦。", "target_word": "养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多老人喜欢在家养小鸟，每天喂它们。", "target_word": "养", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸妈妈工作很忙，孩子是爷爷养的。", "target_word": "养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们房子太小，不能养狗。", "target_word": "养", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "养了", "label": "体标"}, {"form": "养过", "label": "体标"}, {"form": "养着", "label": "体标"}, {"form": "养育", "label": "复合词"}, {"form": "養", "label": "繁体"}], "register": "中性", "sense_fingerprint": "养：照顾、喂养宠物或孩子，让其长大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c40d4862-37ee-47f3-905b-3a171e8ebee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91057, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "养", "is_correct": true, "explanation": "正确。养 yǎng（第三声）：照顾并喂养小动物或孩子。"}, {"text": "羊", "is_correct": false, "explanation": "羊 yáng（第二声）与 yǎng（第三声）声调不同，意思是羊。"}, {"text": "样", "is_correct": false, "explanation": "样 yàng（第四声）与 yǎng（第三声）声调不同，意思是样子。"}, {"text": "眼", "is_correct": false, "explanation": "眼 yǎn 与 yǎng 的韵母不同（ng 变成 n），意思是眼睛。"}, {"text": "想", "is_correct": false, "explanation": "想 xiǎng 与 yǎng 的声母不同（x 与 y），意思是想念或想法。"}], "explanations": {"养": "正确。养 yǎng（第三声）：照顾并喂养小动物或孩子。", "羊": "羊 yáng（第二声）与 yǎng（第三声）声调不同，意思是羊。", "样": "样 yàng（第四声）与 yǎng（第三声）声调不同，意思是样子。", "眼": "眼 yǎn 与 yǎng 的韵母不同（ng 变成 n），意思是眼睛。", "想": "想 xiǎng 与 yǎng 的声母不同（x 与 y），意思是想念或想法。"}, "sentence_index": null, "correct_answer": "养"}, "level_3": {"options": [{"text": "养", "is_correct": true, "explanation": "正确。“我家养了一只小狗”中的“养”指饲养，与后文“每天都要喂它”相符。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”是出售，卖掉之后就不必“每天都要喂它”，与后文矛盾。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的宾语一般是食物，不能说“煮一只小狗”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，扔掉之后又说“每天都要喂它”，前后矛盾。"}], "explanations": {"养": "正确。“我家养了一只小狗”中的“养”指饲养，与后文“每天都要喂它”相符。", "卖": "语义：“卖”是出售，卖掉之后就不必“每天都要喂它”，与后文矛盾。", "煮": "搭配：“煮”的宾语一般是食物，不能说“煮一只小狗”。", "扔": "语义：“扔”是丢弃，扔掉之后又说“每天都要喂它”，前后矛盾。"}, "sentence_index": 0, "correct_answer": "养"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位护士每天养病人，帮他们量体温。", "explanation": "这里应该用〈照顾〉。养多用于饲养动物或抚育幼儿，照顾病人要用“照顾”。"}, {"text": "这家工厂养了三百张桌子。", "explanation": "这里应该用〈买〉。养指饲养动物或抚育孩子，桌子是物件，要说“买”，不能说“养桌子”。"}, {"text": "这所学校养了很多优秀的学生。", "explanation": "这里应该用〈培养〉。培养用于人才、能力，养多指饲养动物或抚育孩子，不说“养学生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91057, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "养", "is_correct": true, "explanation": "正确。养 yǎng（第三声）：照顾并喂养小动物或孩子。"}, {"text": "阳", "is_correct": false, "explanation": "阳 yáng（第二声）与 yǎng（第三声）声调不同，意思是阳光、太阳。"}, {"text": "响", "is_correct": false, "explanation": "响 xiǎng 与 yǎng 的声母不同（x 与 y），意思是响声。"}, {"text": "掩", "is_correct": false, "explanation": "掩 yǎn 与 yǎng 的韵母不同（ng 变成 n），意思是遮掩。"}, {"text": "享", "is_correct": false, "explanation": "享 xiǎng 与 yǎng 的声母不同（x 与 y），意思是享受。"}], "explanations": {"养": "正确。养 yǎng（第三声）：照顾并喂养小动物或孩子。", "阳": "阳 yáng（第二声）与 yǎng（第三声）声调不同，意思是阳光、太阳。", "响": "响 xiǎng 与 yǎng 的声母不同（x 与 y），意思是响声。", "掩": "掩 yǎn 与 yǎng 的韵母不同（ng 变成 n），意思是遮掩。", "享": "享 xiǎng 与 yǎng 的声母不同（x 与 y），意思是享受。"}, "sentence_index": null, "correct_answer": "养"}, "level_3": {"options": [{"text": "养", "is_correct": true, "explanation": "正确。“养孩子”指抚育孩子，与后文“要花很多钱，也很辛苦”相符。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”是击打，与“要花很多钱，也很辛苦”的抚育含义不符。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”是责备，不是抚育，与“要花很多钱”无关。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不与“孩子”构成抚育的说法，“吃孩子”不能表示“养育孩子”。"}], "explanations": {"养": "正确。“养孩子”指抚育孩子，与后文“要花很多钱，也很辛苦”相符。", "打": "语义：“打”是击打，与“要花很多钱，也很辛苦”的抚育含义不符。", "骂": "语义：“骂”是责备，不是抚育，与“要花很多钱”无关。", "吃": "搭配：“吃”不与“孩子”构成抚育的说法，“吃孩子”不能表示“养育孩子”。"}, "sentence_index": 6, "correct_answer": "养"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天都养电脑，它陪我工作。", "explanation": "这里应该用〈用〉。养指饲养动物或抚育孩子，电脑是物件，只能说“用”，不能说“养电脑”。"}, {"text": "妈妈每天给孩子养一顿晚饭。", "explanation": "这里应该用〈做〉。养指饲养或抚育，做饭要说“做”，不能说“养晚饭”。"}, {"text": "快去养它吃饭，它饿了。", "explanation": "这里应该用〈喂〉。给动物送食物要说“喂”，“养”指长期饲养，不说“养它吃饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91057, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们家养了着一只猫。", "corrected_sentence": "他们家养着一只猫。", "error_description": "错误：“养了着”，“了”与“着”不能同时用。正确：“养着”。“着”表示状态持续，“养”的持续状态要用“养着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91057, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把小狗大养了。", "corrected_sentence": "他们把小狗养大了。", "error_description": "错误：“大养了”，结果补语“大”要紧跟在动词之后。正确：“养大了”，表示把小狗养到长大。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91058, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91058, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91058, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "饲养家畜、水产等动物；培植花草。", "primary_collocate": null, "pronunciation": "yǎng", "ipa": "jɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "我在阳台上养了很多花，每天浇水。", "target_word": "养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民在村子里养猪和鸡。", "target_word": "养", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在池塘里养鱼，每年卖很多钱。", "target_word": "养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客厅里养着一盆兰花，很香。", "target_word": "养", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花不好养，太热太冷都不行。", "target_word": "养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷在山上养了五十只羊。", "target_word": "养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她养的花开得很漂亮，邻居都来看。", "target_word": "养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我弟弟小时候养过蚕，看它们吃叶子。", "target_word": "养", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司在海边养虾，卖到很多国家。", "target_word": "养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家养了二十头奶牛，每天早上挤奶。", "target_word": "养", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "养了", "label": "体标"}, {"form": "养过", "label": "体标"}, {"form": "养着", "label": "体标"}, {"form": "养养", "label": "重叠"}, {"form": "饲养", "label": "复合词"}, {"form": "養", "label": "繁体"}], "register": "中性", "sense_fingerprint": "养：饲养家畜水产、培植花草", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c40d4862-37ee-47f3-905b-3a171e8ebee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91058, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "养", "is_correct": true, "explanation": "正确。养 yǎng（第三声）：饲养或培植花草，使其生长。"}, {"text": "阳", "is_correct": false, "explanation": "阳 yáng（第二声）与 yǎng（第三声）声调不同，意思是阳光、太阳。"}, {"text": "样", "is_correct": false, "explanation": "样 yàng（第四声）与 yǎng（第三声）声调不同，意思是样子。"}, {"text": "掩", "is_correct": false, "explanation": "掩 yǎn 与 yǎng 的韵母不同（ng 变成 n），意思是遮掩。"}, {"text": "想", "is_correct": false, "explanation": "想 xiǎng 与 yǎng 的声母不同（x 与 y），意思是想念或想法。"}], "explanations": {"养": "正确。养 yǎng（第三声）：饲养或培植花草，使其生长。", "阳": "阳 yáng（第二声）与 yǎng（第三声）声调不同，意思是阳光、太阳。", "样": "样 yàng（第四声）与 yǎng（第三声）声调不同，意思是样子。", "掩": "掩 yǎn 与 yǎng 的韵母不同（ng 变成 n），意思是遮掩。", "想": "想 xiǎng 与 yǎng 的声母不同（x 与 y），意思是想念或想法。"}, "sentence_index": null, "correct_answer": "养"}, "level_3": {"options": [{"text": "养", "is_correct": true, "explanation": "正确。“我在阳台上养了很多花”中的“养”指培植花草，与后文“每天浇水”相符。"}, {"text": "摘", "is_correct": false, "explanation": "语义：“摘”是采下，摘下的花不再需要“每天浇水”，前后矛盾。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不与“花”搭配来表示培植，不能说“洗了很多花”。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”用于给动物或人送食物，不说“喂花”。"}], "explanations": {"养": "正确。“我在阳台上养了很多花”中的“养”指培植花草，与后文“每天浇水”相符。", "摘": "语义：“摘”是采下，摘下的花不再需要“每天浇水”，前后矛盾。", "洗": "搭配：“洗”不与“花”搭配来表示培植，不能说“洗了很多花”。", "喂": "搭配：“喂”用于给动物或人送食物，不说“喂花”。"}, "sentence_index": 0, "correct_answer": "养"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "园丁每周养树枝，把多余的枝叶去掉。", "explanation": "这里应该用〈修剪〉。修剪是去掉多余的枝叶，不能说“养树枝”；养用于饲养动物和培植花草。"}, {"text": "妈妈在厨房养了一桌好菜，大家都夸她。", "explanation": "这里应该用〈做〉。养指饲养或培植，做菜要说“做”，不能说“养一桌菜”。"}, {"text": "这个月我的体重养了三公斤。", "explanation": "这里应该用〈增加〉。养指饲养或培植，体重变化要用“增加”，不说“养了三公斤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91058, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "养", "is_correct": true, "explanation": "正确。养 yǎng（第三声）：饲养或培植花草，使其生长。"}, {"text": "羊", "is_correct": false, "explanation": "羊 yáng（第二声）与 yǎng（第三声）声调不同，意思是羊。"}, {"text": "眼", "is_correct": false, "explanation": "眼 yǎn 与 yǎng 的韵母不同（ng 变成 n），意思是眼睛。"}, {"text": "响", "is_correct": false, "explanation": "响 xiǎng 与 yǎng 的声母不同（x 与 y），意思是响声。"}, {"text": "享", "is_correct": false, "explanation": "享 xiǎng 与 yǎng 的声母不同（x 与 y），意思是享受。"}], "explanations": {"养": "正确。养 yǎng（第三声）：饲养或培植花草，使其生长。", "羊": "羊 yáng（第二声）与 yǎng（第三声）声调不同，意思是羊。", "眼": "眼 yǎn 与 yǎng 的韵母不同（ng 变成 n），意思是眼睛。", "响": "响 xiǎng 与 yǎng 的声母不同（x 与 y），意思是响声。", "享": "享 xiǎng 与 yǎng 的声母不同（x 与 y），意思是享受。"}, "sentence_index": null, "correct_answer": "养"}, "level_3": {"options": [{"text": "养", "is_correct": true, "explanation": "正确。“她养的花”指培植花草，与后文“开得很漂亮”相符。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”是落下使其破碎，摔过的花不会“开得很漂亮”，前后矛盾。"}, {"text": "踩", "is_correct": false, "explanation": "语义：“踩”是踏坏，被踩的花不会“开得很漂亮”，与后文矛盾。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”的对象一般是柴火、纸张等，不说“烧的花”来指培植。"}], "explanations": {"养": "正确。“她养的花”指培植花草，与后文“开得很漂亮”相符。", "摔": "语义：“摔”是落下使其破碎，摔过的花不会“开得很漂亮”，前后矛盾。", "踩": "语义：“踩”是踏坏，被踩的花不会“开得很漂亮”，与后文矛盾。", "烧": "搭配：“烧”的对象一般是柴火、纸张等，不说“烧的花”来指培植。"}, "sentence_index": 6, "correct_answer": "养"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民春天养了一场大雨，秋天就收获了。", "explanation": "这里应该用〈下〉。养指饲养或培植，降雨要说“下”，不能说“养一场大雨”。"}, {"text": "这家工厂养了一座新大楼，很漂亮。", "explanation": "这里应该用〈建〉。养指饲养或培植生物，修建楼房要说“建”，不说“养一座楼”。"}, {"text": "他每个月养一万块钱，很厉害。", "explanation": "这里应该用〈挣〉。养指饲养或培植，赚钱要说“挣”，不说“养一万块钱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈在窗台上养了着一盆仙人掌。", "corrected_sentence": "我妈妈在窗台上养着一盆仙人掌。", "error_description": "错误：“养了着”，“了”与“着”不同用。正确：“养着”，表示仙人掌持续养在窗台上的状态。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那盆花活养了。", "corrected_sentence": "他把那盆花养活了。", "error_description": "错误：“活养了”，结果补语“活”要放在动词之后。正确：“养活了”，表示花经过照料保持了生命。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
