INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91060, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "民间通常的称呼，不是正式的名称。", "primary_collocate": null, "pronunciation": "sú chēng", "ipa": "su˧˥ ʈʂʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "土豆是马铃薯的俗称。", "target_word": "俗称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鱼的俗称很有意思。", "target_word": "俗称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "耗子是老鼠的俗称。", "target_word": "俗称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上写的是学名，不是俗称。", "target_word": "俗称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这种花的俗称吗？", "target_word": "俗称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜻蜓在我们家乡有个俗称。", "target_word": "俗称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个药的正式名字很长，俗称却很短。", "target_word": "俗称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只知道这种草的俗称。", "target_word": "俗称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人只记得它的俗称。", "target_word": "俗称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先写了学名，再写俗称。", "target_word": "俗称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "民间通行的非正式名称，与学名相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2159400-947f-4fbc-9ddc-227cd6535575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91060, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "俗称", "is_correct": true, "explanation": "正确答案。“俗称”是民间通行的叫法，“土豆”就是大家对马铃薯的叫法。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是钱的数额，“土豆”是一个名字，不是价格。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指红、黄等，“土豆”不是一种颜色。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指酸甜苦辣，“土豆”是名字，不是味道。"}], "explanations": {"俗称": "正确答案。“俗称”是民间通行的叫法，“土豆”就是大家对马铃薯的叫法。", "价格": "语义：“价格”是钱的数额，“土豆”是一个名字，不是价格。", "颜色": "语义：“颜色”指红、黄等，“土豆”不是一种颜色。", "味道": "语义：“味道”指酸甜苦辣，“土豆”是名字，不是味道。"}, "sentence_index": 0, "correct_answer": "俗称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国家标准的编号要用俗称，才方便大家查找。", "explanation": "这里应该用〈正式名称〉。国家标准编号须用正式名称；俗称是民间通行的叫法，不能用于标准编号。"}, {"text": "这份合同要写清楚双方的俗称。", "explanation": "这里应该用〈正式名称〉。合同等正式文件要写正式名称；俗称是民间非正式的叫法，不能写进合同。"}, {"text": "他被授予“劳动模范”的俗称。", "explanation": "这里应该用〈称号〉。称号是授予的荣誉名称；俗称只是民间通行的叫法，不能被授予。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "俗称", "is_correct": true, "explanation": "正确答案。“俗称”指民间通行的叫法，与“正式名字”相对，句中“却很短”正好对应。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人或生物的体型高度，不能用来形容药名的长短，句子不通。"}, {"text": "包装", "is_correct": false, "explanation": "语义：“包装”指外层的装潢或容器，与名字的长短无关，句子不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指价值的货币数额，不能与名字的长短相对，句子不通。"}], "explanations": {"俗称": "正确答案。“俗称”指民间通行的叫法，与“正式名字”相对，句中“却很短”正好对应。", "身高": "体貌：“身高”指人或生物的体型高度，不能用来形容药名的长短，句子不通。", "包装": "语义：“包装”指外层的装潢或容器，与名字的长短无关，句子不通。", "价格": "语义：“价格”指价值的货币数额，不能与名字的长短相对，句子不通。"}, "sentence_index": 6, "correct_answer": "俗称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这项军事行动的俗称是“夜鹰”，只有少数人知道。", "explanation": "这里应该用〈代号〉。军事行动或保密项目用代号；俗称是民间通行的叫法，不用于保密行动。"}, {"text": "杭州的俗称是“钱塘”，常见于古诗之中。", "explanation": "这里应该用〈雅称〉。“钱塘”是杭州文雅的别称，多见于古诗；俗称指民间通行的叫法，不能用来指文雅的称呼。"}, {"text": "这所学校的俗称是北京市第一中学，大家都叫它一中。", "explanation": "这里应该用〈全称〉。“北京市第一中学”是完整的全称，大家平时叫的“一中”才是俗称，两者不能对调。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "它俗称很好听。", "corrected_sentence": "它的俗称很好听。", "error_description": "错误在于“俗称”前漏掉了定语标记“的”。应为“它的俗称”，表示“它”所属的民间叫法；“它俗称”不能作主语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这味药有两本俗称，大家都知道。", "corrected_sentence": "这味药有两个俗称，大家都知道。", "error_description": "量词错误：“俗称”是名称，应用“个”或“种”，不能用书籍的“本”。应为“两个俗称”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
