INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91061, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "现在正在用的。", "primary_collocate": null, "pronunciation": "xiàn xíng", "ipa": "ɕjɛn˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "现行的车票价格是五元。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们现行的软件用起来很慢。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现行的教材已经用了三年。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是现行的地图，请放心用。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校现行的作息时间是八点上课。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现行的方案太麻烦，大家都不喜欢。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套现行的办法比旧的简单。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请记住现行的联系方式。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧版本不能用了，请换成现行版本。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现行的包装比以前的结实。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "现在正在使用的版本、方案、东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4cfc666-8119-44d9-9cb1-da1cda7a5a1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91061, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "现行", "is_correct": true, "explanation": "正确：现行，表示现在正在使用的。"}, {"text": "先行", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，先行意思是事先行动，与现行不同。"}, {"text": "线性", "is_correct": false, "explanation": "xiàn 相同，xìng（第四声）与 xíng（第二声）声调不同，线性指呈直线关系的性质，意思不同。"}, {"text": "显性", "is_correct": false, "explanation": "xiǎn（第三声）与 xiàn（第四声）声调不同，显性指表现出来的性状，意思不同。"}, {"text": "显形", "is_correct": false, "explanation": "xiǎn（第三声）与 xiàn（第四声）声调不同，显形意思是显露出原形，与现行不同。"}], "explanations": {"现行": "正确：现行，表示现在正在使用的。", "先行": "xiān（第一声）与 xiàn（第四声）声调不同，先行意思是事先行动，与现行不同。", "线性": "xiàn 相同，xìng（第四声）与 xíng（第二声）声调不同，线性指呈直线关系的性质，意思不同。", "显性": "xiǎn（第三声）与 xiàn（第四声）声调不同，显性指表现出来的性状，意思不同。", "显形": "xiǎn（第三声）与 xiàn（第四声）声调不同，显形意思是显露出原形，与现行不同。"}, "sentence_index": null, "correct_answer": "现行"}, "level_3": {"options": [{"text": "现行", "is_correct": true, "explanation": "正确：“现行”表示现在正在使用，与“车票价格是五元”相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外观，不能修饰“车票价格”。"}, {"text": "过期", "is_correct": false, "explanation": "语义：过期车票已不再有效，“过期的车票价格是五元”与常识相矛盾。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”形容人的态度，不能修饰价格。"}], "explanations": {"现行": "正确：“现行”表示现在正在使用，与“车票价格是五元”相符。", "漂亮": "搭配：“漂亮”形容外观，不能修饰“车票价格”。", "过期": "语义：过期车票已不再有效，“过期的车票价格是五元”与常识相矛盾。", "热情": "搭配：“热情”形容人的态度，不能修饰价格。"}, "sentence_index": 0, "correct_answer": "现行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "现行的天气很好。", "explanation": "这里应该用〈目前的〉。现行指正在使用的物品或版本，不用于天气。"}, {"text": "我现行的年龄是二十岁。", "explanation": "这里应该用〈现在的〉。现行指正在使用的物品或版本，不用于年龄等人的状况。"}, {"text": "现行的困难很多。", "explanation": "这里应该用〈眼下的〉。现行指正在使用的物品或版本，不用于困难。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91061, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现行", "is_correct": true, "explanation": "正确：“现行”表示正在使用，与“比旧的简单”的比较相符。"}, {"text": "复杂", "is_correct": false, "explanation": "语义：“复杂”与“比旧的简单”的比较相矛盾。"}, {"text": "漫长", "is_correct": false, "explanation": "搭配：“漫长”形容时间或路程，不能修饰“办法”。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”形容心情，不能修饰“办法”。"}], "explanations": {"现行": "正确：“现行”表示正在使用，与“比旧的简单”的比较相符。", "复杂": "语义：“复杂”与“比旧的简单”的比较相矛盾。", "漫长": "搭配：“漫长”形容时间或路程，不能修饰“办法”。", "高兴": "搭配：“高兴”形容心情，不能修饰“办法”。"}, "sentence_index": 6, "correct_answer": "现行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们现行的人手不够。", "explanation": "这里应该用〈现有〉。现行用于正在使用的物品或版本，不用于指人手数量。"}, {"text": "他现行的体重是六十公斤。", "explanation": "这里应该用〈现在的〉。现行指正在使用的物品或版本，不用于体重等人的状况。"}, {"text": "现行的形势很复杂。", "explanation": "这里应该用〈当前的〉。现行指正在使用的物品或版本，不用于形势。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91061, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新版本还没推出，大家先用很现行版本。", "corrected_sentence": "新版本还没推出，大家先用现行版本。", "error_description": "错误：“很现行版本”。“现行”不能受“很”修饰，应直接说“现行版本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91061, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们只能用现行了办法。", "corrected_sentence": "我们只能用现行办法。", "error_description": "错误：“现行了办法”。“现行”是属性词，后面不能加“了”，应说“现行办法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
