INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91063, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中点是一条线正中间的那一个点。", "primary_collocate": null, "pronunciation": "zhōng diǎn", "ipa": "ʈʂʊŋ˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "先找这条线的中点。", "target_word": "中点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这根六十厘米的木棍，中点在三十厘米处。", "target_word": "中点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在中点画了一个圆点。", "target_word": "中点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根绳子的中点有一个红点。", "target_word": "中点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桥的中点离两边一样远。", "target_word": "中点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你能说出这条线的中点在哪儿吗？", "target_word": "中点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把尺子放在线上，量出了中点。", "target_word": "中点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明用折纸的方法找到了线的中点。", "target_word": "中点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中点把一条线分成了相等的两段。", "target_word": "中点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上两个城市连成一条线，中点在河边。", "target_word": "中点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一条线正中间的那个点，两边一样长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82430042-cc86-4152-a716-ac186622f809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91063, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：线条没有味道，“找味道”说不通。"}, {"text": "中点", "is_correct": true, "explanation": "正确：中点是一条线正中间的点，“找这条线的中点”符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "语义：线条没有声音，“这条线的声音”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：线条没有体重，“这条线的体重”说不通。"}], "explanations": {"味道": "语义：线条没有味道，“找味道”说不通。", "中点": "正确：中点是一条线正中间的点，“找这条线的中点”符合句意。", "声音": "语义：线条没有声音，“这条线的声音”说不通。", "体重": "语义：线条没有体重，“这条线的体重”说不通。"}, "sentence_index": 0, "correct_answer": "中点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "舞台的中点站着一个人。", "explanation": "这里应该用〈中央〉。中点指线段上到两端等距的点，舞台不是线段，应说“中央”。"}, {"text": "这张照片的中点在花上。", "explanation": "这里应该用〈焦点〉。中点指线段上的点，照片没有两端，画面的聚焦点应说“焦点”。"}, {"text": "老师用圆规画了一个圆，然后标出了圆的中点。", "explanation": "这里应该用〈圆心〉。中点指线段上到两端等距的点，圆的正中间应说“圆心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329c3694-5d44-4224-a3c5-49edf76ba398') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91063, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重量", "is_correct": false, "explanation": "搭配：尺子只能量长度，不能量“重量”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：尺子量不出颜色，句子说不通。"}, {"text": "中点", "is_correct": true, "explanation": "正确：“量出了中点”指用尺子找出线的中间点，符合句意。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”要用温度计来测，尺子不能量“温度”。"}], "explanations": {"重量": "搭配：尺子只能量长度，不能量“重量”。", "颜色": "语义：尺子量不出颜色，句子说不通。", "中点": "正确：“量出了中点”指用尺子找出线的中间点，符合句意。", "温度": "搭配：“温度”要用温度计来测，尺子不能量“温度”。"}, "sentence_index": 6, "correct_answer": "中点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的中点偏低，很稳。", "explanation": "这里应该用〈重心〉。中点只指线段上的点，椅子不是线段，稳定与否看的是重心。"}, {"text": "这个问题的中点是钱。", "explanation": "这里应该用〈核心〉。中点只指线段上到两端等距的点，问题不是线段，说事情的关键应用“核心”。"}, {"text": "这个皮球的中点有一个小孔。", "explanation": "这里应该用〈中心〉。中点只指线段上的点，皮球是立体的，应说“中心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329c3694-5d44-4224-a3c5-49edf76ba398') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91063, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师在纸上标出了一条中点。", "corrected_sentence": "老师在纸上标出了一个中点。", "error_description": "量词错误：“中点”应用“个”，不能用“条”，“条”用于细长的物体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329c3694-5d44-4224-a3c5-49edf76ba398') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91063, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈帮我找到了绳子了中点。", "corrected_sentence": "妈妈帮我找到了绳子的中点。", "error_description": "结构助词错误：“绳子的中点”中“的”连接修饰语和中心语，不能写成“了”；应说“绳子的中点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329c3694-5d44-4224-a3c5-49edf76ba398') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
