INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91064, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "线段上距离两端相等的点。", "primary_collocate": null, "pronunciation": "zhōng diǎn", "ipa": "ʈʂʊŋ˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "线段的中点到两端一样远。", "target_word": "中点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在这条线上找出中点。", "target_word": "中点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "点C是线段AB的中点。", "target_word": "中点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师在黑板上画了线段的中点。", "target_word": "中点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用尺子量出了这条线的中点。", "target_word": "中点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从中点到两端的长度相等。", "target_word": "中点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条线长十厘米，中点离两端各五厘米。", "target_word": "中点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这条线的中点标出来。", "target_word": "中点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圆心是直径的中点。", "target_word": "中点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "纸上画着一条线，中点用红笔做了记号。", "target_word": "中点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中點", "label": "繁体"}], "register": "书面", "sense_fingerprint": "数学术语，线段上到两个端点距离相等的那个点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82430042-cc86-4152-a716-ac186622f809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91064, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长度", "is_correct": false, "explanation": "搭配：“到两端一样远”说的是位置，不能与“长度”搭配。"}, {"text": "端点", "is_correct": false, "explanation": "语义：端点位于线段的两头，本身就是端，不可能与两端等距。"}, {"text": "中点", "is_correct": true, "explanation": "正确：中点是线段上到两端距离相等的点，填入后与句意一致。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：线段的颜色与距离无关，句子说不通。"}], "explanations": {"长度": "搭配：“到两端一样远”说的是位置，不能与“长度”搭配。", "端点": "语义：端点位于线段的两头，本身就是端，不可能与两端等距。", "中点": "正确：中点是线段上到两端距离相等的点，填入后与句意一致。", "颜色": "语义：线段的颜色与距离无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "中点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个广场的中点有一座喷泉。", "explanation": "这里应该用〈中心〉。中点只指线段上到两端距离相等的点，广场不是线段，应说“中心”。"}, {"text": "教室的中点放着一张桌子。", "explanation": "这里应该用〈中央〉。中点只用于线段，教室没有两端，应说“中央”。"}, {"text": "我在纸上画了一只中点。", "explanation": "这里量词应该用〈个〉。中点是抽象的点，“只”用于动物或成对的物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329c3694-5d44-4224-a3c5-49edf76ba398') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91064, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宽度", "is_correct": false, "explanation": "语义：线段只有长度，没有宽度可以离两端各五厘米，句子说不通。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“离两端各五厘米”说的是位置，不能与“重量”搭配。"}, {"text": "中点", "is_correct": true, "explanation": "正确：中点是线段正中间的点，离两端各五厘米符合线长十厘米的条件。"}, {"text": "高度", "is_correct": false, "explanation": "语义：这是一条线，没有高度，“高度离两端各五厘米”说不通。"}], "explanations": {"宽度": "语义：线段只有长度，没有宽度可以离两端各五厘米，句子说不通。", "重量": "搭配：“离两端各五厘米”说的是位置，不能与“重量”搭配。", "中点": "正确：中点是线段正中间的点，离两端各五厘米符合线长十厘米的条件。", "高度": "语义：这是一条线，没有高度，“高度离两端各五厘米”说不通。"}, "sentence_index": 6, "correct_answer": "中点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块铁板的中点偏左。", "explanation": "这里应该用〈重心〉。中点只指线段上到两端等距的点，铁板不是线段，重心才是平衡的支点。"}, {"text": "这块饼干的中点有一个洞。", "explanation": "这里应该用〈中间〉。中点指线段上到两端等距的点，饼干不是线段，应说“中间”。"}, {"text": "他站在院子的中点，等大家来。", "explanation": "这里应该用〈正中〉。中点只指线段上到两端等距的点，院子不是线段，表示站在中间的位置应说“正中”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329c3694-5d44-4224-a3c5-49edf76ba398') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在这条线上标出了一只中点。", "corrected_sentence": "他在这条线上标出了一个中点。", "error_description": "量词错误：“中点”的量词应为“个”，写成“只”不对，“只”用于动物或成对的物件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329c3694-5d44-4224-a3c5-49edf76ba398') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈用尺子量出了线段的中点们。", "corrected_sentence": "妈妈用尺子量出了线段的中点。", "error_description": "词缀错误：“们”只用于人，不能加在抽象的“中点”后面，应说“线段的中点”，不说“线段的中点们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329c3694-5d44-4224-a3c5-49edf76ba398') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
