INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91065, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "倒闭是店开不下去了，只好关门不开了。", "primary_collocate": null, "pronunciation": "dǎo bì", "ipa": "taʊ̯²¹⁴ pi⁵¹", "syllable_count": 2, "sentences": [{"text": "我家旁边的小饭馆倒闭了。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为客人太少，这家书店倒闭了。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板没有钱了，小店只好倒闭。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家面包店开了半年就倒闭了。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最爱去的咖啡馆倒闭了，真可惜。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多小店都怕倒闭，所以天天打折。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生意不好，这家店快要倒闭了。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街上的商店一家一家地倒闭了。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开的花店没倒闭，生意还不错。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那家玩具店倒闭了，你知道吗？", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倒闭了", "label": "体标"}, {"form": "倒閉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "店开不下去，只好关门不开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9bab8fe-0b72-43ae-8aa8-81542a01a1dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91065, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "倒闭", "is_correct": true, "explanation": "正确：倒闭指店铺经营不下去而关门，与“我家旁边的小饭馆”相符。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：结婚的主语必须是人，小饭馆不能结婚。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：毕业用于学生，不能用于小饭馆。"}, {"text": "长高", "is_correct": false, "explanation": "语义：长高指人或植物长高，与小饭馆不符。"}], "explanations": {"倒闭": "正确：倒闭指店铺经营不下去而关门，与“我家旁边的小饭馆”相符。", "结婚": "搭配：结婚的主语必须是人，小饭馆不能结婚。", "毕业": "搭配：毕业用于学生，不能用于小饭馆。", "长高": "语义：长高指人或植物长高，与小饭馆不符。"}, "sentence_index": 0, "correct_answer": "倒闭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家面包店因为装修，暂时倒闭了一个月。", "explanation": "这里应该用〈停业〉。倒闭指因亏损而永久关门，装修造成的暂时歇业要说停业。"}, {"text": "每天晚上十点，这家店倒闭。", "explanation": "这里应该用〈关门〉。每天按时打烊不是经营失败，不能说倒闭，应说关门。"}, {"text": "司机们因为油价上涨倒闭了。", "explanation": "这里应该用〈罢工〉。倒闭用于企业或商店，司机因油价而停止工作要说罢工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91065, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倒闭", "is_correct": true, "explanation": "正确：经营不好、快要关门，正是“倒闭”的含义。"}, {"text": "开业", "is_correct": false, "explanation": "语义：“生意不好”与“快要开业”相互矛盾，句意不通。"}, {"text": "失恋", "is_correct": false, "explanation": "搭配：“失恋”只用于人，店铺不会失恋。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：出生只用于人或动物，不能用于店铺。"}], "explanations": {"倒闭": "正确：经营不好、快要关门，正是“倒闭”的含义。", "开业": "语义：“生意不好”与“快要开业”相互矛盾，句意不通。", "失恋": "搭配：“失恋”只用于人，店铺不会失恋。", "出生": "搭配：出生只用于人或动物，不能用于店铺。"}, "sentence_index": 6, "correct_answer": "倒闭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的叔叔欠了很多钱，已经倒闭了。", "explanation": "这里应该用〈破产〉。倒闭说的是企业或商店，个人欠债后要说破产。"}, {"text": "国庆假期，这家书店倒闭了三天。", "explanation": "这里应该用〈歇业〉。倒闭是永久关门，国庆期间的短期停业要说歇业。"}, {"text": "这家工厂因为停电，暂时倒闭。", "explanation": "这里应该用〈停工〉。倒闭不用于暂时停产，因停电而暂停生产要说停工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91065, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家小超市生意冷清，最后还是被倒闭了。", "corrected_sentence": "这家小超市生意冷清，最后还是倒闭了。", "error_description": "被动误用：“倒闭”是不及物动词，没有被动用法，不能说“被倒闭”，应直接说“倒闭了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91065, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家书店很倒闭了。", "corrected_sentence": "那家书店真的倒闭了。", "error_description": "副词误用：“很”不能修饰“倒闭”这类动作动词，应说“真的倒闭了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
