INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91066, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "企业或商店因亏损或债务而停业关门。", "primary_collocate": null, "pronunciation": "dǎo bì", "ipa": "taʊ̯²¹⁴ pi⁵¹", "syllable_count": 2, "sentences": [{"text": "这家公司因为欠了很多钱，去年倒闭了。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济不好，很多小企业都倒闭了。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，工厂可能下个月就要倒闭。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行没有倒闭，客人不用担心。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年前，这家大商场倒闭了。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的公司亏了几年，终于倒闭了。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上购物的冲击让不少实体店倒闭。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个厂倒闭以后，工人都找不到工作。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了不让公司倒闭，他们想了很多办法。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家有名的企业倒闭，让大家很吃惊。", "target_word": "倒闭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倒闭了", "label": "体标"}, {"form": "倒閉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "企业或商店因亏损或债务而停业关门", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9bab8fe-0b72-43ae-8aa8-81542a01a1dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "倒闭", "is_correct": true, "explanation": "正确：倒闭指因亏损或债务而停业关门，与“欠了很多钱”相符。"}, {"text": "盈利", "is_correct": false, "explanation": "语义：欠了很多钱的公司不会因此盈利，与前文矛盾。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：毕业只用于人，公司不能毕业。"}, {"text": "复工", "is_correct": false, "explanation": "语义：复工是停工后恢复生产，与“欠钱”导致的结果不符。"}], "explanations": {"倒闭": "正确：倒闭指因亏损或债务而停业关门，与“欠了很多钱”相符。", "盈利": "语义：欠了很多钱的公司不会因此盈利，与前文矛盾。", "毕业": "搭配：毕业只用于人，公司不能毕业。", "复工": "语义：复工是停工后恢复生产，与“欠钱”导致的结果不符。"}, "sentence_index": 0, "correct_answer": "倒闭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店因为装修，暂时倒闭了三天。", "explanation": "这里应该用〈停业〉。倒闭指因亏损而永久关门，装修造成的暂时歇业要说停业。"}, {"text": "他欠了很多债，最后倒闭了。", "explanation": "这里应该用〈破产〉。倒闭说的是企业或商店，个人因债务而失去财产要说破产。"}, {"text": "下雨了，店家都倒闭了。", "explanation": "这里应该用〈关门〉。天气原因的暂时关门不是经营失败，不能说倒闭，应说关门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倒闭", "is_correct": true, "explanation": "正确：网上购物的冲击使实体店关门，符合句意。"}, {"text": "开张", "is_correct": false, "explanation": "语义：开张表示开始营业，与网上购物造成的冲击正好相反。"}, {"text": "繁荣", "is_correct": false, "explanation": "语义：“冲击”是负面影响，不会让实体店繁荣，句意矛盾。"}, {"text": "扩张", "is_correct": false, "explanation": "语义：扩张指规模变大，与“让……”后面的负面影响矛盾。"}], "explanations": {"倒闭": "正确：网上购物的冲击使实体店关门，符合句意。", "开张": "语义：开张表示开始营业，与网上购物造成的冲击正好相反。", "繁荣": "语义：“冲击”是负面影响，不会让实体店繁荣，句意矛盾。", "扩张": "语义：扩张指规模变大，与“让……”后面的负面影响矛盾。"}, "sentence_index": 6, "correct_answer": "倒闭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们因为工资问题倒闭了。", "explanation": "这里应该用〈罢工〉。倒闭指企业或商店停业关门，工人因工资问题停止工作要说罢工。"}, {"text": "春节期间，很多饭馆倒闭了一周。", "explanation": "这里应该用〈歇业〉。倒闭是永久关门，过年期间的短期停业要说歇业。"}, {"text": "工厂因为设备坏了，暂时倒闭。", "explanation": "这里应该用〈停工〉。倒闭不用于暂时的停产，因设备故障而暂停生产要说停工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家书店因为亏损，今年终于被倒闭了。", "corrected_sentence": "这家书店因为亏损，今年终于倒闭了。", "error_description": "被动误用：“倒闭”是不及物动词，没有被动用法，不能说“被倒闭”，应直接说“倒闭了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店很倒闭了，大家都很难过。", "corrected_sentence": "这家店真的倒闭了，大家都很难过。", "error_description": "副词误用：“很”不能修饰“倒闭”这类动作动词，应说“真的倒闭了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
