INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91069, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "倾听是认真地听别人说话。", "primary_collocate": null, "pronunciation": "qīng tīng", "ipa": "tɕʰiŋ⁵⁵ tʰiŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "好老师会认真倾听学生的想法。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友难过时，你要安静地倾听。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在我旁边，倾听我说了一个小时。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈总是倾听我的烦恼。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，经理倾听了大家的意见。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "倾听别人说话，是一种好习惯。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她倾听着老人讲过去的故事。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱说话，却很会倾听。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生先倾听病人的话，再开药。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你耐心倾听孩子的心里话。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倾听着", "label": "体标"}, {"form": "倾听了", "label": "体标"}, {"form": "倾听过", "label": "体标"}, {"form": "傾聽", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "认真地听别人说话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9bab8fe-0b72-43ae-8aa8-81542a01a1dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91069, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "倾听", "is_correct": true, "explanation": "“倾听”表示认真地听别人说话，与“好老师”“认真”的语境相符。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”是不重视，与“好老师”和“认真”的语境相反。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是讥笑别人，与“好老师”的身份不符。"}, {"text": "微笑", "is_correct": false, "explanation": "配价：“微笑”是不及物动词，不能直接带“学生的想法”作宾语。"}], "explanations": {"倾听": "“倾听”表示认真地听别人说话，与“好老师”“认真”的语境相符。", "忽视": "语义：“忽视”是不重视，与“好老师”和“认真”的语境相反。", "嘲笑": "语义：“嘲笑”是讥笑别人，与“好老师”的身份不符。", "微笑": "配价：“微笑”是不及物动词，不能直接带“学生的想法”作宾语。"}, "sentence_index": 0, "correct_answer": "倾听"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他慢慢倾听这杯茶的味道。", "explanation": "这里应该用〈品尝〉。“倾听”用于听说话或声音，尝味道要用“品尝”。"}, {"text": "他走进厨房，倾听饭菜的香味。", "explanation": "这里应该用〈闻〉。香味是用鼻子闻的，“倾听”只用于听说话或声音。"}, {"text": "观众们在剧场里倾听舞台上的灯光。", "explanation": "这里应该用〈观看〉。灯光是用眼睛看的，“倾听”只用于听说话或声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91069, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倾听", "is_correct": true, "explanation": "“倾听”表示认真地听，与“老人讲过去的故事”的语境相符。"}, {"text": "忘记", "is_correct": false, "explanation": "体貌：“忘记”是瞬间动词，不能用“着”表示正在进行。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“老人讲过去的故事”作宾语。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”是不及物动词，后面不能接宾语，句子读不通。"}], "explanations": {"倾听": "“倾听”表示认真地听，与“老人讲过去的故事”的语境相符。", "忘记": "体貌：“忘记”是瞬间动词，不能用“着”表示正在进行。", "哭": "配价：“哭”是不及物动词，不能带“老人讲过去的故事”作宾语。", "咳嗽": "配价：“咳嗽”是不及物动词，后面不能接宾语，句子读不通。"}, "sentence_index": 6, "correct_answer": "倾听"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在窗前倾听着月亮，一直看到深夜。", "explanation": "这里应该用〈注视〉。“倾听”用于说话或声音，看月亮要用“注视”。"}, {"text": "过马路时，我们要倾听安全。", "explanation": "这里应该用〈注意〉。“注意安全”是固定说法，“倾听”只能用于听说话或声音。"}, {"text": "我们在美术馆里倾听这幅画的美。", "explanation": "这里应该用〈欣赏〉。“欣赏”指觉得美好而观看，“倾听”只用于听说话或声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91069, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他认真倾听了着学生的发言。", "corrected_sentence": "他认真倾听着学生的发言。", "error_description": "“倾听”后面不能同时用“了”和“着”两个动态助词。应去掉“了”，改为“倾听着”，表示动作正在进行。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91069, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师正在耐心倾听过学生的问题。", "corrected_sentence": "老师正在耐心倾听学生的问题。", "error_description": "体标错误：“正在”表示动作正在进行，不能和表示过去经历的“过”一起用在“倾听”后面。应去掉“过”，说“正在耐心倾听学生的问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
