INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91070, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91070, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "专心、认真地听。", "primary_collocate": null, "pronunciation": "qīng tīng", "ipa": "tɕʰiŋ⁵⁵ tʰiŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "我们坐在湖边，倾听风的声音。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她闭上眼睛，倾听这首美丽的歌。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里很安静，我倾听着窗外的雨声。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都专心倾听校长的讲话。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们倾听着老师讲的故事。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在海边，倾听海浪的声音。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听音乐时，我喜欢一个人倾听。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们认真倾听，没有一个人说话。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你倾听过自己心里的声音吗？", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的早上，我倾听小鸟唱歌。", "target_word": "倾听", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倾听着", "label": "体标"}, {"form": "倾听了", "label": "体标"}, {"form": "倾听过", "label": "体标"}, {"form": "傾聽", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "专心、认真地听", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9bab8fe-0b72-43ae-8aa8-81542a01a1dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91070, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "倾听", "is_correct": true, "explanation": "“倾听”表示专心地听，与“风的声音”相符。"}, {"text": "观看", "is_correct": false, "explanation": "搭配：“观看”针对看得见的对象，不说“观看声音”。"}, {"text": "注视", "is_correct": false, "explanation": "搭配：“注视”是用目光看，不能用来搭配“风的声音”。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：“讨论”需要可以讨论的话题，风的声音不能被讨论。"}], "explanations": {"倾听": "“倾听”表示专心地听，与“风的声音”相符。", "观看": "搭配：“观看”针对看得见的对象，不说“观看声音”。", "注视": "搭配：“注视”是用目光看，不能用来搭配“风的声音”。", "讨论": "语义：“讨论”需要可以讨论的话题，风的声音不能被讨论。"}, "sentence_index": 0, "correct_answer": "倾听"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家在公园里倾听盛开的花。", "explanation": "这里应该用〈观赏〉。“倾听”用于声音或别人说话，看花要用“观赏”。"}, {"text": "他喜欢在晚上倾听天上的星星。", "explanation": "这里应该用〈观察〉。星星是用眼睛看的，“倾听”只用于听说话或声音，看星星要用“观察”。"}, {"text": "老师正在倾听同学们的图画。", "explanation": "这里应该用〈欣赏〉。图画是用来看的，“倾听”只用于听说话或声音，看图画要用“欣赏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倾听", "is_correct": true, "explanation": "“倾听”表示认真地听，与“听音乐”相符。"}, {"text": "擦拭", "is_correct": false, "explanation": "配价：“擦拭”需要带宾语，句末没有宾语，句子读不通。"}, {"text": "拍摄", "is_correct": false, "explanation": "语义：“拍摄”是用镜头记录画面，与“听音乐”的听觉感受不符。"}, {"text": "捕捉", "is_correct": false, "explanation": "配价：“捕捉”需要带宾语，单独用在这里说不通。"}], "explanations": {"倾听": "“倾听”表示认真地听，与“听音乐”相符。", "擦拭": "配价：“擦拭”需要带宾语，句末没有宾语，句子读不通。", "拍摄": "语义：“拍摄”是用镜头记录画面，与“听音乐”的听觉感受不符。", "捕捉": "配价：“捕捉”需要带宾语，单独用在这里说不通。"}, "sentence_index": 6, "correct_answer": "倾听"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他站在山顶倾听远处的落日。", "explanation": "这里应该用〈眺望〉。“倾听”用于声音或说话，远处的景色要用“眺望”。"}, {"text": "我在人群中倾听那个熟悉的身影。", "explanation": "这里应该用〈注视〉。“倾听”用于声音或说话，看人的身影要用“注视”。"}, {"text": "他在操场上倾听遗失的钥匙。", "explanation": "这里应该用〈寻找〉。“倾听”用于声音或说话，丢失的东西要用“寻找”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们安静地倾听清楚雨声。", "corrected_sentence": "孩子们安静地倾听雨声。", "error_description": "“倾听”表示专心地听的过程，后面不能带结果补语“清楚”（可以说“听清楚”，不说“倾听清楚”）。应去掉“清楚”，说“倾听雨声”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有认真倾听了老师的讲解。", "corrected_sentence": "他没有认真倾听老师的讲解。", "error_description": "“没有”表示否定时不能再用“了”。应去掉“倾听”后的“了”，说“没有认真倾听老师的讲解”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
