INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91072, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "监督检查机关或人员的工作和行为是否合乎规定。", "primary_collocate": null, "pronunciation": "jiān chá", "ipa": "tɕjɛn˥ ʈʂʰa˧˥", "syllable_count": 2, "sentences": [{"text": "纪检部门负责监察公务员的行为。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上级正在监察各部门的工作。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家设立专门机构监察官员的行为。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们监察了这个部门一年的工作。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个委员会负责监察政府是否守法。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "必须有人监察官员有没有违反规定。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校成立小组监察食堂的卫生工作。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市里派人监察各个医院的收费情况。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司内部有人专门监察员工的行为。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上级已经监察过这家银行的工作。", "target_word": "监察", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "监察了", "label": "体标"}, {"form": "监察过", "label": "体标"}, {"form": "监察机关", "label": "复合"}, {"form": "監察", "label": "繁体"}], "register": "书面", "sense_fingerprint": "监督检查机关或人员的工作和行为是否合规", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72962ab9-2347-4d76-bde0-711257f30022') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91072, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "监察", "is_correct": true, "explanation": "正确：“监察”指监督检查人员的行为是否合规，符合“纪检部门负责……公务员的行为”的语境。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是赞赏观看，不是监督检查工作和行为。"}, {"text": "放映", "is_correct": false, "explanation": "搭配：“放映”的对象是影片，不能用于“公务员的行为”。"}, {"text": "款待", "is_correct": false, "explanation": "语义：“款待”是招待客人，与“监督公务员的行为”无关。"}], "explanations": {"监察": "正确：“监察”指监督检查人员的行为是否合规，符合“纪检部门负责……公务员的行为”的语境。", "欣赏": "语义：“欣赏”是赞赏观看，不是监督检查工作和行为。", "放映": "搭配：“放映”的对象是影片，不能用于“公务员的行为”。", "款待": "语义：“款待”是招待客人，与“监督公务员的行为”无关。"}, "sentence_index": 0, "correct_answer": "监察"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人监察了这台机器。", "explanation": "这里应该用〈检查〉。监察指监督检查机关或人员的工作和行为是否合规，检查机器的状况要用〈检查〉。"}, {"text": "他每天监察这片花园。", "explanation": "这里应该用〈照看〉。监察针对机关或人员的工作和行为，照看花园要用〈照看〉。"}, {"text": "医生监察了这位病人。", "explanation": "这里应该用〈检查〉。监察指监督检查人员的工作和行为，给病人做身体检查要用〈检查〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "监察", "is_correct": true, "explanation": "正确：“监察”指监督检查工作，符合“学校成立小组……食堂的卫生工作”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能和“卫生工作”搭配。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”是修复器物，不能用于“卫生工作”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”没有“卫生工作”这样的宾语。"}], "explanations": {"监察": "正确：“监察”指监督检查工作，符合“学校成立小组……食堂的卫生工作”的语境。", "吃": "搭配：“吃”不能和“卫生工作”搭配。", "修理": "语义：“修理”是修复器物，不能用于“卫生工作”。", "唱": "搭配：“唱”没有“卫生工作”这样的宾语。"}, "sentence_index": 6, "correct_answer": "监察"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天在厨房监察蛋糕。", "explanation": "这里应该用〈照看〉。监察指监督检查人员的工作和行为，看着蛋糕防止烤焦要用〈照看〉。"}, {"text": "我们在河边监察风景。", "explanation": "这里应该用〈欣赏〉。监察不用于观看风景，欣赏风景要用〈欣赏〉。"}, {"text": "孩子们在院子里监察蝴蝶。", "explanation": "这里应该用〈观察〉。监察针对人的行为，观察蝴蝶要用〈观察〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上级部门派专人仔细监察在各乡镇的财务。", "corrected_sentence": "上级部门派专人仔细监察各乡镇的财务。", "error_description": "错误：“各乡镇的财务”前多了“在”，“监察”直接带宾语，不能加“在”；正确为“仔细监察各乡镇的财务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会计部门定期监察在公司的账目。", "corrected_sentence": "会计部门定期监察公司的账目。", "error_description": "错误：“公司的账目”前多了“在”，“监察”直接带宾语，不能加“在”；正确为“监察公司的账目”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91073, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外交", "is_correct": true, "explanation": "外交与内政相对：内政指一个国家自己里面的事，外交指与别国的交往，二者是反义关系。"}, {"text": "花朵", "is_correct": false, "explanation": "花朵是植物的部分，与内政的概念没有反义关系。"}, {"text": "公路", "is_correct": false, "explanation": "公路是道路，与内政的概念没有反义关系。"}, {"text": "礼物", "is_correct": false, "explanation": "礼物是赠送的物品，与内政的概念没有反义关系。"}], "correct_answer": "外交", "explanations": {"外交": "外交与内政相对：内政指一个国家自己里面的事，外交指与别国的交往，二者是反义关系。", "花朵": "花朵是植物的部分，与内政的概念没有反义关系。", "公路": "公路是道路，与内政的概念没有反义关系。", "礼物": "礼物是赠送的物品，与内政的概念没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91073, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外交", "is_correct": true, "explanation": "外交与内政相对：内政指一个国家自己里面的事，外交指与别国的交往，二者是反义关系。"}, {"text": "海洋", "is_correct": false, "explanation": "海洋是地理事物，与内政的概念没有反义关系。"}, {"text": "书桌", "is_correct": false, "explanation": "书桌是家具，与内政的概念没有反义关系。"}, {"text": "钢琴", "is_correct": false, "explanation": "钢琴是乐器，与内政的概念没有反义关系。"}], "correct_answer": "外交", "explanations": {"外交": "外交与内政相对：内政指一个国家自己里面的事，外交指与别国的交往，二者是反义关系。", "海洋": "海洋是地理事物，与内政的概念没有反义关系。", "书桌": "书桌是家具，与内政的概念没有反义关系。", "钢琴": "钢琴是乐器，与内政的概念没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91073, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "内政是一个国家里面的事。", "primary_collocate": null, "pronunciation": "nèi zhèng", "ipa": "neɪ̯˥˩ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这是我们国家自己的内政。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别的国家不能干涉我们的内政。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们不想管别国的内政。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "内政就是一个国家里面的事。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事是内政，外人不用管。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国都不应该干涉对方的内政。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外国人不应该插手这个国家的内政。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "内政和外交是两回事。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人很关心国家的内政。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者问了很多关于内政的问题。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "内政部", "label": "复合"}, {"form": "內政", "label": "繁体"}], "register": "正式", "sense_fingerprint": "一个国家自己里面的事，不是别国的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3f596a-ea6f-4092-8aea-7d56453cebea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91073, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内政", "is_correct": true, "explanation": "内政指一个国家自己里面的事，不是别国的事，这里正好指国家自己的事务。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，“国家自己的天气”不成立，与国家自身的事务无关。"}, {"text": "晚霞", "is_correct": false, "explanation": "语义：晚霞是傍晚天空的景象，不能说成国家自己的，句子不通。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语化的闲话，与正式语域的“内政”不合，也与国家的事务无关。"}], "explanations": {"内政": "内政指一个国家自己里面的事，不是别国的事，这里正好指国家自己的事务。", "天气": "语义：天气是自然现象，“国家自己的天气”不成立，与国家自身的事务无关。", "晚霞": "语义：晚霞是傍晚天空的景象，不能说成国家自己的，句子不通。", "八卦": "语域：“八卦”是口语化的闲话，与正式语域的“内政”不合，也与国家的事务无关。"}, "sentence_index": 0, "correct_answer": "内政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府要加强对市场的内政。", "explanation": "这里应该用〈管理〉。内政是名词，指国家内部的政务，不指对市场进行的管理行为。"}, {"text": "这场比赛的内政很精彩，大家都在看。", "explanation": "这里应该用〈过程〉。内政指国家内部的政务，不能用来指比赛的进程，应说“比赛的过程很精彩”。"}, {"text": "他家的内政很乱，房间从来不打扫。", "explanation": "这里应该用〈家务〉。内政指一个国家自己里面的事，不指一个家庭的家务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91073, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内政", "is_correct": true, "explanation": "内政指国家内部的事务，外国人不应插手的正是这个国家自己的政务。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是日常食物，“插手这个国家的饭菜”不成立，与外交语境不符。"}, {"text": "球鞋", "is_correct": false, "explanation": "搭配：“插手”要求抽象事务作宾语，不能与“球鞋”这类具体物品搭配。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是种植花草的地方，不能被“插手”，与政务无关。"}], "explanations": {"内政": "内政指国家内部的事务，外国人不应插手的正是这个国家自己的政务。", "饭菜": "语义：饭菜是日常食物，“插手这个国家的饭菜”不成立，与外交语境不符。", "球鞋": "搭配：“插手”要求抽象事务作宾语，不能与“球鞋”这类具体物品搭配。", "花园": "语义：花园是种植花草的地方，不能被“插手”，与政务无关。"}, "sentence_index": 6, "correct_answer": "内政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的内政很动听，我很喜欢。", "explanation": "这里应该用〈歌词〉或〈旋律〉。内政指国家的政务，不能用来指歌曲的内容。"}, {"text": "他在考场上遇到了内政，不知道怎么办。", "explanation": "这里应该用〈问题〉。内政是政务范畴的名词，不能像事件一样被“遇到”。"}, {"text": "这只小狗的内政很可爱，大家都喜欢它。", "explanation": "这里应该用〈性格〉。内政指国家事务，不能用来形容动物的性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91073, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是他们自己国家的一条内政。", "corrected_sentence": "这是他们自己国家的内政。", "error_description": "量词错误：“内政”是抽象事务，不能用量词“条”来数。应去掉“一条”，说“他们自己国家的内政”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91073, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "外国不应该干涉我们的一只内政。", "corrected_sentence": "外国不应该干涉我们的内政。", "error_description": "量词错误：“内政”是抽象事务，不能用量词“只”。这里应直接说“我们的内政”，不能说“我们的一只内政”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91074, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外交", "is_correct": true, "explanation": "外交与内政相对：内政指国家内部的事务，外交指对外的交往，二者是反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "天气是自然现象，与内政的概念没有反义关系。"}, {"text": "音乐", "is_correct": false, "explanation": "音乐是艺术形式，与内政的概念没有反义关系。"}, {"text": "厨房", "is_correct": false, "explanation": "厨房是房间，与内政的概念没有反义关系。"}], "correct_answer": "外交", "explanations": {"外交": "外交与内政相对：内政指国家内部的事务，外交指对外的交往，二者是反义关系。", "天气": "天气是自然现象，与内政的概念没有反义关系。", "音乐": "音乐是艺术形式，与内政的概念没有反义关系。", "厨房": "厨房是房间，与内政的概念没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91074, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外交", "is_correct": true, "explanation": "外交与内政相对：内政指国家内部的事务，外交指对外的交往，二者是反义关系。"}, {"text": "海洋", "is_correct": false, "explanation": "海洋是地理事物，与内政的概念没有反义关系。"}, {"text": "花园", "is_correct": false, "explanation": "花园是种植花草的地方，与内政的概念没有反义关系。"}, {"text": "足球", "is_correct": false, "explanation": "足球是体育运动，与内政的概念没有反义关系。"}], "correct_answer": "外交", "explanations": {"外交": "外交与内政相对：内政指国家内部的事务，外交指对外的交往，二者是反义关系。", "海洋": "海洋是地理事物，与内政的概念没有反义关系。", "花园": "花园是种植花草的地方，与内政的概念没有反义关系。", "足球": "足球是体育运动，与内政的概念没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91074, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个国家内部的政务，如治安、教育、民生等。", "primary_collocate": null, "pronunciation": "nèi zhèng", "ipa": "neɪ̯˥˩ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "内政包括治安和教育。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位部长负责国家的内政。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的内政能让人民生活更好。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府要先做好内政。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对国家的内政很了解。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教育和治安都是内政的一部分。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "内政不好，外交也很难做好。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的内政很稳定。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新总统先处理内政问题。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位官员专门负责内政方面的工作。", "target_word": "内政", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "内政部", "label": "复合"}, {"form": "內政", "label": "繁体"}], "register": "正式", "sense_fingerprint": "国家内部的政务，如治安、教育、民生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3f596a-ea6f-4092-8aea-7d56453cebea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91074, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内政", "is_correct": true, "explanation": "内政指国家内部的政务，治安和教育都属于这个范围，可以作主语。"}, {"text": "外交", "is_correct": false, "explanation": "语义：外交指对外的交往，不包括国家内部的治安和教育，“外交包括治安和教育”不通。"}, {"text": "家务", "is_correct": false, "explanation": "语义：家务指家里的日常事务，与国家的治安和教育无关，句子不通。"}, {"text": "生意", "is_correct": false, "explanation": "语域：“生意”是口语化的说法，与正式语域的“内政”不合，而且做生意不包括治安和教育。"}], "explanations": {"内政": "内政指国家内部的政务，治安和教育都属于这个范围，可以作主语。", "外交": "语义：外交指对外的交往，不包括国家内部的治安和教育，“外交包括治安和教育”不通。", "家务": "语义：家务指家里的日常事务，与国家的治安和教育无关，句子不通。", "生意": "语域：“生意”是口语化的说法，与正式语域的“内政”不合，而且做生意不包括治安和教育。"}, "sentence_index": 0, "correct_answer": "内政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的内政很丰富，常常想很多事。", "explanation": "这里应该用〈内心〉。内政指国家内部的政务，不指人的内心世界。"}, {"text": "他去市场买了两斤内政。", "explanation": "这里把“内政”当成了可以买卖、称重的实物，应该用〈物资〉。内政指国家内部的政务，是抽象概念，不能买，也不能用斤计量。"}, {"text": "这是两国之间的内政，需要共同协商。", "explanation": "这里应该用〈外交〉。内政只指一个国家内部的事务，两国之间的事务不能称为内政。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内政", "is_correct": true, "explanation": "内政指国家内部的政务，内政搞不好，外交也就很难做好。"}, {"text": "身体", "is_correct": false, "explanation": "语义：“身体不好”说的是个人健康，与国家的外交无关，句子不通。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是家用电器，“电视不好”与国家的民生和政务无关，句子不通。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业指学生的课后练习，与国家的事务无关，“作业不好”无法说明外交的情况。"}], "explanations": {"内政": "内政指国家内部的政务，内政搞不好，外交也就很难做好。", "身体": "语义：“身体不好”说的是个人健康，与国家的外交无关，句子不通。", "电视": "语义：电视是家用电器，“电视不好”与国家的民生和政务无关，句子不通。", "作业": "语义：作业指学生的课后练习，与国家的事务无关，“作业不好”无法说明外交的情况。"}, "sentence_index": 6, "correct_answer": "内政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的内政很高，一下子就跳过了栏杆。", "explanation": "这里应该用〈身高〉。内政指国家内部的政务，不能用来描述人的身高。"}, {"text": "新内政成立后，首先召开了会议。", "explanation": "这里应该用〈内阁〉。内政指国家内部的政务，不是政府机构，能够成立并召开会议的是内阁。"}, {"text": "这次考试他的内政得了八十分。", "explanation": "这里应该用〈政治〉。内政是政务领域的概念，不是考试科目，也不能得分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "部长每天都在处理国家的一个内政。", "corrected_sentence": "部长每天都在处理国家的内政。", "error_description": "量词误用：内政是抽象的集合名词，不能用“一个”计数，应去掉“一个”，说“国家的内政”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "别国不应该干涉我们的内政们。", "corrected_sentence": "别国不应该干涉我们的内政。", "error_description": "后缀误用：“们”只用于指人的名词，“内政”是抽象名词，不能加“们”，应说“我们的内政”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
