INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91075, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从小到老的一辈子。", "primary_collocate": null, "pronunciation": "zhōng shēn", "ipa": "ʈʂʊŋ˥ ʂən˥", "syllable_count": 2, "sentences": [{"text": "他从小爱读书，终身没有放下书本。", "target_word": "终身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把终身献给了教育事业。", "target_word": "终身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，学会读书会让人终身受益。", "target_word": "终身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位工人终身在同一家工厂工作。", "target_word": "终身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他终身都喜欢爬山。", "target_word": "终身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事给她留下了终身的遗憾。", "target_word": "终身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷终身没有后悔自己的选择。", "target_word": "终身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和小王成了终身的朋友。", "target_word": "终身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种好习惯会让人终身受益。", "target_word": "终身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他终身研究这种小鸟，写了很多书。", "target_word": "终身", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "終身", "label": "繁体"}, {"form": "终身学习", "label": "复合"}, {"form": "终身制", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：从小到老的整个人生，如终身学习、终身遗憾、影响终身", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c21081-19c8-4e43-9122-d082b2713663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91075, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "终身", "is_correct": true, "explanation": "正确。「终身」指从小到老的一辈子，与「从小爱读书」「没有放下书本」相符。"}, {"text": "刹那", "is_correct": false, "explanation": "语义：「刹那」指极短的一瞬，与「从小到老」的长期习惯矛盾。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：「午夜」是一个时刻，不能表示一生的长期习惯。"}, {"text": "年头", "is_correct": false, "explanation": "搭配：「年头」多用于「这年头」「年头长了」，不能直接作「没有放下书本」的时间状语。"}], "explanations": {"终身": "正确。「终身」指从小到老的一辈子，与「从小爱读书」「没有放下书本」相符。", "刹那": "语义：「刹那」指极短的一瞬，与「从小到老」的长期习惯矛盾。", "午夜": "语义：「午夜」是一个时刻，不能表示一生的长期习惯。", "年头": "搭配：「年头」多用于「这年头」「年头长了」，不能直接作「没有放下书本」的时间状语。"}, "sentence_index": 0, "correct_answer": "终身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终身工作了五年，后来就去了别的城市。", "explanation": "时长：「终身」表示一辈子，不能与「五年」这类有限期限连用；若指有限期限，应该用〈一段时间〉。"}, {"text": "这位工人把终身放进了抽屉里。", "explanation": "物化：这里把「终身」当成了可以放进抽屉的物品，应该用〈物品〉这类实物名词。"}, {"text": "我只想终身休息一下。", "explanation": "近义替换：这里应该用〈暂时〉，「终身」指一辈子，不能与「休息一下」这种短暂的动作搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91075, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "终身", "is_correct": true, "explanation": "正确。「终身没有后悔」指一辈子都没有后悔过，与「终身」的一生含义相符。"}, {"text": "瞬间", "is_correct": false, "explanation": "语义：「瞬间」指极短时间，与「没有后悔」这种长期心态不符。"}, {"text": "片刻", "is_correct": false, "explanation": "语义：「片刻」指很短的一段时间，与一辈子的范围不相符。"}, {"text": "年底", "is_correct": false, "explanation": "搭配：「年底」指一年的末尾，不能作「没有后悔」的时间范围，这里应说「终身」。"}], "explanations": {"终身": "正确。「终身没有后悔」指一辈子都没有后悔过，与「终身」的一生含义相符。", "瞬间": "语义：「瞬间」指极短时间，与「没有后悔」这种长期心态不符。", "片刻": "语义：「片刻」指很短的一段时间，与一辈子的范围不相符。", "年底": "搭配：「年底」指一年的末尾，不能作「没有后悔」的时间范围，这里应说「终身」。"}, "sentence_index": 6, "correct_answer": "终身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份工作是他终身的，干了一周就辞职了。", "explanation": "近义替换：这里应该用〈临时〉，「终身」指一辈子，不能说干了一周就辞职的工作。"}, {"text": "她终身做了一次临时工，第二天就走了。", "explanation": "时长：「终身」指一辈子，与「做了一次」「第二天就走了」这种短暂经历矛盾。"}, {"text": "她终身跳完了一支舞。", "explanation": "时长：这里应该用〈一下子〉，「终身」指一辈子，不能用来形容跳完一支舞这种短暂的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91075, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她终身了都在这个小镇上生活。", "corrected_sentence": "她终身都在这个小镇上生活。", "error_description": "「终身」是时间词，后面不能直接加「了」；应说「终身都在这个小镇上生活」，「了」应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91075, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很终身喜欢收集邮票。", "corrected_sentence": "他终身喜欢收集邮票。", "error_description": "「终身」作状语表示一辈子，不能受「很」修饰；应说「终身喜欢」，不说「很终身喜欢」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
