INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91077, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "公报是正式告诉大家消息的文件。", "primary_collocate": null, "pronunciation": "gōng bào", "ipa": "kʊŋ˥ pɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "政府今天发表了一份公报。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公报说，今年全市人口增加了。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在报纸上读到了这份公报。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份公报只有两页。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府把公报发布在网上，方便大家查看。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公报里写着这次会议的结果。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者认真地看了公报。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家统计局发布了公报，介绍去年的经济情况。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把公报念给大家听。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公报上的消息让大家很高兴。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "联合公报", "label": "复合"}], "register": "正式", "sense_fingerprint": "正式告诉大家消息的文件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0120cb63-e99a-4427-ab15-5932136b311c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91077, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公报", "is_correct": true, "explanation": "公报指正式发布的文件，符合“政府今天发表了一份”的语境。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“发表”用于声明、文章等，不说发表礼物。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不能被发表，与政府的正式行为不符。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐不能被发表，句子说的是正式发布的文件。"}], "explanations": {"公报": "公报指正式发布的文件，符合“政府今天发表了一份”的语境。", "礼物": "搭配：“发表”用于声明、文章等，不说发表礼物。", "蛋糕": "语义：蛋糕不能被发表，与政府的正式行为不符。", "早餐": "语义：早餐不能被发表，句子说的是正式发布的文件。"}, "sentence_index": 0, "correct_answer": "公报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我给朋友写了一份公报，告诉他我的近况。", "explanation": "这里应该用〈信〉。公报是政府或团体正式发布的消息，写给朋友应该用信。"}, {"text": "我昨晚写了一份公报，记录了今天的心情。", "explanation": "这里应该用〈日记〉。公报是政府或团体正式发布的文件，记录个人心情要用日记。"}, {"text": "我在网上发表了一份公报，介绍了我最喜欢的电影。", "explanation": "这里应该用〈影评〉。公报是正式告诉大家消息的文件，介绍喜欢的电影要用影评。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91077, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公报", "is_correct": true, "explanation": "公报指正式发布的文件，是记者认真阅读的对象，符合句意。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“看”的对象应是可见的文字或物品，心情不能被看。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看声音”不这样说，听声音才用“听”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道要用闻或尝来感受，不能用“看”。"}], "explanations": {"公报": "公报指正式发布的文件，是记者认真阅读的对象，符合句意。", "心情": "语义：“看”的对象应是可见的文字或物品，心情不能被看。", "声音": "搭配：“看声音”不这样说，听声音才用“听”。", "味道": "语义：味道要用闻或尝来感受，不能用“看”。"}, "sentence_index": 6, "correct_answer": "公报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在冰箱上贴了一份公报，提醒妈妈买牛奶。", "explanation": "这里应该用〈便条〉。公报是政府或团体正式发布的文件，家人之间提醒小事用便条。"}, {"text": "他把公报吃进了肚子里。", "explanation": "这里把〈公报〉当成了〈食物〉。公报是政府发布的书面文件，不能吃，只能读或看。"}, {"text": "他的个子很高，比公报还高。", "explanation": "这里误把〈公报〉当成了〈人〉。公报是文件，没有身高，不能拿来和人比较高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91077, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市政府今天发布了一场公报，提醒大家注意天气。", "corrected_sentence": "市政府今天发布了一份公报，提醒大家注意天气。", "error_description": "量词错误。错误形式是「一场公报」，「场」用于比赛、演出、雨雪等事件，不能用于公报；公报作为文件应用量词「份」，正确形式是「一份公报」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91077, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "记者在公报看到了新的通知。", "corrected_sentence": "记者在公报上看到了新的通知。", "error_description": "方位词漏掉。错误形式是「在公报看到」，正确形式是「在公报上看到」，表示从文件上看到消息要加方位词「上」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
