INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91078, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "政府、团体正式发布的报告或声明。", "primary_collocate": null, "pronunciation": "gōng bào", "ipa": "kʊŋ˥ pɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "两国发表了联合公报。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议结束后，大会发表了公报。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外交部的公报表示支持这个决定。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公报中说双方会继续合作。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团体向社会发布公报。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份公报是昨天晚上公布的。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公报提到明年要建新医院。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府的公报很正式，用词很严肃。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们读一读这份公报。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里正在播放公报的内容。", "target_word": "公报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "联合公报", "label": "复合"}], "register": "正式", "sense_fingerprint": "政府、团体正式发布的报告或声明", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0120cb63-e99a-4427-ab15-5932136b311c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91078, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公报", "is_correct": true, "explanation": "公报指政府、团体正式发布的声明，符合“两国发表了联合”的语境。"}, {"text": "演出", "is_correct": false, "explanation": "搭配：“发表”用于言论、文章等，不说发表演出。"}, {"text": "宿舍", "is_correct": false, "explanation": "语义：宿舍不能由两国发表，句子说的是正式声明。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐与两国正式发表的内容无关。"}], "explanations": {"公报": "公报指政府、团体正式发布的声明，符合“两国发表了联合”的语境。", "演出": "搭配：“发表”用于言论、文章等，不说发表演出。", "宿舍": "语义：宿舍不能由两国发表，句子说的是正式声明。", "早餐": "语义：早餐与两国正式发表的内容无关。"}, "sentence_index": 0, "correct_answer": "公报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我给女朋友发了一份公报，问她晚上吃什么。", "explanation": "这里应该用〈短信〉。公报是政府、团体正式发布的文件，私人聊天不用公报。"}, {"text": "我在桌上留了一份公报，告诉妈妈我出门了。", "explanation": "这里应该用〈便条〉。公报是正式发布的声明，家人之间留言用便条。"}, {"text": "老板让我写一份公报，总结这个月的销售情况。", "explanation": "这里应该用〈报告〉。公报是政府、团体对外正式发布的消息，公司内部的总结要用报告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公报", "is_correct": true, "explanation": "公报指政府发布的正式声明，符合“提到明年要建新医院”的语境。"}, {"text": "晚饭", "is_correct": false, "explanation": "语义：晚饭不能提到建医院的计划，句子需要能发布声明的主语。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不能提到未来的建设计划。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“提到”的主语应是能说话或发布文件的人或机构，雨伞不能用。"}], "explanations": {"公报": "公报指政府发布的正式声明，符合“提到明年要建新医院”的语境。", "晚饭": "语义：晚饭不能提到建医院的计划，句子需要能发布声明的主语。", "小猫": "语义：小猫不能提到未来的建设计划。", "雨伞": "搭配：“提到”的主语应是能说话或发布文件的人或机构，雨伞不能用。"}, "sentence_index": 6, "correct_answer": "公报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首公报很好听，我每天都唱。", "explanation": "这里应该用〈歌〉。公报是正式发布的文件，不是歌，不能用来说好听或唱。"}, {"text": "他把公报吃进了肚子里。", "explanation": "这里把〈公报〉当成了〈食物〉。公报是政府、团体发布的书面文件，不能吃，只能读或看。"}, {"text": "我的公报比哥哥还高。", "explanation": "这里误把〈公报〉当成了〈人〉。公报是文件，没有身高，不能和人比较高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个组织今天发布了一台公报，宣布了新的目标。", "corrected_sentence": "这个组织今天发布了一份公报，宣布了新的目标。", "error_description": "量词错误。错误形式是「一台公报」，「台」用于机器、节目等，不能用于公报；公报作为文件应用量词「份」，正确形式是「一份公报」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府今天公布了一支公报，宣布了新规定。", "corrected_sentence": "政府今天公布了一份公报，宣布了新规定。", "error_description": "量词错误。错误形式是「一支公报」，「支」用于笔、队伍、歌曲等，不能用于公报；公报作为文件应用量词「份」，正确形式是「一份公报」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
