INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91081, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "共计是把所有的数合在一起算。", "primary_collocate": null, "pronunciation": "gòng jì", "ipa": "kʊŋ˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "这家店上个月的收入共计两万元。", "target_word": "共计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张单子上的费用共计多少钱？", "target_word": "共计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个仓库的货物共计五百箱。", "target_word": "共计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家今年的水电费共计一千元。", "target_word": "共计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年他读的书共计三十本。", "target_word": "共计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这五个人带的箱子共计八个。", "target_word": "共计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中他的得分共计四十分。", "target_word": "共计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师批改的作业共计两百份。", "target_word": "共计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三次考试的分数共计二百六十分。", "target_word": "共计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动共计有五十个人参加。", "target_word": "共计", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共計", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把所有数目合在一起算出总数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3f596a-ea6f-4092-8aea-7d56453cebea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91081, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "共计", "is_correct": true, "explanation": "共计：把所有的数目合在一起算出总数。gòng jì 两个音节都是第四声。"}, {"text": "攻击", "is_correct": false, "explanation": "gōng jī 两个音节都是第一声，与 gòng jì（都是第四声）声调不同。攻击是进攻、抨击的意思。"}, {"text": "供给", "is_correct": false, "explanation": "gōng（第一声）与 gòng（第四声）、jǐ（第三声）与 jì（第四声）声调都不同，供给是供应的意思。"}, {"text": "功绩", "is_correct": false, "explanation": "gōng（第一声）与 gòng（第四声）声调不同，jì 相同，功绩是功劳和成绩的意思。"}], "explanations": {"共计": "共计：把所有的数目合在一起算出总数。gòng jì 两个音节都是第四声。", "攻击": "gōng jī 两个音节都是第一声，与 gòng jì（都是第四声）声调不同。攻击是进攻、抨击的意思。", "供给": "gōng（第一声）与 gòng（第四声）、jǐ（第三声）与 jì（第四声）声调都不同，供给是供应的意思。", "功绩": "gōng（第一声）与 gòng（第四声）声调不同，jì 相同，功绩是功劳和成绩的意思。"}, "sentence_index": null, "correct_answer": "共计"}, "level_3": {"options": [{"text": "共计", "is_correct": true, "explanation": "共计：把所有的收入加起来，说出总额，这里说的是这家店的收入总数。"}, {"text": "支付", "is_correct": false, "explanation": "搭配：“支付”指付出钱款，不能与“收入”搭配，“收入支付两万元”不通。"}, {"text": "赔偿", "is_correct": false, "explanation": "搭配：“赔偿”指补偿损失，不能说“收入赔偿两万元”。"}, {"text": "说明", "is_correct": false, "explanation": "语义：“说明”是解释的意思，与表示收入数量的句子无关，句子不通。"}], "explanations": {"共计": "共计：把所有的收入加起来，说出总额，这里说的是这家店的收入总数。", "支付": "搭配：“支付”指付出钱款，不能与“收入”搭配，“收入支付两万元”不通。", "赔偿": "搭配：“赔偿”指补偿损失，不能说“收入赔偿两万元”。", "说明": "语义：“说明”是解释的意思，与表示收入数量的句子无关，句子不通。"}, "sentence_index": 0, "correct_answer": "共计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的服务共计很周到，客人都很满意。", "explanation": "这里应该用〈非常〉修饰形容词“周到”。“共计”只表示合起来算总数，不能用来形容服务的质量。"}, {"text": "他下班以后共计跑到了公园。", "explanation": "这里应该用〈就〉。“共计”只表示合起来算总数，不能表示先后的动作或移动，应说“下班以后就跑到了公园”。"}, {"text": "我和朋友共计商量了一下周末的安排。", "explanation": "这里应该用〈合计〉。“共计”没有商量的意思，商量才用“合计”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91081, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共计", "is_correct": true, "explanation": "共计：把各次的得分加起来，说出总分，这里说的是他比赛中的总分。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与得分无关，句子不通。"}, {"text": "转让", "is_correct": false, "explanation": "搭配：“转让”指把权利或物品让给别人，不能与“得分”搭配。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”指把东西给别人，与比赛中的得分情境不符，句子不通。"}], "explanations": {"共计": "共计：把各次的得分加起来，说出总分，这里说的是他比赛中的总分。", "吃": "语义：“吃”指进食，与得分无关，句子不通。", "转让": "搭配：“转让”指把权利或物品让给别人，不能与“得分”搭配。", "送": "语义：“送”指把东西给别人，与比赛中的得分情境不符，句子不通。"}, "sentence_index": 6, "correct_answer": "共计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师共计生气了，因为学生迟到。", "explanation": "这里应该用〈马上〉。“共计”表示合起来算总数，不能用来表示情绪的变化。"}, {"text": "我们共计下午去超市。", "explanation": "这里应该用〈计划〉。“共计”表示合起来算总数，不能用来安排将来的活动。"}, {"text": "妈妈共计把房间打扫得很干净。", "explanation": "这里应该用〈亲自〉。“共计”表示合起来算总数，不能用在“把”字句的动作前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91081, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月的房租共计了两千元。", "corrected_sentence": "这个月的房租共计两千元。", "error_description": "体标错误：“共计”不能加“了”，“共计了两千元”不成立。应说“这个月的房租共计两千元”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91081, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个学期的作业共计着二十页。", "corrected_sentence": "这个学期的作业共计二十页。", "error_description": "体标错误：“共计”表示总数，不能带“着”，应直接接数量：“共计二十页”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
