INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91083, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用笔和颜色画出图画。", "primary_collocate": null, "pronunciation": "huì huà", "ipa": "xweɪ˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们在纸上绘画。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拿着彩笔在墙上绘画。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常常在公园里绘画。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边听音乐一边绘画。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天下午在教室里绘画了两个小时。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们在黑板上绘画。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会绘画，只会写字。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她安静地坐在窗边绘画。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢用蜡笔绘画。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他绘画的时候，不喜欢别人说话。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "绘画了", "label": "体标（了）"}, {"form": "绘画过", "label": "体标（过）"}, {"form": "繪畫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：用笔和颜色画画这一动作，常带地点、工具状语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c21081-19c8-4e43-9122-d082b2713663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91083, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绘画", "is_correct": true, "explanation": "正确：绘画是动词，指用笔和颜色画画，与“在纸上”相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉不能在纸上进行，与“在纸上”冲突。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能说“在纸上煮”。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物或身体，不能说“在纸上洗”。"}], "explanations": {"绘画": "正确：绘画是动词，指用笔和颜色画画，与“在纸上”相符。", "睡觉": "语义：睡觉不能在纸上进行，与“在纸上”冲突。", "煮": "搭配：“煮”的对象是食物，不能说“在纸上煮”。", "洗": "搭配：“洗”的对象是衣物或身体，不能说“在纸上洗”。"}, "sentence_index": 0, "correct_answer": "绘画"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在纸上绘画了作业。", "explanation": "这里应该用〈做〉。“绘画”只指用笔画图，不能指做作业，做作业要用〈做〉。"}, {"text": "这篇文章绘画春天的美景。", "explanation": "这里应该用〈描绘〉。文章写景要用〈描绘〉，“绘画”只指用笔和颜色作画。"}, {"text": "工人在墙上绘画一张地图。", "explanation": "这里应该用〈绘制〉。地图、图表要用〈绘制〉，“绘画”指艺术创作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91083, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绘画", "is_correct": true, "explanation": "正确：绘画是动词，指画画这一技能，与“只会写字”形成对比。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：呼吸是本能，不是可以“会”的技能，句意不通。"}, {"text": "眨眼", "is_correct": false, "explanation": "语义：眨眼是本能动作，不是技能，与“不会”搭配不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“会”一般接技能，“吃饭”是本能行为，不说“不会吃饭”表示技能。"}], "explanations": {"绘画": "正确：绘画是动词，指画画这一技能，与“只会写字”形成对比。", "呼吸": "语义：呼吸是本能，不是可以“会”的技能，句意不通。", "眨眼": "语义：眨眼是本能动作，不是技能，与“不会”搭配不通。", "吃饭": "搭配：“会”一般接技能，“吃饭”是本能行为，不说“不会吃饭”表示技能。"}, "sentence_index": 6, "correct_answer": "绘画"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用刀绘画西瓜。", "explanation": "这里应该用〈切〉。“绘画”指用笔作画，不能用刀操作，用刀分开西瓜要用〈切〉。"}, {"text": "他每天在跑步机上绘画一个小时。", "explanation": "这里应该用〈跑步〉。“绘画”指用笔画图，不能指在跑步机上运动，这里要用〈跑步〉。"}, {"text": "我们一起去绘画电影。", "explanation": "这里应该用〈拍〉。“绘画”指用笔画图，不能指摄制电影，拍电影要用〈拍〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91083, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小明书桌前绘画。", "corrected_sentence": "小明在书桌前绘画。", "error_description": "介词错误：地点状语“书桌前”前漏掉介词“在”，应写作“小明在书桌前绘画”；“小明书桌前绘画”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91083, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在窗边绘画地很好。", "corrected_sentence": "她在窗边绘画得很好。", "error_description": "助词错误：动词“绘画”后的补语前应用“得”，写作“绘画得很好”；“地”用于动词前作状语，放在补语前不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
