INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91084, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用线条和色彩在平面上描绘出形象的造型艺术；画画。", "primary_collocate": null, "pronunciation": "huì huà", "ipa": "xweɪ˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "我很喜欢中国的传统绘画。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家美术馆有很多现代绘画。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绘画需要耐心，也需要想象力。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小学习绘画，现在是画家。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的绘画作品在北京展出了。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绘画和音乐都是我爱好的艺术。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师教孩子们绘画和书法。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西方绘画常常用油彩。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有很多唐代绘画。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对绘画很有兴趣，周末常去看展览。", "target_word": "绘画", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "繪畫", "label": "繁体"}, {"form": "绘画作品", "label": "复合"}, {"form": "绘画课", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：作为造型艺术门类的绘画，如传统绘画、现代绘画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c21081-19c8-4e43-9122-d082b2713663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91084, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绘画", "is_correct": true, "explanation": "正确：绘画指作为艺术门类的画画，与“中国的传统”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不属于文化艺术，“传统”修饰的不是天气，句意不通。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是现代交通工具，不能说“传统地铁”。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“传统”修饰文化类事物，不能修饰疾病“感冒”。"}], "explanations": {"绘画": "正确：绘画指作为艺术门类的画画，与“中国的传统”相符。", "天气": "语义：天气不属于文化艺术，“传统”修饰的不是天气，句意不通。", "地铁": "语义：地铁是现代交通工具，不能说“传统地铁”。", "感冒": "搭配：“传统”修饰文化类事物，不能修饰疾病“感冒”。"}, "sentence_index": 0, "correct_answer": "绘画"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位著名的绘画，作品很多。", "explanation": "这里应该用〈画家〉。“绘画”指艺术门类，不能指人，画画的人要用〈画家〉。"}, {"text": "我每天晚上都听绘画，很放松。", "explanation": "这里应该用〈音乐〉。“绘画”是用眼睛欣赏的艺术，不能用“听”；放松地听要用〈音乐〉。"}, {"text": "妈妈把绘画放进锅里煮了。", "explanation": "这里应该用〈菜〉。“绘画”指艺术门类，不能放进锅里煮，煮的对象是〈菜〉这类食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91084, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绘画", "is_correct": true, "explanation": "正确：绘画指作为艺术门类的画画，与“教孩子们”和“书法”并列相符。"}, {"text": "汽油", "is_correct": false, "explanation": "搭配：“教”的对象是可以学会的技能，“汽油”不能被教。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，不是可以教的内容，与句意不符。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒是微生物，不能用来教给孩子，句意荒谬。"}], "explanations": {"绘画": "正确：绘画指作为艺术门类的画画，与“教孩子们”和“书法”并列相符。", "汽油": "搭配：“教”的对象是可以学会的技能，“汽油”不能被教。", "地震": "语义：地震是自然灾害，不是可以教的内容，与句意不符。", "病毒": "语义：病毒是微生物，不能用来教给孩子，句意荒谬。"}, "sentence_index": 6, "correct_answer": "绘画"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的绘画很好吃。", "explanation": "这里应该用〈菜〉。“绘画”指艺术门类，不能吃，形容味道好要用〈菜〉。"}, {"text": "他在舞台上唱绘画。", "explanation": "这里应该用〈歌〉。“绘画”是看的艺术，不能用“唱”，唱的对象是〈歌〉。"}, {"text": "我们在花园里种绘画。", "explanation": "这里应该用〈花〉。“绘画”不能种植，种的对象是〈花〉之类的植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只绘画很有名，很多人都喜欢。", "corrected_sentence": "这幅绘画很有名，很多人都喜欢。", "error_description": "量词错误：“只”用于动物，绘画作品应该用“幅”，写作“这幅绘画”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位画家的很绘画作品很受欢迎。", "corrected_sentence": "这位画家的绘画作品很受欢迎。", "error_description": "程度副词「很」不能修饰名词「绘画作品」，应删去「很」，写作「这位画家的绘画作品很受欢迎」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
