INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91085, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "再现是以前的事又出现在眼前。", "primary_collocate": null, "pronunciation": "zài xiàn", "ipa": "tsaɪ̯˥˩ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "看到老照片，小时候的事在眼前再现。", "target_word": "再现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一闻到这个味道，童年的生活就再现了。", "target_word": "再现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人闭上眼睛，战争的情景在脑海里再现。", "target_word": "再现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听着这首老歌，那个夏天的画面再现了。", "target_word": "再现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回到老家后，小时候玩游戏的样子在眼前再现。", "target_word": "再现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每次走过那条路，当年的情景都会再现。", "target_word": "再现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完那部老电影，过去的日子仿佛再现了。", "target_word": "再现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那场大雨过后，往事一幕一幕地再现。", "target_word": "再现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈做的饺子让我小时候的快乐再现了。", "target_word": "再现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在梦里，十年前的那个晚上再现了。", "target_word": "再现", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "再现了", "label": "体标（了）"}, {"form": "再现过", "label": "体标（过）"}], "register": "书面", "sense_fingerprint": "往事、情景重新浮现在眼前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5a0525c-6c30-4575-ae39-cf48177bb3a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91085, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再现", "is_correct": true, "explanation": "正确：“再现”表示往事重新出现在眼前，与看到老照片的语境相符。"}, {"text": "消失", "is_correct": false, "explanation": "语义：“消失”指不见了，与看到老照片后往事重新浮现的语境相反。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”需要具体的物件作宾语，不能用来说往事。"}, {"text": "切割", "is_correct": false, "explanation": "搭配：“切割”指把东西分开，不能用来形容往事出现在眼前。"}], "explanations": {"再现": "正确：“再现”表示往事重新出现在眼前，与看到老照片的语境相符。", "消失": "语义：“消失”指不见了，与看到老照片后往事重新浮现的语境相反。", "修理": "搭配：“修理”需要具体的物件作宾语，不能用来说往事。", "切割": "搭配：“切割”指把东西分开，不能用来形容往事出现在眼前。"}, "sentence_index": 0, "correct_answer": "再现"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一个陌生的人在门口再现了，我吓了一跳。", "explanation": "这里应该用〈出现〉。再现指以前的事物重新出现，初次出现的人不能用再现。"}, {"text": "这座新城很快在荒地上再现了。", "explanation": "这里应该用〈诞生〉。再现指以前的事又出现，全新事物第一次出现要用诞生。"}, {"text": "这个新计划昨天才再现。", "explanation": "这里应该用〈提出〉。再现指以前的事又出现，新计划第一次出现要用提出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91085, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再现", "is_correct": true, "explanation": "正确：“再现”表示过去的日子重新浮现，与看完老电影的语境相符。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”指拆掉建筑或设施，不能用来说日子。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”针对房屋或空间，不能用来说过去的日子。"}, {"text": "粉碎", "is_correct": false, "explanation": "语义：“粉碎”指彻底打碎，与看完老电影后往事重新浮现的语境相反。"}], "explanations": {"再现": "正确：“再现”表示过去的日子重新浮现，与看完老电影的语境相符。", "拆除": "搭配：“拆除”指拆掉建筑或设施，不能用来说日子。", "装修": "搭配：“装修”针对房屋或空间，不能用来说过去的日子。", "粉碎": "语义：“粉碎”指彻底打碎，与看完老电影后往事重新浮现的语境相反。"}, "sentence_index": 6, "correct_answer": "再现"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的新想法在脑海里再现出来，很清楚。", "explanation": "这里应该用〈浮现〉。再现指以前的事物重新出现，新想法首次出现不能用再现。"}, {"text": "这款新产品在昨天的发布会上再现了。", "explanation": "这里应该用〈亮相〉。再现指以前的事又出现，新产品第一次露面要用亮相。"}, {"text": "科学家再现了一颗新的星球。", "explanation": "这里应该用〈发现〉。再现要求事物以前出现过，首次发现的星球不能用再现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91085, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那首歌一响起，我的童年就眼前再现了。", "corrected_sentence": "那首歌一响起，我的童年就在眼前再现了。", "error_description": "错误：“再现”表示事物在某处重新出现，地点要用介词“在”引出，漏掉“在”。正确：“就在眼前再现了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91085, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "看着老照片，过去的事又把心里再现了。", "corrected_sentence": "看着老照片，过去的事又在心里再现了。", "error_description": "错误：表示地点要用介词“在”引出，不能用“把”。正确：“又在心里再现了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
