INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91086, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "再次出现；重新显示出来。", "primary_collocate": null, "pronunciation": "zài xiàn", "ipa": "tsaɪ̯˥˩ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这部电影再现了一百年前的上海。", "target_word": "再现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "画家用画笔再现了山村的春天。", "target_word": "再现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个博物馆用模型再现了古代的市场。", "target_word": "再现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书把当年的生活真实地再现出来。", "target_word": "再现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望学生能在作文里再现那天的情景。", "target_word": "再现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一实验结果在第二次实验中再现了。", "target_word": "再现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏能让比赛的精彩画面再现。", "target_word": "再现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些旧照片再现了小镇过去的样子。", "target_word": "再现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作人员用电脑再现了那场事故的经过。", "target_word": "再现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台上再现了古代宫廷的热闹场面。", "target_word": "再现", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "再现了", "label": "体标（了）"}, {"form": "再现过", "label": "体标（过）"}], "register": "书面", "sense_fingerprint": "再次出现；用艺术或技术手段重新显示", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5a0525c-6c30-4575-ae39-cf48177bb3a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91086, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再现", "is_correct": true, "explanation": "正确：“再现”表示用影像等手段重新显示一百年前的上海，与句意相符。"}, {"text": "忘记", "is_correct": false, "explanation": "搭配：电影不能主动忘记，“忘记”需要有意识的主体。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”表示吞食，与电影描绘历史的意思不符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”指修补物件，不能用来说电影呈现的内容。"}], "explanations": {"再现": "正确：“再现”表示用影像等手段重新显示一百年前的上海，与句意相符。", "忘记": "搭配：电影不能主动忘记，“忘记”需要有意识的主体。", "吃掉": "语义：“吃掉”表示吞食，与电影描绘历史的意思不符。", "修理": "搭配：“修理”指修补物件，不能用来说电影呈现的内容。"}, "sentence_index": 0, "correct_answer": "再现"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作者再现了一本新书，书中讲述了这段历史。", "explanation": "这里应该用〈出版〉。再现指重新显示，不表示首次印刷发行新书。"}, {"text": "工程师再现了一种新机器。", "explanation": "这里应该用〈创造〉。再现指重新显示已有的事物，不表示创造全新的东西。"}, {"text": "这种病毒第一次再现在这个城市。", "explanation": "这里应该用〈出现〉。再现表示再次出现，病毒第一次出现不能用再现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再现", "is_correct": true, "explanation": "正确：“再现”表示让比赛的精彩画面重新显示，与句意一致。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”指去掉，与“能让画面重新显示”的意思相反。"}, {"text": "消毒", "is_correct": false, "explanation": "搭配：“消毒”针对物品或环境，不能用来说比赛画面。"}, {"text": "哄骗", "is_correct": false, "explanation": "搭配：“哄骗”的对象是人，不能用来说画面。"}], "explanations": {"再现": "正确：“再现”表示让比赛的精彩画面重新显示，与句意一致。", "删除": "语义：“删除”指去掉，与“能让画面重新显示”的意思相反。", "消毒": "搭配：“消毒”针对物品或环境，不能用来说比赛画面。", "哄骗": "搭配：“哄骗”的对象是人，不能用来说画面。"}, "sentence_index": 6, "correct_answer": "再现"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂再现了一批新的玩具。", "explanation": "这里应该用〈生产〉。再现表示以前的事物重新显示，批量制造全新的东西要用生产。"}, {"text": "大火再现了整个村庄。", "explanation": "这里应该用〈销毁〉。再现是重新显示，不表示毁掉东西。"}, {"text": "他第一次来到这个城市，这里的一切都再现了。", "explanation": "这里应该用〈映入眼帘〉。再现指以前的事物重新显示，第一次见到的景象不能用再现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套模型在再现了古代村庄的样子。", "corrected_sentence": "这套模型再现了古代村庄的样子。", "error_description": "错误：“在”误作进行标记，与表示完成的“了”冲突；“再现”前不加“在”。正确：“这套模型再现了古代村庄的样子。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次展览将再现了那个年代的街道。", "corrected_sentence": "这次展览将再现那个年代的街道。", "error_description": "错误：“将”表示将来，“了”表示动作已完成，二者矛盾。正确：去掉“了”，“这次展览将再现那个年代的街道。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
