INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91087, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "平常的人们，不是大官的人。", "primary_collocate": null, "pronunciation": "lǎo bǎi xìng", "ipa": "lau²¹⁴ pai²¹⁴ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "他是个老百姓，不是什么大官。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长常去村里，和老百姓聊天。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官员应该为老百姓做事。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家是老百姓，没有当官的亲戚。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓都说他是个好官。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓有话，可以直接对市长说。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了大官，可是还像老百姓一样生活。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓的日子好了，官员也高兴。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新政策出来了，老百姓最关心价格。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官员坐车去上班，老百姓多坐公交车。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "百姓", "label": "简称"}], "register": "口语", "sense_fingerprint": "与官员相对的普通人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2c25b5f-321c-4d4e-a8d4-6527f919495c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91087, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老百姓", "is_correct": true, "explanation": "正确。与后句「不是什么大官」相对，指平常的普通人，句意连贯。"}, {"text": "大官", "is_correct": false, "explanation": "语义：前半句说「他是个大官」，后半句又说「不是什么大官」，自相矛盾。"}, {"text": "首相", "is_correct": false, "explanation": "语义：首相是最高级别的官员，与「不是什么大官」的语义相抵触。"}, {"text": "皇帝", "is_correct": false, "explanation": "语义：皇帝是最高统治者，「他是个皇帝，不是什么大官」自相矛盾。"}], "explanations": {"老百姓": "正确。与后句「不是什么大官」相对，指平常的普通人，句意连贯。", "大官": "语义：前半句说「他是个大官」，后半句又说「不是什么大官」，自相矛盾。", "首相": "语义：首相是最高级别的官员，与「不是什么大官」的语义相抵触。", "皇帝": "语义：皇帝是最高统治者，「他是个皇帝，不是什么大官」自相矛盾。"}, "sentence_index": 0, "correct_answer": "老百姓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家幼儿园的老百姓都很可爱，每天都爱画画。", "explanation": "这里是把〈老百姓〉当成「小朋友」来用，它指平常的普通人，不指孩子。"}, {"text": "他是市政府的老百姓，专门负责审批。", "explanation": "这里是把〈老百姓〉当成掌握权力的人来用，它指平常的普通人，不指有权力的官员。"}, {"text": "这次会议请来的专家是一位老百姓，他连基本理论都不懂。", "explanation": "这里是把〈老百姓〉用来指有专业身份的人，但它只指平常的普通人，不指这类人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91087, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老百姓", "is_correct": true, "explanation": "正确。「当了大官」与「还像……一样生活」形成对照，指朴素的普通人，句意连贯。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会生活，「像石头一样生活」与句意不合。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不会生活，「像木头一样生活」与句意不合。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：「像鱼一样生活」不能描述人的生活方式，句意不通。"}], "explanations": {"老百姓": "正确。「当了大官」与「还像……一样生活」形成对照，指朴素的普通人，句意连贯。", "石头": "语义：石头不会生活，「像石头一样生活」与句意不合。", "木头": "语义：木头不会生活，「像木头一样生活」与句意不合。", "鱼": "语义：「像鱼一样生活」不能描述人的生活方式，句意不通。"}, "sentence_index": 6, "correct_answer": "老百姓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在电影里演老百姓演员。", "explanation": "这里应该用〈群众〉。“群众演员”是固定说法，“老百姓演员”不这样说。"}, {"text": "我们必须坚持老百姓路线，不能脱离实际。", "explanation": "这里应该用〈群众〉。「群众路线」是固定词组，「老百姓路线」不这样说。"}, {"text": "这个老百姓区环境很好，适合居住。", "explanation": "这里应该用〈居民〉。「居民区」是固定说法，「老百姓区」不成词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91087, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只老百姓向市长提了意见。", "corrected_sentence": "那个老百姓向市长提了意见。", "error_description": "错误：量词「只」。正确：量词「个」。「老百姓」指人，「只」用于动物等，应说「那个老百姓」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91087, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张老百姓很爱帮助别人。", "corrected_sentence": "这个老百姓很爱帮助别人。", "error_description": "错误：量词「张」。正确：量词「个」。「老百姓」指人，「张」用于纸、桌子等，不能用来数人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
