INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91088, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "普通的民众；平民。", "primary_collocate": null, "pronunciation": "lǎo bǎi xìng", "ipa": "lau²¹⁴ pai²¹⁴ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "老百姓最怕物价上涨。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束了，老百姓终于能回家。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓都爱看这个电视节目。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多老百姓晚上喜欢去公园散步。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆很便宜，老百姓都吃得起。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争时，老百姓和士兵都很苦。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓每天都要买菜做饭。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新地铁开了，老百姓上班方便了。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些东西很贵，老百姓买不起。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓过年时喜欢和家人吃饺子。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "百姓", "label": "简称"}], "register": "口语", "sense_fingerprint": "普通民众、平民", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2c25b5f-321c-4d4e-a8d4-6527f919495c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91088, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老百姓", "is_correct": true, "explanation": "正确。指普通民众，「最怕物价上涨」符合人的心理，句意通顺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有感情，不能「怕」物价上涨。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子没有感情，不能说「最怕」。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑没有感情，不能「最怕」物价上涨，与句意不合。"}], "explanations": {"老百姓": "正确。指普通民众，「最怕物价上涨」符合人的心理，句意通顺。", "石头": "语义：石头没有感情，不能「怕」物价上涨。", "房子": "语义：房子没有感情，不能说「最怕」。", "电脑": "语义：电脑没有感情，不能「最怕」物价上涨，与句意不合。"}, "sentence_index": 0, "correct_answer": "老百姓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家医院的老百姓都是医生，每天忙着看病。", "explanation": "这里是把〈老百姓〉当成有专业身份的职业人员来用，它指平常的普通人，不指这类人。"}, {"text": "他是公司的老百姓，负责管钱。", "explanation": "这里是把〈老百姓〉当成掌握权力的人来用，它指普通民众，不指掌握钱财的人。"}, {"text": "这家店的老百姓都是老板，说话很有权威。", "explanation": "这里是把〈老百姓〉当成有权力的人来用，它指平常的普通人，不指掌权的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91088, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老百姓", "is_correct": true, "explanation": "正确。指普通民众，「每天都要买菜做饭」是普通人的日常，句意通顺。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗不会买菜做饭，与句意不合。"}, {"text": "太子", "is_correct": false, "explanation": "语义：太子身份尊贵，一般不做买菜做饭的家务，与句意相抵触。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会买菜做饭，与句意不合。"}], "explanations": {"老百姓": "正确。指普通民众，「每天都要买菜做饭」是普通人的日常，句意通顺。", "狗": "语义：狗不会买菜做饭，与句意不合。", "太子": "语义：太子身份尊贵，一般不做买菜做饭的家务，与句意相抵触。", "石头": "语义：石头不会买菜做饭，与句意不合。"}, "sentence_index": 6, "correct_answer": "老百姓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个商店只收老百姓币。", "explanation": "这里应该用〈人民〉。「人民币」是固定说法，不能换成「老百姓」。"}, {"text": "他在电影里演老百姓演员。", "explanation": "这里应该用〈群众〉。「群众演员」是固定说法，「老百姓演员」不这样说。"}, {"text": "这栋老百姓楼很旧了。", "explanation": "这里应该用〈居民〉。「居民楼」是固定说法，「老百姓楼」不成词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91088, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条老百姓家里有三个孩子。", "corrected_sentence": "那位老百姓家里有三个孩子。", "error_description": "错误：量词「条」。正确：量词「位」或「个」。「老百姓」指人，「条」不能用来数人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91088, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只老百姓每天都早起散步。", "corrected_sentence": "这个老百姓每天都早起散步。", "error_description": "错误：量词「只」。正确：量词「个」。「老百姓」指人，「只」用于动物等，不能用来数人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91089, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死路", "is_correct": true, "explanation": "反义：“死路”指走不通的路，与“出路”相对。"}, {"text": "河流", "is_correct": false, "explanation": "“河流”是自然景物，与“出路”没有反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "“桌子”是家具，与“出路”没有反义关系。"}, {"text": "天空", "is_correct": false, "explanation": "“天空”是自然景物，与“出路”没有反义关系。"}], "correct_answer": "死路", "explanations": {"死路": "反义：“死路”指走不通的路，与“出路”相对。", "河流": "“河流”是自然景物，与“出路”没有反义关系。", "桌子": "“桌子”是家具，与“出路”没有反义关系。", "天空": "“天空”是自然景物，与“出路”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91089, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "绝路", "is_correct": true, "explanation": "反义：“绝路”指没有出路、无法摆脱的境地，与“出路”相对。"}, {"text": "山峰", "is_correct": false, "explanation": "“山峰”是地形名词，与“出路”没有反义关系。"}, {"text": "书包", "is_correct": false, "explanation": "“书包”是学习用品，与“出路”没有反义关系。"}, {"text": "雨水", "is_correct": false, "explanation": "“雨水”是自然现象，与“出路”没有反义关系。"}], "correct_answer": "绝路", "explanations": {"绝路": "反义：“绝路”指没有出路、无法摆脱的境地，与“出路”相对。", "山峰": "“山峰”是地形名词，与“出路”没有反义关系。", "书包": "“书包”是学习用品，与“出路”没有反义关系。", "雨水": "“雨水”是自然现象，与“出路”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91089, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "出路是能走出去的路，也是以后能走的好办法。", "primary_collocate": null, "pronunciation": "chū lù", "ipa": "ʈʂʰu˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "这条小巷是死胡同，没有出路。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在森林里走了一天，没找到出路。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个迷宫很复杂，我们找了半天才看到出路。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作丢了以后，他很担心以后的出路。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师帮学生想以后的出路。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意亏了，我们得想想新的出路。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李说，学好英语，以后出路更多。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要不放弃，总会有出路的。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得种地没有出路，所以去了城里。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对困难，哭是没有出路的，要想办法。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条出路", "label": "量词"}], "register": "中性", "sense_fingerprint": "出路：能走出去的路，也指以后可走的好办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '014adc03-4858-4184-a9b1-120df8f0a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91089, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出路", "is_correct": true, "explanation": "正确答案：出路（chū lù），指能走出去的路，也指以后可走的好办法。"}, {"text": "出力", "is_correct": false, "explanation": "lù（第四声）与 lì（第四声）韵母不同，一个是 u，一个是 i。“出力”意思是出力气、尽力。"}, {"text": "处理", "is_correct": false, "explanation": "chū 与 chǔ 声调不同，lù 与 lǐ 韵母和声调都不同（u 与 i）。“处理”意思是处置、办理。"}, {"text": "出炉", "is_correct": false, "explanation": "lù（第四声）与 lú（第二声）声调不同。“出炉”意思是从炉子里取出成品。"}], "explanations": {"出路": "正确答案：出路（chū lù），指能走出去的路，也指以后可走的好办法。", "出力": "lù（第四声）与 lì（第四声）韵母不同，一个是 u，一个是 i。“出力”意思是出力气、尽力。", "处理": "chū 与 chǔ 声调不同，lù 与 lǐ 韵母和声调都不同（u 与 i）。“处理”意思是处置、办理。", "出炉": "lù（第四声）与 lú（第二声）声调不同。“出炉”意思是从炉子里取出成品。"}, "sentence_index": null, "correct_answer": "出路"}, "level_3": {"options": [{"text": "尽头", "is_correct": false, "explanation": "语义：死胡同本身就是路的尽头，“没有尽头”与句意矛盾。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“没有时间”说的是人的安排，不能用来描述小巷。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：“朋友”指人，小巷不能“没有朋友”。"}, {"text": "出路", "is_correct": true, "explanation": "正确：“出路”指能走出去的路，死胡同恰恰没有可以走出去的路。"}], "explanations": {"尽头": "语义：死胡同本身就是路的尽头，“没有尽头”与句意矛盾。", "时间": "搭配：“没有时间”说的是人的安排，不能用来描述小巷。", "朋友": "语义：“朋友”指人，小巷不能“没有朋友”。", "出路": "正确：“出路”指能走出去的路，死胡同恰恰没有可以走出去的路。"}, "sentence_index": 0, "correct_answer": "出路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用一条出路修好了自行车。", "explanation": "这里应该用〈扳手〉。修自行车要用工具，“出路”不能作修理的工具。"}, {"text": "我给他端了一杯出路。", "explanation": "这里应该用〈茶〉。“一杯”后面应是能盛在杯中的饮品，“出路”不能盛在杯里，也不能被端。"}, {"text": "他把这条出路贴在墙上了。", "explanation": "这里应该用〈告示〉。“贴”的对象是告示、海报等纸张，“出路”不是可以贴的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91089, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "出路", "is_correct": true, "explanation": "正确答案：出路（chū lù）。"}, {"text": "出入", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），两者都是第四声。“出入”意思是进出。"}, {"text": "出租", "is_correct": false, "explanation": "lù 与 zū 声母不同（l 与 z），声调也不同（第四声与第一声）。“出租”意思是把东西租给别人。"}, {"text": "出炉", "is_correct": false, "explanation": "lù（第四声）与 lú（第二声）声调不同。“出炉”意思是从炉子里取出成品。"}], "explanations": {"出路": "正确答案：出路（chū lù）。", "出入": "lù 与 rù 声母不同（l 与 r），两者都是第四声。“出入”意思是进出。", "出租": "lù 与 zū 声母不同（l 与 z），声调也不同（第四声与第一声）。“出租”意思是把东西租给别人。", "出炉": "lù（第四声）与 lú（第二声）声调不同。“出炉”意思是从炉子里取出成品。"}, "sentence_index": null, "correct_answer": "出路"}, "level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“以后天气更多”没有意义，“学好英语”的好处应与发展机会相关。"}, {"text": "水果", "is_correct": false, "explanation": "语义：“水果”是食物，学好英语不会带来更多水果。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“感冒”指疾病，“以后感冒更多”与“学好英语”没有关联，搭配不当。"}, {"text": "出路", "is_correct": true, "explanation": "正确：“出路”指以后可以走的路，学好英语能带来更多发展机会。"}], "explanations": {"天气": "语义：“以后天气更多”没有意义，“学好英语”的好处应与发展机会相关。", "水果": "语义：“水果”是食物，学好英语不会带来更多水果。", "感冒": "搭配：“感冒”指疾病，“以后感冒更多”与“学好英语”没有关联，搭配不当。", "出路": "正确：“出路”指以后可以走的路，学好英语能带来更多发展机会。"}, "sentence_index": 6, "correct_answer": "出路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用红色出路画了一幅画。", "explanation": "这里应该用〈颜料〉。画画要用颜料，“出路”不能作画画的材料。"}, {"text": "他昨天读完了出路。", "explanation": "这里应该用〈书〉。“读”的对象是书，“出路”不能被读。"}, {"text": "我查了一下出路，找到了这个字。", "explanation": "这里应该用〈词典〉。查字要用词典，“出路”不能用来查字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91089, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在森林里走了很久，终于找到了一条很窄出路。", "corrected_sentence": "他在森林里走了很久，终于找到了一条很窄的出路。", "error_description": "“很窄”修饰名词“出路”时要加“的”，应说“很窄的出路”，漏掉“的”不合语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91089, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "只要有决心，就会有一只出路。", "corrected_sentence": "只要有决心，就会有一条出路。", "error_description": "“出路”的量词要用“条”，应说“一条出路”，不能说“一只出路”；“只”用于动物等，不能搭配“出路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
