INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91090, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死路", "is_correct": true, "explanation": "反义：“死路”指走不通的路，与“出路”相对。"}, {"text": "山峰", "is_correct": false, "explanation": "“山峰”是地形名词，与“出路”没有反义关系。"}, {"text": "书包", "is_correct": false, "explanation": "“书包”是学习用品，与“出路”没有反义关系。"}, {"text": "雨水", "is_correct": false, "explanation": "“雨水”是自然现象，与“出路”没有反义关系。"}], "correct_answer": "死路", "explanations": {"死路": "反义：“死路”指走不通的路，与“出路”相对。", "山峰": "“山峰”是地形名词，与“出路”没有反义关系。", "书包": "“书包”是学习用品，与“出路”没有反义关系。", "雨水": "“雨水”是自然现象，与“出路”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91090, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "通向外面的道路；比喻解决困难的办法或前途。", "primary_collocate": null, "pronunciation": "chū lù", "ipa": "ʈʂʰu˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "这家小工厂没有订单，老板在找新的出路。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的年轻人想在城里找一条出路。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只读书不实践，毕业后很难找到出路。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起讨论，终于想出了一条出路。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，学一门技术就是孩子最好的出路。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司亏了很多钱，他看不到出路。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个专业的毕业生出路很宽。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在山洞里转了很久，还是找不到出路。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走廊里烟很大，他在黑暗中摸索着找出路。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得只有考上大学，才有出路。", "target_word": "出路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条出路", "label": "量词"}], "register": "中性", "sense_fingerprint": "出路：摆脱困境的办法或前途，也指通向外面的道路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '014adc03-4858-4184-a9b1-120df8f0a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91090, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出路", "is_correct": true, "explanation": "正确答案：出路（chū lù），指通向外面的道路，也指摆脱困境的办法或前途。"}, {"text": "出力", "is_correct": false, "explanation": "lù（第四声）与 lì（第四声）韵母不同，一个是 u，一个是 i。“出力”意思是出力气、尽力。"}, {"text": "处理", "is_correct": false, "explanation": "chū 与 chǔ 声调不同，lù 与 lǐ 韵母和声调都不同（u 与 i）。“处理”意思是处置、办理。"}, {"text": "出炉", "is_correct": false, "explanation": "lù（第四声）与 lú（第二声）声调不同。“出炉”意思是从炉子里取出成品。"}], "explanations": {"出路": "正确答案：出路（chū lù），指通向外面的道路，也指摆脱困境的办法或前途。", "出力": "lù（第四声）与 lì（第四声）韵母不同，一个是 u，一个是 i。“出力”意思是出力气、尽力。", "处理": "chū 与 chǔ 声调不同，lù 与 lǐ 韵母和声调都不同（u 与 i）。“处理”意思是处置、办理。", "出炉": "lù（第四声）与 lú（第二声）声调不同。“出炉”意思是从炉子里取出成品。"}, "sentence_index": null, "correct_answer": "出路"}, "level_3": {"options": [{"text": "工资", "is_correct": false, "explanation": "搭配：“找”的对象不能是“工资”，句中是在找解决困境的办法，不说“找新的工资”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性格或情绪，与“没有订单”的困境无关，老板不会去“找”脾气。"}, {"text": "笑容", "is_correct": false, "explanation": "语义：“笑容”是表情，老板不会去找新的笑容，与没有订单的困境无关。"}, {"text": "出路", "is_correct": true, "explanation": "正确：“出路”指摆脱困境的办法，与“没有订单”需要解决的问题相符。"}], "explanations": {"工资": "搭配：“找”的对象不能是“工资”，句中是在找解决困境的办法，不说“找新的工资”。", "脾气": "语义：“脾气”指性格或情绪，与“没有订单”的困境无关，老板不会去“找”脾气。", "笑容": "语义：“笑容”是表情，老板不会去找新的笑容，与没有订单的困境无关。", "出路": "正确：“出路”指摆脱困境的办法，与“没有订单”需要解决的问题相符。"}, "sentence_index": 0, "correct_answer": "出路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用一条出路打开了门。", "explanation": "这里应该用〈办法〉。“办法”可以指具体的操作方法，用来打开门；“出路”指摆脱困境的办法或前途，不指具体的操作。"}, {"text": "他吃光了出路。", "explanation": "这里应该用〈饭菜〉。“吃”的对象是饭菜，“出路”不能被吃，这里搭配不合适。"}, {"text": "他端起碗，把出路喝了下去。", "explanation": "这里应该用〈汤〉。“喝”的对象是汤、水等液体，“出路”不能被喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91090, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "出路", "is_correct": true, "explanation": "正确答案：出路（chū lù）。"}, {"text": "出入", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），两者都是第四声。“出入”意思是进出。"}, {"text": "出租", "is_correct": false, "explanation": "lù 与 zū 声母不同（l 与 z），声调也不同（第四声与第一声）。“出租”意思是把东西租给别人。"}, {"text": "出炉", "is_correct": false, "explanation": "lù（第四声）与 lú（第二声）声调不同。“出炉”意思是从炉子里取出成品。"}], "explanations": {"出路": "正确答案：出路（chū lù）。", "出入": "lù 与 rù 声母不同（l 与 r），两者都是第四声。“出入”意思是进出。", "出租": "lù 与 zū 声母不同（l 与 z），声调也不同（第四声与第一声）。“出租”意思是把东西租给别人。", "出炉": "lù（第四声）与 lú（第二声）声调不同。“出炉”意思是从炉子里取出成品。"}, "sentence_index": null, "correct_answer": "出路"}, "level_3": {"options": [{"text": "河流", "is_correct": false, "explanation": "语义：“毕业生”指人，不能说“河流很宽”，句子读起来不通。"}, {"text": "年纪", "is_correct": false, "explanation": "搭配：“宽”不能修饰“年纪”，“年纪很宽”不成立。"}, {"text": "脑袋", "is_correct": false, "explanation": "体貌：“脑袋很宽”描述头部外形，不用来说毕业生的前景。"}, {"text": "出路", "is_correct": true, "explanation": "正确：“出路”指以后的发展前途，“出路很宽”说的是毕业后的选择多。"}], "explanations": {"河流": "语义：“毕业生”指人，不能说“河流很宽”，句子读起来不通。", "年纪": "搭配：“宽”不能修饰“年纪”，“年纪很宽”不成立。", "脑袋": "体貌：“脑袋很宽”描述头部外形，不用来说毕业生的前景。", "出路": "正确：“出路”指以后的发展前途，“出路很宽”说的是毕业后的选择多。"}, "sentence_index": 6, "correct_answer": "出路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们通过网络出路销售产品。", "explanation": "这里应该用〈渠道〉。“渠道”指商品流通的途径，网络销售要说“渠道”；“出路”不指销售渠道。"}, {"text": "他饿了，拿起出路咬了一大口。", "explanation": "这里应该用〈面包〉。“咬”的对象是食物，“出路”不能被咬。"}, {"text": "他按了一下出路，灯就亮了。", "explanation": "这里应该用〈开关〉。按一下能开灯的是开关；“出路”不能被按，也不能开灯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个专业的毕业生有很宽出路。", "corrected_sentence": "这个专业的毕业生有很宽的出路。", "error_description": "“很宽”修饰名词“出路”时要加“的”，应说“很宽的出路”，漏掉“的”就不合语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个专业的毕业生有一只出路。", "corrected_sentence": "这个专业的毕业生有一条出路。", "error_description": "“出路”的量词要用“条”，应说“一条出路”，不能说“一只出路”；“只”用于动物等，不能搭配“出路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91091, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91091, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91091, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体里软软的、能让我们动起来的部分。", "primary_collocate": null, "pronunciation": "jī ròu", "ipa": "tɕi˥ ʐoʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他每天去健身房练肌肉。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的腿上肌肉很酸。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看他手臂上的肌肉多大！", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动后肌肉会有点痛。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的肌肉很结实。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的肌肉没有年轻人有力。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想让肌肉放松一下。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用热水敷着肩膀的肌肉。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多吃肉和蛋，肌肉会长得快。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练了一年，肌肉变大了。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "肌肉男", "label": "复合"}], "register": "口语", "sense_fingerprint": "身体里软软的、能让人动起来的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fdab5a9-2bdd-478f-be4b-21194dec5a85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91091, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "血液", "is_correct": false, "explanation": "语义：血液不是可以通过健身来锻炼的身体部位。"}, {"text": "关节", "is_correct": false, "explanation": "搭配：说“活动关节”，不说“练关节”。"}, {"text": "肌肉", "is_correct": true, "explanation": "“练肌肉”指通过锻炼增强肌肉，与去健身房的语境相符。"}, {"text": "神经", "is_correct": false, "explanation": "语义：神经不能通过健身房的锻炼来练，它不是可以训练的肌体部分。"}], "explanations": {"血液": "语义：血液不是可以通过健身来锻炼的身体部位。", "关节": "搭配：说“活动关节”，不说“练关节”。", "肌肉": "“练肌肉”指通过锻炼增强肌肉，与去健身房的语境相符。", "神经": "语义：神经不能通过健身房的锻炼来练，它不是可以训练的肌体部分。"}, "sentence_index": 0, "correct_answer": "肌肉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的肌肉每天刷两次。", "explanation": "这里应该用〈牙齿〉。刷的是牙齿，肌肉是身体里的组织，不能用“刷”。"}, {"text": "他的手臂上有一只肌肉很结实。", "explanation": "这里应该用〈块〉。肌肉用“块”来数，“只”一般用于动物或成对的东西。"}, {"text": "我的朋友是个肌肉，天天健身。", "explanation": "这里应该用〈肌肉男〉。“肌肉”不能直接指人，要说“肌肉男”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91091, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骨骼", "is_correct": false, "explanation": "语义：骨骼是支撑身体的骨架，不能“放松”。"}, {"text": "脂肪", "is_correct": false, "explanation": "语义：脂肪是储存能量的组织，不能“放松”。"}, {"text": "肌肉", "is_correct": true, "explanation": "肌肉可以放松，“让肌肉放松一下”是自然的说法。"}, {"text": "力气", "is_correct": false, "explanation": "搭配：说“放松身体”或“松劲”，不说“放松力气”。"}], "explanations": {"骨骼": "语义：骨骼是支撑身体的骨架，不能“放松”。", "脂肪": "语义：脂肪是储存能量的组织，不能“放松”。", "肌肉": "肌肉可以放松，“让肌肉放松一下”是自然的说法。", "力气": "搭配：说“放松身体”或“松劲”，不说“放松力气”。"}, "sentence_index": 6, "correct_answer": "肌肉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他晒了一个夏天的太阳，肌肉变黑了。", "explanation": "这里应该用〈皮肤〉。晒黑的是皮肤，肌肉在身体内部，不会因为晒太阳而变黑。"}, {"text": "他练了一年，肌肉变长了，现在要扎辫子。", "explanation": "这里应该用〈头发〉。能扎辫子的是头发，肌肉不能扎辫子。"}, {"text": "他理了个发，肌肉变短了。", "explanation": "这里应该用〈头发〉。理发以后变短的是头发，肌肉不会因此变短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91091, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我胳膊上的一个肌肉很酸。", "corrected_sentence": "我胳膊上的一块肌肉很酸。", "error_description": "量词错误：“肌肉”应该用量词“块”，不能说“一个肌肉”，正确说法是「一块肌肉」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91091, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我胳膊上的肌肉硬很。", "corrected_sentence": "我胳膊上的肌肉很硬。", "error_description": "语序错误：形容词作谓语时，“很”要放在形容词前面，“硬很”不成立，应说「很硬」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
