INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91092, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人和动物体内由肌纤维构成、能收缩产生运动的组织。", "primary_collocate": null, "pronunciation": "jī ròu", "ipa": "tɕi˥ ʐoʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "肌肉能收缩，身体才会动。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心脏也是由肌肉组成的。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他腿上的肌肉受伤了。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肌肉里有很多细小的纤维。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物的肌肉需要蛋白质。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步前要先拉伸一下肌肉。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肌肉收缩时会产生力量。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的背部肌肉有点酸痛。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间不运动，肌肉会变少。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的身体里有几百块肌肉。", "target_word": "肌肉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "肌肉组织", "label": "复合"}], "register": "中性", "sense_fingerprint": "人和动物体内由肌纤维构成、能收缩的运动组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fdab5a9-2bdd-478f-be4b-21194dec5a85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91092, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骨骼", "is_correct": false, "explanation": "语义：骨骼本身不会收缩，收缩的是附着在骨头上的肌肉。"}, {"text": "肌肉", "is_correct": true, "explanation": "肌肉是能收缩产生运动的组织，与“能收缩，身体才会动”相符。"}, {"text": "力气", "is_correct": false, "explanation": "搭配：“力气”不能作“收缩”的主语，力气不是可以收缩的组织。"}, {"text": "血液", "is_correct": false, "explanation": "语义：血液靠心脏搏动流动，并不是通过自身收缩使身体运动的组织。"}], "explanations": {"骨骼": "语义：骨骼本身不会收缩，收缩的是附着在骨头上的肌肉。", "肌肉": "肌肉是能收缩产生运动的组织，与“能收缩，身体才会动”相符。", "力气": "搭配：“力气”不能作“收缩”的主语，力气不是可以收缩的组织。", "血液": "语义：血液靠心脏搏动流动，并不是通过自身收缩使身体运动的组织。"}, "sentence_index": 0, "correct_answer": "肌肉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我下午去菜市场买了一斤肌肉。", "explanation": "这里应该用〈肉〉。肌肉指人或动物体内的组织，买来做菜的要说“肉”。"}, {"text": "医生在我的腿上发现了一个肌肉。", "explanation": "这里应该用〈块〉。肌肉的量词是“块”，不说“个”。"}, {"text": "我哥哥是个肌肉，每天都去健身房。", "explanation": "这里应该用〈肌肉男〉。“肌肉”不能单独指人，指人要说“肌肉男”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91092, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脂肪", "is_correct": false, "explanation": "语义：脂肪不会收缩产生力量，它是储存能量的组织。"}, {"text": "力量", "is_correct": false, "explanation": "搭配：“力量”不能作“收缩”的主语，说“力量收缩”不成立。"}, {"text": "肌肉", "is_correct": true, "explanation": "肌肉收缩时会产生力量，与句中“收缩时会产生力量”的描述相符。"}, {"text": "神经", "is_correct": false, "explanation": "语义：神经负责传导信号，本身并不靠收缩产生力量。"}], "explanations": {"脂肪": "语义：脂肪不会收缩产生力量，它是储存能量的组织。", "力量": "搭配：“力量”不能作“收缩”的主语，说“力量收缩”不成立。", "肌肉": "肌肉收缩时会产生力量，与句中“收缩时会产生力量”的描述相符。", "神经": "语义：神经负责传导信号，本身并不靠收缩产生力量。"}, "sentence_index": 6, "correct_answer": "肌肉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的肌肉很细腻，白里透红。", "explanation": "这里应该用〈肌肤〉。肌肤指皮肤，形容细腻、白皙的是皮肤，肌肉在身体内部，不能这样形容。"}, {"text": "这家店的牛肌肉很新鲜。", "explanation": "这里应该用〈牛肉〉。肌肉是人体组织，卖给人吃的牛肉要说“牛肉”。"}, {"text": "他把肌肉剪短了，看起来很精神。", "explanation": "这里应该用〈头发〉。能剪短的是头发，肌肉是身体内部的组织，不能剪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91092, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的胳膊上有三个肌肉。", "corrected_sentence": "他的胳膊上有三块肌肉。", "error_description": "量词错误：“肌肉”应该用量词“块”，不能说“三个肌肉”，正确说法是「三块肌肉」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91092, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚跑完步，肌肉酸很。", "corrected_sentence": "他刚跑完步，肌肉很酸。", "error_description": "语序错误：形容词作谓语时，程度副词“很”要放在形容词前面，“肌肉酸很”不成立，应说「肌肉很酸」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
