INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91093, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "券是一张小纸片，拿着它可以换东西或进门。", "primary_collocate": null, "pronunciation": "quàn", "ipa": "tɕʰɥɛn˥˩", "syllable_count": 1, "sentences": [{"text": "这张券可以换一杯咖啡。", "target_word": "券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进门要先给工作人员看券。", "target_word": "券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把券放在口袋里了。", "target_word": "券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张券只能在周末用。", "target_word": "券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一张券换了一本书。", "target_word": "券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "券上写着使用的时间。", "target_word": "券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的券丢了，不能进去了。", "target_word": "券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友拿着券排队领玩具。", "target_word": "券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张券过期了，不能再用了。", "target_word": "券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的人收了我的券，让我进去。", "target_word": "券", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}], "register": "中性", "sense_fingerprint": "可凭以换物或入场的小纸片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2159400-947f-4fbc-9ddc-227cd6535575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91093, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "券", "is_correct": true, "explanation": "正确答案。券读 quàn（第四声），指可凭以换物或入场的小纸片。"}, {"text": "权", "is_correct": false, "explanation": "quán（第二声）与 quàn（第四声）声调不同，权指权利，意思不同。"}, {"text": "拳", "is_correct": false, "explanation": "quán 与 quàn 只差声调，拳指拳头。"}, {"text": "卷", "is_correct": false, "explanation": "juàn 与 quàn 声母不同（j 与 q），卷指卷起的东西或试卷。"}, {"text": "倦", "is_correct": false, "explanation": "juàn 与 quàn 声母不同（j 与 q），倦指疲倦。"}], "explanations": {"券": "正确答案。券读 quàn（第四声），指可凭以换物或入场的小纸片。", "权": "quán（第二声）与 quàn（第四声）声调不同，权指权利，意思不同。", "拳": "quán 与 quàn 只差声调，拳指拳头。", "卷": "juàn 与 quàn 声母不同（j 与 q），卷指卷起的东西或试卷。", "倦": "juàn 与 quàn 声母不同（j 与 q），倦指疲倦。"}, "sentence_index": null, "correct_answer": "券"}, "level_3": {"options": [{"text": "券", "is_correct": true, "explanation": "正确答案。“这张券可以换一杯咖啡”中，券是可凭以兑换的小纸片。"}, {"text": "床", "is_correct": false, "explanation": "语义：床是睡觉用的家具，不能拿来兑换一杯咖啡，句子不通。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图只用来指路，不能兑换饮品，句子不通。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“换一杯咖啡”需要兑换凭证作依据，“桌子”不能与之搭配，句子不通。"}], "explanations": {"券": "正确答案。“这张券可以换一杯咖啡”中，券是可凭以兑换的小纸片。", "床": "语义：床是睡觉用的家具，不能拿来兑换一杯咖啡，句子不通。", "地图": "语义：地图只用来指路，不能兑换饮品，句子不通。", "桌子": "搭配：“换一杯咖啡”需要兑换凭证作依据，“桌子”不能与之搭配，句子不通。"}, "sentence_index": 0, "correct_answer": "券"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把券插进电脑里拷文件。", "explanation": "这里应该用〈U盘〉。U盘是存储设备，插在电脑上才能拷文件；券是可凭以换物或入场的小纸片，不能插进电脑。"}, {"text": "我用券把门锁上了。", "explanation": "这里应该用〈钥匙〉。钥匙用来开锁、锁门；券是可凭以换物或入场的小纸片，不能用来锁门。"}, {"text": "妈妈用券量了体温。", "explanation": "这里应该用〈体温计〉。体温计用来测量体温；券是可凭以换物或入场的小纸片，不能用来测量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91093, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "券", "is_correct": true, "explanation": "正确答案。券读 quàn（第四声），指可凭以换物或入场的小纸片。"}, {"text": "全", "is_correct": false, "explanation": "quán（第二声）与 quàn（第四声）声调不同，全指完整、全部。"}, {"text": "泉", "is_correct": false, "explanation": "quán 与 quàn 声调不同，泉指泉水。"}, {"text": "圈", "is_correct": false, "explanation": "quān（第一声）与 quàn（第四声）声调不同，圈指环形或范围。"}, {"text": "炫", "is_correct": false, "explanation": "xuàn 与 quàn 声母不同（x 与 q），炫指炫耀、显示。"}], "explanations": {"券": "正确答案。券读 quàn（第四声），指可凭以换物或入场的小纸片。", "全": "quán（第二声）与 quàn（第四声）声调不同，全指完整、全部。", "泉": "quán 与 quàn 声调不同，泉指泉水。", "圈": "quān（第一声）与 quàn（第四声）声调不同，圈指环形或范围。", "炫": "xuàn 与 quàn 声母不同（x 与 q），炫指炫耀、显示。"}, "sentence_index": null, "correct_answer": "券"}, "level_3": {"options": [{"text": "券", "is_correct": true, "explanation": "正确答案。“你的券丢了，不能进去了”中，券是凭以入场的小纸片。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞丢了不影响进门，“不能进去了”的因果关系不成立，句子不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是可以遗失的物品，“你的年龄丢了”不成立。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”属于人的体型特征，不能“丢”，句子不成立。"}], "explanations": {"券": "正确答案。“你的券丢了，不能进去了”中，券是凭以入场的小纸片。", "雨伞": "语义：雨伞丢了不影响进门，“不能进去了”的因果关系不成立，句子不通。", "年龄": "语义：年龄不是可以遗失的物品，“你的年龄丢了”不成立。", "身高": "体貌：“身高”属于人的体型特征，不能“丢”，句子不成立。"}, "sentence_index": 6, "correct_answer": "券"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用券切开了西瓜。", "explanation": "这里应该用〈菜刀〉。菜刀用来切东西；券是可凭以换物或入场的小纸片，不能用来切西瓜。"}, {"text": "他抽了一张券擦汗。", "explanation": "这里应该用〈纸巾〉。纸巾用来擦汗；券是可凭以换物或入场的凭证，不能用来擦拭。"}, {"text": "他在信封上贴了一张券。", "explanation": "这里应该用〈邮票〉。邮票表示邮资，贴在信封上；券不能用来表示邮资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91093, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本券只能用一次。", "corrected_sentence": "这张券只能用一次。", "error_description": "量词错误：券是纸片，应用“张”；“本”用于书籍、册子，不能说“这本券”。应为“这张券”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91093, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把她券收好了。", "corrected_sentence": "妈妈把她的券收好了。", "error_description": "修饰语错误：代词“她”修饰“券”时要加“的”，应为“她的券”，不能说“她券”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
