INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91096, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在自由竞争的市场中由私人自主经营的企业。", "primary_collocate": null, "pronunciation": "zì yóu qǐ yè", "ipa": "tsɿ˥˩ iou˧˥ tɕʰi˨˩˦ iɛ˥˩", "syllable_count": 4, "sentences": [{"text": "自由企业要在市场上和别人竞争。", "target_word": "自由企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在自由市场里，自由企业可以自己定价。", "target_word": "自由企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家的自由企业很多，竞争也很激烈。", "target_word": "自由企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自由企业的所有者是私人，不是国家。", "target_word": "自由企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府很少管自由企业。", "target_word": "自由企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自由企业靠好产品赢得顾客。", "target_word": "自由企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自由企业让市场更有活力。", "target_word": "自由企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个城市，自由企业越来越多。", "target_word": "自由企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自由企业要自己负责赚钱和亏钱。", "target_word": "自由企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的经济主要靠自由企业发展。", "target_word": "自由企业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}], "register": "书面", "sense_fingerprint": "自由竞争市场中由私人自主经营的企业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4236ccb-40e1-4dd6-9f6f-04c3557493d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91096, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自由企业", "is_correct": true, "explanation": "正确：自由企业是在自由竞争市场中经营的私人企业，要与别人竞争，与句意相符。"}, {"text": "寺庙", "is_correct": false, "explanation": "语义：寺庙是宗教场所，不以市场竞争为目的，与“在市场上和别人竞争”矛盾。"}, {"text": "福利院", "is_correct": false, "explanation": "语义：福利院是公益机构，不需要在市场上与别人竞争，与句意矛盾。"}, {"text": "军队", "is_correct": false, "explanation": "搭配：“军队”不说“在市场上和别人竞争”，与这一搭配不符。"}], "explanations": {"自由企业": "正确：自由企业是在自由竞争市场中经营的私人企业，要与别人竞争，与句意相符。", "寺庙": "语义：寺庙是宗教场所，不以市场竞争为目的，与“在市场上和别人竞争”矛盾。", "福利院": "语义：福利院是公益机构，不需要在市场上与别人竞争，与句意矛盾。", "军队": "搭配：“军队”不说“在市场上和别人竞争”，与这一搭配不符。"}, "sentence_index": 0, "correct_answer": "自由企业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家自由企业的经营权归国家所有。", "explanation": "这里应该用〈国有企业〉。经营权归国家所有的，要用国有企业；自由企业的所有者是私人。"}, {"text": "这家自由企业的所有者是全体村民。", "explanation": "这里应该用〈集体企业〉。所有者是全体村民的，要用集体企业；自由企业的所有者是私人。"}, {"text": "这家自由企业的产品价格全部由政府规定，自己不能定价。", "explanation": "这里应该用〈国营企业〉。价格全部由政府规定、自己不能定价的，是计划经济下的国营企业；自由企业可以在市场上自主定价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自由企业", "is_correct": true, "explanation": "正确：自由企业在市场中竞争、经营，能让市场更有活力，与句意相符。"}, {"text": "大雾", "is_correct": false, "explanation": "语义：大雾是天气现象，不能让市场更有活力，与句意矛盾。"}, {"text": "寒流", "is_correct": false, "explanation": "语义：寒流是天气现象，与市场活力无关，句意不通。"}, {"text": "垃圾", "is_correct": false, "explanation": "搭配：“垃圾”与“让市场更有活力”搭配不当，句子不成立。"}], "explanations": {"自由企业": "正确：自由企业在市场中竞争、经营，能让市场更有活力，与句意相符。", "大雾": "语义：大雾是天气现象，不能让市场更有活力，与句意矛盾。", "寒流": "语义：寒流是天气现象，与市场活力无关，句意不通。", "垃圾": "搭配：“垃圾”与“让市场更有活力”搭配不当，句子不成立。"}, "sentence_index": 6, "correct_answer": "自由企业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家自由企业的经费由财政拨付，不用自己赚钱。", "explanation": "这里应该用〈政府机关〉。经费由财政拨付、不用自己赚钱的，要用政府机关之类的单位；自由企业要自己负责赚钱和亏钱。"}, {"text": "这家自由企业由两国政府共同出资经营。", "explanation": "这里应该用〈合营企业〉。由两国政府共同出资的，要用合营企业；自由企业由私人自主经营。"}, {"text": "这家自由企业的人事由上级部门统一安排。", "explanation": "这里应该用〈事业单位〉。人事由上级统一安排的，要用事业单位；自由企业由私人自主经营。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在自由市场上，每只自由企业都要与别人竞争。", "corrected_sentence": "在自由市场上，每家自由企业都要与别人竞争。", "error_description": "错误：“自由企业”的量词用成了“只”。正确：应用量词“家”，即“每家自由企业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市新开了很多只自由企业。", "corrected_sentence": "这个城市新开了很多家自由企业。", "error_description": "错误：“自由企业”的量词用成了“只”。正确：应用量词“家”，即“很多家自由企业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
