INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91097, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示一个动作刚发生，紧接着就出现另一件事或另一情况。", "primary_collocate": null, "pronunciation": "gāng yī", "ipa": "kɑŋ˥ i˥", "syllable_count": 2, "sentences": [{"text": "我刚一出门，就下雨了。", "target_word": "刚一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚一坐下，电话就响了。", "target_word": "刚一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子刚一看到妈妈，就哭了。", "target_word": "刚一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚一到家，朋友就来找我。", "target_word": "刚一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她刚一打开门，猫就跑出去了。", "target_word": "刚一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师刚一走进教室，大家就安静了。", "target_word": "刚一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机刚一落地，我就开了手机。", "target_word": "刚一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚一听到好消息，就跳了起来。", "target_word": "刚一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚一躺下，就睡着了。", "target_word": "刚一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天刚一亮，爸爸就起床做早饭了。", "target_word": "刚一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "刚一：前一动作刚发生，后一情况紧接着出现，常与“就”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '422192c1-2427-4ec1-9369-3724e9165a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91097, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刚一", "is_correct": true, "explanation": "刚一：表示刚出门就下雨，后一情况紧接着出现，符合句意。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”表示持续不变，与“刚一”表示的瞬间发生相矛盾。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示永久，与“刚”的瞬间性相矛盾。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”多与否定词连用，不能直接修饰肯定的“出门”。"}], "explanations": {"刚一": "刚一：表示刚出门就下雨，后一情况紧接着出现，符合句意。", "始终": "语义：“始终”表示持续不变，与“刚一”表示的瞬间发生相矛盾。", "永远": "语义：“永远”表示永久，与“刚”的瞬间性相矛盾。", "根本": "搭配：“根本”多与否定词连用，不能直接修饰肯定的“出门”。"}, "sentence_index": 0, "correct_answer": "刚一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚一跑了两个小时，就累得躺下了。", "explanation": "刚一表示动作刚发生就紧接着出现另一情况，不能修饰“跑了两个小时”这样的持续时间。可以说“他跑了两个小时，累得躺下了”。"}, {"text": "我刚一到家，三天以后朋友才来找我。", "explanation": "刚一表示后一情况紧接着出现，不能与“三天以后才”这样的长时间间隔连用。"}, {"text": "我刚一到家，朋友就已经来找我很久了。", "explanation": "刚一表示刚发生的动作，不能与“已经……很久了”这样表示时间久远的说法连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91097, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刚一", "is_correct": true, "explanation": "刚一：表示飞机刚落地，我随即开了手机，符合句意。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”修饰有意志的人，不能修饰“飞机”的落地。"}, {"text": "一概", "is_correct": false, "explanation": "语义：“一概”表示全部、没有例外，与“落地”这一次动作不相合。"}, {"text": "从未", "is_correct": false, "explanation": "语义：“从未”表示从来没有，与落地后又开手机的情况相矛盾。"}], "explanations": {"刚一": "刚一：表示飞机刚落地，我随即开了手机，符合句意。", "亲自": "搭配：“亲自”修饰有意志的人，不能修饰“飞机”的落地。", "一概": "语义：“一概”表示全部、没有例外，与“落地”这一次动作不相合。", "从未": "语义：“从未”表示从来没有，与落地后又开手机的情况相矛盾。"}, "sentence_index": 6, "correct_answer": "刚一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚一是学生，就想当老师。", "explanation": "这里应该用〈原来〉。刚一表示动作刚发生，后面要接动作或变化，不能用于“是……”这样的判断句；说明过去的身份应该用〈原来〉。"}, {"text": "他刚一下班，就已经在门口等了三个小时了。", "explanation": "刚一表示刚发生的动作，不能与“已经等了三个小时”这样的长时间连用。"}, {"text": "他刚一听到消息，就一直不知道。", "explanation": "刚一表示后面立刻出现反应，与“一直不知道”的持续状态相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91097, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚一下车，再看见了朋友。", "corrected_sentence": "我刚一下车，就看见了朋友。", "error_description": "错误：“再”。“刚一”后面要接“就”，表示紧接着出现的情况，不能用“再”。正确说法是“刚一下车，就看见了朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91097, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚一进门，要打开了电视。", "corrected_sentence": "他刚一进门，就打开了电视。", "error_description": "错误：“要”。“刚一”后面应接“就”，表示紧接着出现的情况，不能用“要”。正确说法是“刚一进门，就打开了电视”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
