INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91100, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "飞机按固定时间、固定航线飞行的班次。", "primary_collocate": null, "pronunciation": "háng bān", "ipa": "xɑŋ˧˥ pan˥", "syllable_count": 2, "sentences": [{"text": "北京到东京每周有十个航班。", "target_word": "航班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条航线每天有三个航班。", "target_word": "航班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天时，航班会比冬天多。", "target_word": "航班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司新开了直飞成都的航班。", "target_word": "航班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以在网上查航班时刻表。", "target_word": "航班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的航班常常很满。", "target_word": "航班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场每天有上百个航班。", "target_word": "航班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际航班需要带护照。", "target_word": "航班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市每周只有两个航班。", "target_word": "航班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航班的起飞时间是固定的。", "target_word": "航班", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "班", "label": "量词"}, {"form": "航班号", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：按固定时间和航线运行的班次，如每天三个航班、国际航班", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c21081-19c8-4e43-9122-d082b2713663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91100, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "航班", "is_correct": true, "explanation": "正确。「每周有十个航班」指北京到东京每周固定运行的班次数量。"}, {"text": "客车", "is_correct": false, "explanation": "语义：「客车」是陆地上的大巴，北京到东京之间没有这样的运行班次。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：「地铁」是城市内的轨道交通，不能往返北京和东京。"}, {"text": "航线", "is_correct": false, "explanation": "搭配：「航线」用「条」计量，说「十个航线」不合搭配，且指路线而不是班次。"}], "explanations": {"航班": "正确。「每周有十个航班」指北京到东京每周固定运行的班次数量。", "客车": "语义：「客车」是陆地上的大巴，北京到东京之间没有这样的运行班次。", "地铁": "语义：「地铁」是城市内的轨道交通，不能往返北京和东京。", "航线": "搭配：「航线」用「条」计量，说「十个航线」不合搭配，且指路线而不是班次。"}, "sentence_index": 0, "correct_answer": "航班"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司新开了一只直飞成都的航班。", "explanation": "量词：「航班」用「个」或「班」计量，不用「只」，这里应该用〈个〉。"}, {"text": "这家公司把直飞成都的航班打包寄走了。", "explanation": "物化：这里把「航班」当成了可以打包寄送的实物，应该用〈包裹〉这类词。"}, {"text": "这家公司新开的航班今天生气了。", "explanation": "拟人：「航班」是班次，不会「生气」，句子把它当成了有情绪的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91100, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "航班", "is_correct": true, "explanation": "正确。「机场每天有上百个航班」指机场每天运行的班次很多，符合「航班」的含义。"}, {"text": "台风", "is_correct": false, "explanation": "语义：「台风」是天气现象，不是机场每天运行的班次。"}, {"text": "星期", "is_correct": false, "explanation": "语义：「星期」是时间单位，不能说机场「有」上百个星期。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：「钥匙」不是班次，「机场每天有上百个钥匙」句意不通。"}], "explanations": {"航班": "正确。「机场每天有上百个航班」指机场每天运行的班次很多，符合「航班」的含义。", "台风": "语义：「台风」是天气现象，不是机场每天运行的班次。", "星期": "语义：「星期」是时间单位，不能说机场「有」上百个星期。", "钥匙": "语义：「钥匙」不是班次，「机场每天有上百个钥匙」句意不通。"}, "sentence_index": 6, "correct_answer": "航班"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上给航班洗澡。", "explanation": "物化：「航班」是班次，不是实物，不能给它「洗澡」，这里应该用〈飞机〉这类实物。"}, {"text": "我的航班一直在吃饭。", "explanation": "拟人：「航班」是班次，不能进行「吃饭」这类动作，句子把它当成了有生命的人。"}, {"text": "这个航班的作业做完了。", "explanation": "语义：这里把「航班」当成了有学习任务的人，应该用〈学生〉这类人称，而不是班次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91100, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上海到东京每周有五辆航班。", "corrected_sentence": "上海到东京每周有五个航班。", "error_description": "「辆」用于车辆，「航班」应用「个」「班」或「趟」计量；应说「五个航班」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91100, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们订地航班已经起飞了。", "corrected_sentence": "我们订的航班已经起飞了。", "error_description": "助词错误：名词「航班」前的修饰语应用「的」，写作「我们订的航班」；「地」用于动词前作状语，不能放在名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
