INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91101, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "企图是心里想要做一件事，一直想办法去做，常常是坏事。", "primary_collocate": null, "pronunciation": "qǐ tú", "ipa": "tɕʰi˨˩˦ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "小偷企图从窗户进入房间。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他企图骗我的钱，但是我没有上当。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人企图逃跑，被警察抓住了。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生企图在考试时看别人的答案。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他企图骗老师，说自己生病了。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人企图打开门进去。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人企图偷走公司的钱。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个司机企图不付钱就离开。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她企图用假话骗大家。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们企图在比赛中作弊。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "企图了", "label": "体标"}, {"form": "企图过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "心里想做某事并一直想办法去做，多指坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d2fa9c-e3fd-42ad-8411-015657f8b96c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91101, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "企图", "is_correct": true, "explanation": "企图：心里想做某事并想办法去做，这里指小偷想从窗户入室。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是不及物动词，不能接“从窗户进入房间”，句子不通。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场地或卫生，“打扫进入房间”不成立，句子不通。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：“逃跑”与“进入房间”方向相反，小偷不会一边逃跑一边入室，句意矛盾。"}], "explanations": {"企图": "企图：心里想做某事并想办法去做，这里指小偷想从窗户入室。", "睡觉": "配价：“睡觉”是不及物动词，不能接“从窗户进入房间”，句子不通。", "打扫": "搭配：“打扫”的对象是场地或卫生，“打扫进入房间”不成立，句子不通。", "逃跑": "语义：“逃跑”与“进入房间”方向相反，小偷不会一边逃跑一边入室，句意矛盾。"}, "sentence_index": 0, "correct_answer": "企图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天企图学习英语。", "explanation": "这里应该用〈努力〉。“企图”多指坏事，学习英语是好事，不能用“企图”。"}, {"text": "医生企图救活那位病人。", "explanation": "这里应该用〈设法〉。“企图”表示想做坏事，救人是好事，不能用“企图”。"}, {"text": "我企图周末去北京旅游。", "explanation": "这里应该用〈打算〉。“企图”多指坏事，去北京旅游不是坏事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91101, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "企图", "is_correct": true, "explanation": "企图：心里想做坏事并想办法去做，这里指有人想偷公司的钱。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：庆祝是为喜事举行活动，与偷钱的行为不相符。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理是让坏掉的东西恢复正常，不能用于“偷走钱”。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”多接作品、风景等，不接“偷走公司的钱”。"}], "explanations": {"企图": "企图：心里想做坏事并想办法去做，这里指有人想偷公司的钱。", "庆祝": "语义：庆祝是为喜事举行活动，与偷钱的行为不相符。", "修理": "语义：修理是让坏掉的东西恢复正常，不能用于“偷走钱”。", "欣赏": "搭配：“欣赏”多接作品、风景等，不接“偷走公司的钱”。"}, "sentence_index": 6, "correct_answer": "企图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们企图下个月搬进新房子。", "explanation": "这里应该用〈计划〉。“企图”多指坏事，搬进新房子是正常的事，不能用“企图”。"}, {"text": "这位老师企图帮学生们复习功课。", "explanation": "这里应该用〈帮助〉。“企图”多指坏事，帮学生复习功课是好事。"}, {"text": "妈妈企图给我买一件新衣服。", "explanation": "这里应该用〈想〉或〈打算〉。“企图”多指坏事，给我买衣服是好事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91101, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个人很企图从后门溜进屋子。", "corrected_sentence": "那个人企图从后门溜进屋子。", "error_description": "错误：“很企图”。正确：“企图”。“企图”是动词，不能被副词“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91101, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个很企图偷钱的小偷被抓住了。", "corrected_sentence": "一个企图偷钱的小偷被抓住了。", "error_description": "错误：“很企图偷钱”。正确：“企图偷钱”。“企图”是动词，不能被副词“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
