INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91102, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打算（做不好的事）；图谋。", "primary_collocate": null, "pronunciation": "qǐ tú", "ipa": "tɕʰi˨˩˦ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "敌人企图占领这座城市。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他企图用钱让警察放了他。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司企图影响比赛的结果。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早就企图抢走我的工作。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人企图破坏我们的计划，大家要小心。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她企图逃避自己的责任。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他企图靠假消息赚钱。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些人企图进入别人的电脑。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他企图骗过检查的人，可是没有成功。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷企图趁晚上没人来偷东西。", "target_word": "企图", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "企图了", "label": "体标"}, {"form": "企图过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "打算做不好的事，图谋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d2fa9c-e3fd-42ad-8411-015657f8b96c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91102, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "企图", "is_correct": true, "explanation": "企图：打算做不好的事，这里指敌人想占领这座城市。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：敌人不会“欢迎”占领城市，这与句意相反。"}, {"text": "逃跑", "is_correct": false, "explanation": "配价：“逃跑”不能带动词短语“占领这座城市”作宾语，句子不通。"}, {"text": "修缮", "is_correct": false, "explanation": "搭配：“修缮”的对象是建筑物等，不能与“占领”搭配。"}], "explanations": {"企图": "企图：打算做不好的事，这里指敌人想占领这座城市。", "欢迎": "语义：敌人不会“欢迎”占领城市，这与句意相反。", "逃跑": "配价：“逃跑”不能带动词短语“占领这座城市”作宾语，句子不通。", "修缮": "搭配：“修缮”的对象是建筑物等，不能与“占领”搭配。"}, "sentence_index": 0, "correct_answer": "企图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他企图帮我修好电脑。", "explanation": "这里应该用〈打算〉或〈准备〉。“企图”只用于做不好的事，帮我修电脑是好事。"}, {"text": "老人企图教孙子画画。", "explanation": "这里应该用〈想〉。企图只用于做不好的事，教孙子画画是好事。"}, {"text": "同学们企图每天按时交作业。", "explanation": "这里应该用〈努力〉。“企图”只用于做不好的事，按时交作业是好事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91102, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "企图", "is_correct": true, "explanation": "企图：打算做不好的事，这里指他想靠假消息赚钱。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与用假消息赚钱的手段无关，句意不通。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”与“靠假消息赚钱”不相关，句子不通。"}, {"text": "沉默", "is_correct": false, "explanation": "配价：“沉默”是不及物动词，不能带“靠假消息赚钱”这样的结构作宾语。"}], "explanations": {"企图": "企图：打算做不好的事，这里指他想靠假消息赚钱。", "唱歌": "语义：“唱歌”与用假消息赚钱的手段无关，句意不通。", "修理": "语义：“修理”与“靠假消息赚钱”不相关，句子不通。", "沉默": "配价：“沉默”是不及物动词，不能带“靠假消息赚钱”这样的结构作宾语。"}, "sentence_index": 6, "correct_answer": "企图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈企图给我做一顿丰盛的晚饭。", "explanation": "这里应该用〈打算〉。“企图”只用于做不好的事，做晚饭是好事。"}, {"text": "老师企图表扬每一个学生。", "explanation": "这里应该用〈想〉。“企图”只用于做不好的事，表扬学生是好事。"}, {"text": "我企图在考试中得满分。", "explanation": "这里应该用〈争取〉。“企图”只用于做不好的事，得满分是好事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个人企图着偷走我的钱包。", "corrected_sentence": "这个人企图偷走我的钱包。", "error_description": "错误：“企图着偷走”。正确：“企图偷走”。“企图”表示有待实现的意图，一般不接持续体“着”，应删去“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司很企图靠假广告抢占市场。", "corrected_sentence": "这家公司企图靠假广告抢占市场。", "error_description": "错误：“很企图靠假广告抢占”。正确：“企图靠假广告抢占”。“企图”是动词，不能被副词“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91103, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解密", "is_correct": true, "explanation": "反义：加密指给信息上锁，解密指把加密的内容还原成可读的形式，二者互为反义。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：“散步”指随意走走，与“加密”没有反义或近义关系。"}, {"text": "煮饭", "is_correct": false, "explanation": "无反义关系：“煮饭”指做饭，与“加密”的任何义项都无关。"}, {"text": "思考", "is_correct": false, "explanation": "无反义关系：“思考”指动脑子想问题，与“加密”没有反义关系。"}], "correct_answer": "解密", "explanations": {"解密": "反义：加密指给信息上锁，解密指把加密的内容还原成可读的形式，二者互为反义。", "散步": "无反义关系：“散步”指随意走走，与“加密”没有反义或近义关系。", "煮饭": "无反义关系：“煮饭”指做饭，与“加密”的任何义项都无关。", "思考": "无反义关系：“思考”指动脑子想问题，与“加密”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91103, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解密", "is_correct": true, "explanation": "反义：加密指给信息上锁，解密指把加密的内容还原成可读的形式，二者互为反义。"}, {"text": "唱歌", "is_correct": false, "explanation": "无反义关系：“唱歌”指发声歌唱，与“加密”没有反义或近义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无反义关系：“打扫”指清除垃圾、使干净，与“加密”的任何义项都无关。"}, {"text": "游泳", "is_correct": false, "explanation": "无反义关系：“游泳”指在水中活动，与“加密”没有反义关系。"}], "correct_answer": "解密", "explanations": {"解密": "反义：加密指给信息上锁，解密指把加密的内容还原成可读的形式，二者互为反义。", "唱歌": "无反义关系：“唱歌”指发声歌唱，与“加密”没有反义或近义关系。", "打扫": "无反义关系：“打扫”指清除垃圾、使干净，与“加密”的任何义项都无关。", "游泳": "无反义关系：“游泳”指在水中活动，与“加密”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91103, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "加密是给文件上一把锁，别人看不懂。", "primary_collocate": null, "pronunciation": "jiā mì", "ipa": "tɕja˥ mi˥˩", "syllable_count": 2, "sentences": [{"text": "我给这个文件加密了。", "target_word": "加密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把照片加密再发给我。", "target_word": "加密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的电脑文件都加密了。", "target_word": "加密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "重要的资料一定要加密。", "target_word": "加密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的手机加密了吗？", "target_word": "加密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想给日记加密，不让别人看。", "target_word": "加密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份合同我已经加密好了。", "target_word": "加密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板让我把文件加密后再发。", "target_word": "加密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给手机里的相片加密了。", "target_word": "加密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你会不会给压缩包加密？", "target_word": "加密", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "加密了", "label": "体标"}, {"form": "加密过", "label": "体标"}, {"form": "加了密", "label": "离合"}], "register": "中性", "sense_fingerprint": "给文件、照片等上锁，让别人打不开、看不懂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3f596a-ea6f-4092-8aea-7d56453cebea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91103, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "加密", "is_correct": true, "explanation": "正确答案：加密（jiā mì），指给文件等上锁，让别人打不开、看不懂。"}, {"text": "加币", "is_correct": false, "explanation": "bì（第四声）与 mì（第四声）声母不同（b 与 m），意思是加拿大货币。"}, {"text": "加力", "is_correct": false, "explanation": "lì（第四声）与 mì（第四声）声母不同（l 与 m），意思是增加力量。"}, {"text": "价目", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）声调不同，mù 与 mì 韵母不同。价目指商品的价格。"}], "explanations": {"加密": "正确答案：加密（jiā mì），指给文件等上锁，让别人打不开、看不懂。", "加币": "bì（第四声）与 mì（第四声）声母不同（b 与 m），意思是加拿大货币。", "加力": "lì（第四声）与 mì（第四声）声母不同（l 与 m），意思是增加力量。", "价目": "jià（第四声）与 jiā（第一声）声调不同，mù 与 mì 韵母不同。价目指商品的价格。"}, "sentence_index": null, "correct_answer": "加密"}, "level_3": {"options": [{"text": "烘烤", "is_correct": false, "explanation": "语义：“烘烤”是加热食物的动作，与“文件”毫无关系。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”是做饭的动作，与“文件”毫无关系。"}, {"text": "加密", "is_correct": true, "explanation": "正确：“加密”指给文件上锁，与“我给这个文件……了”相符。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”的对象是动物或人，不能用于“文件”。"}], "explanations": {"烘烤": "语义：“烘烤”是加热食物的动作，与“文件”毫无关系。", "烹饪": "语义：“烹饪”是做饭的动作，与“文件”毫无关系。", "加密": "正确：“加密”指给文件上锁，与“我给这个文件……了”相符。", "喂养": "搭配：“喂养”的对象是动物或人，不能用于“文件”。"}, "sentence_index": 0, "correct_answer": "加密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事我们一定要加密，不能告诉别人。", "explanation": "这里应该用〈保密〉。加密指用技术手段把文件、信息变成别人读不懂的形式，对事情保守秘密要说保密。"}, {"text": "这家工厂每天加密上千个零件。", "explanation": "这里应该用〈生产〉。加密指给文件、信息上锁，使别人看不懂，不能用于制造零件。"}, {"text": "他出门前把门加密了。", "explanation": "这里应该用〈上锁〉。加密只用于文件、信息等数据，不能用于给门上锁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91103, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "加密", "is_correct": true, "explanation": "正确答案：加密（jiā mì），指给文件等上锁，让别人打不开、看不懂。"}, {"text": "机密", "is_correct": false, "explanation": "jī（第一声）与 jiā（第一声）韵母不同（少了 a），意思是机要、秘密。"}, {"text": "加气", "is_correct": false, "explanation": "qì（第四声）与 mì（第四声）声母不同（q 与 m），意思是给车辆加注天然气。"}, {"text": "加至", "is_correct": false, "explanation": "zhì（第四声）与 mì（第四声）声母不同（zh 与 m），意思是增加到某一数量。"}], "explanations": {"加密": "正确答案：加密（jiā mì），指给文件等上锁，让别人打不开、看不懂。", "机密": "jī（第一声）与 jiā（第一声）韵母不同（少了 a），意思是机要、秘密。", "加气": "qì（第四声）与 mì（第四声）声母不同（q 与 m），意思是给车辆加注天然气。", "加至": "zhì（第四声）与 mì（第四声）声母不同（zh 与 m），意思是增加到某一数量。"}, "sentence_index": null, "correct_answer": "加密"}, "level_3": {"options": [{"text": "腌制", "is_correct": false, "explanation": "搭配：“腌制”的对象是食物，不能用于“合同”。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”本身已含毁坏的结果，与“已经……好了”的完成语气不符，“烧毁好了”搭配不通。"}, {"text": "擦洗", "is_correct": false, "explanation": "搭配：“擦洗”针对物体表面，不能用于处理“合同”的内容。"}, {"text": "加密", "is_correct": true, "explanation": "正确：“加密”与“这份合同我已经……好了”的语境相符。"}], "explanations": {"腌制": "搭配：“腌制”的对象是食物，不能用于“合同”。", "烧毁": "语义：“烧毁”本身已含毁坏的结果，与“已经……好了”的完成语气不符，“烧毁好了”搭配不通。", "擦洗": "搭配：“擦洗”针对物体表面，不能用于处理“合同”的内容。", "加密": "正确：“加密”与“这份合同我已经……好了”的语境相符。"}, "sentence_index": 6, "correct_answer": "加密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钱加密起来了，谁也找不到。", "explanation": "这里应该用〈藏〉。加密只用于文件、信息等数据，钱不能加密。"}, {"text": "我把行李加密好了，明天带去机场。", "explanation": "这里应该用〈打包〉。加密指把数据变成别人读不懂的形式，把行李整理装好要说打包。"}, {"text": "我把音量加密到最低了。", "explanation": "这里应该用〈调节〉。加密不能用于声音的大小，把音量调低要说调节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91103, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把照片加密着了。", "corrected_sentence": "我已经把照片加密了。", "error_description": "体标错误：“加密”是完成的动作，不能用表示持续的“着”。应说“已经把照片加密了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91103, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从没给照片过加密。", "corrected_sentence": "我从没给照片加过密。", "error_description": "离合词“加密”中的“过”应放在“加”和“密”之间，正确是“加过密”，错误的“过加密”把“过”放在整个词之前，不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91104, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解密", "is_correct": true, "explanation": "反义：加密指把信息变成别人读不懂的形式，解密指把加密的信息还原成可读的形式，二者互为反义。"}, {"text": "跳舞", "is_correct": false, "explanation": "无反义关系：“跳舞”指随音乐做动作，与“加密”没有反义或近义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "无反义关系：“洗澡”指清洁身体，与“加密”的任何义项都无关。"}, {"text": "休息", "is_correct": false, "explanation": "无反义关系：“休息”指停止工作或活动，与“加密”没有反义关系。"}], "correct_answer": "解密", "explanations": {"解密": "反义：加密指把信息变成别人读不懂的形式，解密指把加密的信息还原成可读的形式，二者互为反义。", "跳舞": "无反义关系：“跳舞”指随音乐做动作，与“加密”没有反义或近义关系。", "洗澡": "无反义关系：“洗澡”指清洁身体，与“加密”的任何义项都无关。", "休息": "无反义关系：“休息”指停止工作或活动，与“加密”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91104, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解密", "is_correct": true, "explanation": "反义：加密指把信息变成别人读不懂的形式，解密指把加密的信息还原成可读的形式，二者互为反义。"}, {"text": "唱歌", "is_correct": false, "explanation": "无反义关系：“唱歌”指发声歌唱，与“加密”没有反义或近义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无反义关系：“打扫”指清除垃圾、使干净，与“加密”的任何义项都无关。"}, {"text": "游泳", "is_correct": false, "explanation": "无反义关系：“游泳”指在水中活动，与“加密”没有反义关系。"}], "correct_answer": "解密", "explanations": {"解密": "反义：加密指把信息变成别人读不懂的形式，解密指把加密的信息还原成可读的形式，二者互为反义。", "唱歌": "无反义关系：“唱歌”指发声歌唱，与“加密”没有反义或近义关系。", "打扫": "无反义关系：“打扫”指清除垃圾、使干净，与“加密”的任何义项都无关。", "游泳": "无反义关系：“游泳”指在水中活动，与“加密”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91104, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用特定方法把信息变成他人无法直接读懂的形式。", "primary_collocate": null, "pronunciation": "jiā mì", "ipa": "tɕja˥ mi˥˩", "syllable_count": 2, "sentences": [{"text": "银行把你的密码加密了。", "target_word": "加密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上发送的信息都要加密。", "target_word": "加密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用特殊方法加密短信。", "target_word": "加密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条消息已经加密了，我看不懂。", "target_word": "加密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "聊天软件会自动加密你的话。", "target_word": "加密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "加密以后，别人就读不懂了。", "target_word": "加密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电子邮件加密过，很安全。", "target_word": "加密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队用密码加密重要的消息。", "target_word": "加密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "加密的信息要用密码打开。", "target_word": "加密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司给用户数据加密。", "target_word": "加密", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "加密了", "label": "体标"}, {"form": "加密过", "label": "体标"}, {"form": "加了密", "label": "离合"}], "register": "中性", "sense_fingerprint": "用特定方法把信息转换成别人读不懂的形式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3f596a-ea6f-4092-8aea-7d56453cebea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91104, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "加密", "is_correct": true, "explanation": "正确答案：加密（jiā mì），指用特定方法把信息变成别人无法直接读懂的形式。"}, {"text": "加币", "is_correct": false, "explanation": "bì（第四声）与 mì（第四声）声母不同（b 与 m），意思是加拿大货币。"}, {"text": "加力", "is_correct": false, "explanation": "lì（第四声）与 mì（第四声）声母不同（l 与 m），意思是增加力量。"}, {"text": "加费", "is_correct": false, "explanation": "fèi（第四声）与 mì（第四声）声母不同（f 与 m），意思是额外收取费用。"}], "explanations": {"加密": "正确答案：加密（jiā mì），指用特定方法把信息变成别人无法直接读懂的形式。", "加币": "bì（第四声）与 mì（第四声）声母不同（b 与 m），意思是加拿大货币。", "加力": "lì（第四声）与 mì（第四声）声母不同（l 与 m），意思是增加力量。", "加费": "fèi（第四声）与 mì（第四声）声母不同（f 与 m），意思是额外收取费用。"}, "sentence_index": null, "correct_answer": "加密"}, "level_3": {"options": [{"text": "背诵", "is_correct": false, "explanation": "搭配：“背诵”与“把你的密码”组合不自然，银行的操作不会是背诵。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”是引火的动作，与“银行把你的密码……了”的语境无关。"}, {"text": "加密", "is_correct": true, "explanation": "正确：“加密”指用特定方法把信息变成别人读不懂的形式，与“银行把你的密码……了”相符。"}, {"text": "煎炒", "is_correct": false, "explanation": "语义：“煎炒”是烹调动作，与“密码”和“银行”的语境完全不合。"}], "explanations": {"背诵": "搭配：“背诵”与“把你的密码”组合不自然，银行的操作不会是背诵。", "点燃": "语义：“点燃”是引火的动作，与“银行把你的密码……了”的语境无关。", "加密": "正确：“加密”指用特定方法把信息变成别人读不懂的形式，与“银行把你的密码……了”相符。", "煎炒": "语义：“煎炒”是烹调动作，与“密码”和“银行”的语境完全不合。"}, "sentence_index": 0, "correct_answer": "加密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把日记加密在抽屉里。", "explanation": "这里应该用〈藏〉。加密指把信息变成别人读不懂的形式，不能说把东西加密在某个地方。"}, {"text": "这条线路每天加密很多乘客。", "explanation": "这里应该用〈运送〉。加密指把信息变成他人读不懂的形式，不能用于运载乘客。"}, {"text": "他把自己加密成了游客。", "explanation": "这里应该用〈伪装〉。加密只用于信息的转换，不能用来改变人的外表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91104, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "加密", "is_correct": true, "explanation": "正确答案：加密（jiā mì），指用特定方法把信息变成别人无法直接读懂的形式。"}, {"text": "机密", "is_correct": false, "explanation": "jī（第一声）与 jiā（第一声）韵母不同（少了 a），意思是机要、秘密。"}, {"text": "加气", "is_correct": false, "explanation": "qì（第四声）与 mì（第四声）声母不同（q 与 m），意思是给车辆加注天然气。"}, {"text": "加剧", "is_correct": false, "explanation": "jù（第四声）与 mì（第四声）声母、韵母都不同，意思是变得更加严重。"}], "explanations": {"加密": "正确答案：加密（jiā mì），指用特定方法把信息变成别人无法直接读懂的形式。", "机密": "jī（第一声）与 jiā（第一声）韵母不同（少了 a），意思是机要、秘密。", "加气": "qì（第四声）与 mì（第四声）声母不同（q 与 m），意思是给车辆加注天然气。", "加剧": "jù（第四声）与 mì（第四声）声母、韵母都不同，意思是变得更加严重。"}, "sentence_index": null, "correct_answer": "加密"}, "level_3": {"options": [{"text": "晾晒", "is_correct": false, "explanation": "语义：“晾晒”针对衣物等实物，与“电子邮件”不相容。"}, {"text": "煎炸", "is_correct": false, "explanation": "语义：“煎炸”是烹调动作，与“电子邮件”毫无关系。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”的对象是枝叶、头发等，不能用于“电子邮件”。"}, {"text": "加密", "is_correct": true, "explanation": "正确：“加密”与“电子邮件……过，很安全”的语境相符。"}], "explanations": {"晾晒": "语义：“晾晒”针对衣物等实物，与“电子邮件”不相容。", "煎炸": "语义：“煎炸”是烹调动作，与“电子邮件”毫无关系。", "修剪": "搭配：“修剪”的对象是枝叶、头发等，不能用于“电子邮件”。", "加密": "正确：“加密”与“电子邮件……过，很安全”的语境相符。"}, "sentence_index": 6, "correct_answer": "加密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请把这份说明书加密成英文。", "explanation": "这里应该用〈翻译〉。加密指把信息变成别人读不懂的形式，改变语言要说翻译。"}, {"text": "他加密了漏水的水管。", "explanation": "这里应该用〈修理〉。加密指把信息变成他人读不懂的形式，修理漏水的水管要说修理。"}, {"text": "工人们把墙加密成了白色。", "explanation": "这里应该用〈粉刷〉。加密指把信息变成他人读不懂的形式，给墙涂色要说粉刷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给账本加密很仔细。", "corrected_sentence": "妈妈给账本加密得很仔细。", "error_description": "动词后的程度补语需要用“得”引出。正确是“加密得很仔细”，错误的“加密很仔细”缺少“得”，不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司给用户数据加密很严密。", "corrected_sentence": "这家公司给用户数据加密得很严密。", "error_description": "动词后的程度补语需要用“得”引出，正确是“加密得很严密”，缺少“得”，“加密很严密”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
