INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91106, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由若干军舰编成的海军作战部队。", "primary_collocate": null, "pronunciation": "jiàn duì", "ipa": "tɕjɛn˥˩ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "海军派出了一支舰队。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支舰队的任务是保护海上的航线。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舰队已经出发了。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人的舰队开始向我们靠近。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舰队由十艘军舰组成。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争中，这支舰队立过大功。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家派舰队去海外训练。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舰队在演习中打了一场胜仗。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的舰队已经建成了。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那支舰队的指挥官很有经验。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}, {"form": "舰队司令", "label": "复合"}], "register": "中性", "sense_fingerprint": "海军编制的军舰作战部队", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72962ab9-2347-4d76-bde0-711257f30022') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91106, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "舰队", "is_correct": true, "explanation": "正确。海军派出的是由军舰编成的作战部队，“一支舰队”符合句意。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是存放书籍的场所，不能被海军派出去作战。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的气体，不能被派出。"}, {"text": "大炮", "is_correct": false, "explanation": "搭配：大炮的量词是“门”，“一支大炮”搭配不当，句子也不宜这样说。"}], "explanations": {"舰队": "正确。海军派出的是由军舰编成的作战部队，“一支舰队”符合句意。", "图书馆": "语义：图书馆是存放书籍的场所，不能被海军派出去作战。", "空气": "语义：空气是无形的气体，不能被派出。", "大炮": "搭配：大炮的量词是“门”，“一支大炮”搭配不当，句子也不宜这样说。"}, "sentence_index": 0, "correct_answer": "舰队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支舰队在公路上行驶。", "explanation": "这里应该用〈车队〉。舰队是由军舰组成的海军部队，不能在公路上行驶。"}, {"text": "这支舰队在草原上奔跑。", "explanation": "这里应该用〈马队〉。舰队由军舰组成，不能在草原上奔跑。"}, {"text": "这支舰队在海上捕鱼，每天收获很多。", "explanation": "这里应该用〈船队〉。舰队是军舰组成的海军部队，出海捕鱼的船只组成的队伍要用〈船队〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91106, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "舰队", "is_correct": true, "explanation": "正确。国家派舰队去海外训练，符合句意。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海是水域，不能被派去海外训练。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不能被派去海外训练。"}, {"text": "大米", "is_correct": false, "explanation": "语义：大米是粮食，不能被派去海外训练。"}], "explanations": {"舰队": "正确。国家派舰队去海外训练，符合句意。", "大海": "语义：大海是水域，不能被派去海外训练。", "太阳": "语义：太阳是天体，不能被派去海外训练。", "大米": "语义：大米是粮食，不能被派去海外训练。"}, "sentence_index": 6, "correct_answer": "舰队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支舰队在篮球场上赢了比赛。", "explanation": "这里应该用〈球队〉。舰队是海军部队，打篮球比赛的队伍要用〈球队〉。"}, {"text": "这支舰队在广场上唱了一首歌。", "explanation": "这里应该用〈合唱团〉。舰队是海军部队，一起唱歌的人要用〈合唱团〉。"}, {"text": "这支舰队在山里修了一条路。", "explanation": "这里应该用〈工程队〉。舰队是海军部队，负责修路的队伍要用〈工程队〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这艘舰队已经出发了。", "corrected_sentence": "这支舰队已经出发了。", "error_description": "量词错误。“舰队”是由多艘军舰组成的编队，量词应用“支”；“艘”只用于单艘船，不能说“这艘舰队”，应说“这支舰队”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支舰队们的指挥官很年轻。", "corrected_sentence": "这支舰队的指挥官很年轻。", "error_description": "复数错误。“舰队”本身是整体名词，不能加“们”表示复数，应说“这支舰队的指挥官”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91107, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "排斥", "is_correct": true, "explanation": "反义：包容指接受别人的不同，排斥指拒绝或排除别人，二者互为反义。"}, {"text": "思考", "is_correct": false, "explanation": "无反义关系：“思考”指动脑子想问题，与“包容”的任何义项都不构成反义。"}, {"text": "等待", "is_correct": false, "explanation": "无反义关系：“等待”指停下来等候，与“包容”此义项没有反义关系。"}, {"text": "支持", "is_correct": false, "explanation": "无反义关系：“支持”指赞成或帮助，不是“包容”此义项的反义词。"}], "correct_answer": "排斥", "explanations": {"排斥": "反义：包容指接受别人的不同，排斥指拒绝或排除别人，二者互为反义。", "思考": "无反义关系：“思考”指动脑子想问题，与“包容”的任何义项都不构成反义。", "等待": "无反义关系：“等待”指停下来等候，与“包容”此义项没有反义关系。", "支持": "无反义关系：“支持”指赞成或帮助，不是“包容”此义项的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91107, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "排斥", "is_correct": true, "explanation": "反义：包容指接受别人的不同，排斥指拒绝或排除别人，二者互为反义。"}, {"text": "赞美", "is_correct": false, "explanation": "无反义关系：“赞美”指称赞、夸奖，与“包容”此义项没有反义关系。"}, {"text": "前进", "is_correct": false, "explanation": "无反义关系：“前进”指向前移动，与“包容”的任何义项都无关。"}, {"text": "保存", "is_correct": false, "explanation": "无反义关系：“保存”指留存或保管，不是“包容”此义项的反义词。"}], "correct_answer": "排斥", "explanations": {"排斥": "反义：包容指接受别人的不同，排斥指拒绝或排除别人，二者互为反义。", "赞美": "无反义关系：“赞美”指称赞、夸奖，与“包容”此义项没有反义关系。", "前进": "无反义关系：“前进”指向前移动，与“包容”的任何义项都无关。", "保存": "无反义关系：“保存”指留存或保管，不是“包容”此义项的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91107, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "包容是不生别人的气，肯接受别人和自己不一样。", "primary_collocate": null, "pronunciation": "bāo róng", "ipa": "pɑʊ̯˥ ʐʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我的朋友很包容我。", "target_word": "包容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈总是包容我的小错误。", "target_word": "包容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他脾气好，很会包容别人。", "target_word": "包容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夫妻之间要互相包容。", "target_word": "包容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师包容了我的迟到。", "target_word": "包容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能不能多包容他一点？", "target_word": "包容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要学会包容不同的想法。", "target_word": "包容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她包容着弟弟的坏脾气。", "target_word": "包容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你一直包容我。", "target_word": "包容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来没有包容过别人的错。", "target_word": "包容", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "包容了", "label": "体标"}, {"form": "包容着", "label": "体标"}, {"form": "包容过", "label": "体标"}], "register": "中性", "sense_fingerprint": "对人宽容，不生气，接受别人与自己的不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3f596a-ea6f-4092-8aea-7d56453cebea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91107, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生气", "is_correct": false, "explanation": "配价：“生气”要说“生某人的气”，不能直接带人作宾语，“很生气我”不成立。"}, {"text": "殴打", "is_correct": false, "explanation": "语义：“殴打”与“朋友”和友好的语境相反，句子读起来不合理。"}, {"text": "包容", "is_correct": true, "explanation": "正确：“包容”表示不生别人的气、接受对方，与“朋友很……我”的语境相符。"}, {"text": "辱骂", "is_correct": false, "explanation": "语义：“辱骂”与“朋友”之间的友好关系相冲突，不符合句子语境。"}], "explanations": {"生气": "配价：“生气”要说“生某人的气”，不能直接带人作宾语，“很生气我”不成立。", "殴打": "语义：“殴打”与“朋友”和友好的语境相反，句子读起来不合理。", "包容": "正确：“包容”表示不生别人的气、接受对方，与“朋友很……我”的语境相符。", "辱骂": "语义：“辱骂”与“朋友”之间的友好关系相冲突，不符合句子语境。"}, "sentence_index": 0, "correct_answer": "包容"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她包容了伤心的朋友。", "explanation": "这里应该用〈安慰〉。包容指接受别人的缺点或不同，不表示劝慰伤心的人。"}, {"text": "老师包容了他的作业。", "explanation": "这里应该用〈批改〉。包容指接受别人的缺点或不同，不能用于处理作业。"}, {"text": "我实在包容不了这么大的噪音。", "explanation": "这里应该用〈容忍〉。包容用于接受他人的缺点或不同的想法，不用于忍受噪音等外界刺激。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91107, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”与“要学会”所表达的正面态度相反，不符合句子语境。"}, {"text": "复制", "is_correct": false, "explanation": "搭配：“复制”的对象是文件、图像等，不能与“想法”搭配。"}, {"text": "贬低", "is_correct": false, "explanation": "语义：“贬低”与“要学会”的正面态度相悖，句子读起来不合理。"}, {"text": "包容", "is_correct": true, "explanation": "正确：“包容”表示接受与自己不同的想法，与“要学会……不同的想法”相符。"}], "explanations": {"嘲笑": "语义：“嘲笑”与“要学会”所表达的正面态度相反，不符合句子语境。", "复制": "搭配：“复制”的对象是文件、图像等，不能与“想法”搭配。", "贬低": "语义：“贬低”与“要学会”的正面态度相悖，句子读起来不合理。", "包容": "正确：“包容”表示接受与自己不同的想法，与“要学会……不同的想法”相符。"}, "sentence_index": 6, "correct_answer": "包容"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她包容着剧痛，一声不吭。", "explanation": "这里应该用〈忍耐〉。包容用于接受别人的缺点或不同，不用于身体上的疼痛。"}, {"text": "老师包容了他的进步。", "explanation": "这里应该用〈表扬〉。包容是接受对方的缺点或不同，不能用来赞许对方的进步。"}, {"text": "妈妈在店里包容了一件外套。", "explanation": "这里应该用〈挑选〉。包容指接纳别人的缺点或不同，不能用于从多件东西中选出一件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91107, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "哥哥一直包容过我的任性。", "corrected_sentence": "哥哥一直包容着我的任性。", "error_description": "“过”表示经历过，与表示持续状态的“一直”不搭配，应改为表示持续的“着”。正确是“一直包容着”，错误的“一直包容过”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91107, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很少包容了别人的错误。", "corrected_sentence": "他很少包容别人的错误。", "error_description": "“很少”表示经常性的频率，与表示完成的“了”不搭配，应去掉“了”。正确是“很少包容别人的错误”，错误的“很少包容了”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91108, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "排斥", "is_correct": true, "explanation": "反义：包容指容纳、接受，排斥指拒绝或排除，二者互为反义。"}, {"text": "思考", "is_correct": false, "explanation": "无反义关系：“思考”指动脑子想问题，与“包容”的任何义项都不构成反义。"}, {"text": "等待", "is_correct": false, "explanation": "无反义关系：“等待”指停下来等候，与“包容”没有反义关系。"}, {"text": "支持", "is_correct": false, "explanation": "无反义关系：“支持”指赞成或帮助，不是“包容”的反义词。"}], "correct_answer": "排斥", "explanations": {"排斥": "反义：包容指容纳、接受，排斥指拒绝或排除，二者互为反义。", "思考": "无反义关系：“思考”指动脑子想问题，与“包容”的任何义项都不构成反义。", "等待": "无反义关系：“等待”指停下来等候，与“包容”没有反义关系。", "支持": "无反义关系：“支持”指赞成或帮助，不是“包容”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91108, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "排斥", "is_correct": true, "explanation": "反义：包容指接受别人的不同，排斥指拒绝或排除别人，二者互为反义。"}, {"text": "赞美", "is_correct": false, "explanation": "无反义关系：“赞美”指称赞、夸奖，与“包容”没有反义关系。"}, {"text": "前进", "is_correct": false, "explanation": "无反义关系：“前进”指向前移动，与“包容”的任何义项都无关。"}, {"text": "保存", "is_correct": false, "explanation": "无反义关系：“保存”指留存或保管，不是“包容”的反义词。"}], "correct_answer": "排斥", "explanations": {"排斥": "反义：包容指接受别人的不同，排斥指拒绝或排除别人，二者互为反义。", "赞美": "无反义关系：“赞美”指称赞、夸奖，与“包容”没有反义关系。", "前进": "无反义关系：“前进”指向前移动，与“包容”的任何义项都无关。", "保存": "无反义关系：“保存”指留存或保管，不是“包容”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91108, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "宽容、容纳，接受别人的缺点或不同。", "primary_collocate": null, "pronunciation": "bāo róng", "ipa": "pɑʊ̯˥ ʐʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这座城市包容各种文化。", "target_word": "包容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个班的同学包容了新来的学生。", "target_word": "包容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好老师会包容学生的缺点。", "target_word": "包容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个社会应该包容不同的人。", "target_word": "包容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的心很大，能包容一切。", "target_word": "包容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司包容员工犯的小错。", "target_word": "包容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友之间要包容对方的缺点。", "target_word": "包容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸包容着我所有的任性。", "target_word": "包容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的国家包容多种语言。", "target_word": "包容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从没包容过他的缺点。", "target_word": "包容", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "包容了", "label": "体标"}, {"form": "包容着", "label": "体标"}, {"form": "包容过", "label": "体标"}], "register": "中性", "sense_fingerprint": "宽容并容纳他人的缺点或不同的事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3f596a-ea6f-4092-8aea-7d56453cebea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "切割", "is_correct": false, "explanation": "搭配：“切割”通常用于实物，不能与“文化”搭配。"}, {"text": "煮沸", "is_correct": false, "explanation": "语义：“煮沸”指把液体加热到沸腾，与“城市”和“文化”的语境无关。"}, {"text": "包容", "is_correct": true, "explanation": "正确：“包容”表示容纳、接受，与“这座城市……各种文化”的语境相符。"}, {"text": "驱逐", "is_correct": false, "explanation": "语义：“驱逐”指把人或势力赶走，与“城市包容各种文化”的语境相反。"}], "explanations": {"切割": "搭配：“切割”通常用于实物，不能与“文化”搭配。", "煮沸": "语义：“煮沸”指把液体加热到沸腾，与“城市”和“文化”的语境无关。", "包容": "正确：“包容”表示容纳、接受，与“这座城市……各种文化”的语境相符。", "驱逐": "语义：“驱逐”指把人或势力赶走，与“城市包容各种文化”的语境相反。"}, "sentence_index": 0, "correct_answer": "包容"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这封信包容给了老师。", "explanation": "这里应该用〈交给〉。包容指容纳或接受，不能表示把东西递交给别人。"}, {"text": "领导包容了他的努力。", "explanation": "这里应该用〈表扬〉。包容是接纳与自己不同的人或事，不能用来赞许对方的努力。"}, {"text": "银行包容了他的贷款。", "explanation": "这里应该用〈批准〉。包容指接纳人的缺点或不同，不用于银行同意贷款的事务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”对方的缺点与“朋友之间要”的友好要求相违背。"}, {"text": "复制", "is_correct": false, "explanation": "搭配：“复制”不能与“缺点”搭配，“复制对方的缺点”没有意义。"}, {"text": "贬低", "is_correct": false, "explanation": "语义：“贬低”对方与“朋友之间要”的友好要求相反，句子不合理。"}, {"text": "包容", "is_correct": true, "explanation": "正确：“包容”表示接受对方的缺点，与“朋友之间要……对方的缺点”相符。"}], "explanations": {"嘲笑": "语义：“嘲笑”对方的缺点与“朋友之间要”的友好要求相违背。", "复制": "搭配：“复制”不能与“缺点”搭配，“复制对方的缺点”没有意义。", "贬低": "语义：“贬低”对方与“朋友之间要”的友好要求相反，句子不合理。", "包容": "正确：“包容”表示接受对方的缺点，与“朋友之间要……对方的缺点”相符。"}, "sentence_index": 6, "correct_answer": "包容"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很包容你的帮助。", "explanation": "这里应该用〈感谢〉。包容指接纳别人的缺点或不同，不能用来表达对别人帮助的感谢。"}, {"text": "我包容了他的邀请。", "explanation": "这里应该用〈接受〉。包容用于接纳人的缺点或不同，不用于答应别人的邀请。"}, {"text": "我很包容他的勇气。", "explanation": "这里应该用〈赞赏〉。包容不表示赞美，形容别人的勇气应使用赞赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对朋友包容很宽。", "corrected_sentence": "他对朋友包容得很宽。", "error_description": "动词后的程度补语需要用“得”引出。正确是“包容得很宽”，错误的“包容很宽”缺少“得”，不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很少包容了别人的缺点。", "corrected_sentence": "我很少包容别人的缺点。", "error_description": "“很少”表示经常性的频率，与表示完成的“了”不搭配，应去掉“了”。正确是“很少包容别人的缺点”，错误的“很少包容了”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91109, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离去", "is_correct": true, "explanation": "正确：到来（来临）的反义是离去，指时间、季节或人离开。"}, {"text": "停留", "is_correct": false, "explanation": "与到来无反义关系：停留是待在原地，并不是与“来临”相对的意思。"}, {"text": "保持", "is_correct": false, "explanation": "与到来无反义关系：保持表示维持原状，不表示离开。"}, {"text": "继续", "is_correct": false, "explanation": "与到来无反义关系：继续表示接着做下去，不与“来临”相对。"}], "correct_answer": "离去", "explanations": {"离去": "正确：到来（来临）的反义是离去，指时间、季节或人离开。", "停留": "与到来无反义关系：停留是待在原地，并不是与“来临”相对的意思。", "保持": "与到来无反义关系：保持表示维持原状，不表示离开。", "继续": "与到来无反义关系：继续表示接着做下去，不与“来临”相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91109, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离去", "is_correct": true, "explanation": "正确：到来（来临）的反义是离去，指时间、季节或人离开。"}, {"text": "坚持", "is_correct": false, "explanation": "与到来无反义关系：坚持表示持续做某事，不与“来临”相对。"}, {"text": "停止", "is_correct": false, "explanation": "与到来无反义关系：停止与“继续”相对，并不与“到来”相对。"}, {"text": "等待", "is_correct": false, "explanation": "与到来无反义关系：等待表示期望某事发生，与“来临”并不相对。"}], "correct_answer": "离去", "explanations": {"离去": "正确：到来（来临）的反义是离去，指时间、季节或人离开。", "坚持": "与到来无反义关系：坚持表示持续做某事，不与“来临”相对。", "停止": "与到来无反义关系：停止与“继续”相对，并不与“到来”相对。", "等待": "与到来无反义关系：等待表示期望某事发生，与“来临”并不相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91109, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到来是时间或客人来了。", "primary_collocate": null, "pronunciation": "dào lái", "ipa": "taʊ˥˩ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "客人到来时，妈妈正在做饭。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们热情欢迎客人的到来。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的到来让我很意外。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他到来以前，我们先把房间打扫好。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天到来，树叶慢慢变黄了。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课的时间还没到来，同学们在教室里聊天。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末到来，大家都想出去玩。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新同学的到来让班里更热闹了。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们等了很久，客人才到来。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日到来之前，街上就挂满了灯。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "到来了", "label": "体标"}, {"form": "到来的", "label": "复合"}], "register": "中性", "sense_fingerprint": "时间到了或客人、人来了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '336a0206-f607-4671-866d-44fb53eddaab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91109, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "到来", "is_correct": true, "explanation": "正确答案。到来（dào lái）意思是时间到了或人来了。"}, {"text": "带来", "is_correct": false, "explanation": "dài（第四声）与 dào 的韵母不同（ai 与 ao），声调相同，意思是“带来”。"}, {"text": "打来", "is_correct": false, "explanation": "dǎ（第三声）与 dào 韵母和声调都不同，意思是“打来”（如打来电话）。"}, {"text": "得来", "is_correct": false, "explanation": "dé（第二声）与 dào 韵母与声调都不同，意思是“得来”。"}], "explanations": {"到来": "正确答案。到来（dào lái）意思是时间到了或人来了。", "带来": "dài（第四声）与 dào 的韵母不同（ai 与 ao），声调相同，意思是“带来”。", "打来": "dǎ（第三声）与 dào 韵母和声调都不同，意思是“打来”（如打来电话）。", "得来": "dé（第二声）与 dào 韵母与声调都不同，意思是“得来”。"}, "sentence_index": null, "correct_answer": "到来"}, "level_3": {"options": [{"text": "到来", "is_correct": true, "explanation": "正确：到来表示客人来了，与“妈妈正在做饭”的情境相符。"}, {"text": "融化", "is_correct": false, "explanation": "语义：人不会融化，“客人融化时”说不通，与“妈妈正在做饭”的情境不合。"}, {"text": "消失", "is_correct": false, "explanation": "语义：“客人消失时”与“妈妈正在做饭”的情境不合，人不会这样出现。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“客人结束时”说不通，客人不能“结束”。"}], "explanations": {"到来": "正确：到来表示客人来了，与“妈妈正在做饭”的情境相符。", "融化": "语义：人不会融化，“客人融化时”说不通，与“妈妈正在做饭”的情境不合。", "消失": "语义：“客人消失时”与“妈妈正在做饭”的情境不合，人不会这样出现。", "结束": "语义：“客人结束时”说不通，客人不能“结束”。"}, "sentence_index": 0, "correct_answer": "到来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片森林到来了。", "explanation": "这里应该用〈出现〉。到来用于时间或客人来临，森林不能“到来”，森林映入眼帘应说“出现”。"}, {"text": "这座城市到来了。", "explanation": "这里应该用〈建成〉。到来用于时间或客人来临，城市不能“到来”，城市建成应说“建成”。"}, {"text": "这片草地到来了。", "explanation": "这里应该用〈长满〉。到来用于时间或客人来临，草地不能“到来”，草地长满了花应说“长满”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91109, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "到来", "is_correct": true, "explanation": "正确答案。到来（dào lái）意思是时间到了或人来了。"}, {"text": "调来", "is_correct": false, "explanation": "diào（第四声）比 dào 多一个介音 i，意思是“调来”（如调来一位同事）。"}, {"text": "叫来", "is_correct": false, "explanation": "jiào（第四声）与 dào 声母不同（j 与 d），意思是“叫来”。"}, {"text": "早来", "is_correct": false, "explanation": "zǎo（第三声）与 dào 声母不同（z 与 d），声调也不同，意思是“早来”。"}, {"text": "讨来", "is_correct": false, "explanation": "tǎo（第三声）与 dào 声母不同（t 与 d），声调也不同，意思是“讨来”。"}], "explanations": {"到来": "正确答案。到来（dào lái）意思是时间到了或人来了。", "调来": "diào（第四声）比 dào 多一个介音 i，意思是“调来”（如调来一位同事）。", "叫来": "jiào（第四声）与 dào 声母不同（j 与 d），意思是“叫来”。", "早来": "zǎo（第三声）与 dào 声母不同（z 与 d），声调也不同，意思是“早来”。", "讨来": "tǎo（第三声）与 dào 声母不同（t 与 d），声调也不同，意思是“讨来”。"}, "sentence_index": null, "correct_answer": "到来"}, "level_3": {"options": [{"text": "到来", "is_correct": true, "explanation": "正确：到来表示周末来临，与“大家都想出去玩”的语境相符。"}, {"text": "远去", "is_correct": false, "explanation": "语义：“周末远去”与“大家都想出去玩”的时间语境相悖。"}, {"text": "光临", "is_correct": false, "explanation": "语域：“光临”是敬辞，用于客人到访，不宜用来叙述周末。"}, {"text": "撤离", "is_correct": false, "explanation": "语义：“周末撤离”说不通，周末不会像人一样撤走。"}], "explanations": {"到来": "正确：到来表示周末来临，与“大家都想出去玩”的语境相符。", "远去": "语义：“周末远去”与“大家都想出去玩”的时间语境相悖。", "光临": "语域：“光临”是敬辞，用于客人到访，不宜用来叙述周末。", "撤离": "语义：“周末撤离”说不通，周末不会像人一样撤走。"}, "sentence_index": 6, "correct_answer": "到来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌到来了。", "explanation": "这里应该用〈响起〉。到来用于时间或客人来临，歌不能“到来”，歌声响起应说“响起”。"}, {"text": "这间教室到来了。", "explanation": "这里应该用〈布置好〉。到来不能用于教室，教室布置好了应说“布置好”。"}, {"text": "这盆花到来了。", "explanation": "这里应该用〈开〉。到来不能用于花，花开了应说“开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91109, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "客人到来了时，我们正在吃饭。", "corrected_sentence": "客人到来时，我们正在吃饭。", "error_description": "错误：“到来了时”不成立。“到来了”可作谓语（如“春天到来了”），但接“时”组成时间状语时不带“了”，应为“客人到来时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91109, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天节日就要到来过，街上很热闹。", "corrected_sentence": "明天节日就要到来，街上很热闹。", "error_description": "错误：“到来”后多加了“过”。“过”表示曾经的经历，与“就要”所表示的将来不符。正确形式是去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
