INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91110, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离去", "is_correct": true, "explanation": "正确：到来（来临）的反义是离去，指时间、季节或人离开。"}, {"text": "坚持", "is_correct": false, "explanation": "与到来无反义关系：坚持表示持续做某事，不与“来临”相对。"}, {"text": "停止", "is_correct": false, "explanation": "与到来无反义关系：停止表示不再继续，它与“继续”相对，而不与“到来”相对。"}, {"text": "等待", "is_correct": false, "explanation": "与到来无反义关系：等待表示期望某事发生，与“来临”并不相对。"}], "correct_answer": "离去", "explanations": {"离去": "正确：到来（来临）的反义是离去，指时间、季节或人离开。", "坚持": "与到来无反义关系：坚持表示持续做某事，不与“来临”相对。", "停止": "与到来无反义关系：停止表示不再继续，它与“继续”相对，而不与“到来”相对。", "等待": "与到来无反义关系：等待表示期望某事发生，与“来临”并不相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91110, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "来到；来临。", "primary_collocate": null, "pronunciation": "dào lái", "ipa": "taʊ˥˩ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "春天到来了，花都开了。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年就要到来，大家都很高兴。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一直期待着比赛的到来。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试到来之前，我每天复习。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到来，天气一天比一天冷。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在等新年的到来。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好消息的到来让全家人很开心。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天到来了，我们去海边玩吧。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期快要到来，同学们很兴奋。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨季到来后，这里常常下雨。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "到来了", "label": "体标"}, {"form": "到来的", "label": "复合"}], "register": "中性", "sense_fingerprint": "某个时刻、季节或事情来临、来到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '336a0206-f607-4671-866d-44fb53eddaab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91110, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "到来", "is_correct": true, "explanation": "正确答案。到来（dào lái）意思是来到、来临。"}, {"text": "带来", "is_correct": false, "explanation": "dài（第四声）与 dào 的韵母不同（ai 与 ao），声调相同，意思是“带来”。"}, {"text": "讨来", "is_correct": false, "explanation": "tǎo（第三声）与 dào 声母不同（t 与 d），声调也不同，意思是“讨来”。"}, {"text": "打来", "is_correct": false, "explanation": "dǎ（第三声）与 dào 韵母和声调都不同，意思是“打来”（如打来电话）。"}, {"text": "得来", "is_correct": false, "explanation": "dé（第二声）与 dào 韵母与声调都不同，意思是“得来”（如得来不易）。"}], "explanations": {"到来": "正确答案。到来（dào lái）意思是来到、来临。", "带来": "dài（第四声）与 dào 的韵母不同（ai 与 ao），声调相同，意思是“带来”。", "讨来": "tǎo（第三声）与 dào 声母不同（t 与 d），声调也不同，意思是“讨来”。", "打来": "dǎ（第三声）与 dào 韵母和声调都不同，意思是“打来”（如打来电话）。", "得来": "dé（第二声）与 dào 韵母与声调都不同，意思是“得来”（如得来不易）。"}, "sentence_index": null, "correct_answer": "到来"}, "level_3": {"options": [{"text": "到来", "is_correct": true, "explanation": "正确：到来表示春天来临，与后文“花都开了”相符。"}, {"text": "离开", "is_correct": false, "explanation": "语义：“春天离开了”与后文“花都开了”的时令冲突。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“春天结束了”与“花都开了”的时令不合。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：春天不能被“拆除”，“春天拆除了”说不通，与“花都开了”也不合。"}], "explanations": {"到来": "正确：到来表示春天来临，与后文“花都开了”相符。", "离开": "语义：“春天离开了”与后文“花都开了”的时令冲突。", "结束": "语义：“春天结束了”与“花都开了”的时令不合。", "拆除": "语义：春天不能被“拆除”，“春天拆除了”说不通，与“花都开了”也不合。"}, "sentence_index": 0, "correct_answer": "到来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山到来了。", "explanation": "这里应该用〈出现〉。到来用于人、季节或事情来临，山不能“到来”，山映入眼帘应说“出现”。"}, {"text": "他的身高到来了。", "explanation": "这里应该用〈长高〉。到来指人、季节或事情来临，身高是人的属性，不能说“到来”，应说“长高”。"}, {"text": "这条路到来了。", "explanation": "这里应该用〈延伸〉。到来指人、季节或事情来临，道路不能“到来”，表示道路向前伸展应说“延伸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91110, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "到来", "is_correct": true, "explanation": "正确答案。到来（dào lái）意思是来到、来临。"}, {"text": "调来", "is_correct": false, "explanation": "diào（第四声）比 dào 多一个介音 i，意思是“调来”（如调来一位老师）。"}, {"text": "叫来", "is_correct": false, "explanation": "jiào（第四声）与 dào 声母不同（j 与 d），意思是“叫来”。"}, {"text": "早来", "is_correct": false, "explanation": "zǎo（第三声）与 dào 声母不同（z 与 d），声调也不同，意思是“早来”。"}], "explanations": {"到来": "正确答案。到来（dào lái）意思是来到、来临。", "调来": "diào（第四声）比 dào 多一个介音 i，意思是“调来”（如调来一位老师）。", "叫来": "jiào（第四声）与 dào 声母不同（j 与 d），意思是“叫来”。", "早来": "zǎo（第三声）与 dào 声母不同（z 与 d），声调也不同，意思是“早来”。"}, "sentence_index": null, "correct_answer": "到来"}, "level_3": {"options": [{"text": "到来", "is_correct": true, "explanation": "正确：到来作名词，指好消息的来临，与“让全家人很开心”相符。"}, {"text": "远去", "is_correct": false, "explanation": "语义：“好消息远去”与“全家人很开心”的结果相悖。"}, {"text": "撤离", "is_correct": false, "explanation": "语义：“好消息撤离”说不通，与全家人开心的结果不合。"}, {"text": "消逝", "is_correct": false, "explanation": "搭配：“消逝”多用于时光、记忆，不宜说好消息的消逝。"}], "explanations": {"到来": "正确：到来作名词，指好消息的来临，与“让全家人很开心”相符。", "远去": "语义：“好消息远去”与“全家人很开心”的结果相悖。", "撤离": "语义：“好消息撤离”说不通，与全家人开心的结果不合。", "消逝": "搭配：“消逝”多用于时光、记忆，不宜说好消息的消逝。"}, "sentence_index": 6, "correct_answer": "到来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥到来了。", "explanation": "这里应该用〈建成〉。到来用于人、季节或事情来临，桥不能“到来”，桥修好了应说“建成”。"}, {"text": "这首诗到来了。", "explanation": "这里应该用〈写成〉。到来不能用于作品，诗写成了应说“写成”。"}, {"text": "这个道理到来了。", "explanation": "这里应该用〈懂得〉。到来不能用于道理，懂得一个道理应说“懂得”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秋天到来的了，树叶黄了。", "corrected_sentence": "秋天到来了，树叶黄了。", "error_description": "错误：“到来的了”在“了”前多加了“的”。“到来”作谓语时不加“的”，加“的”后“到来”变成定语，后面不能接谓语，不成句。正确形式是“秋天到来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天春节就要到来过，家家户户都很忙。", "corrected_sentence": "明天春节就要到来，家家户户都很忙。", "error_description": "错误：“到来”后多加了“过”。“过”表示曾经的经历，与“就要”所表示的将来不符。正确形式是去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
