INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91111, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一家大公司里最大的头头。", "primary_collocate": null, "pronunciation": "dǒng shì zhǎng", "ipa": "tʊŋ˨˩ ʂɻ̩˥˩ ʈʂɑŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "他是这家大公司的董事长。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的舅舅当了董事长。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "董事长的办公室在最高的一层。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里谁都得听董事长的。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "董事长开着一辆黑色的车来了。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想做大公司的董事长。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见到董事长，大家都站了起来。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "董事长一句话，全公司都忙起来。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是我们公司最年轻的董事长。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "董事长今天请大家吃饭。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副董事长", "label": "复合"}], "register": "口语", "sense_fingerprint": "大公司里最大的头头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fdab5a9-2bdd-478f-be4b-21194dec5a85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91111, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：学生是在校学习的人，不是大公司的负责人。"}, {"text": "董事长", "is_correct": true, "explanation": "“他是这家大公司的董事长”说的是大公司里的最大负责人，符合句意。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不是人，不能说“他是公司的椅子”。"}, {"text": "会议", "is_correct": false, "explanation": "配价：“是……的”后要接人，会议不能充当人物。"}], "explanations": {"学生": "语义：学生是在校学习的人，不是大公司的负责人。", "董事长": "“他是这家大公司的董事长”说的是大公司里的最大负责人，符合句意。", "椅子": "语义：椅子是家具，不是人，不能说“他是公司的椅子”。", "会议": "配价：“是……的”后要接人，会议不能充当人物。"}, "sentence_index": 0, "correct_answer": "董事长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的董事长很负责任。", "explanation": "这里应该用〈班主任〉。董事长是公司董事会的负责人，班级的负责人是班主任。"}, {"text": "我们公司来了一棵董事长。", "explanation": "这里应该用〈个〉。“棵”用于植物，指人要用“个”或“位”。"}, {"text": "连队的董事长下了命令。", "explanation": "这里应该用〈连长〉。连队的负责人是连长，董事长只用于公司。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91111, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小狗", "is_correct": false, "explanation": "语义：小狗不会让大家一见到它就站起来，句意不通。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不会让大家一见就站起来，这种说法不符合常理。"}, {"text": "董事长", "is_correct": true, "explanation": "“见到董事长”表示大家见到地位高的人而站起来，符合句意。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“见到考试”后大家站起来，语义不通，与“站起来”的礼节场景不搭。"}], "explanations": {"小狗": "语义：小狗不会让大家一见到它就站起来，句意不通。", "雨": "语义：雨不会让大家一见就站起来，这种说法不符合常理。", "董事长": "“见到董事长”表示大家见到地位高的人而站起来，符合句意。", "考试": "搭配：“见到考试”后大家站起来，语义不通，与“站起来”的礼节场景不搭。"}, "sentence_index": 6, "correct_answer": "董事长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "董事长今天给大家打针。", "explanation": "这里应该用〈医生〉。董事长不负责给人打针。"}, {"text": "这台机器是我们公司的董事长。", "explanation": "这里应该用〈设备〉。董事长指公司董事会的负责人，只能指人，机器应说“设备”。"}, {"text": "董事长今天守着大门。", "explanation": "这里应该用〈保安〉。董事长管理公司，不负责守门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91111, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "董事长说很对。", "corrected_sentence": "董事长说得很对。", "error_description": "补语错误：“说很对”缺少补语标记“得”，应该说「说得很对」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91111, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "董事长站了讲话。", "corrected_sentence": "董事长站着讲话。", "error_description": "体标错误：表示“站”的持续状态要用“着”，不能用“了”，应该说「站着讲话」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
