INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91112, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "公司董事会的负责人，代表公司主持重大决策。", "primary_collocate": null, "pronunciation": "dǒng shì zhǎng", "ipa": "tʊŋ˨˩ ʂɻ̩˥˩ ʈʂɑŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "董事长主持了今天的董事会。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的董事长是一位老先生。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "董事长要决定这件大事。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他三年前当上了董事长。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "董事长在会上讲了公司的计划。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的董事长姓王。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "董事长把重要的文件交给了秘书。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的董事长很少接受采访。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "董事长和经理一起讨论新项目。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "董事长对大家的工作很满意。", "target_word": "董事长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副董事长", "label": "复合"}], "register": "书面", "sense_fingerprint": "公司董事会的负责人，主持重大决策", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fdab5a9-2bdd-478f-be4b-21194dec5a85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91112, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小狗", "is_correct": false, "explanation": "语义：小狗不能主持公司的董事会。"}, {"text": "董事长", "is_correct": true, "explanation": "董事长是董事会的负责人，主持董事会是其职责。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生不会主持公司的董事会。"}, {"text": "会议", "is_correct": false, "explanation": "搭配：“会议”不能作“主持”的施事，应由人来主持会议。"}], "explanations": {"小狗": "语义：小狗不能主持公司的董事会。", "董事长": "董事长是董事会的负责人，主持董事会是其职责。", "学生": "语义：学生不会主持公司的董事会。", "会议": "搭配：“会议”不能作“主持”的施事，应由人来主持会议。"}, "sentence_index": 0, "correct_answer": "董事长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他三年前当上了办公室的董事长。", "explanation": "这里应该用〈主任〉。办公室的负责人叫主任，董事长是公司董事会的负责人。"}, {"text": "他三年前当选为国家董事长。", "explanation": "这里应该用〈主席〉。国家的最高负责人称主席，董事长只用于公司。"}, {"text": "他三年前当上了军队的董事长。", "explanation": "这里应该用〈司令〉。军队的负责人是司令或首长，董事长只用于公司。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下雨", "is_correct": false, "explanation": "配价：“下雨”是天气现象，不能作“把文件交给秘书”的施事。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不能管理公司文件，句子不成立。"}, {"text": "董事长", "is_correct": true, "explanation": "董事长有权把重要文件交给秘书，与句意相符。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“交给”需要有生命的施事，窗户不能作施事。"}], "explanations": {"下雨": "配价：“下雨”是天气现象，不能作“把文件交给秘书”的施事。", "小猫": "语义：小猫不能管理公司文件，句子不成立。", "董事长": "董事长有权把重要文件交给秘书，与句意相符。", "窗户": "配价：“交给”需要有生命的施事，窗户不能作施事。"}, "sentence_index": 6, "correct_answer": "董事长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班里的董事长对大家的工作很满意。", "explanation": "这里应该用〈班长〉。董事长指公司董事会的负责人，班级的负责人叫班长。"}, {"text": "那位董事长治好了他的病。", "explanation": "这里应该用〈医生〉。董事长是公司负责人，不负责治病。"}, {"text": "门口的董事长每天守着大门。", "explanation": "这里应该用〈保安〉。董事长管理公司，不负责看守大门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司来了一只新董事长。", "corrected_sentence": "这家公司来了一位新董事长。", "error_description": "量词错误：董事长指人，应用表示尊敬的量词“位”，不能用动物量词“只”，正确说法是「一位新董事长」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "董事长讲很清楚。", "corrected_sentence": "董事长讲得很清楚。", "error_description": "补语错误：“讲很清楚”缺少补语标记“得”，应该说「讲得很清楚」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91113, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "分散与汇集构成反义：汇集是聚到一处，分散是散开。"}, {"text": "漂浮", "is_correct": false, "explanation": "漂浮指浮在液体表面，与汇集没有反义关系。"}, {"text": "修建", "is_correct": false, "explanation": "修建指建造工程，与汇集没有反义关系。"}, {"text": "放弃", "is_correct": false, "explanation": "放弃指舍去某种念头或权利，与汇集没有反义关系。"}], "correct_answer": "分散", "explanations": {"分散": "分散与汇集构成反义：汇集是聚到一处，分散是散开。", "漂浮": "漂浮指浮在液体表面，与汇集没有反义关系。", "修建": "修建指建造工程，与汇集没有反义关系。", "放弃": "放弃指舍去某种念头或权利，与汇集没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
