INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91113, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "汇集是把很多东西聚到一个地方。", "primary_collocate": null, "pronunciation": "huì jí", "ipa": "xweɪ˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "河水都汇集到这个湖里。", "target_word": "汇集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水汇集在路边的小沟里。", "target_word": "汇集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把大家的作业汇集到一起。", "target_word": "汇集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小溪汇集成一条大河。", "target_word": "汇集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把所有的照片汇集在一本书里。", "target_word": "汇集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的水汇集到了山脚下。", "target_word": "汇集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把各种信息汇集起来，写成报告。", "target_word": "汇集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，水汇集在院子中间。", "target_word": "汇集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里汇集了很多好书。", "target_word": "汇集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些资料是从各地汇集起来的。", "target_word": "汇集", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "汇集了", "label": "体标"}, {"form": "汇集着", "label": "体标"}, {"form": "汇集过", "label": "体标"}], "register": "书面", "sense_fingerprint": "许多事物（水、物品、资料）聚到同一处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2159400-947f-4fbc-9ddc-227cd6535575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91113, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汇集", "is_correct": true, "explanation": "正确：汇集指许多事物聚到同一处，与“河水都……到这个湖里”的语义相合。"}, {"text": "分散", "is_correct": false, "explanation": "语义：分散是散开，与“都……到这个湖里”的聚合方向相反。"}, {"text": "蒸发", "is_correct": false, "explanation": "语义：蒸发是水变成水汽，不会流到湖里。"}, {"text": "干涸", "is_correct": false, "explanation": "配价：干涸是不及物动词，不能带“到这个湖里”这样的处所补足语。"}], "explanations": {"汇集": "正确：汇集指许多事物聚到同一处，与“河水都……到这个湖里”的语义相合。", "分散": "语义：分散是散开，与“都……到这个湖里”的聚合方向相反。", "蒸发": "语义：蒸发是水变成水汽，不会流到湖里。", "干涸": "配价：干涸是不及物动词，不能带“到这个湖里”这样的处所补足语。"}, "sentence_index": 0, "correct_answer": "汇集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一只鸟汇集在树上。", "explanation": "这里应该用〈停〉。汇集指许多事物聚到一处，单只鸟停在树上要说“停”。"}, {"text": "我每天去海边汇集贝壳。", "explanation": "这里应该用〈收集〉。汇集强调从各处聚拢，个人拾取贝壳要说“收集”。"}, {"text": "这把椅子汇集在房间里。", "explanation": "这里应该用〈放〉。汇集指许多事物聚到一处，单独一把椅子摆在房间里要说“放”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91113, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汇集", "is_correct": true, "explanation": "正确：汇集指许多信息聚到一起，与“把各种信息……起来，写成报告”相合。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：隐藏起来就无法用来写报告，与后文的“写成报告”相冲突。"}, {"text": "散布", "is_correct": false, "explanation": "语义：散布是扩散开来，与“起来”表示聚合的用法不符。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：“删除”后一般不接“起来”，应说“删掉”。"}], "explanations": {"汇集": "正确：汇集指许多信息聚到一起，与“把各种信息……起来，写成报告”相合。", "隐藏": "语义：隐藏起来就无法用来写报告，与后文的“写成报告”相冲突。", "散布": "语义：散布是扩散开来，与“起来”表示聚合的用法不符。", "删除": "搭配：“删除”后一般不接“起来”，应说“删掉”。"}, "sentence_index": 6, "correct_answer": "汇集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师汇集全班同学开会。", "explanation": "这里应该用〈召集〉。召集是主动把人叫到一起，汇集只说人或事物从各处聚拢，不用于主动号召。"}, {"text": "她把房间汇集得干净整洁。", "explanation": "这里应该用〈收拾〉。汇集指聚到一处，不表示整理使其干净。"}, {"text": "他把工资汇集到了妈妈的账户。", "explanation": "这里应该用〈汇〉。汇集指许多事物聚到一处，把钱寄给别人要用“汇”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91113, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨水都汇集池塘里。", "corrected_sentence": "雨水都汇集到池塘里。", "error_description": "“汇集”后面引出处所要用“到”（或“在”）。这里漏掉了“到”，应改为“汇集到池塘里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91113, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "各地的资料都汇集了一起。", "corrected_sentence": "各地的资料都汇集到了一起。", "error_description": "“汇集”后引出归宿要用“到”（或“在”）。这里漏掉了“到”，应为“汇集到了一起”；“汇集了一起”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
