INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91116, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "旧时指科举考试中选，特别是考中进士。", "primary_collocate": null, "pronunciation": "jí dì", "ipa": "tɕi˧˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "他在京城参加科举，终于及第了。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的书生都盼着能及第。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥去京城赶考，可惜没有及第。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说儿子在科举中及第，全家都高兴极了。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他及第以后，皇帝让他去当县官。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子很多年没人及第过。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在科举中不但及第了，而且是第一名。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考官读了他的文章，说他一定能及第。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的书生想及第，要先读很多年书。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考了三次科举，第四次才及第。", "target_word": "及第", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "及第了", "label": "体标"}, {"form": "及第过", "label": "体标"}, {"form": "状元及第", "label": "复合"}], "register": "书面", "sense_fingerprint": "旧时科举考试中选，尤指考中进士", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7282aa94-d036-4e81-924d-e6357978ec59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91116, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "及第", "is_correct": true, "explanation": "及第：本题目标词，读作 jí dì，指旧时科举中选。"}, {"text": "基地", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是基地（根据地）。"}, {"text": "寄递", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是寄递（邮寄传递）。"}, {"text": "急待", "is_correct": false, "explanation": "dài（第四声）与 dì（第四声）韵母不同，意思是急切地需要或等待。"}], "explanations": {"及第": "及第：本题目标词，读作 jí dì，指旧时科举中选。", "基地": "jī（第一声）与 jí（第二声）声调不同，意思是基地（根据地）。", "寄递": "jì（第四声）与 jí（第二声）声调不同，意思是寄递（邮寄传递）。", "急待": "dài（第四声）与 dì（第四声）韵母不同，意思是急切地需要或等待。"}, "sentence_index": null, "correct_answer": "及第"}, "level_3": {"options": [{"text": "及第", "is_correct": true, "explanation": "及第：科举中选，与“终于”搭配，符合句意。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：“毕业”用于学校，不用于科举考试。"}, {"text": "退休", "is_correct": false, "explanation": "语义：退休与“参加科举”矛盾，参加考试的人不会退休。"}, {"text": "出发", "is_correct": false, "explanation": "语义：“在京城”说明人已经在京城，“出发”与之矛盾。"}], "explanations": {"及第": "及第：科举中选，与“终于”搭配，符合句意。", "毕业": "搭配：“毕业”用于学校，不用于科举考试。", "退休": "语义：退休与“参加科举”矛盾，参加考试的人不会退休。", "出发": "语义：“在京城”说明人已经在京城，“出发”与之矛盾。"}, "sentence_index": 0, "correct_answer": "及第"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的公司这次投标及第了。", "explanation": "这里应该用〈中标〉。及第只指科举中选，投标中选不说“及第”。"}, {"text": "他在运动会上及第了。", "explanation": "这里应该用〈获奖〉。及第只指科举中选，运动会上获奖不说“及第”。"}, {"text": "他在国家队选拔中及第了。", "explanation": "这里应该用〈入选〉。及第是科举用语，不用于国家队这类一般选拔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91116, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "及第", "is_correct": true, "explanation": "及第：本题目标词，读作 jí dì，指旧时科举中选。"}, {"text": "基底", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）、dǐ（第三声）与 dì（第四声）声调都不同，意思是基础、底子。"}, {"text": "极力", "is_correct": false, "explanation": "lì（第四声）与 dì（第四声）声母不同，意思是竭尽全力。"}, {"text": "嫡弟", "is_correct": false, "explanation": "dí（第二声）与 jí（第二声）声母不同（d 与 j），第二个音节同为 dì，意思是同父同母的亲弟弟。"}], "explanations": {"及第": "及第：本题目标词，读作 jí dì，指旧时科举中选。", "基底": "jī（第一声）与 jí（第二声）、dǐ（第三声）与 dì（第四声）声调都不同，意思是基础、底子。", "极力": "lì（第四声）与 dì（第四声）声母不同，意思是竭尽全力。", "嫡弟": "dí（第二声）与 jí（第二声）声母不同（d 与 j），第二个音节同为 dì，意思是同父同母的亲弟弟。"}, "sentence_index": null, "correct_answer": "及第"}, "level_3": {"options": [{"text": "及第", "is_correct": true, "explanation": "及第：科举中选，与“不但……而且是第一名”的语境相符。"}, {"text": "落第", "is_correct": false, "explanation": "语义：落第与后面的“第一名”矛盾，考试没有考中不可能是第一名。"}, {"text": "辞职", "is_correct": false, "explanation": "搭配：“辞职”用于工作单位，不用于科举考试。"}, {"text": "退学", "is_correct": false, "explanation": "搭配：“退学”用于学校，不用于科举考试。"}], "explanations": {"及第": "及第：科举中选，与“不但……而且是第一名”的语境相符。", "落第": "语义：落第与后面的“第一名”矛盾，考试没有考中不可能是第一名。", "辞职": "搭配：“辞职”用于工作单位，不用于科举考试。", "退学": "搭配：“退学”用于学校，不用于科举考试。"}, "sentence_index": 6, "correct_answer": "及第"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次数学考试及第了。", "explanation": "这里应该用〈及格〉。及第只指旧时科举中选，学校考试用“及格”。"}, {"text": "他面试及第了。", "explanation": "这里应该用〈通过〉。及第专指科举中选，面试不用“及第”。"}, {"text": "这批产品及第了。", "explanation": "这里应该用〈合格〉。及第只用于人在科举中考中，产品不能说“及第”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的祖父当年被及第了，做了县令。", "corrected_sentence": "他的祖父当年及第了，做了县令。", "error_description": "错误：在“及第”前加了“被”。“及第”是不及物动词，不能构成被动句。应说“他的祖父当年及第了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年没及第了，很难过。", "corrected_sentence": "他去年没及第，很难过。", "error_description": "错误：否定句“没及第”后面多加了“了”。“没”与“了”不能同时用在这里，应去掉“了”，说“他去年没及第”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91117, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "善待", "is_correct": true, "explanation": "与“虐待”相反，指好好地对待人或动物。"}, {"text": "观察", "is_correct": false, "explanation": "只表示仔细看，与“虐待”没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "表示把东西从一处运到另一处，与“虐待”没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "表示使东西恢复正常，与“虐待”没有反义关系。"}], "correct_answer": "善待", "explanations": {"善待": "与“虐待”相反，指好好地对待人或动物。", "观察": "只表示仔细看，与“虐待”没有反义关系。", "搬运": "表示把东西从一处运到另一处，与“虐待”没有反义关系。", "修理": "表示使东西恢复正常，与“虐待”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91117, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "善待", "is_correct": true, "explanation": "与“虐待”相反，指好好地对待人或动物。"}, {"text": "翻译", "is_correct": false, "explanation": "表示把一种语言转换成另一种语言，与“虐待”没有反义关系。"}, {"text": "装修", "is_correct": false, "explanation": "表示对房屋进行修饰布置，与“虐待”没有反义关系。"}, {"text": "吟诵", "is_correct": false, "explanation": "表示有节奏地朗读诗文，与“虐待”没有反义关系。"}], "correct_answer": "善待", "explanations": {"善待": "与“虐待”相反，指好好地对待人或动物。", "翻译": "表示把一种语言转换成另一种语言，与“虐待”没有反义关系。", "装修": "表示对房屋进行修饰布置，与“虐待”没有反义关系。", "吟诵": "表示有节奏地朗读诗文，与“虐待”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91117, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对人或小动物很坏，让他们很疼很难过。", "primary_collocate": null, "pronunciation": "nüè dài", "ipa": "nɥe˥˩ tai˥˩", "syllable_count": 2, "sentences": [{"text": "他的继母常常虐待他。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要虐待小猫小狗。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人虐待过自己的狗。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虐待老人是不对的。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居虐待孩子，我们报了警。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为什么要虐待那只小鸟？", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人虐待了流浪猫，大家都很生气。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，不能虐待小动物。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们虐待小狗，让它每天挨饿。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是虐待我，我很难过。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "虐待了", "label": "体标"}, {"form": "虐待过", "label": "体标"}], "register": "中性", "sense_fingerprint": "对弱小的人或小动物很坏，让他们疼痛难过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730fb564-1f17-41e9-bd26-11f585744996') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91117, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "虐待", "is_correct": true, "explanation": "残忍地对待，正好符合句中“继母常常……他”的意思。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”多用于动物或家畜，不说饲养一个人。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”用于植物或田地，不用于人。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”指修饰物品，句中的对象是“他”，说不通。"}], "explanations": {"虐待": "残忍地对待，正好符合句中“继母常常……他”的意思。", "饲养": "搭配：“饲养”多用于动物或家畜，不说饲养一个人。", "浇灌": "搭配：“浇灌”用于植物或田地，不用于人。", "装饰": "语义：“装饰”指修饰物品，句中的对象是“他”，说不通。"}, "sentence_index": 0, "correct_answer": "虐待"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总是认真虐待每一份工作。", "explanation": "这里应该用〈对待〉。虐待只用于残忍地对待人或小动物，不能用于工作。"}, {"text": "这场大病虐待了他整整一年。", "explanation": "这里应该用〈折磨〉。虐待的施事通常是人或动物，疾病不能“虐待”人，应说“折磨”。"}, {"text": "他热情虐待了远道而来的客人。", "explanation": "这里应该用〈招待〉。虐待是残忍地对待，与“热情”矛盾，招待客人才说“热情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91117, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "虐待", "is_correct": true, "explanation": "残忍地对待，符合句中“有人……流浪猫”的意思。"}, {"text": "救助", "is_correct": false, "explanation": "语义：“救助”是帮助，与后面“大家都很生气”矛盾。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”是称赞，与“大家都很生气”矛盾。"}, {"text": "养育", "is_correct": false, "explanation": "搭配：“养育”多用于子女或人，不说养育流浪猫。"}], "explanations": {"虐待": "残忍地对待，符合句中“有人……流浪猫”的意思。", "救助": "语义：“救助”是帮助，与后面“大家都很生气”矛盾。", "赞美": "语义：“赞美”是称赞，与“大家都很生气”矛盾。", "养育": "搭配：“养育”多用于子女或人，不说养育流浪猫。"}, "sentence_index": 6, "correct_answer": "虐待"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶把孙子虐待得很好。", "explanation": "这里应该用〈照顾〉。虐待是残忍地对待，不能说“虐待得很好”。"}, {"text": "他不小心虐待了那只小猫。", "explanation": "这里应该用〈伤害〉。虐待含有故意残忍的意思，不小心造成的伤害不能用“虐待”。"}, {"text": "他的虐待让我很高兴。", "explanation": "这里应该用〈关心〉。虐待是伤害别人的行为，不会让人高兴，关心别人才会让人感到温暖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91117, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把小猫虐待很惨。", "corrected_sentence": "他把小猫虐待得很惨。", "error_description": "“虐待”后接程度补语时，要在动词和补语之间加“得”。应说“虐待得很惨”，不能省略“得”直接说“虐待很惨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91117, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她被继母虐待的很惨。", "corrected_sentence": "她被继母虐待得很惨。", "error_description": "“虐待”后的程度补语要用结构助词“得”，不能用“的”。应说“虐待得很惨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91118, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "善待", "is_correct": true, "explanation": "与“虐待”相反，指好好地对待人或动物。"}, {"text": "写作", "is_correct": false, "explanation": "表示写文章或作品，与“虐待”没有反义关系。"}, {"text": "收拾", "is_correct": false, "explanation": "表示整理、归置物品，与“虐待”没有反义关系。"}, {"text": "点燃", "is_correct": false, "explanation": "表示使东西着火，与“虐待”没有反义关系。"}], "correct_answer": "善待", "explanations": {"善待": "与“虐待”相反，指好好地对待人或动物。", "写作": "表示写文章或作品，与“虐待”没有反义关系。", "收拾": "表示整理、归置物品，与“虐待”没有反义关系。", "点燃": "表示使东西着火，与“虐待”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91118, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "善待", "is_correct": true, "explanation": "与“虐待”相反，指好好地对待人或动物。"}, {"text": "演唱", "is_correct": false, "explanation": "表示唱歌给别人听，与“虐待”没有反义关系。"}, {"text": "训练", "is_correct": false, "explanation": "表示通过练习使人或动物掌握技能，与“虐待”没有反义关系。"}, {"text": "散布", "is_correct": false, "explanation": "表示向四处传播，与“虐待”没有反义关系。"}], "correct_answer": "善待", "explanations": {"善待": "与“虐待”相反，指好好地对待人或动物。", "演唱": "表示唱歌给别人听，与“虐待”没有反义关系。", "训练": "表示通过练习使人或动物掌握技能，与“虐待”没有反义关系。", "散布": "表示向四处传播，与“虐待”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91118, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用残忍的手段对待，使人或动物身心受到伤害。", "primary_collocate": null, "pronunciation": "nüè dài", "ipa": "nɥe˥˩ tai˥˩", "syllable_count": 2, "sentences": [{"text": "战争中，士兵虐待俘虏。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用残忍的办法虐待那只狗。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个坏人虐待了孩子很多年。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律不允许虐待老人。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他虐待自己的妻子，身上全是伤。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们虐待员工，不给饭吃。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人用火烧小猫，这是虐待动物。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位母亲虐待女儿，让她身心都受了伤。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人说老板常常打骂并虐待他们。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓了虐待儿童的人。", "target_word": "虐待", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "虐待了", "label": "体标"}, {"form": "虐待过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用残忍的手段对待人或动物，造成身心伤害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730fb564-1f17-41e9-bd26-11f585744996') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91118, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "虐待", "is_correct": true, "explanation": "残忍地对待，符合句中“士兵……俘虏”的意思。"}, {"text": "招募", "is_correct": false, "explanation": "搭配：“招募”用于征集兵员或志愿者，不用于俘虏。"}, {"text": "雇用", "is_correct": false, "explanation": "语义：士兵在战争中不会“雇用”俘虏，与句意不符。"}, {"text": "检阅", "is_correct": false, "explanation": "语义：“检阅”是检查队伍，不能用来形容对待俘虏。"}], "explanations": {"虐待": "残忍地对待，符合句中“士兵……俘虏”的意思。", "招募": "搭配：“招募”用于征集兵员或志愿者，不用于俘虏。", "雇用": "语义：士兵在战争中不会“雇用”俘虏，与句意不符。", "检阅": "语义：“检阅”是检查队伍，不能用来形容对待俘虏。"}, "sentence_index": 0, "correct_answer": "虐待"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人认真虐待了那台机器。", "explanation": "这里应该用〈修理〉。虐待只用于对待人或动物，不能用于机器。"}, {"text": "这场大火虐待了很多人。", "explanation": "这里应该用〈伤害〉。虐待的施事通常是人或动物，大火不能“虐待”人。"}, {"text": "护士细心虐待病人。", "explanation": "这里应该用〈照顾〉。虐待是残忍地对待，与“细心”矛盾，照顾病人才说“细心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91118, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "虐待", "is_correct": true, "explanation": "残忍地对待，符合句中“用火烧小猫”的意思。"}, {"text": "爱护", "is_correct": false, "explanation": "语义：“爱护”与“用火烧小猫”的意思完全相反。"}, {"text": "驯化", "is_correct": false, "explanation": "搭配：“驯化”多指把野生动物变为家养，不说驯化家里的小猫。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”与“用火烧小猫”矛盾。"}], "explanations": {"虐待": "残忍地对待，符合句中“用火烧小猫”的意思。", "爱护": "语义：“爱护”与“用火烧小猫”的意思完全相反。", "驯化": "搭配：“驯化”多指把野生动物变为家养，不说驯化家里的小猫。", "照顾": "语义：“照顾”与“用火烧小猫”矛盾。"}, "sentence_index": 6, "correct_answer": "虐待"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生把他虐待得很好。", "explanation": "这里应该用〈治疗〉。虐待是残忍地对待，不能说“虐待得很好”。"}, {"text": "他无意中虐待了老师。", "explanation": "这里应该用〈冒犯〉。虐待含有故意残忍的意思，不能用于无意的过失。"}, {"text": "老师的虐待让我很高兴。", "explanation": "这里应该用〈鼓励〉。虐待会让人痛苦，不会让人高兴，应说“鼓励”让人高兴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91118, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很虐待那只小猫。", "corrected_sentence": "他常常虐待那只小猫。", "error_description": "副词“很”不能修饰动词“虐待”，应用“常常”表示经常发生，说“常常虐待”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91118, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被父亲虐待了过。", "corrected_sentence": "他被父亲虐待过。", "error_description": "动态助词“过”和“了”不能同时用在同一个动词后，应只说“虐待过”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
