INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91119, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "区域网络是把一个小地方里的电脑连起来的网。", "primary_collocate": null, "pronunciation": "qū yù wǎng luò", "ipa": "tɕʰy˥ y˥˩ wɑŋ˨˩˦ lu̯ɔ˥˩", "syllable_count": 4, "sentences": [{"text": "我们学校有一个区域网络。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的电脑都连在区域网络上。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室用区域网络打印文件。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "区域网络出问题了，大家都不能上网。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个区域网络只有十台电脑。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店里的区域网络是新装的。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在区域网络里玩游戏。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他帮公司修好了区域网络。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网吧的区域网络又快又稳。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，区域网络只能连附近的电脑。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个区域网络", "label": "量词"}, {"form": "區域網絡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把一个小地方的电脑连在一起的网", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec25974-71fd-4a3e-aa7f-4714ae3f80b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91119, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "区域网络", "is_correct": true, "explanation": "正确。“我们学校有一个区域网络”指学校里把电脑连起来的网。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：心跳是生物的生理活动，学校不能「有一个心跳」，与「学校」语义冲突。"}, {"text": "流感", "is_correct": false, "explanation": "语义：流感是一种疾病，量词用「场」，学校不能「有一个流感」作为设施。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：学校里不会有沙漠，与“学校”这个场所语义冲突。"}], "explanations": {"区域网络": "正确。“我们学校有一个区域网络”指学校里把电脑连起来的网。", "心跳": "语义：心跳是生物的生理活动，学校不能「有一个心跳」，与「学校」语义冲突。", "流感": "语义：流感是一种疾病，量词用「场」，学校不能「有一个流感」作为设施。", "沙漠": "语义：学校里不会有沙漠，与“学校”这个场所语义冲突。"}, "sentence_index": 0, "correct_answer": "区域网络"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全世界的人都可以用区域网络聊天。", "explanation": "这里应该用〈互联网〉。区域网络只连接较小范围内的设备，不能让全世界的人都连上。"}, {"text": "这次考试的区域网络是三点。", "explanation": "这里应该用〈时间〉。区域网络指把电脑连起来的网，不用来说考试的时间。"}, {"text": "妈妈在厨房里做了一锅区域网络。", "explanation": "这里应该用〈汤〉。区域网络指把电脑连起来的网，不能用来说锅里做的食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91119, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "区域网络", "is_correct": true, "explanation": "正确。“孩子们在区域网络里玩游戏”指在局域范围内的网络里玩游戏。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：孩子不能在冰箱里玩游戏，与常识不符。"}, {"text": "云层", "is_correct": false, "explanation": "语义：孩子不能待在云层里玩游戏，与常识不符。"}, {"text": "方言", "is_correct": false, "explanation": "配价：「在……里」要接场所或范围，方言不是玩游戏的场所。"}], "explanations": {"区域网络": "正确。“孩子们在区域网络里玩游戏”指在局域范围内的网络里玩游戏。", "冰箱": "语义：孩子不能在冰箱里玩游戏，与常识不符。", "云层": "语义：孩子不能待在云层里玩游戏，与常识不符。", "方言": "配价：「在……里」要接场所或范围，方言不是玩游戏的场所。"}, "sentence_index": 6, "correct_answer": "区域网络"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们用区域网络和远方的朋友聊天。", "explanation": "这里应该用〈电话〉。区域网络只连接附近的设备，不能跨越远距离通话。"}, {"text": "今天的区域网络很晴朗。", "explanation": "这里应该用〈天气〉。区域网络指把电脑连起来的网，不能用来形容天气。"}, {"text": "他的区域网络是一名医生。", "explanation": "这里应该用〈人〉。区域网络指把电脑连起来的网，不能用来说一个人的职业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91119, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首区域网络连接了十台电脑。", "corrected_sentence": "这个区域网络连接了十台电脑。", "error_description": "量词错误：「区域网络」应用量词「个」，「首」用于诗词、歌曲，应改为「这个区域网络」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91119, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "区域网络了坏，大家都上不了网。", "corrected_sentence": "区域网络坏了，大家都上不了网。", "error_description": "体标位置错误：「了」应紧跟动词「坏」之后，不能放在「区域网络」与「坏」之间，应说「区域网络坏了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
