INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91120, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在较小范围内将计算机等设备互相连接而成的网络。", "primary_collocate": null, "pronunciation": "qū yù wǎng luò", "ipa": "tɕʰy˥ y˥˩ wɑŋ˨˩˦ lu̯ɔ˥˩", "syllable_count": 4, "sentences": [{"text": "区域网络可以让办公室的电脑互相连接。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "区域网络的范围一般不大，比如一栋楼。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院用区域网络传送病人的资料。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在每层楼都装了区域网络。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "区域网络连接着打印机和电脑。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "区域网络和互联网不一样，范围小得多。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在检查大楼里的区域网络。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生通过区域网络共用一台打印机。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个区域网络里最多能连一百台设备。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用无线路由器也能建一个区域网络。", "target_word": "区域网络", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个区域网络", "label": "量词"}, {"form": "區域網絡", "label": "繁体"}], "register": "书面", "sense_fingerprint": "较小范围内计算机等设备互相连接形成的网络", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec25974-71fd-4a3e-aa7f-4714ae3f80b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "区域网络", "is_correct": true, "explanation": "正确。“区域网络可以让办公室的电脑互相连接”指较小范围内连接设备的网络。"}, {"text": "粉笔", "is_correct": false, "explanation": "语义：粉笔是写字用的文具，没有联网功能，不能让它们互相连接。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水是书写用的液体，与电脑连接无关。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有联网功能，不能让它们互相连接。"}], "explanations": {"区域网络": "正确。“区域网络可以让办公室的电脑互相连接”指较小范围内连接设备的网络。", "粉笔": "语义：粉笔是写字用的文具，没有联网功能，不能让它们互相连接。", "墨水": "语义：墨水是书写用的液体，与电脑连接无关。", "石头": "语义：石头没有联网功能，不能让它们互相连接。"}, "sentence_index": 0, "correct_answer": "区域网络"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "员工可以通过区域网络连接全世界的电脑。", "explanation": "这里应该用〈互联网〉。区域网络只连接较小范围内的设备，不能连接全世界的电脑。"}, {"text": "这一层的区域网络比我高。", "explanation": "这里应该用〈身高〉。区域网络指把设备连起来的网，不能用来比较人的高矮。"}, {"text": "工厂的区域网络很好吃。", "explanation": "这里应该用〈味道〉。区域网络指把设备连起来的网，不能用来说好吃与否。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "区域网络", "is_correct": true, "explanation": "正确。“工程师正在检查大楼里的区域网络”指检查大楼内的网络设备。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是人的情绪，不是可以被检查的设备或网络。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：大楼里不会有云朵可以让工程师检查。"}, {"text": "兴趣", "is_correct": false, "explanation": "搭配：「检查」不能和「兴趣」搭配，应说「培养兴趣」。"}], "explanations": {"区域网络": "正确。“工程师正在检查大楼里的区域网络”指检查大楼内的网络设备。", "心情": "语义：心情是人的情绪，不是可以被检查的设备或网络。", "云朵": "语义：大楼里不会有云朵可以让工程师检查。", "兴趣": "搭配：「检查」不能和「兴趣」搭配，应说「培养兴趣」。"}, "sentence_index": 6, "correct_answer": "区域网络"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们用区域网络和外地的朋友视频通话。", "explanation": "这里应该用〈互联网〉。区域网络只连接较小范围内的设备，不能和外地的人视频通话。"}, {"text": "这次数学测验，区域网络考了九十分。", "explanation": "这里应该用〈成绩〉。区域网络指把设备连起来的网，不能用来说考试的分数。"}, {"text": "办公室的区域网络每天跑步。", "explanation": "这里应该用〈人〉。区域网络指把设备连起来的网，不能做跑步这样的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "办公室的电脑都连在一首区域网络上。", "corrected_sentence": "办公室的电脑都连在一个区域网络上。", "error_description": "量词错误：「区域网络」应用量词「个」，「首」用于诗词、歌曲，应说「一个区域网络」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工程师把区域网络好装了。", "corrected_sentence": "工程师把区域网络装好了。", "error_description": "补语位置错误：「装好」是动补结构，「好」应紧跟动词「装」之后，不能放在「区域网络」与「装」之间，应说「把区域网络装好了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
