INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91121, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "别人给你一些钱，让你不够用的地方够用。", "primary_collocate": null, "pronunciation": "bǔ tiē", "ipa": "pu˨˩˦ tʰi̯e˥", "syllable_count": 2, "sentences": [{"text": "妈妈每月给我一点生活补贴。", "target_word": "补贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的工资不高，幸好有房租补贴。", "target_word": "补贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了这笔补贴，我就能交房租。", "target_word": "补贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸给我的补贴，我都用来买书了。", "target_word": "补贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给我们每人二百元电话补贴。", "target_word": "补贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点补贴够我坐地铁上班。", "target_word": "补贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用补贴买了一台旧电脑。", "target_word": "补贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每个月都有一份交通补贴。", "target_word": "补贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给留学生发生活补贴。", "target_word": "补贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥说他的补贴不够付房租。", "target_word": "补贴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔补贴", "label": "量词"}, {"form": "生活补贴", "label": "复合"}, {"form": "補貼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "别人给个人的、用来补足不够用的开销的一点钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2e039c7-c01e-4c40-b644-454870abac61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91121, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "补贴", "is_correct": true, "explanation": "补贴：指别人给个人用来补足开销的钱，与“生活”搭配，句子通顺。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线不是可以给人的钱款，“生活电线”说不通。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：“生活”修饰“饼干”说不通，饼干不是生活中用来补足开销的钱。"}, {"text": "颜料", "is_correct": false, "explanation": "搭配：“生活”不能修饰“颜料”，“生活颜料”两者不搭配。"}], "explanations": {"补贴": "补贴：指别人给个人用来补足开销的钱，与“生活”搭配，句子通顺。", "电线": "语义：电线不是可以给人的钱款，“生活电线”说不通。", "饼干": "语义：“生活”修饰“饼干”说不通，饼干不是生活中用来补足开销的钱。", "颜料": "搭配：“生活”不能修饰“颜料”，“生活颜料”两者不搭配。"}, "sentence_index": 0, "correct_answer": "补贴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在超市买了一包补贴，在路上吃。", "explanation": "这里应该用〈零食〉。补贴是别人给的钱，不是能买来吃的东西，买来吃的要用零食。"}, {"text": "我向朋友借了一笔补贴。", "explanation": "这里应该用〈借款〉。补贴是给予的钱，不能借入或借出，借钱要用借款。"}, {"text": "房东收了我一笔补贴，作为房子的押金。", "explanation": "这里应该用〈押金〉。补贴是别人给的钱，房东收取并退还的钱要用押金。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91121, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "补贴", "is_correct": true, "explanation": "补贴：指别人给的钱，可以用来买东西，与“用……买”搭配，句子通顺。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶不是钱款，不能用来买电脑。"}, {"text": "积木", "is_correct": false, "explanation": "语义：积木是玩具，不能充当买电脑的钱。"}, {"text": "笑容", "is_correct": false, "explanation": "配价：“用……买”要求用钱或有价的东西作凭借，“笑容”不能充当买东西的凭借。"}], "explanations": {"补贴": "补贴：指别人给的钱，可以用来买东西，与“用……买”搭配，句子通顺。", "树叶": "语义：树叶不是钱款，不能用来买电脑。", "积木": "语义：积木是玩具，不能充当买电脑的钱。", "笑容": "配价：“用……买”要求用钱或有价的东西作凭借，“笑容”不能充当买东西的凭借。"}, "sentence_index": 6, "correct_answer": "补贴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每学期要交一笔补贴。", "explanation": "这里应该用〈学费〉。补贴是别人给的钱，不能说交出去，缴纳学费要用学费。"}, {"text": "他继承了一笔补贴，是爷爷留下的。", "explanation": "这里应该用〈遗产〉。补贴是给予的钱，不是留下的财产，继承的财产要用遗产。"}, {"text": "这些股票每年都会给他带来一笔补贴。", "explanation": "这里应该用〈股息〉。股票的收益要用股息，补贴不是股票的收益。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91121, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "表哥上个月给了我一条生活补贴。", "corrected_sentence": "表哥上个月给了我一笔生活补贴。", "error_description": "量词错误：“补贴”是钱款，应用量词“笔”，说“一笔生活补贴”，不能说“一条生活补贴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91121, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哥哥每个月都有一个补贴，够付房租了。", "corrected_sentence": "哥哥每个月都有一笔补贴，够付房租了。", "error_description": "量词错误：“补贴”是钱款，应用量词“笔”，说“一笔补贴”，不能说“一个补贴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
