INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91123, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "吃的是可以拿来吃的东西。", "primary_collocate": null, "pronunciation": "chī de", "ipa": "tʂʰɻ̩˥ tə", "syllable_count": 2, "sentences": [{"text": "冰箱里没有吃的了。", "target_word": "吃的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去山上玩，别忘了带吃的。", "target_word": "吃的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里有吃的，也有喝的。", "target_word": "吃的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我饿了，家里有什么吃的吗？", "target_word": "吃的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们看到吃的，眼睛都亮了。", "target_word": "吃的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈给我们准备了很多吃的。", "target_word": "吃的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我去超市买点吃的，你在家等我。", "target_word": "吃的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里没有商店，我们得自己带吃的。", "target_word": "吃的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚会上除了吃的，还有很多游戏。", "target_word": "吃的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每次出门，包里都放着吃的。", "target_word": "吃的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "口语里泛指可以拿来吃的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ef076da-1144-4cb2-9ae1-fa1a201e95f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91123, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃的", "is_correct": true, "explanation": "正确。“冰箱里没有吃的了”指冰箱里没有可以吃的东西。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：冰箱里放的是食物，“电脑”不能放进冰箱，这里句子说不通。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“冰箱里没有……了”后面接的是能放在冰箱里的东西，“椅子”不属于这一类。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不是冰箱里会有的东西，这里句子说不通。"}], "explanations": {"吃的": "正确。“冰箱里没有吃的了”指冰箱里没有可以吃的东西。", "电脑": "语义：冰箱里放的是食物，“电脑”不能放进冰箱，这里句子说不通。", "椅子": "搭配：“冰箱里没有……了”后面接的是能放在冰箱里的东西，“椅子”不属于这一类。", "书包": "语义：书包是装东西的袋子，不是冰箱里会有的东西，这里句子说不通。"}, "sentence_index": 0, "correct_answer": "吃的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种营养吃的对孩子的发育很有好处。", "explanation": "这里应该用〈食物〉。“营养食物”是固定说法，口语“吃的”不这样修饰“营养”。"}, {"text": "吃的安全关系到国家的稳定。", "explanation": "这里应该用〈粮食〉。谈国家层面的供应要说“粮食”，“吃的”只指日常可以吃的东西，不用于这类宏观说法。"}, {"text": "我在超市买了几本吃的。", "explanation": "这里应该用〈包〉或〈袋〉。“本”用于书、本子，不能用来数“吃的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91123, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃的", "is_correct": true, "explanation": "正确。“买点吃的”指买一些可以吃的东西。"}, {"text": "房子", "is_correct": false, "explanation": "语义：超市卖的是日用品和食品，不卖房子，这里说不通。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”不是超市里能买到的东西，“买点作业”没有意义。"}, {"text": "爱情", "is_correct": false, "explanation": "搭配：“买”后面不接“爱情”这样的抽象名词，句子不通。"}], "explanations": {"吃的": "正确。“买点吃的”指买一些可以吃的东西。", "房子": "语义：超市卖的是日用品和食品，不卖房子，这里说不通。", "作业": "语义：“作业”不是超市里能买到的东西，“买点作业”没有意义。", "爱情": "搭配：“买”后面不接“爱情”这样的抽象名词，句子不通。"}, "sentence_index": 6, "correct_answer": "吃的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的吃的习惯一直很健康，从不乱吃。", "explanation": "这里应该用〈饮食〉。“饮食习惯”是固定说法，“吃的”不能与“习惯”组合。"}, {"text": "他把吃的当成了钥匙，插进了锁孔里。", "explanation": "这里是把“吃的”当成了钥匙，“吃的”只指可以吃的食物，不能这样用。"}, {"text": "他把吃的当成书，一页一页地读。", "explanation": "这里是把“吃的”当成了可以阅读的东西，“吃的”只指可以吃的食物，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91123, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他带了一台吃的上山。", "corrected_sentence": "他带了一包吃的上山。", "error_description": "量词错误：“吃的”是食物，应该用量词“包”。“台”只用于机器、电器，不能用来数“吃的”。正确说法：他带了一包吃的上山。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91123, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了两辆吃的，准备去野餐。", "corrected_sentence": "他买了两包吃的，准备去野餐。", "error_description": "量词错误：“吃的”是食物，应该用量词“包”。“辆”只用于车辆，不能用来数“吃的”。正确说法：他买了两包吃的，准备去野餐。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
