INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91124, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以吃的东西；食物。", "primary_collocate": null, "pronunciation": "chī de", "ipa": "tʂʰɻ̩˥ tə", "syllable_count": 2, "sentences": [{"text": "桌子上放着很多吃的。", "target_word": "吃的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在找吃的。", "target_word": "吃的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们带的吃的不够，快去买点吧。", "target_word": "吃的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里饿了，他想找点吃的。", "target_word": "吃的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春节的时候，家里总有很多吃的。", "target_word": "吃的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行的时候，我最关心吃的和住的。", "target_word": "吃的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把吃的分给了每个孩子。", "target_word": "吃的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友来我家玩，我准备了不少吃的。", "target_word": "吃的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市二楼卖吃的，一楼卖衣服。", "target_word": "吃的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灾区的人们最需要吃的和水。", "target_word": "吃的", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "口语里指食物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ef076da-1144-4cb2-9ae1-fa1a201e95f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91124, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃的", "is_correct": true, "explanation": "正确。“桌子上放着很多吃的”指桌上摆着很多食物。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“桌子上”放的是可以拿在手里的东西，“河流”不能放在桌子上，句子说不通。"}, {"text": "雷声", "is_correct": false, "explanation": "语义：雷声是声音，不能“放”在桌子上，句子说不通。"}, {"text": "梦想", "is_correct": false, "explanation": "搭配：“放着很多”后面接的是具体的东西，“梦想”这样的抽象名词不能这样搭配。"}], "explanations": {"吃的": "正确。“桌子上放着很多吃的”指桌上摆着很多食物。", "河流": "语义：“桌子上”放的是可以拿在手里的东西，“河流”不能放在桌子上，句子说不通。", "雷声": "语义：雷声是声音，不能“放”在桌子上，句子说不通。", "梦想": "搭配：“放着很多”后面接的是具体的东西，“梦想”这样的抽象名词不能这样搭配。"}, "sentence_index": 0, "correct_answer": "吃的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜里饿了，他买了一座吃的。", "explanation": "这里应该用〈份〉或〈包〉。“座”用于山、桥、楼等大型建筑，不能用来数“吃的”。"}, {"text": "夜里饿了，他把吃的当成了书，一页一页地读。", "explanation": "这里“吃的”指食物，不能当作可以阅读的东西，这样用是错的。"}, {"text": "夜里饿了，他想找点吃的，就把吃的穿在身上。", "explanation": "搭配：“穿”只用于衣物，不能用于“吃的”，这里应该用〈带〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃的", "is_correct": true, "explanation": "正确。“分给每个孩子”的是可以吃的东西。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵不能拿来分给孩子，句子说不通。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋无法拿来分给每个孩子，句子说不通。"}, {"text": "早晨", "is_correct": false, "explanation": "搭配：“分”后面接的是具体的物品，不接“早晨”这样的时间词。"}], "explanations": {"吃的": "正确。“分给每个孩子”的是可以吃的东西。", "云朵": "语义：云朵不能拿来分给孩子，句子说不通。", "海洋": "语义：海洋无法拿来分给每个孩子，句子说不通。", "早晨": "搭配：“分”后面接的是具体的物品，不接“早晨”这样的时间词。"}, "sentence_index": 6, "correct_answer": "吃的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "灾区的人们最需要吃的和水，医生就给吃的打了一针。", "explanation": "这里是把“吃的”当成了可以打针的病人；“吃的”指食物，不能这样用。"}, {"text": "灾区的人们最需要吃的和水，救援队却先给吃的修了一条路。", "explanation": "这里是把“吃的”当成了可以修建的东西，“吃的”指食物，不能作修建的对象。"}, {"text": "灾区的人们最需要吃的和水，他们给吃的戴上了帽子。", "explanation": "这里是把“吃的”当成了可以戴在头上的东西；“吃的”指食物，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌子上摆着一只吃的。", "corrected_sentence": "桌子上摆着一些吃的。", "error_description": "量词错误：“吃的”是食物，不能用“只”来数，应该用“一些”或“一份”。正确说法：桌子上摆着一些吃的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冰箱里还有一辆吃的，够我们吃两天。", "corrected_sentence": "冰箱里还有一些吃的，够我们吃两天。", "error_description": "量词错误：“吃的”是食物，应该用“一些”；“辆”只用于车，不能用来数“吃的”。正确说法：冰箱里还有一些吃的，够我们吃两天。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
