INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91125, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "半夜是晚上很晚、大家都睡着的时候。", "primary_collocate": null, "pronunciation": "bàn yè", "ipa": "pan˥˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "半夜大家都睡着了，房子里很安静。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我半夜醒了，再也睡不着。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半夜孩子哭了，妈妈马上起床。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天半夜，外面下了一场大雨。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕吵醒家人，半夜不敢开灯。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半夜我口渴了，去厨房喝水。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半夜的街上一个人也没有。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟半夜说梦话，我听见了。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫半夜在窗外叫，我睡不好。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她半夜起床，轻轻关上了窗户。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "半夜三更", "label": "复合"}, {"form": "大半夜", "label": "复合"}], "register": "口语", "sense_fingerprint": "晚上很晚、大家都睡着的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e23a7c-9131-4a56-a854-f3c79c067e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91125, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "半夜", "is_correct": true, "explanation": "半夜指晚上很晚、大家都睡着的时候，即正确答案。"}, {"text": "汗液", "is_correct": false, "explanation": "hàn（第四声）与 bàn 声母不同，汗液指人体排出的汗水，意思不同。"}, {"text": "半月", "is_correct": false, "explanation": "yuè 与 yè 韵母不同，半月指半个月，或半圆形的月亮。"}, {"text": "版页", "is_correct": false, "explanation": "bǎn（第三声）与 bàn（第四声）声调不同，版页指书籍的版面和页码。"}, {"text": "烂叶", "is_correct": false, "explanation": "làn 与 bàn 声母不同，烂叶指腐烂的叶子。"}], "explanations": {"半夜": "半夜指晚上很晚、大家都睡着的时候，即正确答案。", "汗液": "hàn（第四声）与 bàn 声母不同，汗液指人体排出的汗水，意思不同。", "半月": "yuè 与 yè 韵母不同，半月指半个月，或半圆形的月亮。", "版页": "bǎn（第三声）与 bàn（第四声）声调不同，版页指书籍的版面和页码。", "烂叶": "làn 与 bàn 声母不同，烂叶指腐烂的叶子。"}, "sentence_index": null, "correct_answer": "半夜"}, "level_3": {"options": [{"text": "半夜", "is_correct": true, "explanation": "半夜指夜里很晚、大家都睡着的时候，与句意相符。"}, {"text": "傍晚", "is_correct": false, "explanation": "语义：傍晚天色刚暗、人一般还醒着，与“大家都睡着了”的时间不合。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间不会睡着，“大家都睡着了”的主语必须是人，句子不通。"}, {"text": "半年", "is_correct": false, "explanation": "语义：半年是一段时间，不是时间点，与“大家都睡着了”的时刻不合。"}], "explanations": {"半夜": "半夜指夜里很晚、大家都睡着的时候，与句意相符。", "傍晚": "语义：傍晚天色刚暗、人一般还醒着，与“大家都睡着了”的时间不合。", "房间": "语义：房间不会睡着，“大家都睡着了”的主语必须是人，句子不通。", "半年": "语义：半年是一段时间，不是时间点，与“大家都睡着了”的时刻不合。"}, "sentence_index": 0, "correct_answer": "半夜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他半夜八点就起床了。", "explanation": "这里应该用〈早上〉。“半夜”是晚上很晚、大家睡觉的时候，不能和早上八点起床放在一起。"}, {"text": "孩子们每天半夜去学校上课。", "explanation": "这里应该用〈早上〉。“半夜”是大家都在睡觉的时候，不是去学校上课的时间。"}, {"text": "半夜七点我们一起吃饭。", "explanation": "这里应该用〈晚上〉。“半夜”指十二点前后，不能用来指七点的晚饭时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91125, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "半夜", "is_correct": true, "explanation": "半夜指夜里很晚的时候，与“街上一个人也没有”的时间相符。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室在学校里，不在街上，“教室的街上”说不通。"}, {"text": "一年", "is_correct": false, "explanation": "语义：一年是一段时间，不能用来指街上某一时刻的情况。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌是桌子，不是时间词，“课桌的街上”说不通。"}], "explanations": {"半夜": "半夜指夜里很晚的时候，与“街上一个人也没有”的时间相符。", "教室": "语义：教室在学校里，不在街上，“教室的街上”说不通。", "一年": "语义：一年是一段时间，不能用来指街上某一时刻的情况。", "课桌": "语义：课桌是桌子，不是时间词，“课桌的街上”说不通。"}, "sentence_index": 6, "correct_answer": "半夜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议半夜九点开始。", "explanation": "这里应该用〈上午〉。“半夜”指十二点前后，与九点的开会时间矛盾。"}, {"text": "他半夜六点下班。", "explanation": "这里应该用〈下午〉。“半夜”指深夜，不能用来指下午六点的下班时间。"}, {"text": "半夜七点，妈妈开始做饭。", "explanation": "这里应该用〈傍晚〉。“半夜”指深夜，与傍晚七点的做饭时间不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91125, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸半夜的起床去看孩子。", "corrected_sentence": "爸爸半夜起床去看孩子。", "error_description": "错误：时间词“半夜”作状语时后面不能加“的”。正确：应说“半夜起床”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91125, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈半夜的醒来，去看了看宝宝。", "corrected_sentence": "妈妈半夜醒来，去看了看宝宝。", "error_description": "错误：时间词“半夜”作状语时后面不能加“的”。正确：应说“半夜醒来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
