INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91126, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "夜间十二点前后，深夜。", "primary_collocate": null, "pronunciation": "bàn yè", "ipa": "pan˥˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "现在是半夜十二点，该睡觉了。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们半夜十二点才到家。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影半夜十二点才演完。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天工作到半夜十二点。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半夜十二点，钟声响了。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车半夜十二点左右到站。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚球赛打到半夜才结束。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年的钟声在半夜响起。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他半夜一点还在写作业。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机半夜才到，我们等了很久。", "target_word": "半夜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "半夜三更", "label": "复合"}, {"form": "大半夜", "label": "复合"}], "register": "口语", "sense_fingerprint": "夜里十二点前后的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e23a7c-9131-4a56-a854-f3c79c067e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91126, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "半夜", "is_correct": true, "explanation": "半夜指夜里十二点前后的时候，即正确答案。"}, {"text": "汗液", "is_correct": false, "explanation": "hàn（第四声）与 bàn 声母不同，汗液指人体排出的汗水，意思不同。"}, {"text": "半月", "is_correct": false, "explanation": "yuè 与 yè 韵母不同，半月指半个月，或半圆形的月亮。"}, {"text": "版页", "is_correct": false, "explanation": "bǎn（第三声）与 bàn（第四声）声调不同，版页指书籍的版面和页码。"}, {"text": "烂叶", "is_correct": false, "explanation": "làn 与 bàn 声母不同，烂叶指腐烂的叶子。"}], "explanations": {"半夜": "半夜指夜里十二点前后的时候，即正确答案。", "汗液": "hàn（第四声）与 bàn 声母不同，汗液指人体排出的汗水，意思不同。", "半月": "yuè 与 yè 韵母不同，半月指半个月，或半圆形的月亮。", "版页": "bǎn（第三声）与 bàn（第四声）声调不同，版页指书籍的版面和页码。", "烂叶": "làn 与 bàn 声母不同，烂叶指腐烂的叶子。"}, "sentence_index": null, "correct_answer": "半夜"}, "level_3": {"options": [{"text": "半夜", "is_correct": true, "explanation": "半夜指夜里十二点前后，与句中的“十二点”相符。"}, {"text": "清晨", "is_correct": false, "explanation": "搭配：清晨指天刚亮的时候，与“十二点”的时刻不搭。"}, {"text": "黄昏", "is_correct": false, "explanation": "语义：黄昏指傍晚天色将暗的时候，与“十二点”不符。"}, {"text": "半年", "is_correct": false, "explanation": "语义：半年是一段时间，不是十二点这样的时刻。"}], "explanations": {"半夜": "半夜指夜里十二点前后，与句中的“十二点”相符。", "清晨": "搭配：清晨指天刚亮的时候，与“十二点”的时刻不搭。", "黄昏": "语义：黄昏指傍晚天色将暗的时候，与“十二点”不符。", "半年": "语义：半年是一段时间，不是十二点这样的时刻。"}, "sentence_index": 0, "correct_answer": "半夜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他半夜七点就去上班了。", "explanation": "这里应该用〈早上〉。“半夜”指十二点前后，不能指七点的上班时间。"}, {"text": "我们每天半夜十二点吃午饭。", "explanation": "这里应该用〈中午〉。午饭在中午十二点吃，“半夜”指夜里十二点前后。"}, {"text": "晚饭一般在半夜六点吃。", "explanation": "这里应该用〈傍晚〉。晚饭一般在傍晚吃，“半夜”指十二点前后，与晚饭时间不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt