INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91126, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "半夜", "is_correct": true, "explanation": "半夜指夜里十二点前后，与“昨晚”的时间相符。"}, {"text": "上周", "is_correct": false, "explanation": "语义：上周指过去的一周，与“昨晚”的时间不合，句子不通。"}, {"text": "上个月", "is_correct": false, "explanation": "语义：上个月指上一个月，与“昨晚”的时间相差太远，句子不通。"}, {"text": "傍晚", "is_correct": false, "explanation": "搭配：“昨晚”与“傍晚”时间矛盾，不能说昨晚打到傍晚才结束。"}], "explanations": {"半夜": "半夜指夜里十二点前后，与“昨晚”的时间相符。", "上周": "语义：上周指过去的一周，与“昨晚”的时间不合，句子不通。", "上个月": "语义：上个月指上一个月，与“昨晚”的时间相差太远，句子不通。", "傍晚": "搭配：“昨晚”与“傍晚”时间矛盾，不能说昨晚打到傍晚才结束。"}, "sentence_index": 6, "correct_answer": "半夜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "图书馆半夜九点开门。", "explanation": "这里应该用〈上午〉。“半夜”指十二点前后，与九点开门的时间矛盾。"}, {"text": "商店每天半夜六点关门。", "explanation": "这里应该用〈下午〉。“半夜”指深夜，不能用来指下午六点关门的时间。"}, {"text": "学生每天半夜八点放学。", "explanation": "这里应该用〈晚上〉。“半夜”指十二点前后，与八点放学的时间不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
