INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91128, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "里面和外面；内部与外部。", "primary_collocate": null, "pronunciation": "lǐ wài", "ipa": "li˨˩˦ waɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这件事公司里外都知道了。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里外的人都很关心这次比赛。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对公司里外的人都一视同仁。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "里外的人都想帮这个忙。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人管着家里外头的事，里外都忙。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里外的工人一起开会。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人忙着里外的事情。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次改革得到了公司里外的支持。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家里外配合，工作就顺利了。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事在单位里外都传开了。", "target_word": "里外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "里里外外", "label": "重叠"}], "register": "中性", "sense_fingerprint": "机构或事情的内部与外部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72962ab9-2347-4d76-bde0-711257f30022') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "里外", "is_correct": true, "explanation": "「里外」指公司的内部与外部，「都知道了」说的是公司全体人员，与语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「知道」的对象是事情或消息，不能说「天气都知道了」。"}, {"text": "地图", "is_correct": false, "explanation": "语义：「地图」是一种图，不是事情，不能作为「这件事」的内容。"}, {"text": "身高", "is_correct": false, "explanation": "语义：「身高」指人的高矮，不是事件，与「这件事」冲突。"}], "explanations": {"里外": "「里外」指公司的内部与外部，「都知道了」说的是公司全体人员，与语境相符。", "天气": "搭配：「知道」的对象是事情或消息，不能说「天气都知道了」。", "地图": "语义：「地图」是一种图，不是事情，不能作为「这件事」的内容。", "身高": "语义：「身高」指人的高矮，不是事件，与「这件事」冲突。"}, "sentence_index": 0, "correct_answer": "里外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位叔叔是我的里外，很关心我。", "explanation": "这里应该用〈家人〉。里外指内外的全体，不指某一个人，表示亲人要说家人。"}, {"text": "这个人是里外，不能随便进入研究室。", "explanation": "这里应该用〈外人〉。里外指内外的全体，不能单独指一个人，要说外人。"}, {"text": "他的里外很高。", "explanation": "这里应该用〈体温〉。里外指内部与外部，不能用来说体温的高低，不说里外。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "里外", "is_correct": true, "explanation": "「忙着里外的事情」指内部与外部的事务，与语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「忙着」后面的「事情」要能去做，「颜色」不能被忙着去做。"}, {"text": "味道", "is_correct": false, "explanation": "语义：「味道」指气味或滋味，不是可以忙的事情。"}, {"text": "河流", "is_correct": false, "explanation": "语义：「河流」是地理事物，不能作为「忙着」的事务。"}], "explanations": {"里外": "「忙着里外的事情」指内部与外部的事务，与语境相符。", "颜色": "搭配：「忙着」后面的「事情」要能去做，「颜色」不能被忙着去做。", "味道": "语义：「味道」指气味或滋味，不是可以忙的事情。", "河流": "语义：「河流」是地理事物，不能作为「忙着」的事务。"}, "sentence_index": 6, "correct_answer": "里外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的里外很高。", "explanation": "这里应该用〈收入〉。里外指内部与外部，不能用来说收入的高低，不说里外。"}, {"text": "这家公司有两扇里外。", "explanation": "这里应该用〈门〉。里外不是可以用量词「扇」计数的东西，要数门的数量时才用「扇」。"}, {"text": "这件事只是里外现象。", "explanation": "这里应该用〈表面〉。里外指内部与外部，不能表示表面现象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校里外了都在议论这件事。", "corrected_sentence": "学校里外都在议论这件事。", "error_description": "错误：「里外了」，正确：「里外」。「里外」是方位名词，后面不能直接加「了」，应去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个部门里外里外都在忙这件事。", "corrected_sentence": "这个部门里里外外都在忙这件事。", "error_description": "错误：「里外里外」，正确：「里里外外」。表示全体各处的重叠形式是「里里外外」，「里外」不能整体重复。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
