INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91129, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "吹是嘴巴嘟起来，把气送出去。", "primary_collocate": null, "pronunciation": "chuī", "ipa": "tʂʰweɪ˥", "syllable_count": 1, "sentences": [{"text": "他深吸一口气，把蜡烛吹灭了。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤太烫了，你先吹一吹再喝。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用嘴给我吹凉了热粥。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明正在吹气球，脸都红了。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生日那天，我一口气吹灭了蛋糕上的蜡烛。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷得发抖，他对着手吹了吹。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用力吹，肥皂泡飞了起来。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让我对着机器用力吹。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她轻轻吹了吹纸上的灰。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟吹不灭蛋糕上的蜡烛，急得直哭。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吹了", "label": "体标"}, {"form": "吹着", "label": "体标"}, {"form": "吹过", "label": "体标"}, {"form": "吹吹", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用嘴把气送出去，如吹蜡烛、吹气球、吹凉热的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b7baea-ca68-407f-84e5-c669a1b09102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91129, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吹", "is_correct": true, "explanation": "正确答案。吹（chuī）指用嘴把气送出去。"}, {"text": "垂", "is_correct": false, "explanation": "垂（chuí）与 吹（chuī）声调不同，意思是向下垂。"}, {"text": "催", "is_correct": false, "explanation": "催（cuī）与 吹（chuī）声母不同（c 与 ch），意思是催促。"}, {"text": "追", "is_correct": false, "explanation": "追（zhuī）与 吹（chuī）声母不同（zh 与 ch），意思是追赶。"}, {"text": "锤", "is_correct": false, "explanation": "锤（chuí）与 吹（chuī）声调不同，意思是锤子。"}], "explanations": {"吹": "正确答案。吹（chuī）指用嘴把气送出去。", "垂": "垂（chuí）与 吹（chuī）声调不同，意思是向下垂。", "催": "催（cuī）与 吹（chuī）声母不同（c 与 ch），意思是催促。", "追": "追（zhuī）与 吹（chuī）声母不同（zh 与 ch），意思是追赶。", "锤": "锤（chuí）与 吹（chuī）声调不同，意思是锤子。"}, "sentence_index": null, "correct_answer": "吹"}, "level_3": {"options": [{"text": "吹", "is_correct": true, "explanation": "正确。「把蜡烛…灭了」需要用气把蜡烛弄灭，「吹」符合句意。"}, {"text": "点", "is_correct": false, "explanation": "语义：「点」是点燃，蜡烛要先点燃，不能说「点灭了」。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」是用嘴进食，不能让蜡烛熄灭，句子说不通。"}, {"text": "放", "is_correct": false, "explanation": "搭配：「放」与「灭了」搭配不通，不能说「放灭了蜡烛」。"}], "explanations": {"吹": "正确。「把蜡烛…灭了」需要用气把蜡烛弄灭，「吹」符合句意。", "点": "语义：「点」是点燃，蜡烛要先点燃，不能说「点灭了」。", "吃": "语义：「吃」是用嘴进食，不能让蜡烛熄灭，句子说不通。", "放": "搭配：「放」与「灭了」搭配不通，不能说「放灭了蜡烛」。"}, "sentence_index": 0, "correct_answer": "吹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总爱吹牛，把自己的成绩说得很夸张。", "explanation": "这里是〈吹牛〉的意思，指夸大其词，不是用嘴把气送出去。"}, {"text": "那次合作吹了，大家都很失望。", "explanation": "这里是〈吹了〉的意思，指事情没有办成、作罢，与用嘴出气无关。"}, {"text": "大家都在吹他，他听了很得意。", "explanation": "这里是〈吹捧〉的意思，指夸奖奉承，与用嘴把气送出去无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91129, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吹", "is_correct": true, "explanation": "正确。肥皂泡要靠吹气才能飞起来，「吹」符合句意。"}, {"text": "按", "is_correct": false, "explanation": "语义：「按」是用手或物体压下，不能让肥皂泡飞起来，句意不通。"}, {"text": "搓", "is_correct": false, "explanation": "语义：「搓」是来回摩擦，用于手、衣服等，不能使肥皂泡飞起。"}, {"text": "喝", "is_correct": false, "explanation": "配价：「喝」要带液体作宾语，「用力喝」后没有合适的对象，句子说不通。"}], "explanations": {"吹": "正确。肥皂泡要靠吹气才能飞起来，「吹」符合句意。", "按": "语义：「按」是用手或物体压下，不能让肥皂泡飞起来，句意不通。", "搓": "语义：「搓」是来回摩擦，用于手、衣服等，不能使肥皂泡飞起。", "喝": "配价：「喝」要带液体作宾语，「用力喝」后没有合适的对象，句子说不通。"}, "sentence_index": 6, "correct_answer": "吹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在花园里用水枪吹水玩。", "explanation": "这里应该用〈喷〉。用水枪射出水要说“喷”，“吹”指用嘴或风送出气，不用于液体。"}, {"text": "她每天吹头发，花了很长时间。", "explanation": "这里是〈吹干〉的意思，指用吹风机的热风把头发弄干，不是用嘴把气送出去。"}, {"text": "他说话总爱吹毛求疵，挑别人的小毛病。", "explanation": "这里是〈挑剔〉的意思，指找细小的毛病，与用嘴出气无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91129, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹对着杯子吹吹了，想让茶凉一点。", "corrected_sentence": "妹妹对着杯子吹了吹，想让茶凉一点。", "error_description": "错误：「吹吹了」。正确：「吹了吹」。动词重叠「吹吹」中间要加「了」，说「吹了吹」，不说「吹吹了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91129, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹把蜡烛吹了灭，屋里黑了。", "corrected_sentence": "妹妹把蜡烛吹灭了，屋里黑了。", "error_description": "错误：「吹了灭」。正确：「吹灭了」。结果补语「灭」要紧跟动词「吹」，「了」放在补语后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
