INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91130, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "风、气流流动，使物体移动或飘动。", "primary_collocate": null, "pronunciation": "chuī", "ipa": "tʂʰweɪ˥", "syllable_count": 1, "sentences": [{"text": "今天风很大，把我的帽子吹走了。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的风吹在脸上很舒服。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户开着，凉风从外面吹进来。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的北风吹得人直发抖。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外起风了，把桌上的纸吹到了地上。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调一直对着我吹，有点冷。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春风吹过，树上的花开了。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏夜的风吹过院子，树叶沙沙作响。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，一阵凉风吹来。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，门就关上了。", "target_word": "吹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吹了", "label": "体标"}, {"form": "吹着", "label": "体标"}, {"form": "吹过", "label": "体标"}, {"form": "吹吹", "label": "重叠"}], "register": "中性", "sense_fingerprint": "风或气流流动使物体移动，如风吹、吹走、吹来、吹进来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b7baea-ca68-407f-84e5-c669a1b09102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91130, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吹", "is_correct": true, "explanation": "正确答案。吹（chuī）指风或气流流动，使物体移动。"}, {"text": "垂", "is_correct": false, "explanation": "垂（chuí）与 吹（chuī）声调不同，意思是向下垂。"}, {"text": "催", "is_correct": false, "explanation": "催（cuī）与 吹（chuī）声母不同（c 与 ch），意思是催促。"}, {"text": "追", "is_correct": false, "explanation": "追（zhuī）与 吹（chuī）声母不同（zh 与 ch），意思是追赶。"}, {"text": "锤", "is_correct": false, "explanation": "锤（chuí）与 吹（chuī）声调不同，意思是锤子。"}], "explanations": {"吹": "正确答案。吹（chuī）指风或气流流动，使物体移动。", "垂": "垂（chuí）与 吹（chuī）声调不同，意思是向下垂。", "催": "催（cuī）与 吹（chuī）声母不同（c 与 ch），意思是催促。", "追": "追（zhuī）与 吹（chuī）声母不同（zh 与 ch），意思是追赶。", "锤": "锤（chuí）与 吹（chuī）声调不同，意思是锤子。"}, "sentence_index": null, "correct_answer": "吹"}, "level_3": {"options": [{"text": "吹", "is_correct": true, "explanation": "正确。风把帽子吹走，「吹」指风使物体移动，符合句意。"}, {"text": "搬", "is_correct": false, "explanation": "语义：「搬」是人用手或借助工具移动物体，句中是风，句意不通。"}, {"text": "咬", "is_correct": false, "explanation": "语义：「咬」要用牙齿，风不能咬帽子，句意不通。"}, {"text": "捡", "is_correct": false, "explanation": "配价：「捡」的施事要是人，句中的风不能「捡」帽子。"}], "explanations": {"吹": "正确。风把帽子吹走，「吹」指风使物体移动，符合句意。", "搬": "语义：「搬」是人用手或借助工具移动物体，句中是风，句意不通。", "咬": "语义：「咬」要用牙齿，风不能咬帽子，句意不通。", "捡": "配价：「捡」的施事要是人，句中的风不能「捡」帽子。"}, "sentence_index": 0, "correct_answer": "吹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很会吹牛，大家都不太相信他。", "explanation": "这里是〈吹牛〉的意思，指夸大其词，与风或气流流动无关。"}, {"text": "那场比赛吹了，大家都很遗憾。", "explanation": "这里是〈吹了〉的意思，指事情作罢，不表示风或气流流动。"}, {"text": "同事们总吹他，他听了很得意。", "explanation": "这里是〈吹捧〉的意思，指夸奖奉承，不表示风或气流流动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吹", "is_correct": true, "explanation": "正确。「春风吹过」指风从面前拂过，「吹」符合句意。"}, {"text": "喝", "is_correct": false, "explanation": "配价：「喝」要带液体作宾语，「春风喝过」不成立。"}, {"text": "切", "is_correct": false, "explanation": "语义：「切」是用刀分开，春风不能切东西，句意不通。"}, {"text": "叠", "is_correct": false, "explanation": "搭配：「叠」用于衣物、被子等，不能与「春风」搭配，「春风叠过」说不通。"}], "explanations": {"吹": "正确。「春风吹过」指风从面前拂过，「吹」符合句意。", "喝": "配价：「喝」要带液体作宾语，「春风喝过」不成立。", "切": "语义：「切」是用刀分开，春风不能切东西，句意不通。", "叠": "搭配：「叠」用于衣物、被子等，不能与「春风」搭配，「春风叠过」说不通。"}, "sentence_index": 6, "correct_answer": "吹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把一盆脏水吹到了街上。", "explanation": "这里应该用〈泼〉。把液体猛地倒出要说“泼”，“吹”指风或气流使物体移动，不用于液体。"}, {"text": "园丁用水管吹水浇花。", "explanation": "这里应该用〈喷〉。用水管射出水要说“喷”，“吹”不用于液体。"}, {"text": "这位老师总是吹毛求疵，挑学生的小错。", "explanation": "这里是〈挑剔〉的意思，指找细小的毛病，与风或气流无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一阵风把窗帘动吹了，屋里很凉快。", "corrected_sentence": "一阵风把窗帘吹动了，屋里很凉快。", "error_description": "错误：「动吹了」。正确：「吹动了」。结果补语「动」要紧跟动词「吹」，写作「吹动了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风把门开吹了，我们都觉得凉快。", "corrected_sentence": "风把门吹开了，我们都觉得凉快。", "error_description": "错误：「开吹了」。正确：「吹开了」。结果补语「开」要紧跟动词「吹」，写作「吹开了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
