INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91132, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从受到刺激到做出反应所需要的时间。", "primary_collocate": null, "pronunciation": "fǎn yìng shí jiān", "ipa": "fan˨˩ iŋ˥˩ ʂɻ̩˧˥ tɕjɛn˥", "syllable_count": 4, "sentences": [{"text": "医生用小锤测试病人的反应时间。", "target_word": "反应时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声音越大，人的反应时间越短。", "target_word": "反应时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师记录了大家的反应时间。", "target_word": "反应时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器可以算出你的反应时间。", "target_word": "反应时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手碰到火后，反应时间非常短。", "target_word": "反应时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疲劳会使人的反应时间变长。", "target_word": "反应时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次实验的平均反应时间是半秒。", "target_word": "反应时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过练习，他的反应时间变短了。", "target_word": "反应时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年纪大了，对灯光的反应时间会变长。", "target_word": "反应时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们比较了两组人的反应时间。", "target_word": "反应时间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反應時間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "受到刺激到产生反应所用的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3f596a-ea6f-4092-8aea-7d56453cebea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91132, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反应时间", "is_correct": true, "explanation": "“反应时间”指受刺激到做出反应的时长，小锤测试的正是这一项，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，与用小锤测试无关。"}, {"text": "作文", "is_correct": false, "explanation": "语义：“作文”是写的文章，不能用小锤来测试。"}, {"text": "房价", "is_correct": false, "explanation": "搭配：“房价”不属于病人，不能说“病人的房价”。"}], "explanations": {"反应时间": "“反应时间”指受刺激到做出反应的时长，小锤测试的正是这一项，符合句意。", "味道": "语义：“味道”指气味或滋味，与用小锤测试无关。", "作文": "语义：“作文”是写的文章，不能用小锤来测试。", "房价": "搭配：“房价”不属于病人，不能说“病人的房价”。"}, "sentence_index": 0, "correct_answer": "反应时间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "加热后，这个化学反应的反应时间变短了。", "explanation": "这里用的是〈化学反应〉的意思，指物质发生变化所需的时间，不是人受刺激后做出反应的时间。"}, {"text": "这场比赛的反应时间是九十分钟。", "explanation": "这里应该用〈时长〉。反应时间只指受刺激后做出反应所用的时间，不能用来说比赛的长度。"}, {"text": "这支队伍的反应时间很强。", "explanation": "这里应该用〈反应能力〉。能力可以说“强”，反应时间是时长，不说“强”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91132, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反应时间", "is_correct": true, "explanation": "“反应时间”指受刺激到做出反应的平均时长，这里以“半秒”计，符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”以年计，不以秒计，“平均年龄是半秒”说不通。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热程度，不用秒来计量，句子说不通。"}, {"text": "面貌", "is_correct": false, "explanation": "语义：“面貌”指人的外貌，与实验的平均数据无关，不能说“是半秒”。"}], "explanations": {"反应时间": "“反应时间”指受刺激到做出反应的平均时长，这里以“半秒”计，符合句意。", "年龄": "语义：“年龄”以年计，不以秒计，“平均年龄是半秒”说不通。", "温度": "语义：“温度”指冷热程度，不用秒来计量，句子说不通。", "面貌": "语义：“面貌”指人的外貌，与实验的平均数据无关，不能说“是半秒”。"}, "sentence_index": 6, "correct_answer": "反应时间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的反应时间很强。", "explanation": "这里应该用〈反应能力〉。能力可以说“强”，反应时间是时长，不说“强”。"}, {"text": "这堂课的反应时间是四十分钟。", "explanation": "这里应该用〈时长〉。反应时间指受刺激后做出反应的时间，不能用来说一堂课的长度。"}, {"text": "这个化学实验的反应时间只有几秒。", "explanation": "这里用的是〈化学反应〉的意思，指物质发生变化所需的时间，不是人受刺激后做出反应的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "吃了药以后，我的反应时间变长着。", "corrected_sentence": "吃了药以后，我的反应时间变长了。", "error_description": "“变长”表示已经发生的变化，要用“了”。这里用了“着”，表示持续的状态，不符合句意。正确说法是“变长了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "运动员的反应时间短变了。", "corrected_sentence": "运动员的反应时间变短了。", "error_description": "“变短”是动补结构，“变”和“短”的顺序不能颠倒。正确说法是“运动员的反应时间变短了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
