INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91133, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "医生看病，找出人为什么不舒服。", "primary_collocate": null, "pronunciation": "zhěn duàn", "ipa": "ʈʂən˨˩ tuan˥˩", "syllable_count": 2, "sentences": [{"text": "医生正在诊断，想知道他哪里不舒服。", "target_word": "诊断", "complexity_tier": "T3", "furigana": "yī shēng zhèng zài zhěn duàn, xiǎng zhī dào tā nǎ lǐ bù shū fu.", "sentence_source": "generated"}, {"text": "我头疼，请医生诊断一下。", "target_word": "诊断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生诊断后说我只是感冒。", "target_word": "诊断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不去医院，没人能诊断他的病。", "target_word": "诊断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生诊断了半天，才找到原因。", "target_word": "诊断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老医生诊断我是太累了。", "target_word": "诊断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给她诊断了一下。", "target_word": "诊断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生诊断病情很认真。", "target_word": "诊断", "complexity_tier": "T3", "furigana": "zhè wèi yī shēng zhěn duàn bìng qíng hěn rèn zhēn.", "sentence_source": "generated"}, {"text": "他肚子疼，医生诊断是吃坏了。", "target_word": "诊断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子发烧了，医生马上诊断。", "target_word": "诊断", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诊断了", "label": "体标"}, {"form": "诊断过", "label": "体标"}, {"form": "诊断书", "label": "复合"}], "register": "口语", "sense_fingerprint": "医生看病，找出人不舒服的原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fdab5a9-2bdd-478f-be4b-21194dec5a85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91133, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "诊断", "is_correct": true, "explanation": "诊断（zhěn duàn）：医生看病、找出病因，即本题目标词。"}, {"text": "整段", "is_correct": false, "explanation": "zhěng（第三声）与 zhěn（第三声）韵母不同，整段意思是成段的部分。"}, {"text": "斩断", "is_correct": false, "explanation": "zhǎn（第三声）与 zhěn（第三声）韵母不同，斩断意思是砍断、切断。"}, {"text": "震断", "is_correct": false, "explanation": "zhèn（第四声）与 zhěn（第三声）声调不同，震断意思是震动后断开。"}], "explanations": {"诊断": "诊断（zhěn duàn）：医生看病、找出病因，即本题目标词。", "整段": "zhěng（第三声）与 zhěn（第三声）韵母不同，整段意思是成段的部分。", "斩断": "zhǎn（第三声）与 zhěn（第三声）韵母不同，斩断意思是砍断、切断。", "震断": "zhèn（第四声）与 zhěn（第三声）声调不同，震断意思是震动后断开。"}, "sentence_index": null, "correct_answer": "诊断"}, "level_3": {"options": [{"text": "诊断", "is_correct": true, "explanation": "诊断：正确。医生看病，找出病人不舒服的原因，与语境相符。"}, {"text": "挂号", "is_correct": false, "explanation": "语义：挂号是病人就诊前的手续，医生不挂号，与“想知道他哪里不舒服”矛盾。"}, {"text": "报销", "is_correct": false, "explanation": "语义：报销是处理费用，与找出不舒服的原因无关。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：“发烧”的主语是病人，不说“医生正在发烧”。"}], "explanations": {"诊断": "诊断：正确。医生看病，找出病人不舒服的原因，与语境相符。", "挂号": "语义：挂号是病人就诊前的手续，医生不挂号，与“想知道他哪里不舒服”矛盾。", "报销": "语义：报销是处理费用，与找出不舒服的原因无关。", "发烧": "搭配：“发烧”的主语是病人，不说“医生正在发烧”。"}, "sentence_index": 0, "correct_answer": "诊断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家诊断了这幅画，觉得很好看。", "explanation": "这里应该用〈欣赏〉。诊断是判断病因，欣赏一幅画要用欣赏。"}, {"text": "老师诊断了他的午饭。", "explanation": "这里应该用〈吃〉。“诊断”用于判断病情或问题，吃饭要用“吃”。"}, {"text": "他诊断了这个邀请。", "explanation": "这里应该用〈拒绝〉。诊断是判断病因，不能用于邀请，回绝邀请要用拒绝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91133, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诊断", "is_correct": true, "explanation": "诊断：正确。医生给病人看病、找出病因，符合“给她……了一下”的语境。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：“讨论”的对象是事情或问题，不能说“给她讨论了一下”。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与医生为病人做事的语境不合，医生不会拒绝病人。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：医生为病人做的是看病，不是“打扮”，与诊断无关。"}], "explanations": {"诊断": "诊断：正确。医生给病人看病、找出病因，符合“给她……了一下”的语境。", "讨论": "配价：“讨论”的对象是事情或问题，不能说“给她讨论了一下”。", "拒绝": "语义：“拒绝”与医生为病人做事的语境不合，医生不会拒绝病人。", "打扮": "语义：医生为病人做的是看病，不是“打扮”，与诊断无关。"}, "sentence_index": 6, "correct_answer": "诊断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气预报诊断明天会下雨。", "explanation": "这里应该用〈预测〉。诊断针对已经存在的病因，对未来的天气要用预测。"}, {"text": "学校诊断了那个新生。", "explanation": "这里应该用〈录取〉。诊断是判断病情，学校接收学生要用录取。"}, {"text": "妈妈诊断了一件衣服。", "explanation": "这里应该用〈购买〉。诊断指判断病因，买衣服要用购买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91133, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生很快诊断来了他的病因。", "corrected_sentence": "医生很快诊断出了他的病因。", "error_description": "错误：“诊断来了”，正确：“诊断出了”。“诊断”后要用结果补语“出”，表示找出了病因。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91133, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子的病被诊断为了肺炎。", "corrected_sentence": "孩子的病被诊断为肺炎。", "error_description": "错误在“诊断为”之后多出了“了”：“被诊断为”是固定框式，后面直接接病名，不能加“了”；改为“被诊断为肺炎”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
