INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91134, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "医生通过检查，判断病人所患的疾病。", "primary_collocate": null, "pronunciation": "zhěn duàn", "ipa": "ʈʂən˨˩ tuan˥˩", "syllable_count": 2, "sentences": [{"text": "医生诊断他得了胃炎。", "target_word": "诊断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生要先检查，再诊断。", "target_word": "诊断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病很难诊断。", "target_word": "诊断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院诊断出她有糖尿病。", "target_word": "诊断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生诊断了很久，还不能确定。", "target_word": "诊断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病是上个月诊断的。", "target_word": "诊断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生通过验血诊断病情。", "target_word": "诊断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老医生诊断过很多病人。", "target_word": "诊断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生诊断得很准。", "target_word": "诊断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生看过检查结果才能诊断。", "target_word": "诊断", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诊断了", "label": "体标"}, {"form": "诊断过", "label": "体标"}, {"form": "诊断书", "label": "复合"}], "register": "书面", "sense_fingerprint": "医生通过检查判断病人所患的疾病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fdab5a9-2bdd-478f-be4b-21194dec5a85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91134, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "诊断", "is_correct": true, "explanation": "诊断（zhěn duàn）：医生通过检查判断病因，即本题目标词。"}, {"text": "整段", "is_correct": false, "explanation": "zhěng（第三声）与 zhěn（第三声）韵母不同，整段（zhěng duàn）意思是成段的部分。"}, {"text": "斩断", "is_correct": false, "explanation": "zhǎn（第三声）与 zhěn（第三声）韵母不同，斩断意思是砍断、切断。"}, {"text": "震断", "is_correct": false, "explanation": "zhèn（第四声）与 zhěn（第三声）声调不同，震断意思是震动后断开。"}], "explanations": {"诊断": "诊断（zhěn duàn）：医生通过检查判断病因，即本题目标词。", "整段": "zhěng（第三声）与 zhěn（第三声）韵母不同，整段（zhěng duàn）意思是成段的部分。", "斩断": "zhǎn（第三声）与 zhěn（第三声）韵母不同，斩断意思是砍断、切断。", "震断": "zhèn（第四声）与 zhěn（第三声）声调不同，震断意思是震动后断开。"}, "sentence_index": null, "correct_answer": "诊断"}, "level_3": {"options": [{"text": "诊断", "is_correct": true, "explanation": "诊断：正确。医生通过检查判断疾病，与“得了胃炎”的语境相符。"}, {"text": "治愈", "is_correct": false, "explanation": "语义：“治愈”表示病已经治好，与“得了胃炎”（现在患病）矛盾。"}, {"text": "治疗", "is_correct": false, "explanation": "配价：“治疗”的宾语是病，不能直接带“他得了胃炎”这样的小句。"}, {"text": "救", "is_correct": false, "explanation": "语义：“救”指挽救生命，与“得了胃炎”这种患病描述不合。"}], "explanations": {"诊断": "诊断：正确。医生通过检查判断疾病，与“得了胃炎”的语境相符。", "治愈": "语义：“治愈”表示病已经治好，与“得了胃炎”（现在患病）矛盾。", "治疗": "配价：“治疗”的宾语是病，不能直接带“他得了胃炎”这样的小句。", "救": "语义：“救”指挽救生命，与“得了胃炎”这种患病描述不合。"}, "sentence_index": 0, "correct_answer": "诊断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生诊断了他的血压。", "explanation": "这里应该用〈测量〉。诊断指判断疾病，血压的数值要用测量。"}, {"text": "他诊断了一杯咖啡，觉得很香。", "explanation": "这里应该用〈喝〉。诊断指判断疾病，咖啡要用喝。"}, {"text": "他诊断了一张照片。", "explanation": "这里应该用〈拍〉。诊断用于判断病情，照片是拍出来的，不能诊断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91134, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诊断", "is_correct": true, "explanation": "诊断：正确。通过验血判断病因，与“病情”搭配。"}, {"text": "加重", "is_correct": false, "explanation": "语义：验血是检查手段，不会使病情加重，与“通过验血”的语境矛盾。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：验血的目的是了解病情，不能说通过验血来隐瞒病情。"}, {"text": "治疗", "is_correct": false, "explanation": "语义：验血只是检查手段，不能治疗病情，与“通过验血”的语境矛盾。"}], "explanations": {"诊断": "诊断：正确。通过验血判断病因，与“病情”搭配。", "加重": "语义：验血是检查手段，不会使病情加重，与“通过验血”的语境矛盾。", "隐瞒": "语义：验血的目的是了解病情，不能说通过验血来隐瞒病情。", "治疗": "语义：验血只是检查手段，不能治疗病情，与“通过验血”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "诊断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师诊断了这道题，讲得很清楚。", "explanation": "这里应该用〈解释〉。诊断是判断病因，讲解题目要用解释。"}, {"text": "天气预报诊断明天会下雨。", "explanation": "这里应该用〈预测〉。诊断针对已经存在的病因，对未来的天气要用预测。"}, {"text": "学校诊断了他，决定让他入学。", "explanation": "这里应该用〈录取〉。诊断是判断病情，学校接收学生要用录取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的病被诊断为了胃炎。", "corrected_sentence": "他的病被诊断为胃炎。", "error_description": "错误在“为了”：应为“诊断为”。“为了”表示目的，不能引出诊断结果；引出诊断结果要用“诊断为”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的病是医生诊断来的。", "corrected_sentence": "他的病是医生诊断出来的。", "error_description": "错误：“诊断来的”，正确：“诊断出来的”。“诊断”后要用结果补语“出来”，表示通过诊断找到了病因。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91135, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远离", "is_correct": true, "explanation": "正确：围绕（绕着中心转）与远离（离开中心）意思相对。"}, {"text": "停留", "is_correct": false, "explanation": "与围绕无反义关系：停留是待在原地，不是与绕圈相对的意思。"}, {"text": "保持", "is_correct": false, "explanation": "与围绕无反义关系：保持表示维持原状，与绕圈没有相对关系。"}, {"text": "继续", "is_correct": false, "explanation": "与围绕无反义关系：继续表示接着做下去，与绕圈不相对。"}], "correct_answer": "远离", "explanations": {"远离": "正确：围绕（绕着中心转）与远离（离开中心）意思相对。", "停留": "与围绕无反义关系：停留是待在原地，不是与绕圈相对的意思。", "保持": "与围绕无反义关系：保持表示维持原状，与绕圈没有相对关系。", "继续": "与围绕无反义关系：继续表示接着做下去，与绕圈不相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91135, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远离", "is_correct": true, "explanation": "正确：围绕（绕着中心转）与远离（离开中心）意思相对。"}, {"text": "坚持", "is_correct": false, "explanation": "与围绕无反义关系：坚持表示持续做某事，与绕圈不相对。"}, {"text": "停止", "is_correct": false, "explanation": "与围绕无反义关系：停止与“继续”相对，与绕圈没有相对关系。"}, {"text": "等待", "is_correct": false, "explanation": "与围绕无反义关系：等待表示期望某事发生，与绕圈不相对。"}], "correct_answer": "远离", "explanations": {"远离": "正确：围绕（绕着中心转）与远离（离开中心）意思相对。", "坚持": "与围绕无反义关系：坚持表示持续做某事，与绕圈不相对。", "停止": "与围绕无反义关系：停止与“继续”相对，与绕圈没有相对关系。", "等待": "与围绕无反义关系：等待表示期望某事发生，与绕圈不相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91135, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "围绕是围着一个东西转一圈又一圈。", "primary_collocate": null, "pronunciation": "wéi rào", "ipa": "weɪ˧˥ ɻaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们围绕着大树跑来跑去。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮围绕地球转。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟围绕着花园飞了一圈。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家围绕火堆唱歌跳舞。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗围绕主人跑，很高兴。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂围绕花朵飞来飞去。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们围绕着湖边走了一圈。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子围绕着妈妈玩游戏。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球围绕太阳转一圈要一年。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友围绕老师坐成一圈。", "target_word": "围绕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "围绕着", "label": "体标"}, {"form": "围绕了", "label": "体标"}, {"form": "围绕过", "label": "体标"}], "register": "中性", "sense_fingerprint": "绕着某个东西转圈、环绕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '336a0206-f607-4671-866d-44fb53eddaab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91135, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "围绕着", "is_correct": true, "explanation": "正确：“围绕着”表示绕着大树转圈，与后文“跑来跑去”相合。"}, {"text": "修剪着", "is_correct": false, "explanation": "语义：孩子不能一边修剪大树一边跑来跑去，与情境不合。"}, {"text": "背着", "is_correct": false, "explanation": "语义：“背着大树”意为背负大树，与跑来跑去的情境不合。"}, {"text": "追赶着", "is_correct": false, "explanation": "搭配：“追赶”的对象多为人或动物，不说追赶大树。"}], "explanations": {"围绕着": "正确：“围绕着”表示绕着大树转圈，与后文“跑来跑去”相合。", "修剪着": "语义：孩子不能一边修剪大树一边跑来跑去，与情境不合。", "背着": "语义：“背着大树”意为背负大树，与跑来跑去的情境不合。", "追赶着": "搭配：“追赶”的对象多为人或动物，不说追赶大树。"}, "sentence_index": 0, "correct_answer": "围绕着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵围绕了敌人的阵地。", "explanation": "这里应该用〈包围〉。围绕指绕着中心转动，不用于敌人从四面合围。"}, {"text": "孩子们围绕老师站成一排。", "explanation": "这里不宜用〈围绕〉。围绕表示绕成圈，站成一排不是圆形，形状与词义不符。"}, {"text": "小鸟围绕着天空飞向远方。", "explanation": "这里应该用〈飞向〉。围绕指绕着某物转圈，直线飞向远方不能用“围绕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91135, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "围绕着", "is_correct": true, "explanation": "正确：“围绕着”表示绕着湖边走圈，与“走了一圈”相合。"}, {"text": "离开", "is_correct": false, "explanation": "语义：“离开着湖边走了一圈”前后矛盾，离开与绕圈走的情境不合。"}, {"text": "远离", "is_correct": false, "explanation": "语义：“远离着湖边走了一圈”前后矛盾，与绕湖走的情境不合。"}, {"text": "抛弃", "is_correct": false, "explanation": "搭配：“抛弃”的对象多为人或物件，不说抛弃湖边。"}], "explanations": {"围绕着": "正确：“围绕着”表示绕着湖边走圈，与“走了一圈”相合。", "离开": "语义：“离开着湖边走了一圈”前后矛盾，离开与绕圈走的情境不合。", "远离": "语义：“远离着湖边走了一圈”前后矛盾，与绕湖走的情境不合。", "抛弃": "搭配：“抛弃”的对象多为人或物件，不说抛弃湖边。"}, "sentence_index": 6, "correct_answer": "围绕着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他围绕着队伍站到了最前面。", "explanation": "这里应该用〈插〉。围绕指绕着某物转圈，站到队伍前面不是绕圈，应说“插到前面”。"}, {"text": "汽车围绕着隧道开了过去。", "explanation": "这里应该用〈穿过〉。围绕指绕着某物转圈，从隧道中直接通过不是绕圈。"}, {"text": "他围绕着大门走进了教室。", "explanation": "这里应该用〈从〉。围绕指绕着某物转圈，从门进入不是绕圈，应说“从大门走进教室”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91135, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小狗围绕的树跑了一圈。", "corrected_sentence": "小狗围绕着树跑了一圈。", "error_description": "错误：“围绕”后的“着”被换成了“的”。“围绕着”中“着”是体标，表示持续的状态；“的”使“围绕”变成定语，句子不通。正确形式是“围绕着树”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91135, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鸟围绕过大树飞。", "corrected_sentence": "小鸟围绕着大树飞。", "error_description": "错误：“过”表示曾经的经历，此处描述正在进行的动作，应使用“着”。正确形式是“围绕着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
