INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91138, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体右侧的手。", "primary_collocate": null, "pronunciation": "yòu shǒu", "ipa": "joʊ˥˩ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的右手受伤了，不能拿东西。", "target_word": "右手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请举起你的右手。", "target_word": "右手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她右手提着一个红色的包。", "target_word": "右手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的右手有点儿疼。", "target_word": "右手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用右手摸了摸小狗的头。", "target_word": "右手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生看了看我的右手。", "target_word": "右手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的右手戴着一块新手表。", "target_word": "右手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伸出右手，和客人握手。", "target_word": "右手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我左手拿着伞，右手拿着手机。", "target_word": "右手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摔了一跤，右手流血了。", "target_word": "右手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一只右手", "label": "量词"}, {"form": "右手边", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体右侧的那只手，指部位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '422192c1-2427-4ec1-9369-3724e9165a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91138, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "右手", "is_correct": true, "explanation": "正确：“他的……受伤了，不能拿东西”中，“右手”是拿东西的部位，符合句意。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛受伤与“不能拿东西”之间没有直接的因果关系，句子不通顺。"}, {"text": "嘴巴", "is_correct": false, "explanation": "语义：嘴巴不负责拿东西，“嘴巴受伤不能拿东西”与常识不符。"}, {"text": "膝盖", "is_correct": false, "explanation": "语义：膝盖受伤主要影响走路，与“不能拿东西”不相关。"}], "explanations": {"右手": "正确：“他的……受伤了，不能拿东西”中，“右手”是拿东西的部位，符合句意。", "眼睛": "语义：眼睛受伤与“不能拿东西”之间没有直接的因果关系，句子不通顺。", "嘴巴": "语义：嘴巴不负责拿东西，“嘴巴受伤不能拿东西”与常识不符。", "膝盖": "语义：膝盖受伤主要影响走路，与“不能拿东西”不相关。"}, "sentence_index": 0, "correct_answer": "右手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的右手一直在睡觉，所以我很累。", "explanation": "这里应该用〈人〉作睡觉的主语。手不会睡觉，“右手”不能充当睡觉的主语。"}, {"text": "他把右手放进冰箱里保存。", "explanation": "这里应该用〈饭菜〉这类可以保存的东西。“右手”是身体部位，不能放进冰箱保存。"}, {"text": "他的右手穿着一件毛衣。", "explanation": "这里“右手”不能充当穿衣的主语，应改为〈他〉。“右手”是身体部位，不能被穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91138, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "右手", "is_correct": true, "explanation": "正确：“她的……戴着一块新手表”中，手表戴在手上，“右手”符合句意。"}, {"text": "脖子", "is_correct": false, "explanation": "语义：手表一般戴在手腕上，不能戴在脖子上，句子不通顺。"}, {"text": "膝盖", "is_correct": false, "explanation": "语义：手表不会戴在膝盖上，与常识不符。"}, {"text": "鼻子", "is_correct": false, "explanation": "语义：鼻子上不能戴手表，与常识不符。"}], "explanations": {"右手": "正确：“她的……戴着一块新手表”中，手表戴在手上，“右手”符合句意。", "脖子": "语义：手表一般戴在手腕上，不能戴在脖子上，句子不通顺。", "膝盖": "语义：手表不会戴在膝盖上，与常识不符。", "鼻子": "语义：鼻子上不能戴手表，与常识不符。"}, "sentence_index": 6, "correct_answer": "右手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的右手身高一米八。", "explanation": "这里应该用〈人〉作主语。“身高”描述的是整个人，“右手”只是身体的一部分。"}, {"text": "老师的右手戴了一顶帽子。", "explanation": "这里把“右手”当成了戴帽子的人，应该用〈头〉这类可以戴帽子的部位。“右手”不能戴帽子。"}, {"text": "我的右手正在看电视。", "explanation": "这里应该用〈我〉作主语。“右手”是身体部位，不能看电视。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那块新手表戴他的右手上。", "corrected_sentence": "那块新手表戴在他的右手上。", "error_description": "错误形式：“戴”后直接接“他的右手上”，漏掉了介词“在”。正确形式：“戴在他的右手上”，表示手表戴在手上这个位置，引出地点要用“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她向我伸出了一个右手。", "corrected_sentence": "她向我伸出了一只右手。", "error_description": "错误：“一个右手”。手要用量词“只”，不用“个”。正确说法是“一只右手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
