INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91140, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "需要研究或解决的问题；研究的题目。", "primary_collocate": null, "pronunciation": "kè tí", "ipa": "kʰɤ˥˩ tʰi˧˥", "syllable_count": 2, "sentences": [{"text": "这个课题我们研究了三年。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的研究课题是环境污染。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她申请到了一个国家级课题。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个值得研究的课题。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的博士课题和人工智能有关。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项课题得到了学校的支持。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境保护是全世界的重要课题。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这个课题，我们需要很多数据。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家们正在讨论下一个研究课题。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老教授一生只做一个课题。", "target_word": "课题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "課題", "label": "繁体"}, {"form": "研究课题", "label": "复合"}], "register": "中性", "sense_fingerprint": "需要研究或解决的问题、研究题目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae0e34c9-59ed-46c9-8c20-e1198d73bf8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "课题", "is_correct": true, "explanation": "正确：“这个课题”指需要研究的题目，与“研究了三年”搭配。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭不是需要研究的问题，与“研究了三年”不合。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”是纪念出生的日子，不是需要研究解决的问题，与“研究了三年”不合。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是需要研究的问题，语境不符。"}], "explanations": {"课题": "正确：“这个课题”指需要研究的题目，与“研究了三年”搭配。", "午饭": "语义：午饭不是需要研究的问题，与“研究了三年”不合。", "生日": "语义：“生日”是纪念出生的日子，不是需要研究解决的问题，与“研究了三年”不合。", "蛋糕": "语义：蛋糕不是需要研究的问题，语境不符。"}, "sentence_index": 0, "correct_answer": "课题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚会上有很多课题。", "explanation": "这里应该用〈节目〉。晚会上表演的是“节目”，“课题”指需要研究解决的问题。"}, {"text": "我们班的课题都很好吃。", "explanation": "这里应该用〈点心〉。“好吃”形容食物，“课题”不能被吃。"}, {"text": "下雨了，我忘了带课题。", "explanation": "这里应该用〈雨伞〉。下雨要带的是“雨伞”，“课题”指需要研究解决的问题，不能随身携带。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课题", "is_correct": true, "explanation": "正确：“重要课题”指需要研究解决的问题，与语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：环境保护不是颜色，“重要的颜色”语义不通。"}, {"text": "食物", "is_correct": false, "explanation": "语义：“食物”不是需要研究解决的问题，语境不符。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“重要”不能修饰“感冒”，“重要的感冒”搭配不当。"}], "explanations": {"课题": "正确：“重要课题”指需要研究解决的问题，与语境相符。", "颜色": "语义：环境保护不是颜色，“重要的颜色”语义不通。", "食物": "语义：“食物”不是需要研究解决的问题，语境不符。", "感冒": "搭配：“重要”不能修饰“感冒”，“重要的感冒”搭配不当。"}, "sentence_index": 6, "correct_answer": "课题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这学期我们学习了很多课题。", "explanation": "这里应该用〈课程〉。学习的科目用“课程”，“课题”指研究的题目。"}, {"text": "孩子们在操场上玩一个课题。", "explanation": "这里应该用〈游戏〉。在操场上玩的是“游戏”，“课题”指需要研究解决的问题。"}, {"text": "早餐桌上有很多课题。", "explanation": "这里应该用〈面包〉。早餐桌上摆的是“面包”，“课题”指需要研究解决的问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们小组正在做一根新课题。", "corrected_sentence": "我们小组正在做一个新课题。", "error_description": "量词错误：课题应用“个”或“项”，“根”用于细长的东西。错误形式为“一根新课题”，正确形式为“一个新课题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校为他提供了一条课题。", "corrected_sentence": "学校为他提供了一个课题。", "error_description": "量词错误：课题应用“个”或“项”，“条”用于细长的物品。错误形式为“一条课题”，正确形式为“一个课题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91141, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分开", "is_correct": true, "explanation": "“分开”指不再待在同一处，与“在一起”构成反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "“读书”指学习、看书，与“在一起”没有反义关系。"}, {"text": "停留", "is_correct": false, "explanation": "“停留”指暂时待在某处，与“在一起”没有反义关系。"}, {"text": "完成", "is_correct": false, "explanation": "“完成”指做完某件事，与“在一起”没有反义关系。"}], "correct_answer": "分开", "explanations": {"分开": "“分开”指不再待在同一处，与“在一起”构成反义关系。", "读书": "“读书”指学习、看书，与“在一起”没有反义关系。", "停留": "“停留”指暂时待在某处，与“在一起”没有反义关系。", "完成": "“完成”指做完某件事，与“在一起”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91141, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分开", "is_correct": true, "explanation": "“分开”指不再待在同一处，与“在一起”构成反义关系。"}, {"text": "入睡", "is_correct": false, "explanation": "“入睡”指进入睡眠状态，与“在一起”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指随意走动，与“在一起”没有反义关系。"}, {"text": "工作", "is_correct": false, "explanation": "“工作”指从事劳动或职务活动，与“在一起”没有反义关系。"}], "correct_answer": "分开", "explanations": {"分开": "“分开”指不再待在同一处，与“在一起”构成反义关系。", "入睡": "“入睡”指进入睡眠状态，与“在一起”没有反义关系。", "散步": "“散步”指随意走动，与“在一起”没有反义关系。", "工作": "“工作”指从事劳动或职务活动，与“在一起”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91141, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在一起是大家在同一个地方，不分开。", "primary_collocate": null, "pronunciation": "zài yì qǐ", "ipa": "tsai˥˩ i˥˩ tɕʰi˨˩˦", "syllable_count": 3, "sentences": [{"text": "出门旅游，我们要在一起，不要走散。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人多的地方，孩子要和妈妈在一起。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，同学们还在一起聊天。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一直在一起，从没分开过。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些学生每天都在一起上课。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上大家在一起看电视。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们在一起开会，讨论新计划。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照相的时候，请大家站在一起。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟两个人总是在一起。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在一起吃饭，比一个人吃更有意思。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "在一起了", "label": "完成体标"}, {"form": "在一起过", "label": "经历体标"}], "register": "口语", "sense_fingerprint": "大家待在同一地方，不分开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b52513e-fedf-4788-b1e7-ec0fa96f5592') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91141, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在一起", "is_correct": true, "explanation": "“在一起”表示大家待在同一处、不分开，符合“出门旅游要互相照应”的语境。"}, {"text": "分开", "is_correct": false, "explanation": "语义：“我们要分开，不要走散”前后矛盾，与“不要走散”的要求相反。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“睡觉”不能作为出门旅游时的共同行动要求。"}, {"text": "迷路", "is_correct": false, "explanation": "语义：“迷路”与“不要走散”的意思相反，句子读不通。"}], "explanations": {"在一起": "“在一起”表示大家待在同一处、不分开，符合“出门旅游要互相照应”的语境。", "分开": "语义：“我们要分开，不要走散”前后矛盾，与“不要走散”的要求相反。", "睡觉": "搭配：“睡觉”不能作为出门旅游时的共同行动要求。", "迷路": "语义：“迷路”与“不要走散”的意思相反，句子读不通。"}, "sentence_index": 0, "correct_answer": "在一起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的说法在一起了，不用再讨论。", "explanation": "这里应该用〈一致〉。“在一起”只表示处于同一处所，不表示观点相同，说法相同应说“一致”。"}, {"text": "我们俩的成绩在一起，差了整整十分。", "explanation": "这里应该用〈相差〉。“在一起”只表示处于同一处所，不表示数量之间的差距，说差距应用“相差”。"}, {"text": "大家的意见要在一起。", "explanation": "这里应该用〈统一〉。意见不能处于同一处所，表示意见一致要用“统一”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91141, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在一起", "is_correct": true, "explanation": "“在一起”表示同事们待在同一处开会，符合“讨论新计划”的语境。"}, {"text": "放假", "is_correct": false, "explanation": "语义：放假期间不会开会讨论新计划，与句意矛盾。"}, {"text": "请假", "is_correct": false, "explanation": "语义：“请假”表示不去上班，与“同事们开会”的语境相反。"}, {"text": "午睡", "is_correct": false, "explanation": "搭配：“午睡”是休息的动作，不能作为开会的方式。"}], "explanations": {"在一起": "“在一起”表示同事们待在同一处开会，符合“讨论新计划”的语境。", "放假": "语义：放假期间不会开会讨论新计划，与句意矛盾。", "请假": "语义：“请假”表示不去上班，与“同事们开会”的语境相反。", "午睡": "搭配：“午睡”是休息的动作，不能作为开会的方式。"}, "sentence_index": 6, "correct_answer": "在一起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两座山在一起，却相距很远。", "explanation": "这里应该用〈相距〉。“在一起”只表示处于同一处所，不表示距离；句中既说在一起又说相距很远，前后矛盾。"}, {"text": "这本书的价格和那本在一起，都是二十块。", "explanation": "这里应该用〈相同〉。“在一起”只表示处于同一处所，不表示数量或价格一样；说价格一样应用“相同”。"}, {"text": "这两个班的人数在一起，却差了整整十个人。", "explanation": "这里应该用〈相差〉。“在一起”只表示处于同一处所，不表示数量上的差距；说人数相差应用“相差”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91141, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每天都在一起了散步。", "corrected_sentence": "我们每天都在一起散步。", "error_description": "错误形式是“我们每天都在一起了散步”，正确形式是“我们每天都在一起散步”。“了”不能插在“在一起”和动词“散步”之间，这里不需要体标。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91141, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在一起了看书。", "corrected_sentence": "我们在一起看书。", "error_description": "错误形式是“我们在一起了看书”，正确形式是“我们在一起看书”。“了”不能插在“在一起”和动词“看书”之间，这里不需要体标。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
