INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91142, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "聚在同一处所；共处。", "primary_collocate": null, "pronunciation": "zài yì qǐ", "ipa": "tsai˥˩ i˥˩ tɕʰi˨˩˦", "syllable_count": 3, "sentences": [{"text": "周末我们全家人都在一起吃饭。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩从小就在一起长大。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，亲戚们都在一起。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和同学在一起复习功课。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷奶奶和我们在一起住了十年。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课的时候，他喜欢和好朋友坐在一起。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在一起玩得很高兴。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在一起工作了三年。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家在一起，什么事都好办。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很想和家人在一起过节。", "target_word": "在一起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "在一起了", "label": "完成体标"}, {"form": "在一起过", "label": "经历体标"}], "register": "口语", "sense_fingerprint": "多人聚在同一处所，共处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b52513e-fedf-4788-b1e7-ec0fa96f5592') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91142, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在一起", "is_correct": true, "explanation": "“在一起”表示多人聚在同一处所，符合“周末全家人共同吃饭”的语境。"}, {"text": "离开", "is_correct": false, "explanation": "语义：“离开”与“全家人都……吃饭”的共处语境相反，句子读不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“睡觉”不能与“吃饭”作为全家共同的活动并列。"}, {"text": "分手", "is_correct": false, "explanation": "搭配：“分手”指各自走开或关系结束，不能用于全家人共同吃饭。"}], "explanations": {"在一起": "“在一起”表示多人聚在同一处所，符合“周末全家人共同吃饭”的语境。", "离开": "语义：“离开”与“全家人都……吃饭”的共处语境相反，句子读不通。", "睡觉": "搭配：“睡觉”不能与“吃饭”作为全家共同的活动并列。", "分手": "搭配：“分手”指各自走开或关系结束，不能用于全家人共同吃饭。"}, "sentence_index": 0, "correct_answer": "在一起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的答案和标准答案在一起，差得很远。", "explanation": "这里应该用〈相差〉。“在一起”只表示处于同一处所，不表示程度差距；句中既说在一起又说差得很远，前后矛盾，应说“相差”。"}, {"text": "两位选手的实力在一起，谁也赢不了谁。", "explanation": "这里应该用〈相当〉。“在一起”只表示处于同一处所，不表示实力接近，形容水平接近要用“相当”。"}, {"text": "这两个城市在一起，离得很远。", "explanation": "这里应该用〈相隔〉。“在一起”只表示处于同一处所，不表示两地有距离，说两地相距远要用“相隔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91142, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在一起", "is_correct": true, "explanation": "“在一起”表示孩子们待在同一处玩耍，符合“玩得很高兴”的语境。"}, {"text": "写作业", "is_correct": false, "explanation": "语义：“写作业”是学习任务，与“玩得很高兴”的语境相反。"}, {"text": "上班", "is_correct": false, "explanation": "搭配：“上班”指成年人的工作，不能用来描述孩子。"}, {"text": "工作", "is_correct": false, "explanation": "语义：“工作”与“玩得很高兴”的语义相反，不能描写孩子玩耍。"}], "explanations": {"在一起": "“在一起”表示孩子们待在同一处玩耍，符合“玩得很高兴”的语境。", "写作业": "语义：“写作业”是学习任务，与“玩得很高兴”的语境相反。", "上班": "搭配：“上班”指成年人的工作，不能用来描述孩子。", "工作": "语义：“工作”与“玩得很高兴”的语义相反，不能描写孩子玩耍。"}, "sentence_index": 6, "correct_answer": "在一起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两台机器的时间在一起，要重新调一下。", "explanation": "这里应该用〈同步〉。“在一起”只表示处于同一处所，不表示时间一致，机器运行时间要一致应说“同步”。"}, {"text": "我和室友的爱好在一起，都喜欢打球。", "explanation": "这里应该用〈相同〉。“在一起”只表示处于同一处所，不表示爱好一样；说爱好一样应用“相同”。"}, {"text": "大家的意见要在一起，才能做出决定。", "explanation": "这里应该用〈统一〉。意见不能处于同一处所，表示意见一致要用“统一”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末全家人都在一起着吃饭。", "corrected_sentence": "周末全家人都在一起吃饭。", "error_description": "错误形式是“在一起着吃饭”，正确形式是“在一起吃饭”。“着”不能插在“在一起”和后面的动词“吃饭”之间，这里不需要体标。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在一起了玩耍。", "corrected_sentence": "他们在一起玩耍。", "error_description": "错误形式是“他们在一起了玩耍”，正确形式是“他们在一起玩耍”。“了”不能插在“在一起”和动词“玩耍”之间，这里不需要体标。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
