INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91143, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "同伴是和你一起玩、一起做事的人。", "primary_collocate": null, "pronunciation": "tóng bàn", "ipa": "tʰʊŋ˧˥ pan˥˩", "syllable_count": 2, "sentences": [{"text": "公园里，小明交到了一个新同伴。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都喜欢和同伴一起玩。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是我从小一起玩的同伴。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟没有同伴，一个人在家玩游戏。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们几个同伴一起去打篮球。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在幼儿园，他和同伴一起搭积木。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同伴们在草地上踢球。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，我去找同伴玩。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩游戏时，我的同伴总是让着我。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩和同伴们一起跳绳。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "同伴们", "label": "复数"}], "register": "中性", "sense_fingerprint": "一起玩耍、一起做事的人，多指孩子的玩伴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b7baea-ca68-407f-84e5-c669a1b09102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91143, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同伴", "is_correct": true, "explanation": "正确答案。同伴 tóng bàn 指一起玩耍或做事的人。"}, {"text": "同班", "is_correct": false, "explanation": "bān（第一声）与 bàn（第四声）声调不同，同班意思是同一个班级。"}, {"text": "通办", "is_correct": false, "explanation": "tōng（第一声）与 tóng（第二声）声调不同，通办意思是跨地区统一办理。"}, {"text": "铜板", "is_correct": false, "explanation": "bǎn（第三声）与 bàn（第四声）声调不同，铜板意思是铜制的硬币。"}], "explanations": {"同伴": "正确答案。同伴 tóng bàn 指一起玩耍或做事的人。", "同班": "bān（第一声）与 bàn（第四声）声调不同，同班意思是同一个班级。", "通办": "tōng（第一声）与 tóng（第二声）声调不同，通办意思是跨地区统一办理。", "铜板": "bǎn（第三声）与 bàn（第四声）声调不同，铜板意思是铜制的硬币。"}, "sentence_index": null, "correct_answer": "同伴"}, "level_3": {"options": [{"text": "同伴", "is_correct": true, "explanation": "正确。“同伴”指一起玩耍的人，符合“交到新朋友”的语境。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟只用来报时，不是能一起玩耍的人，“交到新闹钟”不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能与小明一起玩耍。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材只指体形，不指人，“交到了新身材”不通。"}], "explanations": {"同伴": "正确。“同伴”指一起玩耍的人，符合“交到新朋友”的语境。", "闹钟": "语义：闹钟只用来报时，不是能一起玩耍的人，“交到新闹钟”不通。", "冰箱": "语义：冰箱是家用电器，不能与小明一起玩耍。", "身材": "体貌：身材只指体形，不指人，“交到了新身材”不通。"}, "sentence_index": 0, "correct_answer": "同伴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小明家搬来一条新同伴，我们都去认识他。", "explanation": "这里应该用〈位〉或〈个〉。“条”用于长条形的东西，不能数指人的“同伴”。"}, {"text": "幼儿园新来了一颗小同伴，大家都很喜欢他。", "explanation": "这里应该用〈位〉或〈个〉。“颗”用于粒状的东西，不能数指人的“同伴”。"}, {"text": "我的表妹有一本新同伴，每天都来找她玩。", "explanation": "这里应该用〈位〉或〈个〉。“本”用于书册，不能数指人的“同伴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91143, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同伴", "is_correct": true, "explanation": "正确。“同伴”指一起玩耍的人，可以在草地上踢球。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不会在草地上踢球。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能踢球。"}, {"text": "面孔", "is_correct": false, "explanation": "体貌：面孔只指脸，不能指一起踢球的人。"}], "explanations": {"同伴": "正确。“同伴”指一起玩耍的人，可以在草地上踢球。", "椅子": "语义：椅子是家具，不会在草地上踢球。", "窗户": "语义：窗户是建筑部件，不能踢球。", "面孔": "体貌：面孔只指脸，不能指一起踢球的人。"}, "sentence_index": 6, "correct_answer": "同伴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个人是我的同伴，他每天都在我家门口卖菜。", "explanation": "这里应该用〈小贩〉。同伴指一起玩、一起做事的人，与“在门口卖菜”的买卖关系不符；做买卖的人应说“小贩”。"}, {"text": "那个孩子是我的同伴，我们从不一起玩。", "explanation": "这里应该用〈熟人〉。同伴必须一起玩，“从不一起玩”与“同伴”矛盾；只相识、不一起玩的应说“熟人”。"}, {"text": "那个修车的师傅是我的同伴，他每天帮别人修自行车。", "explanation": "这里应该用〈师傅〉。同伴是和我一起玩或一起做事的人，替别人修车的师傅不属于此义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91143, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们三个同伴们一起去公园玩。", "corrected_sentence": "我们三个同伴一起去公园玩。", "error_description": "错误在“同伴们”：“们”不能与前面的数量词“三个”一起用，应去掉“们”，说“三个同伴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91143, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我放学后找了一只同伴玩。", "corrected_sentence": "我放学后找了一位同伴玩。", "error_description": "错误在量词“只”：“只”多用于动物或小件物品，不能数指人的“同伴”；应用“位”，说“一位同伴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
