INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91144, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一起活动或工作的人。", "primary_collocate": null, "pronunciation": "tóng bàn", "ipa": "tʰʊŋ˧˥ pan˥˩", "syllable_count": 2, "sentences": [{"text": "我在公司有几个很好的同伴。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我爬山时的同伴。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行，我们找到了一个好同伴。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作中，同伴的帮助很重要。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和同伴一起做完了这个项目。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同伴们都在会议室等着你。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步时有同伴，我就不会放弃。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的同伴今天生病了，没来上班。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是同伴，要互相帮助。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让每个人找一位同伴来练习。", "target_word": "同伴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "同伴们", "label": "复数"}], "register": "中性", "sense_fingerprint": "一起工作、行动或活动的人，如工作同伴、旅行同伴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b7baea-ca68-407f-84e5-c669a1b09102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91144, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同伴", "is_correct": true, "explanation": "正确答案。同伴 tóng bàn 指一起活动或工作的人。"}, {"text": "同班", "is_correct": false, "explanation": "bān（第一声）与 bàn（第四声）声调不同，同班意思是同一个班级。"}, {"text": "通办", "is_correct": false, "explanation": "tōng（第一声）与 tóng（第二声）声调不同，通办意思是跨地区统一办理。"}, {"text": "铜板", "is_correct": false, "explanation": "bǎn（第三声）与 bàn（第四声）声调不同，铜板意思是铜制的硬币。"}], "explanations": {"同伴": "正确答案。同伴 tóng bàn 指一起活动或工作的人。", "同班": "bān（第一声）与 bàn（第四声）声调不同，同班意思是同一个班级。", "通办": "tōng（第一声）与 tóng（第二声）声调不同，通办意思是跨地区统一办理。", "铜板": "bǎn（第三声）与 bàn（第四声）声调不同，铜板意思是铜制的硬币。"}, "sentence_index": null, "correct_answer": "同伴"}, "level_3": {"options": [{"text": "同伴", "is_correct": true, "explanation": "正确。“同伴”指一起工作的人，与“在公司”“很好的”相合。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑的部件，不是人，不能说是公司里很好的伙伴。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，不能与人一起工作。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气是不可数的物质，不能与“几个”搭配。"}], "explanations": {"同伴": "正确。“同伴”指一起工作的人，与“在公司”“很好的”相合。", "窗户": "语义：窗户是建筑的部件，不是人，不能说是公司里很好的伙伴。", "石头": "语义：石头是无生命的物体，不能与人一起工作。", "空气": "搭配：空气是不可数的物质，不能与“几个”搭配。"}, "sentence_index": 0, "correct_answer": "同伴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班新来了一只同伴，大家都很高兴。", "explanation": "这里应该用〈位〉或〈个〉。“只”多用于动物或小件物品，数指人的“同伴”要用“位”或“个”。"}, {"text": "我们公司新来了一张同伴，经理让他坐在这里。", "explanation": "这里应该用〈位〉或〈个〉。“张”用于纸张、桌子等平面物件，不能数指人的“同伴”。"}, {"text": "新同学来了，他是一本很好的同伴。", "explanation": "这里应该用〈位〉或〈个〉。“本”用于书册，不能数指人的“同伴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_v