INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同伴", "is_correct": true, "explanation": "正确。“同伴”能一起跑步、互相鼓励，符合语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能一起跑步，也不能让人坚持下去。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟只能报时，不能陪人跑步，也不能让人坚持。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材只指体形，不指能一起跑步的人，“有身材，我就不会放弃”不通。"}], "explanations": {"同伴": "正确。“同伴”能一起跑步、互相鼓励，符合语境。", "冰箱": "语义：冰箱是家用电器，不能一起跑步，也不能让人坚持下去。", "闹钟": "语义：闹钟只能报时，不能陪人跑步，也不能让人坚持。", "身材": "体貌：身材只指体形，不指能一起跑步的人，“有身材，我就不会放弃”不通。"}, "sentence_index": 6, "correct_answer": "同伴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的同伴，我们从来不一起做任何事。", "explanation": "这里应该用〈熟人〉。同伴必须一起活动，“从来不一起做事”与“同伴”矛盾；只相识、不一起活动的应说“熟人”。"}, {"text": "那位路人是我的同伴，我们在街上互不相识。", "explanation": "这里应该用〈路人〉。同伴必须一起活动，“互不相识”的人不是同伴；在路上遇到的陌生人应说“路人”。"}, {"text": "那位清洁工是我的同伴，他每天负责打扫小区的走廊。", "explanation": "这里应该用〈清洁工〉。同伴指和我一起活动或工作的人；清洁工替别人干活，不与我一起工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们三个同伴们都去了图书馆。", "corrected_sentence": "我们三个同伴都去了图书馆。", "error_description": "错误在“同伴们”：“们”不能与前面的数量词“三个”一起用，应去掉“们”，说“三个同伴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家门口有一双同伴在等我。", "corrected_sentence": "我家门口有一位同伴在等我。", "error_description": "错误在量词“双”：“双”用于成对的东西，不能数指人的“同伴”；应用“位”，说“一位同伴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91145, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "马虎", "is_correct": true, "explanation": "反义：“马虎”指做事不仔细、不小心，与“谨慎”相对。"}, {"text": "丰富", "is_correct": false, "explanation": "“丰富”形容数量多或内容多，与“谨慎”没有反义关系。"}, {"text": "晴朗", "is_correct": false, "explanation": "“晴朗”形容天气，与“谨慎”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”形容排列或外观，与“谨慎”没有反义关系。"}], "correct_answer": "马虎", "explanations": {"马虎": "反义：“马虎”指做事不仔细、不小心，与“谨慎”相对。", "丰富": "“丰富”形容数量多或内容多，与“谨慎”没有反义关系。", "晴朗": "“晴朗”形容天气，与“谨慎”没有反义关系。", "整齐": "“整齐”形容排列或外观，与“谨慎”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91145, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "鲁莽", "is_correct": true, "explanation": "反义：“鲁莽”指不经思考、冒冒失失，与“谨慎”相对。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线或眼睛，与“谨慎”没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”形容质地，与“谨慎”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容清洁，与“谨慎”没有反义关系。"}], "correct_answer": "鲁莽", "explanations": {"鲁莽": "反义：“鲁莽”指不经思考、冒冒失失，与“谨慎”相对。", "明亮": "“明亮”形容光线或眼睛，与“谨慎”没有反义关系。", "柔软": "“柔软”形容质地，与“谨慎”没有反义关系。", "干净": "“干净”形容清洁，与“谨慎”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91145, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事慢慢来，很小心。", "primary_collocate": null, "pronunciation": "jǐn shèn", "ipa": "tɕin˨˩˦ ʂən˥˩", "syllable_count": 2, "sentences": [{"text": "他做事很谨慎，每一步都检查两遍。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷走路很谨慎，一步一步慢慢走。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她谨慎地把杯子放在桌子上。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天路滑，大家都走得很谨慎。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个谨慎的人，从不着急做决定。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修理旧手表要谨慎，慢慢来。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫谨慎地向前走了几步。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我太谨慎了，出门前总要看三遍。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过河时他很谨慎，先用脚试试水。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬这个花瓶要谨慎一点，别摔了。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "谨慎地", "label": "状语形式"}, {"form": "小心谨慎", "label": "复合"}], "register": "中性", "sense_fingerprint": "谨慎：做事慢慢来，一步一步，很小心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '014adc03-4858-4184-a9b1-120df8f0a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91145, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迅速", "is_correct": false, "explanation": "语义：“迅速”强调快，与“每一步都检查两遍”的细致相矛盾。"}, {"text": "随便", "is_correct": false, "explanation": "语义：“随便”指不认真，与“每一步都检查两遍”矛盾。"}, {"text": "活泼", "is_correct": false, "explanation": "搭配：“活泼”形容性格或气氛，不说“做事很活泼”。"}, {"text": "谨慎", "is_correct": true, "explanation": "正确：“谨慎”指做事慢慢来、很小心，与“每一步都检查两遍”相符。"}], "explanations": {"迅速": "语义：“迅速”强调快，与“每一步都检查两遍”的细致相矛盾。", "随便": "语义：“随便”指不认真，与“每一步都检查两遍”矛盾。", "活泼": "搭配：“活泼”形容性格或气氛，不说“做事很活泼”。", "谨慎": "正确：“谨慎”指做事慢慢来、很小心，与“每一步都检查两遍”相符。"}, "sentence_index": 0, "correct_answer": "谨慎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他谨慎地闭着眼睛跳进了深水里。", "explanation": "这里应该用〈鲁莽〉。闭着眼睛跳进深水是鲁莽的表现；“谨慎”表示小心，与此矛盾。"}, {"text": "他谨慎地撞翻了花瓶。", "explanation": "这里应该用〈冒失〉。撞翻花瓶是冒失的表现；“谨慎”表示小心，与“撞翻”矛盾。"}, {"text": "他谨慎地忘了关火。", "explanation": "这里应该用〈大意〉。忘记关火是大意的表现；“谨慎”表示小心，与“忘了关火”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91145, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幽默", "is_correct": false, "explanation": "搭配：“幽默”形容谈吐或性格，不用来修饰猫走路的动作。"}, {"text": "慷慨", "is_correct": false, "explanation": "语义：“慷慨”形容待人大方、不吝啬，不用来形容猫走路的样子。"}, {"text": "深情", "is_correct": false, "explanation": "语义：“深情”形容情感，“深情地向前走”与走路的动作不符。"}, {"text": "谨慎", "is_correct": true, "explanation": "正确：“谨慎”指走得小心慢慢，与“向前走了几步”相符。"}], "explanations": {"幽默": "搭配：“幽默”形容谈吐或性格，不用来修饰猫走路的动作。", "慷慨": "语义：“慷慨”形容待人大方、不吝啬，不用来形容猫走路的样子。", "深情": "语义：“深情”形容情感，“深情地向前走”与走路的动作不符。", "谨慎": "正确：“谨慎”指走得小心慢慢，与“向前走了几步”相符。"}, "sentence_index": 6, "correct_answer": "谨慎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他谨慎地把钥匙落在了车上。", "explanation": "这里应该用〈粗心〉。落下钥匙是粗心的表现；“谨慎”表示小心，与“落在车上”矛盾。"}, {"text": "她谨慎地冲出了门，差点撞到人。", "explanation": "这里应该用〈匆忙〉。“匆忙”形容急促，冲出门是匆忙的表现；“谨慎”强调慢慢来，与“冲出门”矛盾。"}, {"text": "他把垃圾谨慎地扔在路上。", "explanation": "这里应该用〈随手〉。随手乱扔垃圾是随便的表现；“谨慎”强调小心，不用于描述乱扔垃圾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91145, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷是个很谨慎老人，走路总是慢慢的。", "corrected_sentence": "爷爷是个很谨慎的老人，走路总是慢慢的。", "error_description": "“很谨慎”修饰名词“老人”时中间要加“的”，应说“很谨慎的老人”，漏掉“的”不合语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91145, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈谨慎的抱起了熟睡的婴儿。", "corrected_sentence": "妈妈谨慎地抱起了熟睡的婴儿。", "error_description": "“谨慎”修饰动词“抱起”时要用“地”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91146, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "鲁莽", "is_correct": true, "explanation": "反义：“鲁莽”指做事不经考虑、冒冒失失，与“谨慎”相对。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容待人的态度，与“谨慎”没有反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”形容心情或状态，与“谨慎”没有反义关系。"}, {"text": "幽默", "is_correct": false, "explanation": "“幽默”形容谈吐风趣，与“谨慎”没有反义关系。"}], "correct_answer": "鲁莽", "explanations": {"鲁莽": "反义：“鲁莽”指做事不经考虑、冒冒失失，与“谨慎”相对。", "热情": "“热情”形容待人的态度，与“谨慎”没有反义关系。", "轻松": "“轻松”形容心情或状态，与“谨慎”没有反义关系。", "幽默": "“幽默”形容谈吐风趣，与“谨慎”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91146, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "草率", "is_correct": true, "explanation": "反义：“草率”指做事马虎、不慎重，与“谨慎”相对。"}, {"text": "冷淡", "is_correct": false, "explanation": "“冷淡”形容态度不热情，与“谨慎”没有反义关系。"}, {"text": "美丽", "is_correct": false, "explanation": "“美丽”形容外貌或景色，与“谨慎”没有反义关系。"}, {"text": "响亮", "is_correct": false, "explanation": "“响亮”形容声音，与“谨慎”没有反义关系。"}], "correct_answer": "草率", "explanations": {"草率": "反义：“草率”指做事马虎、不慎重，与“谨慎”相对。", "冷淡": "“冷淡”形容态度不热情，与“谨慎”没有反义关系。", "美丽": "“美丽”形容外貌或景色，与“谨慎”没有反义关系。", "响亮": "“响亮”形容声音，与“谨慎”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91146, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对外界事物或自己言行密切注意，以免发生不利或不幸的事。", "primary_collocate": null, "pronunciation": "jǐn shèn", "ipa": "tɕin˨˩˦ ʂən˥˩", "syllable_count": 2, "sentences": [{"text": "开车上山路要谨慎，一不小心就会出事。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话很谨慎，从不乱说别人的事。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投资要谨慎，别把钱都放在一个地方。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对陌生人的电话一向很谨慎。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子过马路时要特别谨慎。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板做决定很谨慎，要想很久。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对新的合同，我们必须谨慎。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他谨慎地看了看四周，才打开门。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上买东西要谨慎，别相信陌生人。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生谨慎地检查了病人的伤口。", "target_word": "谨慎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "谨慎地", "label": "状语形式"}, {"form": "小心谨慎", "label": "复合"}], "register": "中性", "sense_fingerprint": "谨慎：对言行、决定密切注意，避免出错或受损", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '014adc03-4858-4184-a9b1-120df8f0a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91146, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容待人的态度，不说“开车上山路要热情”。"}, {"text": "大方", "is_correct": false, "explanation": "语义：“大方”形容举止或待人不吝啬，与驾车的安全要求无关。"}, {"text": "幽默", "is_correct": false, "explanation": "搭配：“幽默”形容谈吐和性格，“要幽默”不能用来说开车。"}, {"text": "谨慎", "is_correct": true, "explanation": "正确：“谨慎”指对行动密切注意，开山路要注意安全，与“一不小心就会出事”相符。"}], "explanations": {"热情": "语义：“热情”形容待人的态度，不说“开车上山路要热情”。", "大方": "语义：“大方”形容举止或待人不吝啬，与驾车的安全要求无关。", "幽默": "搭配：“幽默”形容谈吐和性格，“要幽默”不能用来说开车。", "谨慎": "正确：“谨慎”指对行动密切注意，开山路要注意安全，与“一不小心就会出事”相符。"}, "sentence_index": 0, "correct_answer": "谨慎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他谨慎地把所有的钱都扔进了河里。", "explanation": "这里应该用〈随便〉。“随便”形容不加考虑地做事，把钱全扔进河里正是随便的表现；“谨慎”表示小心，与此矛盾。"}, {"text": "他谨慎地撞进了办公室。", "explanation": "这里应该用〈冒失〉。“冒失”形容做事莽撞，撞进办公室是冒失的表现；“谨慎”表示小心，与“撞”矛盾。"}, {"text": "服务员谨慎地打翻了一整盘饭菜。", "explanation": "这里应该用〈粗心〉。打翻一整盘饭菜是粗心的表现；“谨慎”表示小心，与“打翻”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91146, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热烈", "is_correct": false, "explanation": "语义：“热烈”形容气氛或情感，“必须热烈”与面对合同需要的审慎态度不符。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：“苗条”形容人的体形，不用来说做事的态度。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：“懒散”指不认真、没有精神，与“面对新的合同”需要的态度相反。"}, {"text": "谨慎", "is_correct": true, "explanation": "正确：“谨慎”指面对合同要仔细、慎重，与语境相符。"}], "explanations": {"热烈": "语义：“热烈”形容气氛或情感，“必须热烈”与面对合同需要的审慎态度不符。", "苗条": "体貌：“苗条”形容人的体形，不用来说做事的态度。", "懒散": "语义：“懒散”指不认真、没有精神，与“面对新的合同”需要的态度相反。", "谨慎": "正确：“谨慎”指面对合同要仔细、慎重，与语境相符。"}, "sentence_index": 6, "correct_answer": "谨慎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他谨慎地拍了拍桌子，大喊着“别吵了”。", "explanation": "这里应该用〈粗暴〉。“粗暴”形容态度或动作猛烈；“谨慎”表示小心，与拍桌子、大喊的做法矛盾。"}, {"text": "孩子们在操场上玩得很谨慎，大声笑着。", "explanation": "这里应该用〈活泼〉。孩子玩耍应是活泼的，“谨慎”与大声笑闹的情景矛盾。"}, {"text": "他谨慎地摔门而去，大家都吓了一跳。", "explanation": "这里应该用〈猛烈〉。“摔门而去”是猛烈的动作；“谨慎”表示小心，与这种猛劲矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91146, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是个很谨慎司机，每次过路口都减速。", "corrected_sentence": "他是个很谨慎的司机，每次过路口都减速。", "error_description": "“很谨慎”修饰名词“司机”时中间要加“的”，应说“很谨慎的司机”，漏掉“的”不合语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91146, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她谨慎的打开了箱子，发现里面有一封信。", "corrected_sentence": "她谨慎地打开了箱子，发现里面有一封信。", "error_description": "“谨慎”修饰动词“打开”时要用“地”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
