INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91147, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地下是在地面的下面。", "primary_collocate": null, "pronunciation": "dì xià", "ipa": "ti˥˩ ɕia˥˩", "syllable_count": 2, "sentences": [{"text": "花生是长在地下的。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下三米的地方有水。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房子的地下是空的。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，虫子都躲在地下。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁在地下跑，不会堵车。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱埋在了地下。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下太黑了，我要带一个手电筒。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，地下的东西不能乱挖。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的地下有很多管子。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，种子在地下慢慢长大。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "地下室", "label": "复合"}, {"form": "地下水", "label": "复合"}], "register": "中性", "sense_fingerprint": "在地面的下面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d2fa9c-e3fd-42ad-8411-015657f8b96c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91147, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地下", "is_correct": true, "explanation": "地下 dìxià：在地面的下面，正确答案。"}, {"text": "滴下", "is_correct": false, "explanation": "滴下 dīxià（第一声）与 dìxià 声调不同，意思是液体一滴一滴落下。"}, {"text": "地线", "is_correct": false, "explanation": "地线 dìxiàn 第二音节多了韵尾 n（xiàn 与 xià 不同），意思是接地的电线。"}, {"text": "剃下", "is_correct": false, "explanation": "剃下 tìxià 声母 t 与 d 不同（送气），意思是用剃刀刮下来。"}], "explanations": {"地下": "地下 dìxià：在地面的下面，正确答案。", "滴下": "滴下 dīxià（第一声）与 dìxià 声调不同，意思是液体一滴一滴落下。", "地线": "地线 dìxiàn 第二音节多了韵尾 n（xiàn 与 xià 不同），意思是接地的电线。", "剃下": "剃下 tìxià 声母 t 与 d 不同（送气），意思是用剃刀刮下来。"}, "sentence_index": null, "correct_answer": "地下"}, "level_3": {"options": [{"text": "地下", "is_correct": true, "explanation": "地下：指地面以下，花生在地下生长，与语境相符。"}, {"text": "树上", "is_correct": false, "explanation": "语义：花生不长在树上，与“长在……的”语境冲突。"}, {"text": "天上", "is_correct": false, "explanation": "语义：花生不会长在天上，与常识相悖。"}, {"text": "星期一", "is_correct": false, "explanation": "配价：“长在”要求处所或事物作地点，“星期一”是时间词，不能作地点。"}], "explanations": {"地下": "地下：指地面以下，花生在地下生长，与语境相符。", "树上": "语义：花生不长在树上，与“长在……的”语境冲突。", "天上": "语义：花生不会长在天上，与常识相悖。", "星期一": "配价：“长在”要求处所或事物作地点，“星期一”是时间词，不能作地点。"}, "sentence_index": 0, "correct_answer": "地下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "月亮从地下升起来了。", "explanation": "这里应该用〈地平线〉。月亮从地平线升起，地下指地面以下，不能说月亮从地下升起。"}, {"text": "小船在地下漂。", "explanation": "这里应该用〈水上〉。小船漂在水面上，地下指地面以下，不是水域。"}, {"text": "星星在地下闪着光。", "explanation": "这里应该用〈天上〉。星星在天空中发光，不在地下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91147, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "地下", "is_correct": true, "explanation": "地下 dìxià：在地面的下面，正确答案。"}, {"text": "低下", "is_correct": false, "explanation": "低下 dīxià（第一声）与 dìxià 第一音节声调不同，意思是水平、地位偏低。"}, {"text": "地价", "is_correct": false, "explanation": "地价 dìjià 第二音节声母 j 与 x 不同，意思是土地的价格。"}, {"text": "陛下", "is_correct": false, "explanation": "陛下 bìxià 声母 b 与 d 不同，意思是对皇帝的尊称。"}, {"text": "替下", "is_correct": false, "explanation": "替下 tìxià 声母 t 与 d 不同（送气），意思是换下来。"}], "explanations": {"地下": "地下 dìxià：在地面的下面，正确答案。", "低下": "低下 dīxià（第一声）与 dìxià 第一音节声调不同，意思是水平、地位偏低。", "地价": "地价 dìjià 第二音节声母 j 与 x 不同，意思是土地的价格。", "陛下": "陛下 bìxià 声母 b 与 d 不同，意思是对皇帝的尊称。", "替下": "替下 tìxià 声母 t 与 d 不同（送气），意思是换下来。"}, "sentence_index": null, "correct_answer": "地下"}, "level_3": {"options": [{"text": "地下", "is_correct": true, "explanation": "地下：指地面以下，地下没有光线，所以很黑，与语境相符。"}, {"text": "中午", "is_correct": false, "explanation": "语义：中午阳光充足，不会“太黑了”，与语境冲突。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“黑”形容光线或颜色，不能形容声音，与“太黑了”不搭配。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：“阳光”一般用“明亮、刺眼”形容，不用“太黑了”。"}], "explanations": {"地下": "地下：指地面以下，地下没有光线，所以很黑，与语境相符。", "中午": "语义：中午阳光充足，不会“太黑了”，与语境冲突。", "声音": "搭配：“黑”形容光线或颜色，不能形容声音，与“太黑了”不搭配。", "阳光": "搭配：“阳光”一般用“明亮、刺眼”形容，不用“太黑了”。"}, "sentence_index": 6, "correct_answer": "地下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他站在地下看风景。", "explanation": "这里应该用〈山顶上〉。地下指地面以下，站在低处的地下看不到风景，看风景应在高处。"}, {"text": "孩子们在地下放风筝。", "explanation": "这里应该用〈草地上〉。风筝要飞在空中，地下指地面以下，不能说在地下放风筝。"}, {"text": "海豚在地下跳跃。", "explanation": "这里应该用〈海面上〉。海豚跳跃的地方在海面，不在地下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91147, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "胡萝卜长地下。", "corrected_sentence": "胡萝卜长在地下。", "error_description": "错误：“长”后漏掉了介词“在”。地下作处所时要用“在”引出，应为“长在地下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91147, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蚯蚓生活在的地下。", "corrected_sentence": "蚯蚓生活在地下。", "error_description": "错误：“在”后多了“的”。“在地下”是介词短语，“的”不能加在“在”和“地下”之间，应为“生活在地下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
