INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91148, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地面以下。", "primary_collocate": null, "pronunciation": "dì xià", "ipa": "ti˥˩ ɕia˥˩", "syllable_count": 2, "sentences": [{"text": "地下有一条很长的水管。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些树的根都在地下。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下很凉，夏天也不热。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在地下发现了一个旧箱子。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗把骨头藏在地下了。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水慢慢流到地下去了。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的地下有很多电线。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠住在地下，晚上才出来。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下的水很干净，可以喝。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在地下挖了一个大洞。", "target_word": "地下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "地下室", "label": "复合"}, {"form": "地下水", "label": "复合"}], "register": "中性", "sense_fingerprint": "地面以下的空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d2fa9c-e3fd-42ad-8411-015657f8b96c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91148, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地下", "is_correct": true, "explanation": "地下 dìxià：地面以下，正确答案。"}, {"text": "低下", "is_correct": false, "explanation": "低下 dīxià（第一声）与 dìxià 第一音节声调不同，意思是水平、地位偏低。"}, {"text": "地价", "is_correct": false, "explanation": "地价 dìjià 第二音节声母 j 与 x 不同，意思是土地的价格。"}, {"text": "陛下", "is_correct": false, "explanation": "陛下 bìxià 声母 b 与 d 不同，意思是对皇帝的尊称。"}, {"text": "替下", "is_correct": false, "explanation": "替下 tìxià 声母 t 与 d 不同（送气），意思是换下来。"}], "explanations": {"地下": "地下 dìxià：地面以下，正确答案。", "低下": "低下 dīxià（第一声）与 dìxià 第一音节声调不同，意思是水平、地位偏低。", "地价": "地价 dìjià 第二音节声母 j 与 x 不同，意思是土地的价格。", "陛下": "陛下 bìxià 声母 b 与 d 不同，意思是对皇帝的尊称。", "替下": "替下 tìxià 声母 t 与 d 不同（送气），意思是换下来。"}, "sentence_index": null, "correct_answer": "地下"}, "level_3": {"options": [{"text": "地下", "is_correct": true, "explanation": "地下：指地面以下，水管埋在地面以下，与语境相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空在高处，水管不会在天空中，与“地下”的语境冲突。"}, {"text": "声音", "is_correct": false, "explanation": "配价：“有”引出的存现句要求处所词，“声音”不是处所。"}, {"text": "中午", "is_correct": false, "explanation": "配价：“有”的存现句要求处所词，“中午”是时间词，不能作处所。"}], "explanations": {"地下": "地下：指地面以下，水管埋在地面以下，与语境相符。", "天空": "语义：天空在高处，水管不会在天空中，与“地下”的语境冲突。", "声音": "配价：“有”引出的存现句要求处所词，“声音”不是处所。", "中午": "配价：“有”的存现句要求处所词，“中午”是时间词，不能作处所。"}, "sentence_index": 0, "correct_answer": "地下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "飞机在地下起飞了。", "explanation": "这里应该用〈地面〉。飞机要在地面上滑行起飞，地下指地面以下，不能说飞机在地下起飞。"}, {"text": "这棵树的叶子长在地下。", "explanation": "这里应该用〈地上〉。树叶长在地面以上，地下指地面以下，不能用来说叶子的位置。"}, {"text": "鸟儿在地下飞来飞去。", "explanation": "这里应该用〈天上〉。鸟在天空中飞，地下不是飞行的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91148, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "地下", "is_correct": true, "explanation": "地下 dìxià：地面以下，正确答案。"}, {"text": "滴下", "is_correct": false, "explanation": "滴下 dīxià（第一声）与 dìxià 声调不同，意思是液体一滴一滴落下。"}, {"text": "地线", "is_correct": false, "explanation": "地线 dìxiàn 第二音节多了韵尾 n（xiàn 与 xià 不同），意思是接地的电线。"}, {"text": "剃下", "is_correct": false, "explanation": "剃下 tìxià 声母 t 与 d 不同（送气），意思是用剃刀刮下来。"}], "explanations": {"地下": "地下 dìxià：地面以下，正确答案。", "滴下": "滴下 dīxià（第一声）与 dìxià 声调不同，意思是液体一滴一滴落下。", "地线": "地线 dìxiàn 第二音节多了韵尾 n（xiàn 与 xià 不同），意思是接地的电线。", "剃下": "剃下 tìxià 声母 t 与 d 不同（送气），意思是用剃刀刮下来。"}, "sentence_index": null, "correct_answer": "地下"}, "level_3": {"options": [{"text": "地下", "is_correct": true, "explanation": "地下：指地面以下，城市的地下铺设电线，与语境相符。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”不是可以铺设电线的场所，与“这座城市的……有很多电线”冲突。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是场所，不能铺设电线，与“这座城市的……有很多电线”冲突。"}, {"text": "白天", "is_correct": false, "explanation": "配价：“有”的存现句要求处所词，“白天”是时间词，不能作处所。"}], "explanations": {"地下": "地下：指地面以下，城市的地下铺设电线，与语境相符。", "心情": "语义：“心情”不是可以铺设电线的场所，与“这座城市的……有很多电线”冲突。", "声音": "语义：“声音”不是场所，不能铺设电线，与“这座城市的……有很多电线”冲突。", "白天": "配价：“有”的存现句要求处所词，“白天”是时间词，不能作处所。"}, "sentence_index": 6, "correct_answer": "地下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "太阳从地下升起来了。", "explanation": "这里应该用〈东边〉。太阳从东边升起，地下指地面以下，不能说太阳从地下升起。"}, {"text": "猴子在地下摘桃子。", "explanation": "这里应该用〈树上〉。地下指地面以下，猴子摘桃子的地方在树上。"}, {"text": "鱼儿在地下游来游去。", "explanation": "这里应该用〈水里〉。地下指地面以下，鱼生活在水中，不在地下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid =