INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91149, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91149, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名额是规定能有几个人的数。", "primary_collocate": null, "pronunciation": "míng é", "ipa": "miŋ˧˥ ɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这个班只有五个名额。", "target_word": "名额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给我们班两个名额。", "target_word": "名额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的名额已经满了。", "target_word": "名额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿到了去北京的名额。", "target_word": "名额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想要这个名额吗？", "target_word": "名额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的名额不多。", "target_word": "名额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把名额给了小李。", "target_word": "名额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报名的人太多，名额不够。", "target_word": "名额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司有三个出国学习的名额。", "target_word": "名额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为了一个名额，每天努力学习。", "target_word": "名额", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "规定能有几个人的数目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2159400-947f-4fbc-9ddc-227cd6535575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91149, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名额", "is_correct": true, "explanation": "正确：名额指规定能有几个人的数，与“这个班只有五个”相合。"}, {"text": "名单", "is_correct": false, "explanation": "搭配：名单通常用“份”计量，不说“五个名单”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的练习，不能表示“只有五个”限定的人数或席位。"}, {"text": "意见", "is_correct": false, "explanation": "语义：意见是看法，不是可以被限定数量的名额。"}], "explanations": {"名额": "正确：名额指规定能有几个人的数，与“这个班只有五个”相合。", "名单": "搭配：名单通常用“份”计量，不说“五个名单”。", "作业": "语义：作业是学生的练习，不能表示“只有五个”限定的人数或席位。", "意见": "语义：意见是看法，不是可以被限定数量的名额。"}, "sentence_index": 0, "correct_answer": "名额"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在墙上画了一个名额。", "explanation": "这里应该用〈图〉。名额是规定的人数，不能被画出来，应说“画了一幅图”。"}, {"text": "老师把他的名字写进了名额。", "explanation": "这里应该用〈名单〉。名额是可分配的人数，把名字写进去要用名单。"}, {"text": "他在学校很有名额。", "explanation": "这里应该用〈名声〉。名额不表示别人对他的评价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91149, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名额", "is_correct": true, "explanation": "正确：名额是可以分配的指标，与“老师把……给了小李”相合。"}, {"text": "雷声", "is_correct": false, "explanation": "语义：雷声是声音，不能被“给”出去作为东西分配，与句意不符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以赠予他人的东西，与句意不符。"}, {"text": "高度", "is_correct": false, "explanation": "搭配：“给”通常与可转让的东西或机会搭配，不说“给高度”。"}], "explanations": {"名额": "正确：名额是可以分配的指标，与“老师把……给了小李”相合。", "雷声": "语义：雷声是声音，不能被“给”出去作为东西分配，与句意不符。", "天空": "语义：天空不是可以赠予他人的东西，与句意不符。", "高度": "搭配：“给”通常与可转让的东西或机会搭配，不说“给高度”。"}, "sentence_index": 6, "correct_answer": "名额"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他胸前别着名额。", "explanation": "这里应该用〈名牌〉。名额是人数或名次，不能用来佩戴。"}, {"text": "他读了很多名额。", "explanation": "这里应该用〈名著〉。名额不指书籍，不能用来阅读。"}, {"text": "这家店的名额很有趣。", "explanation": "这里应该用〈名称〉。名额是数量概念，不指店的称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91149, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班分到了三张名额。", "corrected_sentence": "我们班分到了三个名额。", "error_description": "“名额”的量词应用“个”，不说“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91149, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他为了争取一个去北京名额，放弃了整个周末。", "corrected_sentence": "他为了争取一个去北京的名额，放弃了整个周末。", "error_description": "定语与中心语之间漏掉“的”：“去北京”修饰“名额”时要用“的”，应为“去北京的名额”，不能说“去北京名额”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
