INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91152, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一国政府发给本国公民出国旅行、证明其身份和国籍的证件。", "primary_collocate": null, "pronunciation": "hù zhào", "ipa": "xu˥˩ ʈʂɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "出国前，我去公安局办了护照。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的护照上有照片和国籍。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关人员请我给他看护照。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本护照是中国政府发的。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的护照下个月就到期了。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的护照放在桌子上。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场工作人员检查了每个人的护照。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外丢了护照，很着急。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办护照需要两张照片。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想换一本新护照。", "target_word": "护照", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "護照", "label": "繁体"}, {"form": "电子护照", "label": "复合"}, {"form": "护照号码", "label": "复合"}], "register": "中性", "sense_fingerprint": "政府发给公民、证明身份和国籍的出国证件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae0e34c9-59ed-46c9-8c20-e1198d73bf8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "护照", "is_correct": true, "explanation": "正确：“办护照”指办理出国用的证件，符合语境。"}, {"text": "病历", "is_correct": false, "explanation": "语义：公安局办理的是出入境证件，不办理病历。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“办”不能与“作业”搭配，应说“做作业”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“办”不接“蛋糕”，公安局也不办理食品。"}], "explanations": {"护照": "正确：“办护照”指办理出国用的证件，符合语境。", "病历": "语义：公安局办理的是出入境证件，不办理病历。", "作业": "搭配：“办”不能与“作业”搭配，应说“做作业”。", "蛋糕": "搭配：“办”不接“蛋糕”，公安局也不办理食品。"}, "sentence_index": 0, "correct_answer": "护照"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天出门前都用护照开门。", "explanation": "这里应该用〈钥匙〉。开门用钥匙，护照是出入境证件，不能用来开门。"}, {"text": "他在售票处买了一本护照。", "explanation": "这里应该用〈机票〉。售票处卖的是机票，护照是政府发给公民的出入境证件，不能在售票处买。"}, {"text": "吃完饭，他用护照付了饭钱。", "explanation": "这里应该用〈银行卡〉。付钱要用银行卡或现金，护照是出入境证件，不能用来付钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "护照", "is_correct": true, "explanation": "正确：机场检查的是出入境证件，“护照”符合语境。"}, {"text": "作文", "is_correct": false, "explanation": "语义：机场工作人员不检查作文，语境不符。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：机场工作人员不检查乐谱，语境不符。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“检查”不与“性格”搭配，应说“了解”性格。"}], "explanations": {"护照": "正确：机场检查的是出入境证件，“护照”符合语境。", "作文": "语义：机场工作人员不检查作文，语境不符。", "乐谱": "语义：机场工作人员不检查乐谱，语境不符。", "性格": "搭配：“检查”不与“性格”搭配，应说“了解”性格。"}, "sentence_index": 6, "correct_answer": "护照"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "报销时要贴护照。", "explanation": "这里应该用〈发票〉。报销要贴发票，护照是出入境证件，不能用来报销。"}, {"text": "上班要戴护照。", "explanation": "这里应该用〈工作证〉。上班佩戴的是工作证，护照是出国证件。"}, {"text": "他发烧了，就用护照量体温。", "explanation": "这里应该用〈体温计〉。量体温要用体温计，护照是出入境证件，不能用来测量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下周去公安局办了护照。", "corrected_sentence": "我下周去公安局办护照。", "error_description": "时态与“了”冲突：“下周”指将来，动词后的“了”表示已完成，不能共现。错误形式为“办了护照”，正确形式为“办护照”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他上个月换了一只新护照。", "corrected_sentence": "他上个月换了一本新护照。", "error_description": "量词错误：“护照”应用量词“本”，“只”用于成对的物品或动物。错误形式为“一只新护照”，正确形式为“一本新护照”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
