INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91153, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大道是又宽又大的路。", "primary_collocate": null, "pronunciation": "dà dào", "ipa": "ta˥˩ tau˥˩", "syllable_count": 2, "sentences": [{"text": "这条大道又宽又直，两边都是树。", "target_word": "大道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车在大道上开得很快。", "target_word": "大道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家门前有一条大道。", "target_word": "大道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大道两旁种着很多花。", "target_word": "大道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了大道，就是我们学校。", "target_word": "大道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日里，大道上挂满了红灯笼。", "target_word": "大道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑着自行车走在大道上。", "target_word": "大道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条大道通向城外。", "target_word": "大道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大道上车太多，我们走小路吧。", "target_word": "大道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城中心的大道晚上特别亮。", "target_word": "大道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条大道", "label": "量词（条）"}], "register": "中性", "sense_fingerprint": "又宽又大的道路，指实际的街道或公路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940b2af-c4cb-48b8-9d0b-57e75b82fbed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91153, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大道", "is_correct": true, "explanation": "正确答案。大道指又宽又大的道路。"}, {"text": "达到", "is_correct": false, "explanation": "dá（第二声）与 dà（第四声）声调不同，意思是到达。"}, {"text": "大刀", "is_correct": false, "explanation": "dāo（第一声）与 dào（第四声）声调不同，意思是刀具。"}, {"text": "打倒", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）、dǎo（第三声）与 dào（第四声）声调不同，意思是推翻。"}, {"text": "打到", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）声调不同，意思是击中或到达。"}], "explanations": {"大道": "正确答案。大道指又宽又大的道路。", "达到": "dá（第二声）与 dà（第四声）声调不同，意思是到达。", "大刀": "dāo（第一声）与 dào（第四声）声调不同，意思是刀具。", "打倒": "dǎ（第三声）与 dà（第四声）、dǎo（第三声）与 dào（第四声）声调不同，意思是推翻。", "打到": "dǎ（第三声）与 dà（第四声）声调不同，意思是击中或到达。"}, "sentence_index": null, "correct_answer": "大道"}, "level_3": {"options": [{"text": "大道", "is_correct": true, "explanation": "正确：大道是又宽又大的路，与“又宽又直、两边都是树”相符。"}, {"text": "小路", "is_correct": false, "explanation": "语义：小路窄，与“又宽又直”矛盾。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“这条”用于道路、河流等长条形事物，房间应说“这间”，也不会“两边都是树”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会“两边都是树”，也不能说“又宽又直”的路。"}], "explanations": {"大道": "正确：大道是又宽又大的路，与“又宽又直、两边都是树”相符。", "小路": "语义：小路窄，与“又宽又直”矛盾。", "房间": "搭配：“这条”用于道路、河流等长条形事物，房间应说“这间”，也不会“两边都是树”。", "桌子": "语义：桌子不会“两边都是树”，也不能说“又宽又直”的路。"}, "sentence_index": 0, "correct_answer": "大道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们走进一条大道，里面又窄又暗。", "explanation": "这里应该用〈小巷〉。大道又宽又大，不能用来形容又窄又暗的巷子。"}, {"text": "我家门前的大道上种满了麦子，已经黄了。", "explanation": "这里应该用〈田地〉。大道是供车马通行的路，不会种麦子；种庄稼的地方是田地。"}, {"text": "这条大道只能容一个人通过。", "explanation": "这里应该用〈小道〉。大道宽阔，不会只能容一个人通过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91153, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大道", "is_correct": true, "explanation": "正确答案。大道指又宽又大的道路。"}, {"text": "答道", "is_correct": false, "explanation": "dá（第二声）与 dà（第四声）声调不同，意思是回答。"}, {"text": "打到", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）声调不同，意思是击中。"}, {"text": "大岛", "is_correct": false, "explanation": "dǎo（第三声）与 dào（第四声）声调不同，意思是较大的岛屿。"}], "explanations": {"大道": "正确答案。大道指又宽又大的道路。", "答道": "dá（第二声）与 dà（第四声）声调不同，意思是回答。", "打到": "dǎ（第三声）与 dà（第四声）声调不同，意思是击中。", "大岛": "dǎo（第三声）与 dào（第四声）声调不同，意思是较大的岛屿。"}, "sentence_index": null, "correct_answer": "大道"}, "level_3": {"options": [{"text": "大道", "is_correct": true, "explanation": "正确：大道是供车辆行人通行的路，可以“走在大道上”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：人不能骑车走在天空上。"}, {"text": "河水", "is_correct": false, "explanation": "语义：人不能骑车走在水面上。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“走在……上”指路面等表面，教室应说“走在教室里”。"}], "explanations": {"大道": "正确：大道是供车辆行人通行的路，可以“走在大道上”。", "天空": "语义：人不能骑车走在天空上。", "河水": "语义：人不能骑车走在水面上。", "教室": "搭配：“走在……上”指路面等表面，教室应说“走在教室里”。"}, "sentence_index": 6, "correct_answer": "大道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条大道向东流，最后汇入大海。", "explanation": "这里应该用〈河〉。大道是供车马行走的路，不会向东流，也不会汇入大海。"}, {"text": "这条大道很深，水很清，里面有很多鱼。", "explanation": "这里应该用〈水渠〉。大道是陆上的路，不会“很深”，里面也不会有鱼。"}, {"text": "大道的水面上夏天开满了荷花，很美。", "explanation": "这里应该用〈池塘〉。大道是路，没有水面；“开满荷花”指的是池塘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91153, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只大道又宽又直，车开得很快。", "corrected_sentence": "这条大道又宽又直，车开得很快。", "error_description": "量词错误：“大道”是道路，应该用“条”，“只”多用于动物，不能用于道路。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91153, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈推着车走大道上，聊着天。", "corrected_sentence": "妈妈推着车走在大道上，聊着天。", "error_description": "介词缺失：表示在路上行走要说“走在大道上”，“在”不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
