INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91155, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "吧主是管一个网上小圈子的人。", "primary_collocate": null, "pronunciation": "bā zhǔ", "ipa": "pa˥ ʈʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "她是读书小组的吧主。", "target_word": "吧主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吧主管这个小圈子的事。", "target_word": "吧主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的吧主很热心。", "target_word": "吧主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吧主请大家在吧里别发广告。", "target_word": "吧主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当吧主已经三年了。", "target_word": "吧主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吧主欢迎新朋友进来。", "target_word": "吧主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做吧主需要耐心。", "target_word": "吧主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爱猫的人都听这位吧主的话。", "target_word": "吧主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吧主定了一个小规则。", "target_word": "吧主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我给吧主发了一条消息。", "target_word": "吧主", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "网上小圈子的负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9bab8fe-0b72-43ae-8aa8-81542a01a1dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91155, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吧主", "is_correct": true, "explanation": "吧主指管理网上小圈子的人，符合“她是读书小组的吧主”的语境。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师是做饭的人，读书小组里没有这个职务，句子不通。"}, {"text": "局长", "is_correct": false, "explanation": "语义：局长是政府机关的职务，读书小组里没有这一职务，句子不通。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生是给病人看病的人，与管理读书小组无关。"}], "explanations": {"吧主": "吧主指管理网上小圈子的人，符合“她是读书小组的吧主”的语境。", "厨师": "语义：厨师是做饭的人，读书小组里没有这个职务，句子不通。", "局长": "语义：局长是政府机关的职务，读书小组里没有这一职务，句子不通。", "医生": "语义：医生是给病人看病的人，与管理读书小组无关。"}, "sentence_index": 0, "correct_answer": "吧主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的吧主很负责，每天都收作业。", "explanation": "这里应该用〈班长〉。吧主指网上小圈子的管理者，班里的负责人称为班长。"}, {"text": "我们球队的吧主很严格。", "explanation": "这里应该用〈队长〉。吧主用于网上小圈子，体育队的负责人称为队长。"}, {"text": "这个网站的吧主很负责。", "explanation": "这里应该用〈站长〉。吧主管理的是小圈子，网站的负责人称为站长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91155, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吧主", "is_correct": true, "explanation": "吧主指管理网上小圈子的人，“做吧主需要耐心”说的正是这个职务。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以去做的职务，“做空气需要耐心”语义不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能被“做”，句子语义不通。"}, {"text": "阁下", "is_correct": false, "explanation": "语义：“阁下”是对人的敬称，不是职务，不能说“做阁下”。"}], "explanations": {"吧主": "吧主指管理网上小圈子的人，“做吧主需要耐心”说的正是这个职务。", "空气": "语义：空气不是可以去做的职务，“做空气需要耐心”语义不通。", "月亮": "语义：月亮不能被“做”，句子语义不通。", "阁下": "语义：“阁下”是对人的敬称，不是职务，不能说“做阁下”。"}, "sentence_index": 6, "correct_answer": "吧主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司的吧主每天都要开会。", "explanation": "这里应该用〈经理〉。吧主只用于网络贴吧的管理者，公司的负责人称为经理。"}, {"text": "我们医院的吧主很负责。", "explanation": "这里应该用〈院长〉。吧主只用于网络贴吧，医院的负责人称为院长。"}, {"text": "这家工厂的吧主很能干。", "explanation": "这里应该用〈厂长〉。吧主只用于网络贴吧，工厂的负责人称为厂长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91155, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "读书小组新选了一只吧主。", "corrected_sentence": "读书小组新选了一位吧主。", "error_description": "量词错误：吧主指人，应该用量词“位”（或“个”）。“只”多用于动物或器物，不用于数人。正确说法是“一位吧主”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91155, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天我在网上认识了这只吧主。", "corrected_sentence": "昨天我在网上认识了这位吧主。", "error_description": "量词错误：吧主指人，应该用量词“位”（或“个”）。“只”多用于动物，不用于人。应说“这位吧主”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
