INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91157, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "和以前不一样了，换了。", "primary_collocate": null, "pronunciation": "biàn dòng", "ipa": "pi̯ɛn˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "上课时间有变动，请看通知。", "target_word": "变动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的会议地点变动了。", "target_word": "变动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的电话号码有变动，请记下来。", "target_word": "变动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行的安排有一点变动。", "target_word": "变动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的规定没有变动。", "target_word": "变动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "座位的顺序变动了，你坐前面。", "target_word": "变动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天的考试时间有变动吗？", "target_word": "变动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们的名单有变动，要告诉我。", "target_word": "变动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的住址变动了，我不知道新地址。", "target_word": "变动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的上班时间下个月会变动。", "target_word": "变动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变动了", "label": "体标"}, {"form": "變動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "安排、时间、地点等和原来不同，有了更换", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2e039c7-c01e-4c40-b644-454870abac61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91157, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变动", "is_correct": true, "explanation": "变动：表示上课时间有了更改，与“有”搭配，句子通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“上课时间”不是有颜色的事物，“上课时间有颜色”与句意不符。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“时间”一般不说“有重量”，与“上课时间”不搭配。"}, {"text": "味道", "is_correct": false, "explanation": "语义：时间没有味道，“上课时间有味道”说不通。"}], "explanations": {"变动": "变动：表示上课时间有了更改，与“有”搭配，句子通顺。", "颜色": "语义：“上课时间”不是有颜色的事物，“上课时间有颜色”与句意不符。", "重量": "搭配：“时间”一般不说“有重量”，与“上课时间”不搭配。", "味道": "语义：时间没有味道，“上课时间有味道”说不通。"}, "sentence_index": 0, "correct_answer": "变动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几年，他的笑容变动得很厉害。", "explanation": "这里应该用〈变化〉。变动多指时间、地点、安排等的调整，笑容的改变要用变化。"}, {"text": "行李箱慢慢变动到了门口。", "explanation": "这里应该用〈移动〉。变动表示改变，不表示位置的移动，行李箱挪到门口要用移动。"}, {"text": "他终于变动了自己的错误。", "explanation": "这里应该用〈改正〉。变动指安排、时间等发生更改，改掉错误要用改正。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91157, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变动", "is_correct": true, "explanation": "变动：表示考试时间会不会更改，与“有……吗”搭配，句子通顺。"}, {"text": "形状", "is_correct": false, "explanation": "语义：考试时间没有形状，“考试时间有形状吗”与句意不符。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“时间”不能说“有体积”，与“考试时间”搭配不当。"}, {"text": "温度", "is_correct": false, "explanation": "语义：时间没有温度，“考试时间有温度吗”说不通。"}], "explanations": {"变动": "变动：表示考试时间会不会更改，与“有……吗”搭配，句子通顺。", "形状": "语义：考试时间没有形状，“考试时间有形状吗”与句意不符。", "体积": "搭配：“时间”不能说“有体积”，与“考试时间”搭配不当。", "温度": "语义：时间没有温度，“考试时间有温度吗”说不通。"}, "sentence_index": 6, "correct_answer": "变动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把旧的课本变动了，换了一本新的。", "explanation": "这里应该用〈更换〉。变动表示局部或状况的调整，把整本书换成另一本要用更换。"}, {"text": "妈妈轻轻一变动，宝宝就醒了。", "explanation": "这里应该用〈动〉。变动指事物的状况或安排发生改变，人的身体动作要用动，不能说变动。"}, {"text": "公司变动了小王去上海工作。", "explanation": "这里应该用〈调动〉。变动不能用来派人去外地工作，人员的调派要用调动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91157, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议地点很变动，请大家注意。", "corrected_sentence": "会议地点有变动，请大家注意。", "error_description": "“很”不能直接修饰动词“变动”。应用“有”引出“变动”，说“会议地点有变动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91157, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下周的班级名单有一只变动，请大家看通知。", "corrected_sentence": "下周的班级名单有一处变动，请大家看通知。", "error_description": "量词错误：“变动”指名单上的改动，应用量词“处”，说“一处变动”，不能说“一只变动”；“只”用于动物或成对的物品。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
